-- ----------------------------
-- View structure for VE_AC_BOOK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VE_AC_BOOK" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	   A.ID AS VALUE,
	   BOOKCODE AS CODE,
	   BOOKNAME AS TEXT,
	   BOOKNAMEENG AS TEXTENG,
	   A.ORDERNO AS SORTORDER,
	   G.SS_USER_ID,
	   A.ID AC_BOOK_ID,
	   BOOKCODE,
	   BOOKNAME,
	   REFID1NAME,
	   REFID2NAME,
	   REFDATE1NAME,
	   REFDATE2NAME,
	   REFAMOUNT1NAME,
	   REFAMOUNT2NAME,
	   BOOKNAMEENG,
	   A.ORDERNO
FROM   VW_AC_BOOK A
INNER  JOIN SS_EDITBOOK_CH C ON A.ID = C.AC_BOOK_ID
INNER  JOIN SS_MENU M ON M.ID = C.SS_MENU_ID AND M.CODE = 'VN.MIS.AC.GL'
INNER  JOIN SS_ROLE R ON C.SS_ROLE_ID = R.ID
INNER  JOIN SS_ROLEGRANT G ON R.ID = G.SS_ROLE_ID AND G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID;

