-- View structure for VE_BG_BUDGETGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VE_BG_BUDGETGROUP" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
    A.ID AS VALUE,
    BUDGETGROUPCODE AS CODE,
    BUDGETGROUPNAME AS TEXT,
    BUDGETGROUPNAMEENG AS TEXTENG,
    BUDGETGROUPCODE AS SORTORDER,
    G.SS_USER_ID,
    C.SS_MENU_ID,
    R.SS_APPLICATION_ID
FROM   VW_BG_BUDGETGROUP A
INNER  JOIN SS_EDITBUDGETGROUP_CH C ON A.ID = C.BG_BUDGETGROUP_ID
INNER  JOIN SS_ROLE R ON C.SS_ROLE_ID = R.ID
INNER  JOIN SS_ROLEGRANT G ON R.ID = G.SS_ROLE_ID AND
  G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID AND A.LEVEL_ID = 3;

-- ----------------------------
-- View structure for VE_HR_STAFFTYPE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VE_HR_STAFFTYPE" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	   A.ID AS VALUE,
	   A.STAFFTYPECODE AS CODE,
	   A.STAFFTYPENAME AS TEXT,
	   --A.STAFFTYPENAMEENG AS TEXTENG,
	   A.STAFFTYPECODE AS SORTORDER,
	   A.ID HR_STAFFTYPE_ID,
	   G.SS_USER_ID,
	   C.SS_MENU_ID,
	   A.STAFFTYPECODE,
	   A.STAFFTYPENAME,
	   --A.STAFFTYPEABB,
	   --A.DESCRIPTION,
	   --A.STAFFTYPENAMEENG,
	   --A.STAFFTYPEABBENG,
	   --A.ORDERNO,
	   --A.ISREQUIRECITIZENNO_ID,
	   A.ISACTIVE_ID,
	   --A.ISSHOWREPORT_ID,
	   R.SS_APPLICATION_ID
FROM   VW_HR_STAFFTYPE A
INNER  JOIN SS_EDITSTAFFTYPE_CH C ON A.ID = C.HR_STAFFTYPE_ID
INNER  JOIN SS_MENU M ON M.ID = C.SS_MENU_ID
INNER  JOIN SS_ROLE R ON C.SS_ROLE_ID = R.ID AND R.SS_APPLICATION_ID = 160
INNER  JOIN SS_ROLEGRANT G ON R.ID = G.SS_ROLE_ID AND
							  G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID;

-- ----------------------------
-- View structure for VE_MT_DEPARTMENT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VE_MT_DEPARTMENT" AS SELECT M.ID,
	   M.ID                  AS VALUE,
	   DEPARTMENTCODE        AS CODE,
	   DEPARTMENTNAME        AS TEXT,
	   DEPARTMENTNAMEENG     AS TEXTENG,
	   DEPARTMENTCODE        AS SORTORDER,
	   G.SS_USER_ID,
	   C.SS_MENU_ID,
	   R.SS_APPLICATION_ID,
	   DEPARTMENTCODE,
	   DEPARTMENTCODE1,
	   DEPARTMENTCODE2,
	   DEPARTMENTCODE3,
	   DEPARTMENTCODEHR,
	   DEPARTMENTNAME,
	   DEPARTMENTNAMEENG,
	   DEPARTMENTFULLNAME,
	   DEPARTMENTFULLNAMEENG,
	   DEPARTMENTABB,
	   DEPARTMENTABBENG,
	   DEPARTMENTTYPE_ID,
	   DEPARTMENTSTATUS_ID,
	   DEPARTMENTGROUPCODE,
	   MASTER_ID,
	   MT_CAMPUS_ID,
       M.DEPARTMENTINDEX
FROM   VW_MT_DEPARTMENT M
INNER  JOIN SS_EDITDEPARTMENT_CH C ON M.ID = C.MT_DEPARTMENT_ID
INNER  JOIN SS_ROLE R ON C.SS_ROLE_ID = R.ID
INNER  JOIN SS_ROLEGRANT G ON R.ID = G.SS_ROLE_ID AND
							  G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID;

-- ----------------------------
-- View structure for VGE_BG_BUDGETGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VGE_BG_BUDGETGROUP" AS SELECT
     CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
  CASE
       WHEN E.ID IS NULL THEN
      0
       ELSE
      1
     END ISEDITABLE,
     G.CODE,
     G.VALUE,
     G.TEXT,
     G.TEXTENG,
     G.SORTORDER,
     G.SS_USER_ID,
     E.SS_MENU_ID
FROM   VG_BG_BUDGETGROUP G
LEFT   JOIN VE_BG_BUDGETGROUP E ON G.VALUE = E.VALUE AND G.SS_USER_ID = E.SS_USER_ID
GROUP BY CASE
       WHEN E.ID IS NULL THEN
      0
       ELSE
      1
     END,G.CODE,
     G.VALUE,
     G.TEXT,
     G.TEXTENG,
     G.SORTORDER,
     G.SS_USER_ID,
     E.SS_MENU_ID;

-- ----------------------------
-- View structure for VGE_MT_DEPARTMENT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VGE_MT_DEPARTMENT" AS SELECT CASE
		   WHEN E.ID IS NULL THEN
			0
		   ELSE
			1
	   END ISEDITABLE,
	   E.ID,--G.ID,
	   E.VALUE,--G.VALUE,
	   E.CODE,--G.CODE,
	   E.TEXT,--G.TEXT,
	   E.TEXTENG, --G.TEXTENG,
	   E.SORTORDER, --G.SORTORDER,
	   G.SS_USER_ID,
	   E.SS_MENU_ID,
	   G.SS_APPLICATION_ID,
	   G.MASTER_ID,
	   G.MT_CAMPUS_ID
FROM   VG_MT_DEPARTMENT G
LEFT   JOIN VE_MT_DEPARTMENT E
ON     G.VALUE = E.VALUE AND --G.ID = E.ID AND
	   G.SS_USER_ID = E.SS_USER_ID AND
	   G.SS_APPLICATION_ID = E.SS_APPLICATION_ID;

-- ----------------------------
-- View structure for VG_AC_BOOK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_AC_BOOK" AS SELECT CAST(MIN(A.ID) AS NUMBER(12)) ID,
	   CAST(MIN(A.VALUE) AS NUMBER(12)) VALUE,
	   BOOKCODE AS CODE,
	   TEXT,
	   TEXTENG,
	   SORTORDER,
	   SS_USER_ID,
	   AC_BOOK_ID,
	   BOOKCODE,
	   BOOKNAME,
	   REFID1NAME,
	   REFID2NAME,
	   REFDATE1NAME,
	   REFDATE2NAME,
	   REFAMOUNT1NAME,
	   REFAMOUNT2NAME,
	   BOOKNAMEENG,
	   ORDERNO
FROM   (SELECT A.ID,
			   A.ID            AS VALUE,
			   BOOKCODE        AS CODE,
			   BOOKNAME        AS TEXT,
			   BOOKNAMEENG     AS TEXTENG,
			   ORDERNO         AS SORTORDER,
			   G.SS_USER_ID,
			   A.ID            AC_BOOK_ID,
			   BOOKCODE,
			   BOOKNAME,
			   REFID1NAME,
			   REFID2NAME,
			   REFDATE1NAME,
			   REFDATE2NAME,
			   REFAMOUNT1NAME,
			   REFAMOUNT2NAME,
			   BOOKNAMEENG,
			   ORDERNO
		FROM   VW_AC_BOOK A
		INNER  JOIN SS_GRANTBOOK_CH C ON A.ID = C.AC_BOOK_ID
		INNER  JOIN SS_ROLE R ON C.SS_ROLE_ID = R.ID AND R.SS_APPLICATION_ID = 150
		INNER  JOIN SS_ROLEGRANT G ON R.ID = G.SS_ROLE_ID AND G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID
		UNION
		SELECT VALUE,
			   VALUE,
			   CODE,
			   TEXT,
			   TEXTENG,
			   SORTORDER,
			   SS_USER_ID,
			   AC_BOOK_ID,
			   BOOKCODE,
			   BOOKNAME,
			   REFID1NAME,
			   REFID2NAME,
			   REFDATE1NAME,
			   REFDATE2NAME,
			   REFAMOUNT1NAME,
			   REFAMOUNT2NAME,
			   BOOKNAMEENG,
			   ORDERNO
		FROM   VE_AC_BOOK) A
GROUP  BY TEXT,
		  TEXTENG,
		  SORTORDER,
		  SS_USER_ID,
		  AC_BOOK_ID,
		  BOOKCODE,
		  BOOKNAME,
		  REFID1NAME,
		  REFID2NAME,
		  REFDATE1NAME,
		  REFDATE2NAME,
		  REFAMOUNT1NAME,
		  REFAMOUNT2NAME,
		  BOOKNAMEENG,
		  ORDERNO;

-- ----------------------------
-- View structure for VG_BG_BUDGETGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_BG_BUDGETGROUP" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) ID,
    CAST(MIN(VALUE) AS NUMBER(12)) VALUE,
    CODE,
    TEXT,
    TEXTENG,
    SORTORDER,
    SS_USER_ID,
    SS_APPLICATION_ID
FROM
  (
    SELECT A.ID,
            A.ID                AS VALUE,
            BUDGETGROUPCODE     AS CODE,
            BUDGETGROUPNAME     AS TEXT,
            BUDGETGROUPNAMEENG  AS TEXTENG,
            BUDGETGROUPCODE     AS SORTORDER,
            G.SS_USER_ID,
            C.SS_APPLICATION_ID
    FROM   VW_BG_BUDGETGROUP A
            INNER  JOIN SS_GRANTBUDGETGROUP_CH C ON A.ID = C.BG_BUDGETGROUP_ID
            INNER  JOIN SS_ROLE R ON C.SS_ROLE_ID = R.ID
            INNER  JOIN SS_ROLEGRANT G ON R.ID = G.SS_ROLE_ID AND
                    G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID AND
                    A.LEVEL_ID = 3
    UNION
    SELECT ID, VALUE, CODE, TEXT, TEXTENG, SORTORDER, SS_USER_ID, SS_APPLICATION_ID
    FROM   VE_BG_BUDGETGROUP)
GROUP  BY CODE, TEXT, TEXTENG, SORTORDER, SS_USER_ID, SS_APPLICATION_ID;

-- ----------------------------
-- View structure for VG_BG_BUDGETGROUP_YEAR
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_BG_BUDGETGROUP_YEAR" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
  A.BUDGETPERIODID AS BUDGETYEAR,
  B.BUDGETGROUPID AS BG_BUDGETGROUP_ID,
  B.BUDGETGROUPCODE AS BUDGETGROUPCODE,
  B.BUDGETGROUPNAME AS BUDGETGROUPNAME,
  B.BUDGETGROUPNAMEENG AS BUDGETGROUPNAMEENG,
  B.SORTBY AS SORTORDER
FROM PROMIS.BUDGETPERIOD A
  INNER JOIN PROMIS.BUDGETGROUP B ON A.BUDGETGROUPID=B.BUDGETGROUPID;

-- ----------------------------
-- View structure for VG_BG_STBGGROUPDEPT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_BG_STBGGROUPDEPT" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.DEPARTMENTID AS MT_DEPARTMENT_ID,
	B.DEPARTMENTCODE,
	B.DEPARTMENTNAME,
	A.BUDGETPERIODID AS BUDGETYEAR,
	A.BUDGETGROUPID AS BG_BUDGETGROUP_ID
FROM PROMIS.BUDGETSTRUCDEPARTMENT A
	INNER JOIN VG_MT_DEPARTMENT B ON A.DEPARTMENTID=B.VALUE AND B.SS_APPLICATION_ID=110;

-- ----------------------------
-- View structure for VG_BP_BGGROUPDEPT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_BP_BGGROUPDEPT" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID, A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.MT_DEPARTMENT_ID, B.DEPARTMENTCODE, B.DEPARTMENTNAME
FROM BP_PERIODAPP A
	INNER JOIN VG_MT_DEPARTMENT B ON A.MT_DEPARTMENT_ID=B.VALUE AND B.SS_APPLICATION_ID=110
GROUP BY A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.MT_DEPARTMENT_ID, B.DEPARTMENTCODE, B.DEPARTMENTNAME;

-- ----------------------------
-- View structure for VG_HR_EVAPP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_HR_EVAPP" AS SELECT A.ID,
	   A.GUID,
	   A.HR_EVLOTAPP_ID,
	   A.HR_STAFF_ID,
	   A.APPSTATUS_ID,
	   D.DEPARTMENTCODE,
	   D.DEPARTMENTFULLNAME,
	   A.HR_EVPOSITION_ID,
	   E.EVPOSITIONCODE,
	   E.EVPOSITIONNAME,
	   E.ISACTIVE_ID,
	   A.HR_STAFFBOARD1_ID,
	   A.HR_STAFFBOARD2_ID,
	   A.HR_STAFFBOARD3_ID,
	   A.HR_STAFFBOARD4_ID,
	   A.HR_STAFFBOARD5_ID,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,

	   B.STAFFCODE,
	   B.SNAME,
	   B.SNAMEENG,
	   B.SNAMEFULL,
	   B.STAFFSTATUS_ID,
	   B.STAFFSTATUSNAME
FROM   VW_HR_EVAPP_INFO A
INNER  JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID = B.ID
INNER  JOIN VG_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID = D.VALUE
								  AND D.SS_APPLICATION_ID = 160
INNER  JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID = E.ID;

-- ----------------------------
-- View structure for VG_HR_EVCOMMAND
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_HR_EVCOMMAND" AS SELECT A.ID,
	   A.TYPE_ID,
	   A.HR_EVLOTAPP_ID,
	   A.COMMANDNAME,
	   A.DESCRIPTION,
	   A.COMMANDSTATUS_ID,
	   A.SCORE,
	   A.ISSUBMITAPP_ID,
	   A.MT_DEPARTMENT_ID,
	   A.HR_EVCOMMANDTYPE_ID,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.GUID,

	   A.COMMANDSTATUSNAME,
	   A.REGISTERURL,
	   A.BUDGETYEAR,
	   A.FILENAME,
	   A.FILEGUID,

	   A.COMMANDTYPECODE,
	   D.DEPARTMENTCODE
FROM   VW_HR_EVCOMMAND A
INNER  JOIN VG_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID = D.VALUE
								  AND D.SS_APPLICATION_ID = 160;

-- ----------------------------
-- View structure for VG_HR_STAFFTYPE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_HR_STAFFTYPE" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) ID,
	   CAST(MIN(VALUE) AS NUMBER(12)) VALUE,
	   STAFFTYPECODE AS CODE,
	   TEXT,
	   --TEXTENG,
	   SORTORDER,
	   SS_USER_ID,
	   HR_STAFFTYPE_ID,
	   STAFFTYPECODE,
	   STAFFTYPENAME,
	   --STAFFTYPEABB,
	  -- DESCRIPTION,
	   --STAFFTYPENAMEENG,
	   --STAFFTYPEABBENG,
	   --ORDERNO,
	   --ISREQUIRECITIZENNO_ID,
	   ISACTIVE_ID
	   --ISSHOWREPORT_ID
FROM   (SELECT A.ID,
			   A.ID                  AS VALUE,
			   A.STAFFTYPECODE         AS CODE,
			   A.STAFFTYPENAME         AS TEXT,
			   --A.STAFFTYPENAMEENG      AS TEXTENG,
			   A.STAFFTYPECODE         AS SORTORDER,
			   G.SS_USER_ID,
			   A.ID                  HR_STAFFTYPE_ID,
			   A.STAFFTYPECODE,
			   A.STAFFTYPENAME,
			   --A.STAFFTYPEABB,
			   --A.DESCRIPTION,
			   --A.STAFFTYPENAMEENG,
			   --A.STAFFTYPEABBENG,
			   --A.ORDERNO,
			   --A.ISREQUIRECITIZENNO_ID,
			   A.ISACTIVE_ID
			   --A.ISSHOWREPORT_ID
		FROM   VW_HR_STAFFTYPE A
		INNER  JOIN SS_GRANTSTAFFTYPE_CH C ON A.ID = C.HR_STAFFTYPE_ID
		INNER  JOIN SS_ROLE R ON C.SS_ROLE_ID = R.ID AND R.SS_APPLICATION_ID = 160
		INNER  JOIN SS_ROLEGRANT G ON R.ID = G.SS_ROLE_ID AND
									  G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID
		UNION
		SELECT VALUE,
			   VALUE,
			   CODE,
			   TEXT,
			   --TEXTENG,
			   SORTORDER,
			   SS_USER_ID,
			   HR_STAFFTYPE_ID,
			   STAFFTYPECODE,
			   STAFFTYPENAME,
			   --STAFFTYPEABB,
			   --DESCRIPTION,
			   --STAFFTYPENAMEENG,
			   --STAFFTYPEABBENG,
			   --ORDERNO,
			   --ISREQUIRECITIZENNO_ID,
			   ISACTIVE_ID
			   --ISSHOWREPORT_ID
		FROM   VE_HR_STAFFTYPE
		WHERE  SS_APPLICATION_ID = 160)
GROUP  BY TEXT,
		  --TEXTENG,
		  SORTORDER,
		  SS_USER_ID,
		  HR_STAFFTYPE_ID,
		  STAFFTYPECODE,
		  STAFFTYPENAME,
		  --STAFFTYPEABB,
		  --DESCRIPTION,
		  --STAFFTYPENAMEENG,
		  --STAFFTYPEABBENG,
		  --ORDERNO,
		  --ISREQUIRECITIZENNO_ID,
		  ISACTIVE_ID
		 -- ISSHOWREPORT_ID;

-- ----------------------------
-- View structure for VG_MT_DEPARTMENT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_MT_DEPARTMENT" AS SELECT CAST(ROWNUM AS NUMBER(12)) ID,
	   CAST(VALUE AS NUMBER(12)) VALUE,
	   CODE,
	   TEXT,
	   TEXTENG,
	   SORTORDER,
	   SS_APPLICATION_ID,
	   SS_USER_ID,
	   DEPARTMENTTYPE_ID,
	   DEPARTMENTSTATUS_ID,
	   DEPARTMENTGROUPCODE,
	   MASTER_ID,
	   MT_CAMPUS_ID,
	   DEPARTMENTINDEX,
	   CODE DEPARTMENTCODE,
	   TEXT DEPARTMENTNAME,
	   DEPARTMENTFULLNAME,
	   DEPARTMENTCODE1
FROM   (SELECT --M.ID,
		 M.ID                 AS VALUE,
		 DEPARTMENTCODE       AS CODE,
		 DEPARTMENTNAME       AS TEXT,
		 DEPARTMENTNAMEENG    AS TEXTENG,
		 DEPARTMENTCODE       AS SORTORDER,
		 C.SS_APPLICATION_ID,
		 G.SS_USER_ID,
		 DEPARTMENTTYPE_ID,
		 DEPARTMENTSTATUS_ID,
		 DEPARTMENTGROUPCODE,
		 M.DEPARTMENTFULLNAME,
		 MASTER_ID,
		 MT_CAMPUS_ID,
		 M.DEPARTMENTINDEX,
		 M.DEPARTMENTCODE1
		FROM   VW_MT_DEPARTMENT M
		INNER  JOIN SS_GRANTDEPARTMENT_CH C ON M.ID = C.MT_DEPARTMENT_ID
		INNER  JOIN SS_ROLEGRANT G ON C.SS_ROLE_ID = G.SS_ROLE_ID AND
									  G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID
		UNION
		SELECT --ID,
		 VALUE,
		 CODE,
		 TEXT,
		 TEXTENG,
		 SORTORDER,
		 SS_APPLICATION_ID,
		 SS_USER_ID,
		 DEPARTMENTTYPE_ID,
		 DEPARTMENTSTATUS_ID,
		 DEPARTMENTGROUPCODE,
		 DEPARTMENTFULLNAME,
		 MASTER_ID,
		 MT_CAMPUS_ID,
		 DEPARTMENTINDEX,
		 DEPARTMENTCODE1
		FROM   VE_MT_DEPARTMENT);

-- ----------------------------
-- View structure for VG_SK_LOCATION
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_SK_LOCATION" AS SELECT CAST(MIN(ID) AS NUMBER(12)) ID,
     VALUE,
     CODE,
     TEXT,
     TEXTENG,
     SORTORDER,
     SS_USER_ID,
     SS_APPLICATION_ID,
     MT_CAMPUS_ID,
     MT_DEPARTMENTMASTER_ID,
     ORDERNO
FROM   (SELECT A.ID,
         A.ID AS VALUE,
         A.LOCATIONCODE AS CODE,
         A.LOCATIONNAME AS TEXT,
         A.LOCATIONNAME AS TEXTENG,
         A.ORDERNO AS SORTORDER,
         G.SS_USER_ID,
         R.SS_APPLICATION_ID,
         MT_CAMPUS_ID,
         MT_DEPARTMENTMASTER_ID,
         A.ORDERNO
    FROM   VW_SK_LOCATION A
    INNER  JOIN SS_GRANTLOCATION_CH C
    ON     A.LOCATIONCODE = C.SK_LOCATION_CODE
    INNER  JOIN SS_ROLE R
    ON     C.SS_ROLE_ID = R.ID
    INNER  JOIN SS_ROLEGRANT G
    ON     R.ID = G.SS_ROLE_ID
         AND G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID
    /*      UNION
        SELECT ID,
               VALUE,
               CODE,
               TEXT,
               TEXTENG,
               SORTORDER,
               SS_USER_ID,
               SS_APPLICATION_ID,
               MT_CAMPUS_ID,
               MT_DEPARTMENTMASTER_ID
        FROM   VE_SK_LOCATION WHERE SS_USER_ID = FN_SS_PARAMETER_GETUSERID*/
    )
GROUP  BY VALUE,
      CODE,
      TEXT,
      TEXTENG,
      SORTORDER,
      SS_USER_ID,
      SS_APPLICATION_ID,
      MT_CAMPUS_ID,
      MT_DEPARTMENTMASTER_ID,
      ORDERNO;

-- ----------------------------
-- View structure for VG_SS_EXPQRYUSERMENU
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_SS_EXPQRYUSERMENU" AS SELECT
	Q.ID,
	Q.GUID,
	Q.NAME_THA,
	Q.ORDERNO,
	DECODE(Q.NAME_ENG, NULL, Q.NAME_THA, Q.NAME_ENG) AS NAME_ENG,
	Q.DESCRIPTION_THA,
	Q.DESCRIPTION_ENG,
	QGS.ID AS GRPSUB_ID,
	QGS.GUID AS GRPSUB_GUID,
	QGS.ORDERNO AS GRPSUB_ORDERNO,
	QGS.NAME_THA AS GRPSUB_NAME_THA,
	DECODE(QGS.NAME_ENG, NULL, QGS.NAME_THA, QGS.NAME_ENG) AS GRPSUB_NAME_ENG,
	A.ID AS GRP_ID,
  A.GUID AS GRP_GUID,
	A.ORDERNO AS GRP_ORDERNO,
	A.NAME_THA AS GRP_NAME_THA,
	A.NAME_ENG AS GRP_NAME_ENG
FROM SS_EXPQRY Q
JOIN (
     SELECT distinct RG.SS_USER_ID, QG.SS_EXPQRY_ID
     FROM SS_EXPQRYGRANT QG
     JOIN SS_EXPQRYROLEGRANT RG ON RG.SS_EXPQRYROLE_ID = QG.SS_EXPQRYROLE_ID
) G ON G.SS_EXPQRY_ID = Q.ID
JOIN SS_EXPQRYGROUPSUB QGS ON QGS.ID = Q.SS_EXPQRYGROUPSUB_ID
JOIN SS_EXPQRYGROUP A ON A.ID = QGS.SS_EXPQRYGROUP_ID
WHERE
	Q.ISENABLED_ID = 1 AND
	Q.ISSHOWINUSERMENU_ID = 1 AND
	G.SS_USER_ID = FN_SS_PARAMETER_GETUSERID() WITH READ ONLY CONSTRAINTS "SYS_C00169525";

-- ----------------------------
-- View structure for VG_SS_EXPQRYUSERMENUGRP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_SS_EXPQRYUSERMENUGRP" AS SELECT
	T.GRP_ID AS ID,
	T.GRP_ID AS VALUE,
	T.GRP_ID AS CODE,
	T.GRP_NAME_THA AS TEXT,
	T.GRP_NAME_ENG AS TEXTENG,
	T.GRP_ORDERNO AS SORTORDER
FROM VG_SS_EXPQRYUSERMENU T
GROUP BY
	T.GRP_ID,
	T.GRP_NAME_THA,
	T.GRP_NAME_ENG,
	T.GRP_ORDERNO WITH READ ONLY CONSTRAINTS "SYS_C00169542";

-- ----------------------------
-- View structure for VG_SS_EXPQRYUSERMENUGRPSUB
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VG_SS_EXPQRYUSERMENUGRPSUB" AS SELECT
	T.GRPSUB_ID AS ID,
	T.GRPSUB_GUID AS GUID,
	T.GRPSUB_ID AS VALUE,
	T.GRPSUB_ID AS CODE,
	T.GRPSUB_NAME_THA AS TEXT,
	T.GRPSUB_NAME_ENG AS TEXTENG,
	T.GRPSUB_ORDERNO AS SORTORDER,
	T.GRP_ID,
	T.GRP_GUID,
  T.GRP_ORDERNO,
  T.GRP_NAME_THA,
  T.GRP_NAME_ENG
FROM VG_SS_EXPQRYUSERMENU T
GROUP BY
	T.GRPSUB_ID,
	T.GRPSUB_GUID,
	T.GRPSUB_NAME_THA,
	T.GRPSUB_NAME_ENG,
	T.GRPSUB_ORDERNO,
	T.GRP_ID,
	T.GRP_GUID,
  T.GRP_ORDERNO,
  T.GRP_NAME_THA,
  T.GRP_NAME_ENG WITH READ ONLY CONSTRAINTS "SYS_C00169543";

-- ----------------------------
-- View structure for VL_BG_ACTIVITY_STRUC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BG_ACTIVITY_STRUC" AS SELECT CAST(MAX(ROWNUM) AS NUMBER(12)) ID,
     PL.ACTIVITYID AS VALUE,
     PL.ACTIVITYCODE AS CODE,
     PL.ACTIVITYNAME AS TEXT,
     PL.ACTIVITYNAMEENG AS TEXTENG,
     PL.ACTIVITYCODE AS SORTORDER,
     PL.BUDGETPERIODID,
     PL.BUDGETGROUPID,
     PL.BUDGETSTUCTYPE,
     PL.PROJECTID
FROM   PROMIS.V_CMB_BUDGETSTRUCPROJECTAC@MISLINK PL
GROUP  BY PL.ACTIVITYID,
      PL.ACTIVITYCODE,
      PL.ACTIVITYNAME,
      PL.ACTIVITYNAMEENG,
      PL.BUDGETPERIODID,
      PL.BUDGETGROUPID,
      PL.BUDGETSTUCTYPE,
      PL.PROJECTID;

-- ----------------------------
-- View structure for VL_BG_BUDGETGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BG_BUDGETGROUP" AS SELECT A.BUDGETGROUPID AS ID,
  A.BUDGETGROUPCODE,
  A.BUDGETGROUPNAME AS TEXT,
  A.BUDGETGROUPNAMEENG AS TEXTENG,
  A.BUDGETGROUPLEVEL AS LEVEL_ID,
  A.SORTBY AS SORTORDER
FROM PROMIS.BUDGETGROUP@MISLINK A
WHERE A.BUDGETGROUPLEVEL = 4;

-- ----------------------------
-- View structure for VL_BG_PLAN_STRUC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BG_PLAN_STRUC" AS SELECT CAST(MAX(ROWNUM) AS NUMBER(12)) ID,
     PL.PLANID AS VALUE,
     PL.PLANCODE AS CODE,
     PL.PLANNAME AS TEXT,
     PL.PLANNAMEENG AS TEXTENG,
     PL.PLANCODE AS SORTORDER,
     PL.BUDGETSTRUCPLANID,
     PL.BUDGETPERIODID,
     PL.BUDGETGROUPID,
     PL.BUDGETSTUCTYPE
FROM   PROMIS.V_CMB_BUDGETSTRUCPLAN@MISLINK PL
GROUP  BY PL.PLANID,
      PL.PLANCODE,
      PL.PLANNAME,
      PL.PLANNAMEENG,
      PL.BUDGETSTRUCPLANID,
      PL.BUDGETPERIODID,
      PL.BUDGETGROUPID,
      PL.BUDGETSTUCTYPE;

-- ----------------------------
-- View structure for VL_BG_PRODUCT_STRUC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BG_PRODUCT_STRUC" AS SELECT CAST(MAX(ROWNUM) AS NUMBER(12)) ID,
     PL.PRODUCTID AS VALUE,
     PL.PRODUCTCODE AS CODE,
     PL.PRODUCTNAME AS TEXT,
     PL.PRODUCTNAME AS TEXTENG,
     PL.PRODUCTCODE AS SORTORDER,
     PL.PLANID,
	   PL.PLANCODE,
     PL.SORTBY,
	   PL.BUDGETPERIODID,
	   PL.BUDGETGROUPID
FROM   PROMIS.V_CMB_BUDGETSTRUCPRODUCT@MISLINK PL
GROUP  BY PL.PRODUCTID,
      PL.PRODUCTCODE,
      PL.PRODUCTNAME,
      PL.PLANID,
	    PL.PLANCODE,
      PL.SORTBY,
	    PL.BUDGETPERIODID,
	    PL.BUDGETGROUPID;

-- ----------------------------
-- View structure for VL_BG_PROJECT_STRUC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BG_PROJECT_STRUC" AS SELECT MAX(ROWNUM) ID,
     PL.PROJECTID AS VALUE,
     PL.PROJECTCODE AS CODE,
     PL.PROJECTCODE || ': ' || PL.PROJECTNAME AS TEXT,
     PL.PROJECTCODE || ': ' || PL.PROJECTNAME AS TEXTENG,
     PL.PROJECTCODE AS SORTORDER,
     PL.PROJECTNAME,
     PL.BUDGETPERIODID,
     PL.BUDGETGROUPID,
     PL.BUDGETSTUCTYPE,
     PL.PLANID,
     PL.PRODUCTID
FROM   PROMIS.V_CMB_BUDGETSTRUCPROJECT@MISLINK PL
GROUP  BY PL.PROJECTID,
      PL.PROJECTCODE,
      PL.PROJECTNAME,
      PL.BUDGETPERIODID,
      PL.BUDGETGROUPID,
      PL.BUDGETSTUCTYPE,
      PL.PLANID,
      PL.PRODUCTID;

-- ----------------------------
