-- ----------------------------
-- View structure for VL_BP_LOTINDICATORITEM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BP_LOTINDICATORITEM" AS SELECT A.ID,
	   A.ID AS VALUE,
	   A.INDICATORCODE AS CODE,
	   A.INDICATORNAME AS TEXT,
	   A.INDICATORNAME AS TEXTENG,
	   A.INDICATORCODE AS SORTORDER,
	   A.INDICATORLEVEL_ID,
	   A.BP_LOTINDICATOR_ID,
	   B.INDICATORTYPE_ID,
	   C.BUDGETYEAR
FROM BP_LOTINDICATORITEM A
INNER JOIN BP_LOTINDICATOR B ON A.BP_LOTINDICATOR_ID = B.ID
INNER JOIN BP_PERIODINDICATOR C ON B.ID = C.BP_LOTINDICATOR_ID
								   AND B.INDICATORTYPE_ID = C.INDICATORTYPE_ID;

-- ----------------------------
-- View structure for VL_BP_PERIODAPPACT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BP_PERIODAPPACT" AS SELECT A.ID,
	A.ID AS VALUE,
  A.ACTIVITYCODE AS CODE,
  A.ACTIVITYNAME AS TEXT,
  A.ACTIVITYNAMEENG AS TEXTENG,
