-- ----------------------------
-- View structure for VL_BP_PERIODAPPACTEXP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BP_PERIODAPPACTEXP" AS SELECT A.ID,
	A.ID AS VALUE,
  A.ORDERNO AS CODE,
  A.EXPENSE AS TEXT,
  A.EXPENSE AS TEXTENG,
