-- ----------------------------
-- View structure for VL_BP_PERIODUDEVELOP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BP_PERIODUDEVELOP" AS SELECT A.ID,
	A.ID AS VALUE,
	A.UDEVELOPCODE AS CODE,
	A.UDEVELOPNAME AS TEXT,
	A.UDEVELOPCODE AS SORTORDER,
