-- ----------------------------
-- View structure for VL_BP_PERIODUGOAL
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BP_PERIODUGOAL" AS SELECT A.ID,
	A.ID AS VALUE,
	A.UGOALCODE AS CODE,
	A.UGOALNAME AS TEXT,
	A.UGOALCODE AS SORTORDER,
