	INNER JOIN BP_UMISSION B ON A.BP_UMISSION_ID=B.ID;

-- ----------------------------
-- View structure for VL_BP_PERIODUOBJECTIVE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BP_PERIODUOBJECTIVE" AS SELECT A.ID,
	A.ID AS VALUE,
  B.UOBJECTIVECODE AS CODE,
  B.UOBJECTIVENAME AS TEXT,
  B.UOBJECTIVENAME AS TEXTENG,
