	INNER JOIN BP_UOBJECTIVE B ON A.BP_UOBJECTIVE_ID=B.ID;

-- ----------------------------
-- View structure for VL_BP_PERIODUSTRATEGY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BP_PERIODUSTRATEGY" AS SELECT A.ID,
	A.ID AS VALUE,
  B.USTRATEGYCODE AS CODE,
