	INNER JOIN BP_USTRATEGY B ON A.BP_USTRATEGY_ID=B.ID;

-- ----------------------------
-- View structure for VL_BP_PROJECTTYPE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_BP_PROJECTTYPE" AS SELECT A.ID,
	A.ID AS VALUE,
  A.PROJECTTYPECODE AS CODE,
