-- ----------------------------
-- View structure for VL_HR_EVPOSITION_LOT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_HR_EVPOSITION_LOT" AS SELECT CAST(MIN(B.ID) AS NUMBER(12)) AS ID,
	B.HR_EVPOSITION_ID AS VALUE,
	A.EVPOSITIONCODE AS CODE,
	A.EVPOSITIONNAME AS TEXT,
	A.EVPOSITIONNAMEENG AS TEXTENG,
	A.EVPOSITIONCODE AS SORTORDER,
	A.ISACTIVE_ID,
	B.HR_EVLOTAPP_ID,
	A.POSITIONTYPE_ID
FROM VW_HR_EVPOSITION A
	INNER JOIN HR_EVAPP B ON A.ID=B.HR_EVPOSITION_ID
GROUP BY B.HR_EVPOSITION_ID,
	A.EVPOSITIONCODE,
	A.EVPOSITIONNAME,
	A.EVPOSITIONNAMEENG,
	A.ISACTIVE_ID,
	B.HR_EVLOTAPP_ID,
	A.POSITIONTYPE_ID;

-- ----------------------------
-- View structure for VL_HR_STAFF_GRANT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_HR_STAFF_GRANT" AS SELECT T.ID,
     T.ID AS VALUE,
     T.GUID,
     T.STAFFCODE,
     T.SNAME,
    /* T.SNAMEABBRANK AS SNAME,*/
     T.SNAMEENG,
     T.KEYWORDSEARCH,
     D.DEPARTMENTCODE,
     STT.STAFFTYPECODE,
     T.STAFFSTATUS_ID,
     T.MT_DEPARTMENT_ID,
     T.HR_STAFFTYPE_ID,
     T.STAFFNAME,
     T.STAFFNAMEENG,
     T.STAFFSURNAME,
     T.STAFFSURNAMEENG,
     VM.SS_USER_ID,
     VM.SS_APPLICATION_ID,
       T.ISACTIVE_ID
FROM VW_HR_STAFF_NAME T
  INNER JOIN VG_HR_STAFFTYPE VGS ON T.HR_STAFFTYPE_ID = VGS.HR_STAFFTYPE_ID
  LEFT JOIN VW_MT_DEPARTMENT D ON T.MT_DEPARTMENT_ID = D.ID
  LEFT JOIN VW_HR_STAFFTYPE STT ON T.HR_STAFFTYPE_ID = STT.ID
  INNER JOIN VG_MT_DEPARTMENT VM ON T.MT_DEPARTMENT_ID = VM.VALUE AND VM.SS_APPLICATION_ID = 160
  INNER  JOIN VW_SS_CLIENTIDENTIFIER VC ON VM.SS_USER_ID = VC.SS_USER_ID;

-- ----------------------------
-- View structure for VL_MT_DEPARTMENT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_MT_DEPARTMENT" AS SELECT T.ID,
	   T.ID AS VALUE,
	   T.DEPARTMENTCODE AS CODE,
	   T.DEPARTMENTNAME AS TEXT,
	   DECODE(T.DEPARTMENTNAMEENG, NULL, T.DEPARTMENTNAME, T.DEPARTMENTNAMEENG) AS TEXTENG,
	   T.DEPARTMENTCODE AS SORTORDER,
       T.DEPARTMENTINDEX,
       T.DEPARTMENTTYPE_ID
FROM   VW_MT_DEPARTMENT T;

-- ----------------------------
-- View structure for VL_MT_DEPARTMENT_STRUCDEPT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_MT_DEPARTMENT_STRUCDEPT" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
     A.VALUE,
	   A.CODE,
	   A.TEXT,
	   A.TEXTENG,
     A.SS_USER_ID,
     A.SS_APPLICATION_ID,
     B.BUDGETPERIODID,
     B.BUDGETGROUPID
FROM   VG_MT_DEPARTMENT  A
INNER  JOIN PROMIS.BUDGETSTRUCDEPARTMENT@MISLINK B ON A.VALUE = B.DEPARTMENTID
GROUP  BY A.VALUE,
	   A.CODE,
	   A.TEXT,
	   A.TEXTENG,
     A.SS_USER_ID,
     A.SS_APPLICATION_ID,
     B.BUDGETPERIODID,
     B.BUDGETGROUPID;

-- ----------------------------
-- View structure for VL_MT_REFER
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_MT_REFER" AS SELECT T.ID,
	   T.REFERCODE,
	   T.REFERNAME,
	   T.REFERNAMEENG,
	   T.REFERTYPENAME,
	   T.REFERTYPENAMEENG,
	   T.HR_STAFF_ID,
	   T.REFERTYPE_ID,
	   T.ISACTIVED_ID,
	   T.INDIVIDUALTYPE_ID,
       T.STAFFSTATUSNAME,
       T.STAFFSTATUSNAMEENG
FROM   VW_MT_REFER_INFO T;

-- ----------------------------
-- View structure for VL_OL_ABSENTYEAR
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_OL_ABSENTYEAR" AS SELECT YEARINDEX AS ID,
  YEARINDEX AS VALUE,
  EVALUATEYEAR AS TEXT,
  DATEFROM,
  DATETO
FROM PROMIS.EVALUATEPERIOD
WHERE PERIODTYPE='Y';

-- ----------------------------
-- View structure for VL_SK_ASSETSTATUS_SURVEY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SK_ASSETSTATUS_SURVEY" AS SELECT T.ID         AS ID,
	   T.BYTECODE   AS VALUE,
	   T.BYTECODE   AS CODE,
	   T.BYTEDES    TEXT,
	   T.BYTEDESENG TEXTENG,
	   T.BYTEORDER  SORTORDER,
	   T.BYTECODE   ASSETSTATUSID,
	   T.BYTEDES    ASSETSTATUSNAME
FROM   VW_MIS_BYTEDES T
WHERE  T.TABLENAME = 'ASSET' AND T.COLUMNNAME = 'ASSETSTATUS' AND T.BYTECODE < '19';

-- ----------------------------
-- View structure for VL_SS_EXPQRYDATASRC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_EXPQRYDATASRC" AS SELECT
  T.ID AS ID,
  T.ID AS VALUE,
  T.CODE AS CODE,
  G.NAME_THA || ' • ' || T.NAME_THA AS TEXT,
  G.NAME_ENG || ' • ' || DECODE(T.NAME_ENG, NULL, T.NAME_THA, T.NAME_ENG) AS TEXTENG,
  T.ORDERNO AS SORTORDER,
  T.DATASOURCEUSETYPE_ID,
  T.SS_EXPQRYGROUP_ID
FROM SS_EXPQRYDATASRC T
JOIN SS_EXPQRYGROUP G ON G.ID = T.SS_EXPQRYGROUP_ID WITH READ ONLY CONSTRAINTS "SYS_C00169526";

-- ----------------------------
-- View structure for VL_SS_EXPQRYGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_EXPQRYGROUP" AS SELECT
  T.ID AS ID,
  T.ID AS VALUE,
  T.ID AS CODE,
  T.NAME_THA AS TEXT,
  T.NAME_ENG AS TEXTENG,
  T.ORDERNO AS SORTORDER
FROM SS_EXPQRYGROUP T WITH READ ONLY CONSTRAINTS "SYS_C00169527";

-- ----------------------------
-- View structure for VL_SS_EXPQRYGROUPSUB
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_EXPQRYGROUPSUB" AS SELECT
  T.ID AS ID,
  T.ID AS VALUE,
  T.ID AS CODE,
  T.NAME_THA AS TEXT,
  T.NAME_ENG AS TEXTENG,
  T.ORDERNO AS SORTORDER,
  T.SS_EXPQRYGROUP_ID,
  A.NAME_THA AS EXPQRYGROUPNAME,
  A.ORDERNO AS EXPQRYGROUPSORTORDER
FROM SS_EXPQRYGROUPSUB T
INNER JOIN SS_EXPQRYGROUP A ON A.ID = SS_EXPQRYGROUP_ID WITH READ ONLY CONSTRAINTS "SYS_C00169528";

-- ----------------------------
-- View structure for VL_SS_EXPQRYINPUTFORM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_EXPQRYINPUTFORM" AS SELECT
  T.ID AS ID,
  T.ID AS VALUE,
  T.CODE AS CODE,
  T.NAME_THA AS TEXT,
  T.NAME_ENG AS TEXTENG,
  T.CODE AS SORTORDER,
  T.GUID
FROM SS_EXPQRYINPUTFORM T WITH READ ONLY CONSTRAINTS "SYS_C00169529";

-- ----------------------------
-- View structure for VL_SS_EXPQRYROLE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_EXPQRYROLE" AS SELECT
  T.ID AS ID,
  T.ID AS VALUE,
  T.ID AS CODE,
  T.ROLENAME AS TEXT,
  T.ROLENAME AS TEXTENG,
  T.ROLENAME AS SORTORDER
FROM SS_EXPQRYROLE T WITH READ ONLY CONSTRAINTS "SYS_C00169530";

-- ----------------------------
-- View structure for VL_SS_ROLE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_ROLE" AS SELECT A.ID,
	   A.ID VALUE,
	   G.BYTEDES AS CODE,
	   A.ROLENAME AS TEXT,
	   A.ROLENAME AS TEXTENG,
	   G.BYTEDES || ': ' || A.ROLENAME AS SORTORDER,
	   A.ROLEGROUP_ID,
	   A.SS_APPLICATION_ID
FROM   SS_ROLE A,
	   (SELECT *
		FROM   SS_BYTEDES
		WHERE  TABLENAME = 'SS_ROLE' AND COLUMNNAME = 'ROLEGROUP_ID') G
WHERE  A.ROLEGROUP_ID = G.BYTEID;

-- ----------------------------
-- View structure for VL_SS_USER
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_USER" AS SELECT T.ID,
	   T.ID AS VALUE,
	   T.USERNAME AS CODE,
	   T.USERNAME || CASE WHEN MR.REFERNAME IS NOT NULL THEN  ': ' || MR.REFERNAME END AS TEXT,
	   T.USERNAME || CASE WHEN MR.REFERNAME IS NOT NULL THEN  ': ' || MR.REFERNAMEENG END AS TEXTENG,
	   T.USERNAME AS SORTORDER,
	   T.USERNAME,
	   T.MT_REFER_ID,
	   MR.REFERCODE,
	   MR.REFERNAME,
	   MR.REFERNAMEENG,
	   HR.STAFFCODE,
	   HR.SNAMEABB AS SNAME,
	   HR.POSITIONNAME,
	   HR.POSITIONWORKNAME,
	   HR.DEPARTMENTCODE,
	   HR.DEPARTMENTNAME,
	   HR.WORKDEPARTMENTCODE,
	   HR.WORKDEPARTMENTNAME,
	   T.SS_USERPROFILEPASSWORD_ID,
	   T.SS_USERPROFILETIME_ID,
	   T.LASTLOGINDATETIME,
	   T.LOGINTOTAL,
	   T.LASTCHANGEPASSWORDDATETIME,
	   T.LASTLOGOFFDATETIME,
	   T.LASTACCESSDATETIME,
	   T.INVALIDLOGONTOTAL,
	   T.ACCOUNTLOCKOUTSINCE,
	   T.ACCOUNTLOCKOUTTOTAL,
	   T.ACCOUNTLOCKOUTSUMMARY,
	   T.ENCRYPTKEYVERSION,
	   T.ENCRYPTKEYCONTENT,
	   T.CONNECTEDIP,
	   T.TERMINALIP,
	   T.UNILOGINSERVERID,
	   T.UNILOGINENTRYCODE,
	   T.UNILOGINENTRYEXPIRE,
	   T.VALIDDATEFROM,
	   T.VALIDDATETO,
	   T.THEME_ID,
	   T.THEMESIZE,
	   T.ACTIVE_ID,
	   T.ALLOW_ID,
     T.ALLOW_USERIMPERSONATE_ID,
	   T.ALLOWSETUPONCALLER_ID,
	   T.CREATEDATETIME,
	   T.CREATEBY,
	   T.UPDATEDATETIME,
	   T.UPDATEBY,
	   T.GUID
FROM   SS_USER T
LEFT   JOIN VW_MT_REFER MR ON T.MT_REFER_ID = MR.ID
LEFT   JOIN VW_HR_STAFF_INFO HR ON MR.HR_STAFF_ID = HR.ID;

-- ----------------------------
-- View structure for VL_SS_USER_APPLICATION
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_USER_APPLICATION" AS SELECT U.ID,
       U.ID AS VALUE,
       upper(U.USERNAME) AS CODE,
       upper(U.USERNAME) || DECODE(MR.REFERNAME, NULL, NULL, ': ' || MR.REFERNAME) AS TEXT,
      upper(U.USERNAME) || DECODE(MR.REFERNAME, NULL, NULL, ': ' || MR.REFERNAMEENG) AS TEXTENG,
       upper(U.USERNAME) AS SORTORDER,
       SS_MENUGROUP.SS_APPLICATION_ID
FROM   SS_MENU T
INNER  JOIN SS_MENUGROUP ON T.SS_MENUGROUP_ID = SS_MENUGROUP.ID AND T.ACTIVE_ID = 1
INNER  JOIN SS_GRANTMENU ON T.ID = SS_GRANTMENU.SS_MENU_ID
INNER  JOIN SS_GRANTUSERROLE ON SS_GRANTMENU.SS_ROLE_ID = SS_GRANTUSERROLE.SS_ROLE_ID
INNER  JOIN SS_USER U ON SS_GRANTUSERROLE.SS_USER_ID = U.ID
LEFT   JOIN VW_MT_REFER MR ON U.MT_REFER_ID = MR.ID
GROUP  BY SS_MENUGROUP.SS_APPLICATION_ID,
          U.ID,
          U.USERNAME,
          MR.REFERNAME,
          MR.REFERNAMEENG;

-- ----------------------------
-- View structure for VL_SS_USER_MENU
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VL_SS_USER_MENU" AS SELECT U.ID,
	   U.ID AS VALUE,
	   UPPER(U.USERNAME) AS CODE,
	   UPPER(U.USERNAME) || DECODE(MR.REFERNAME, NULL, NULL, ': ' || MR.REFERNAME) AS TEXT,
	   UPPER(U.USERNAME) || DECODE(MR.REFERNAME, NULL, NULL, ': ' || MR.REFERNAMEENG) AS TEXTENG,
	   UPPER(U.USERNAME) AS SORTORDER,
	   SS_MENUGROUP.SS_APPLICATION_ID,
       --T.ID SS_MENU_ID,
	   T.CODE MENU_CODE
FROM   SS_MENU T
INNER  JOIN SS_MENUGROUP ON T.SS_MENUGROUP_ID = SS_MENUGROUP.ID AND T.ACTIVE_ID = 1
INNER  JOIN SS_GRANTMENU ON T.ID = SS_GRANTMENU.SS_MENU_ID
INNER  JOIN SS_GRANTUSERROLE ON SS_GRANTMENU.SS_ROLE_ID = SS_GRANTUSERROLE.SS_ROLE_ID
INNER  JOIN SS_USER U ON SS_GRANTUSERROLE.SS_USER_ID = U.ID
LEFT   JOIN VW_MT_REFER MR ON U.MT_REFER_ID = MR.ID
GROUP  BY SS_MENUGROUP.SS_APPLICATION_ID,--T.ID,
		  T.CODE,
		  U.ID,
		  U.USERNAME,
		  MR.REFERNAME,
		  MR.REFERNAMEENG;

-- ----------------------------
-- View structure for VR_BP_BUDGET
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_BUDGET" AS SELECT V.BUDGETID AS ID,
       V.BUDGETPERIODID,
       V.FUNDGROUPID,
       V.BUDGETGROUPID,
       V.PLANID,
       V.PRODUCTID,
       V.PROJECTID,
       V.DEPARTMENTID,
       V.ACCOUNTTYPEID,
       V.BUDGETNAME,
       V.DESCRIPTION1,
       V.DESCRIPTION2,
       V.UNITPRICE,
       V.TM01,
       V.TM02,
       V.TM03,
       V.TM04,
       V.TM05,
       V.TM06,
       V.TM07,
       V.TM08,
       V.TM09,
       V.TM10,
       V.TM11,
       V.TM12,
       NVL(V.QUANTITY, 0) QUANTITY,
       V.UNITNAME,
       NVL(V.TOTALBUDGET, 0) TOTALBUDGET,
       NVL(V.CURRENTBUDGET, 0) CURRENTBUDGET,
       NVL(V.PRSUM, 0) PRSUM,
       NVL(V.PREPAYSUM, 0) PREPAYSUM,
       NVL(V.PAYSUM, 0) PAYSUM,
       V.BUDGETLEVELTYPE,
       V.ACTIVITYID,
       V.BUDGETLEVEL,
       V.BUDGETIDX,
       V.BUDGETCODE,
       V.BUDGETSTUCTYPE,
       V.FUNDGROUPNAME,
       V.PLANNAME,
       V.PRODUCTNAME,
       V.PROJECTNAME,
       V.BUDGETGROUPNAME,
       V.DEPARTMENTNAME,
       V.FUNDGROUPCODE,
       V.PLANCODE,
       V.PRODUCTCODE,
       V.PROJECTCODE,
       V.ACTIVITYCODE,
       V.BUDGETGROUPCODE,
       V.DEPARTMENTCODE,
       V.ACTIVITYNAME,
       V.ACCOUNTTYPECODE,
       V.ACCOUNTTYPENAME,
       V.BUDGETTYPE AS BUDGETTYPE,
       V.MASTERID AS MASTERID,
       V.INVESTMENTFLAG AS INVESTMENTFLAG,
       V.INVESTMENTFLAGNAME,
       V.SORTBY,
       V.STRATEGYUID,
       V.STRATEGYUCODE,
       V.STRATEGYUNAME,
       V.PLANUID,
       V.PLANUCODE,
       V.PLANUNAME

  FROM PROMIS.V_BUD_BUDGETINFO@MISLINK V
 WHERE V.CURRENTBUDGET <> 0 AND
       V.GROUPTYPE = 1
   AND V.BUDGETLEVELTYPE = 'O'
 GROUP BY V.BUDGETID,
          V.BUDGETPERIODID,
          V.FUNDGROUPID,
          V.BUDGETGROUPID,
          V.PLANID,
          V.PRODUCTID,
          V.PROJECTID,
          V.DEPARTMENTID,
          V.ACCOUNTTYPEID,
          V.BUDGETNAME,
          V.DESCRIPTION1,
          V.DESCRIPTION2,
          V.UNITPRICE,
          V.QUANTITY,
          V.UNITNAME,
          V.TOTALBUDGET,
          V.CURRENTBUDGET,
          V.PRSUM,
          V.PREPAYSUM,
          V.PAYSUM,
          V.BUDGETLEVELTYPE,
          V.ACTIVITYID,
          V.BUDGETLEVEL,
          V.BUDGETIDX,
          V.BUDGETCODE,
          V.BUDGETSTUCTYPE,
          V.FUNDGROUPNAME,
          V.PLANNAME,
          V.PRODUCTNAME,
          V.PROJECTNAME,
          V.BUDGETGROUPNAME,
          V.DEPARTMENTNAME,
          V.FUNDGROUPCODE,
          V.PLANCODE,
          V.PRODUCTCODE,
          V.PROJECTCODE,
          V.ACTIVITYCODE,
          V.BUDGETGROUPCODE,
          V.DEPARTMENTCODE,
          V.ACTIVITYNAME,
          V.ACCOUNTTYPECODE,
          V.ACCOUNTTYPENAME,
          V.BUDGETTYPE,
          V.MASTERID,
          V.INVESTMENTFLAG,
          V.INVESTMENTFLAGNAME,
          V.BUDGETGROUPCODE2,
          V.SORTBY,
          V.STRATEGYUID,
          V.STRATEGYUCODE,
          V.STRATEGYUNAME,
       V.PLANUID,
       V.PLANUCODE,
       V.PLANUNAME,
          V.TM01,
          V.TM02,
          V.TM03,
          V.TM04,
          V.TM05,
          V.TM06,
          V.TM07,
          V.TM08,
          V.TM09,
          V.TM10,
          V.TM11,
          V.TM12;

-- ----------------------------
-- View structure for VR_BP_BUDGETBGBY_DATE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_BUDGETBGBY_DATE" AS SELECT
     V.BUDGETID AS ID,
     V.BUDGETPERIODID,
     V.FUNDGROUPID,
     V.BUDGETGROUPID,
     V.PLANID,
     V.PRODUCTID,
     V.PROJECTID,
     V.DEPARTMENTID,
     V.ACCOUNTTYPEID,
     V.BUDGETNAME,
     V.DESCRIPTION1,
     V.DESCRIPTION2,
     V.UNITPRICE,
     NVL(V.QUANTITY, 0) QUANTITY,
     V.UNITNAME,
     NVL(V.TOTALBUDGET, 0) TOTALBUDGET,
     NVL(V.CURRENTBUDGET, 0) CURRENTBUDGET,
     NVL(V.PRSUM, 0) PRSUM,
     NVL(V.PREPAYSUM, 0) PREPAYSUM,
     NVL(V.PAYSUM, 0) PAYSUM,
     NVL(T.APAYSUM, 0) APAYSUM,
     V.BUDGETLEVELTYPE,
     V.ACTIVITYID,
     V.BUDGETLEVEL,
     V.BUDGETIDX,
     V.BUDGETCODE,
     V.BUDGETSTUCTYPE,
     --V.PRODUCTSUBID,
     FUNDGROUPNAME,
     PLANNAME,
     PRODUCTNAME,
     PROJECTNAME,
     BUDGETGROUPNAME,
     DEPARTMENTNAME,
     FUNDGROUPCODE,
     PLANCODE,
     PRODUCTCODE,
     PROJECTCODE,
     ACTIVITYCODE,
     --PRODUCTSUBCODE,
     BUDGETGROUPCODE,
     DEPARTMENTCODE,
     --PRODUCTSUBNAME,
     ACTIVITYNAME,
     V.ACCOUNTTYPENAME,
     V.BUDGETTYPE AS BUDGETTYPE,
     V.MASTERID AS MASTERID,
     V.INVESTMENTFLAG AS INVESTMENTFLAG,
     V.SORTBY,
     V.STRATEGYUID,
     V.STRATEGYUCODE,
     V.STRATEGYUNAME,
     DECODE(V.BUDGETGROUPCODE, 11101, 1, 0) B11100, --เงินงบประมาณแผ่นดิน
     DECODE(V.BUDGETGROUPCODE, 21101, 1, 0) B21101, --เงินรายได้ (งบนโยบายต่อเนื่อง)
     DECODE(V.BUDGETGROUPCODE, 21102, 1, 0) B21102, --เงินป.โท
     DECODE(V.BUDGETGROUPCODE, 21306, 1, 0) B21306, --เงินโครงการ Ex.LAW
     DECODE(V.BUDGETGROUPCODE, 21701, 1, 0) B21701, --งบบริหารงานเร่งด่วน (งบกลาง)

    CAST(DECODE(V.BUDGETGROUPCODE, 11101, V.CURRENTBUDGET, 0) AS NUMBER(15,2)) BG_A_CURRENT,
    CAST(DECODE(V.BUDGETGROUPCODE, 11101, V.PRSUM, 0) AS NUMBER(15,2)) BG_A_PRSUM,
    CAST(DECODE(V.BUDGETGROUPCODE, 11101, V.CURRENTBUDGET - V.PRSUM, 0) AS NUMBER(15,2)) BG_A_PRSUM_REMAIN,
    CAST(DECODE(V.BUDGETGROUPCODE, 11101, NVL(T.APAYSUM, 0), 0) AS NUMBER(15,2)) BG_A_PAYSUM,
    CAST(DECODE(V.BUDGETGROUPCODE, 11101, V.CURRENTBUDGET - NVL(T.APAYSUM, 0), 0) AS NUMBER(15,2)) BG_A_PAYSUM_REMAIN,


    CAST(CASE WHEN V.BUDGETGROUPCODE IN (21101,21102,21306,21701) THEN V.CURRENTBUDGET ELSE 0 END AS NUMBER(15,2)) BG_B_CURRENT,
    CAST(CASE WHEN V.BUDGETGROUPCODE IN (21101,21102,21306,21701) THEN V.PRSUM ELSE 0 END AS NUMBER(15,2)) BG_B_PRSUM,
    CAST(CASE WHEN V.BUDGETGROUPCODE IN (21101,21102,21306,21701) THEN V.CURRENTBUDGET - V.PRSUM ELSE 0 END AS NUMBER(15,2)) BG_B_PRSUM_REMAIN,
    CAST(CASE WHEN V.BUDGETGROUPCODE IN (21101,21102,21306,21701) THEN NVL(T.APAYSUM, 0) ELSE 0 END AS NUMBER(15,2)) BG_B_PAYSUM,
    CAST(CASE WHEN V.BUDGETGROUPCODE IN (21101,21102,21306,21701) THEN V.CURRENTBUDGET - NVL(T.APAYSUM, 0) ELSE 0 END AS NUMBER(15,2)) BG_B_PAYSUM_REMAIN


FROM   PROMIS.V_BUD_BUDGETINFO@MISLINK V
LEFT   JOIN   (SELECT SUM(DR - CR) AS APAYSUM, PI.BUDGETID
                FROM   PROMIS.PAYMENT@MISLINK P
                LEFT  JOIN PROMIS.PAYMENTITEM@MISLINK PI ON P.PAYMENTID = PI.PAYMENTID
                WHERE P.PAYMENTSTATUS = 'S' AND
                      P.RECEIVEDATETIME BETWEEN FN_SS_PARAMETER_GETDATE('BUDGETBGBY-DATEFROM') AND
                      FN_SS_PARAMETER_GETDATE('BUDGETBGBY-DATETO')
                GROUP BY  PI.BUDGETID) T ON T.BUDGETID = V.BUDGETID

WHERE
     V.GROUPTYPE = 1 AND
     V.BUDGETLEVELTYPE = 'O' AND
     V.BUDGETPERIODID = FN_SS_PARAMETER_GETNUMBER('BUDGETBGBY-BUDGETPERIODID')

GROUP  BY V.BUDGETID,
      V.BUDGETPERIODID,
      V.FUNDGROUPID,
      V.BUDGETGROUPID,
      V.PLANID,
      V.PRODUCTID,
      V.PROJECTID,
      V.DEPARTMENTID,
      V.ACCOUNTTYPEID,
      V.BUDGETNAME,
      V.DESCRIPTION1,
      V.DESCRIPTION2,
      V.UNITPRICE,
      V.QUANTITY,
      V.UNITNAME,
      V.TOTALBUDGET,
      V.CURRENTBUDGET,
      V.PRSUM,
      V.PREPAYSUM,
      V.PAYSUM,
      V.BUDGETLEVELTYPE,
      V.ACTIVITYID,
      V.BUDGETLEVEL,
      V.BUDGETIDX,
      V.BUDGETCODE,
      V.BUDGETSTUCTYPE,
      --V.PRODUCTSUBID,
      FUNDGROUPNAME,
      PLANNAME,
      PRODUCTNAME,
      PROJECTNAME,
      BUDGETGROUPNAME,
      DEPARTMENTNAME,
      FUNDGROUPCODE,
      PLANCODE,
      PRODUCTCODE,
      PROJECTCODE,
      ACTIVITYCODE,
      --PRODUCTSUBCODE,
      BUDGETGROUPCODE,
      DEPARTMENTCODE,
      --PRODUCTSUBNAME,
      ACTIVITYNAME,
      V.ACCOUNTTYPENAME,
      V.BUDGETTYPE,
      V.MASTERID,
      V.INVESTMENTFLAG,
      V.BUDGETGROUPCODE2,T.APAYSUM,
      V.SORTBY,
      V.STRATEGYUID,
      V.STRATEGYUCODE,
      V.STRATEGYUNAME
--WITH READ ONLY;

-- ----------------------------
-- View structure for VR_BP_PERIODAPP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_PERIODAPP" AS SELECT A.ID,
	   A.MT_DEPARTMENT_ID,
	   A.BUDGETYEAR,
	   A.PROJECTNO,
	   B.PROJECTCODE,
	   B.PROJECTNAME,
	   AF.BUDGETGROUPCODE,
	   AF.BUDGETGROUPNAME,
	   AF.BUDGETGROUPNAMEENG,
	   A.BUDGETTOTAL,
	   'IQA.' AS  INDICATORNAME,
	   D.PLANCODE,
	   D.PLANNAME,
	   D.PLANNAMEENG,
	   F.PRODUCTCODE,
	   F.PRODUCTNAME,
	   US.USTRATEGYNAME,
	   UP.UPLANNAME,
	   H.PROJECTTYPECODE,
	   H.PROJECTTYPENAME,
	   I.DEPARTMENTCODE,
	   I.DEPARTMENTNAME,

	   PF.UFOCUSNAME,
	   PD.UDEVELOPNAME,
	   PG.UGOALNAME,
	   M.UMISSIONCODE,
	   M.UMISSIONNAME,
	   O.UOBJECTIVECODE,
	   O.UOBJECTIVENAME,
	   Q.UKPICODE,
	   Q.UKPINAME,

	   CASE
		   WHEN A.BUDGETYEAR < 9999 THEN
			Z.INDICATORNAME
		   ELSE
			AH.INDICATORNAME
	   END AS INDICATORPNAME,
	   CASE
		   WHEN A.BUDGETYEAR < 9999 THEN
			AA.INDICATORNAME
		   ELSE
			AI.INDICATORNAME
	   END AS INDICATORDNAME,
	   CASE
		   WHEN A.BUDGETYEAR < 9999 THEN
			AB.INDICATORNAME
		   ELSE
			AJ.INDICATORNAME
	   END AS INDICATORUNAME,

	   Z.INDICATORCODE AS INDICATORMUAPCODE,
	   Z.INDICATORNAME AS INDICATORMUAPNAME,
	   AA.INDICATORCODE AS INDICATORMUADCODE,
	   AA.INDICATORNAME AS INDICATORMUADNAME,
	   AB.INDICATORCODE AS INDICATORMUAUCODE,
	   AB.INDICATORNAME AS INDICATORMUAUNAME,

	   AC.INDICATORCODE AS INDICATORONESQAPCODE,
	   AC.INDICATORNAME AS INDICATORONESQAPNAME,
	   AD.INDICATORCODE AS INDICATORONESQADCODE,
	   AD.INDICATORNAME AS INDICATORONESQADNAME,
	   AE.INDICATORCODE AS INDICATORONESQAUCODE,
	   AE.INDICATORNAME AS INDICATORONESQAUNAME,

	   AH.INDICATORCODE AS INDICATOROICPCODE,
	   AH.INDICATORNAME AS INDICATOROICPNAME,
	   AI.INDICATORCODE AS INDICATOROICDCODE,
	   AI.INDICATORNAME AS INDICATOROICDNAME,
	   AJ.INDICATORCODE AS INDICATOROICUCODE,
	   AJ.INDICATORNAME AS INDICATOROICUNAME,

	   A.REASON,
	   A.OBJECTIVE,

	   CASE
		   WHEN A.STATUS_ID = 60 THEN
			'(อนุมัติ)'
		   ELSE
			''
	   END AS STAMP
FROM BP_PERIODAPP A,
	 VW_BG_PLANPRDPRJ B,
	 VW_BG_PLAN D,
	 VW_BG_PLANPRD F,
	 BP_PERIODPROJECTTYPE H1,
	 BP_PROJECTTYPE H,
	 VW_MT_DEPARTMENT I,

	 BP_PERIODUMISSION L,
	 BP_UMISSION M,
	 BP_PERIODUOBJECTIVE N,
	 BP_UOBJECTIVE O,
	 BP_PERIODUKPI P,
	 BP_UKPI Q,

	 BP_LOTINDICATORITEM Z,
	 BP_LOTINDICATORITEM AA,
	 BP_LOTINDICATORITEM AB,

	 BP_LOTINDICATORITEM AC,
	 BP_LOTINDICATORITEM AD,
	 BP_LOTINDICATORITEM AE,

	 BP_LOTINDICATORITEM AH,
	 BP_LOTINDICATORITEM AI,
	 BP_LOTINDICATORITEM AJ,

	 VW_BG_BUDGETGROUP AF,

	 VW_BG_USTRATEGY US,
	 VW_BG_UPLAN UP,
	 VW_BP_PERIODUFOCUS PF,
	 VW_BP_PERIODUDEVELOP PD,
	 VW_BP_PERIODUGOAL PG
WHERE A.BG_PLANPRDPRJ_ID = B.ID
	  AND A.BG_PLAN_ID = D.ID
	  AND A.BG_PLANPRD_ID = F.ID
	  AND A.BP_PERIODPROJECTTYPE_ID = H1.ID
	  AND H1.BP_PROJECTTYPE_ID = H.ID
	  AND A.MT_DEPARTMENT_ID = I.ID

	  AND A.BP_PERIODUMISSION_ID = L.ID
	  AND L.BP_UMISSION_ID = M.ID
	  AND A.BP_PERIODUOBJECTIVE_ID = N.ID(+)
	  AND N.BP_UOBJECTIVE_ID = O.ID(+)
	  AND A.BP_PERIODUKPI_ID = P.ID(+)
	  AND P.BP_UKPI_ID = Q.ID(+)

	  AND A.BP_LOTINDICATORITEMMUAP_ID = Z.ID(+)
	  AND A.BP_LOTINDICATORITEMMUAD_ID = AA.ID(+)
	  AND A.BP_LOTINDICATORITEMMUAU_ID = AB.ID(+)

	  AND A.BP_LOTINDICATORITEMONESQAP_ID = AC.ID(+)
	  AND A.BP_LOTINDICATORITEMONESQAD_ID = AD.ID(+)
	  AND A.BP_LOTINDICATORITEMONESQAU_ID = AE.ID(+)

	  AND A.BP_LOTINDICATORITEMOICP_ID = AH.ID(+)
	  AND A.BP_LOTINDICATORITEMOICD_ID = AI.ID(+)
	  AND A.BP_LOTINDICATORITEMOICU_ID = AJ.ID(+)

	  AND A.BG_BUDGETGROUP_ID = AF.ID

	  AND A.BG_USTRATEGY_ID = US.ID
	  AND A.BG_UPLAN_ID = UP.ID
	  AND A.BP_PERIODUFOCUS_ID = PF.ID(+)
	  AND A.BP_PERIODUDEVELOP_ID = PD.ID(+)
	  AND A.BP_PERIODUGOAL_ID = PG.ID(+);

-- ----------------------------
-- View structure for VR_BP_PERIODAPPACTBUDMONTH
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_PERIODAPPACTBUDMONTH" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	   A.BP_PERIODAPP_ID,
	   A.ACTIVITYORDER,
	   A.ACTIVITYNAME,
	   C.TOTAL AS ACTIVITYTOTAL,
	   A.INVESTMENTTYPEORDER,
	   A.INVESTMENTTYPECODE,
	   A.INVESTMENTTYPENAME,
	   A.INVESTMENTTYPENAMEENG,
	   A.MONTH01 AS INVESTMENTTYPE01,
	   A.MONTH02 AS INVESTMENTTYPE02,
	   A.MONTH03 AS INVESTMENTTYPE03,
	   A.MONTH04 AS INVESTMENTTYPE04,
	   A.MONTH05 AS INVESTMENTTYPE05,
	   A.MONTH06 AS INVESTMENTTYPE06,
	   A.MONTH07 AS INVESTMENTTYPE07,
	   A.MONTH08 AS INVESTMENTTYPE08,
	   A.MONTH09 AS INVESTMENTTYPE09,
	   A.MONTH10 AS INVESTMENTTYPE10,
	   A.MONTH11 AS INVESTMENTTYPE11,
	   A.MONTH12 AS INVESTMENTTYPE12,
	   A.TOTAL AS INVESTMENTTYPETOTAL,
	   B.ACCOUNTTYPECODE,
	   B.ACCOUNTTYPENAME,
	   B.ACCOUNTTYPENAMEENG,
	   B.MONTH01,
	   B.MONTH02,
	   B.MONTH03,
	   B.MONTH04,
	   B.MONTH05,
	   B.MONTH06,
	   B.MONTH07,
	   B.MONTH08,
	   B.MONTH09,
	   B.MONTH10,
	   B.MONTH11,
	   B.MONTH12,
	   B.TOTAL
FROM (SELECT A.BP_PERIODAPP_ID,
			 A.BP_PERIODAPPACT_ID,
			 A.ACTIVITYORDER,
			 A.ACTIVITYNAME,
			 A.INVESTMENTTYPEORDER,
			 A.INVESTMENTTYPECODE,
			 A.INVESTMENTTYPENAME,
			 A.INVESTMENTTYPENAMEENG,
			 SUM(A.MONTH01) AS MONTH01,
			 SUM(A.MONTH02) AS MONTH02,
			 SUM(A.MONTH03) AS MONTH03,
			 SUM(A.MONTH04) AS MONTH04,
			 SUM(A.MONTH05) AS MONTH05,
			 SUM(A.MONTH06) AS MONTH06,
			 SUM(A.MONTH07) AS MONTH07,
			 SUM(A.MONTH08) AS MONTH08,
			 SUM(A.MONTH09) AS MONTH09,
			 SUM(A.MONTH10) AS MONTH10,
			 SUM(A.MONTH11) AS MONTH11,
			 SUM(A.MONTH12) AS MONTH12,
			 SUM(A.TOTAL) AS TOTAL
	  FROM VW_BP_PERIODAPPACTEXP A
	  GROUP BY A.BP_PERIODAPP_ID,
			   A.BP_PERIODAPPACT_ID,
			   A.ACTIVITYORDER,
			   A.ACTIVITYNAME,
			   A.INVESTMENTTYPEORDER,
			   A.INVESTMENTTYPECODE,
			   A.INVESTMENTTYPENAME,
			   A.INVESTMENTTYPENAMEENG) A,
	 (SELECT A.BP_PERIODAPP_ID,
			 A.BP_PERIODAPPACT_ID,
			 A.ACTIVITYORDER,
			 A.ACTIVITYNAME,
			 A.INVESTMENTTYPECODE,
			 A.ACCOUNTTYPECODE,
			 A.ACCOUNTTYPENAME,
			 A.ACCOUNTTYPENAMEENG,
			 SUM(A.MONTH01) AS MONTH01,
			 SUM(A.MONTH02) AS MONTH02,
			 SUM(A.MONTH03) AS MONTH03,
			 SUM(A.MONTH04) AS MONTH04,
			 SUM(A.MONTH05) AS MONTH05,
			 SUM(A.MONTH06) AS MONTH06,
			 SUM(A.MONTH07) AS MONTH07,
			 SUM(A.MONTH08) AS MONTH08,
			 SUM(A.MONTH09) AS MONTH09,
			 SUM(A.MONTH10) AS MONTH10,
			 SUM(A.MONTH11) AS MONTH11,
			 SUM(A.MONTH12) AS MONTH12,
			 SUM(A.TOTAL) AS TOTAL
	  FROM VW_BP_PERIODAPPACTEXP A
	  GROUP BY A.BP_PERIODAPP_ID,
			   A.BP_PERIODAPPACT_ID,
			   A.ACTIVITYORDER,
			   A.ACTIVITYNAME,
			   A.INVESTMENTTYPECODE,
			   A.ACCOUNTTYPECODE,
			   A.ACCOUNTTYPENAME,
			   A.ACCOUNTTYPENAMEENG) B,
	 (SELECT A.BP_PERIODAPP_ID,
			 A.BP_PERIODAPPACT_ID,
			 A.ACTIVITYORDER,
			 A.ACTIVITYNAME,
			 SUM(A.MONTH01) AS MONTH01,
			 SUM(A.MONTH02) AS MONTH02,
			 SUM(A.MONTH03) AS MONTH03,
			 SUM(A.MONTH04) AS MONTH04,
			 SUM(A.MONTH05) AS MONTH05,
			 SUM(A.MONTH06) AS MONTH06,
			 SUM(A.MONTH07) AS MONTH07,
			 SUM(A.MONTH08) AS MONTH08,
			 SUM(A.MONTH09) AS MONTH09,
			 SUM(A.MONTH10) AS MONTH10,
			 SUM(A.MONTH11) AS MONTH11,
			 SUM(A.MONTH12) AS MONTH12,
			 SUM(A.TOTAL) AS TOTAL
	  FROM VW_BP_PERIODAPPACTEXP A
	  GROUP BY A.BP_PERIODAPP_ID,
			   A.BP_PERIODAPPACT_ID,
			   A.ACTIVITYORDER,
			   A.ACTIVITYNAME) C
WHERE A.BP_PERIODAPPACT_ID = B.BP_PERIODAPPACT_ID
	  AND A.INVESTMENTTYPECODE = B.INVESTMENTTYPECODE
	  AND A.BP_PERIODAPPACT_ID = C.BP_PERIODAPPACT_ID;

-- ----------------------------
-- View structure for VR_BP_PERIODAPPACTEXP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_PERIODAPPACTEXP" AS SELECT A.ID,
	   A.BP_PERIODAPPACT_ID,
	   A.BG_ACCOUNTTYPE_ID,
	   B.BP_PERIODAPP_ID,
	   A.MONTH01,
	   A.MONTH02,
	   A.MONTH03,
	   A.MONTH01 +  A.MONTH02 + A.MONTH03 AS QUARTER1,
	   A.MONTH04,
	   A.MONTH05,
	   A.MONTH06,
	   A.MONTH04 +  A.MONTH05 + A.MONTH06 AS QUARTER2,
	   A.MONTH07,
	   A.MONTH08,
	   A.MONTH09,
	   A.MONTH07 +  A.MONTH08 + A.MONTH09 AS QUARTER3,
	   A.MONTH10,
	   A.MONTH11,
	   A.MONTH12,
	   A.MONTH10 +  A.MONTH11 + A.MONTH12 AS QUARTER4,
	   A.TOTAL,
	B.BG_ACTIVITY_ID,
	   B.ACTIVITYCODE,
	   B.ACTIVITYNAME,
	   B.ORDERNO AS ACTIVITYORDER,
	   E.ACCOUNTTYPECODE,
	   E.ACCOUNTTYPENAME,
	   E.ACCOUNTTYPENAMEENG,
	   E.INVESTMENTTYPEORDER,
	   E.INVESTMENTTYPECODE,
	   E.INVESTMENTTYPENAME,
	   E.INVESTMENTTYPENAMEENG
FROM BP_PERIODAPPACTEXP A,
	 VW_BP_PERIODAPPACT B,
	 VW_BG_ACCOUNTTYPE E
WHERE A.BP_PERIODAPPACT_ID = B.ID
	  AND A.BG_ACCOUNTTYPE_ID = E.ID;

-- ----------------------------
-- View structure for VR_BP_PERIODAPPACTEXPITEM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_PERIODAPPACTEXPITEM" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	B.BP_PERIODAPP_ID,
  B.ORDERNO AS ACTIVITYORDER,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG,
	CAST(A.TOTAL AS NUMBER(15,2)) AS ACTIVITYTOTAL,
  B.PERSON,
  C.INVESTMENTTYPEORDER,
  C.INVESTMENTTYPECODE,
  C.INVESTMENTTYPENAME,
  C.INVESTMENTTYPENAMEENG,
  C.TOTAL AS INVESTMENTTYPETOTAL,
  F.ACCOUNTTYPECODE,
  F.ACCOUNTTYPENAME,
  F.ACCOUNTTYPENAMEENG,
  F.TOTAL AS TYPETOTAL,
  D.ORDERNO AS EXPORDERNO,
  D.EXPENSE AS EXPEXPENSE,
  D.TOTAL AS EXPTOTAL,
  CASE WHEN D.REFCODE IS NOT NULL THEN '(รหัสงบประมาณ : ' || D.REFCODE || ')' END AS REFCODE,
  E.ORDERNO,
  E.EXPENSE,
  E.TOTAL,
  E.REMARK
FROM BP_PERIODAPPACTBUDQTR A,
	VW_BP_PERIODAPPACT B,
  (
    SELECT A.BP_PERIODAPPACT_ID,
      A.INVESTMENTTYPEORDER,
      A.INVESTMENTTYPECODE,
      A.INVESTMENTTYPENAME,
      A.INVESTMENTTYPENAMEENG,
      SUM(A.TOTAL) AS TOTAL
    FROM VW_BP_PERIODAPPACTEXP A
    GROUP BY A.BP_PERIODAPPACT_ID,
      A.INVESTMENTTYPEORDER,
      A.INVESTMENTTYPECODE,
      A.INVESTMENTTYPENAME,
      A.INVESTMENTTYPENAMEENG
	) C,
  VW_BP_PERIODAPPACTEXP D,
  BP_PERIODAPPACTEXPITEM E,
  (
    SELECT A.BP_PERIODAPPACT_ID,
    	A.BG_ACCOUNTTYPE_ID,
      A.ACCOUNTTYPECODE,
      A.ACCOUNTTYPENAME,
      A.ACCOUNTTYPENAMEENG,
      SUM(A.TOTAL) AS TOTAL
    FROM VW_BP_PERIODAPPACTEXP A
    GROUP BY A.BP_PERIODAPPACT_ID,
    	A.BG_ACCOUNTTYPE_ID,
      A.ACCOUNTTYPECODE,
      A.ACCOUNTTYPENAME,
      A.ACCOUNTTYPENAMEENG
	) F
WHERE A.BP_PERIODAPPACT_ID=B.ID
	AND B.ID=C.BP_PERIODAPPACT_ID(+)
  AND C.BP_PERIODAPPACT_ID=D.BP_PERIODAPPACT_ID(+)
  AND C.INVESTMENTTYPECODE=D.INVESTMENTTYPECODE(+)
  AND D.ID=E.BP_PERIODAPPACTEXP_ID(+)
  AND D.BP_PERIODAPPACT_ID=F.BP_PERIODAPPACT_ID(+)
  AND D.BG_ACCOUNTTYPE_ID=F.BG_ACCOUNTTYPE_ID(+);

-- ----------------------------
-- View structure for VR_BP_PERIODAPPBUDGETBYDEPT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_PERIODAPPBUDGETBYDEPT" AS SELECT A.ID,
	   A.BUDGETYEAR,
	   A.PROJECTNO,
	   A.MT_DEPARTMENT_ID,
	   B.BUDGETTYPE_ID,
	   B.BUDGETGROUPCODE,
	   A.BUDGETTOTAL,
	   C.BP_PROJECTTYPE_ID,
	   C.PROJECTTYPECODE,
	   A.BG_BUDGETGROUP_ID,
	   A.BG_PLAN_ID,
	   A.BG_PLANPRD_ID,
	   A.BG_PLANPRDPRJ_ID,
	   --A.BP_PERIODUSTRATEGY_ID,
	   A.BP_PERIODUMISSION_ID,
	   A.BP_PERIODUOBJECTIVE_ID,
	   A.BP_PERIODUKPI_ID,
	   A.BP_LOTINDICATORITEMMUAP_ID,
	   A.BP_LOTINDICATORITEMMUAD_ID,
	   A.BP_LOTINDICATORITEMMUAU_ID,
	   A.BP_LOTINDICATORITEMONESQAP_ID,
	   A.BP_LOTINDICATORITEMONESQAD_ID,
	   A.BP_LOTINDICATORITEMONESQAU_ID,
	   A.BG_USTRATEGY_ID,
	   A.BG_UPLAN_ID,
	   A.STATUS_ID
FROM BP_PERIODAPP A,
	 VW_BP_BUDGETGROUP B,
	 VW_BP_PERIODPROJECTTYPE C
WHERE A.BG_BUDGETGROUP_ID = B.ID
	  AND A.BP_PERIODPROJECTTYPE_ID = C.ID;

-- ----------------------------
-- View structure for VR_BP_PERIODAPPEXP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_PERIODAPPEXP" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.BP_PERIODAPP_ID,
  A.INVESTMENTTYPEORDER,
  A.INVESTMENTTYPECODE,
  A.INVESTMENTTYPENAME,
  A.INVESTMENTTYPENAMEENG,
  A.TOTAL AS INVESTMENTTYPETOTAL,
  B.ACCOUNTTYPECODE,
  B.ACCOUNTTYPENAME,
  B.ACCOUNTTYPENAMEENG,
  CAST(B.TOTAL AS NUMBER(15,2)) AS TOTAL
FROM
  (
    SELECT A.BP_PERIODAPP_ID,
      A.INVESTMENTTYPEORDER,
      A.INVESTMENTTYPECODE,
      A.INVESTMENTTYPENAME,
      A.INVESTMENTTYPENAMEENG,
      SUM(A.TOTAL) AS TOTAL
    FROM VW_BP_PERIODAPPACTEXP A
    GROUP BY A.BP_PERIODAPP_ID,
      A.INVESTMENTTYPEORDER,
      A.INVESTMENTTYPECODE,
      A.INVESTMENTTYPENAME,
      A.INVESTMENTTYPENAMEENG
  ) A,
  (
    SELECT A.BP_PERIODAPP_ID,
      A.INVESTMENTTYPECODE,
      A.ACCOUNTTYPECODE,
      A.ACCOUNTTYPENAME,
  		A.ACCOUNTTYPENAMEENG,
      SUM(A.TOTAL) AS TOTAL
    FROM VW_BP_PERIODAPPACTEXP A
    GROUP BY A.BP_PERIODAPP_ID,
      A.INVESTMENTTYPECODE,
      A.ACCOUNTTYPECODE,
      A.ACCOUNTTYPENAME,
  		A.ACCOUNTTYPENAMEENG
  )  B
WHERE A.BP_PERIODAPP_ID=B.BP_PERIODAPP_ID
	AND A.INVESTMENTTYPECODE=B.INVESTMENTTYPECODE;

-- ----------------------------
-- View structure for VR_BP_PERIODAPP_INFO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_PERIODAPP_INFO" AS SELECT A.BUDGETYEAR,
	   AF.ID AS BG_BUDGETGROUP_ID,
	   A.MT_DEPARTMENT_ID,
	   A.STATUS_ID,

	   AF.BUDGETGROUPCODE,
	   AF.BUDGETGROUPNAME,
	   I.DEPARTMENTCODE,
	   I.DEPARTMENTNAME,

	   --แผนงาน
	   D.ID AS BG_PLAN_ID,
	   D.PLANCODE,
	   D.PLANNAME,
	   --ยุทธศาสตร์มหาวิทยาลัย
	   US.USTRATEGYCODE,
	   US.USTRATEGYNAME,

	   --ผลผลิต
	   F.ID AS BG_PRODUCT_ID,
	   F.PRODUCTCODE,
	   F.PRODUCTNAME,

	   --โครงการหลัก
	   UP.UPLANCODE,
	   UP.UPLANNAME,

	   --โครงการ
	   B.ID AS BG_PROJECT_ID,
	   A.PROJECTNO,
	   B.PROJECTCODE,
	   B.PROJECTNAME || ' (' || B.PROJECTCODE || ')' AS PROJECTNAME,

	   --กิจกรรม
	   ACE.BG_ACTIVITY_ID,
	   ACE.ACTIVITYORDER,
	   ACE.ACTIVITYCODE,
	   ACE.ACTIVITYNAME,

	   ACE.INVESTMENTTYPEORDER,
	   ACE.INVESTMENTTYPECODE,
	   ACE.INVESTMENTTYPENAME,

	   ACE.ACCOUNTTYPECODE,
	   ACE.ACCOUNTTYPENAME,

	   ACE.TM01,
	   ACE.TM02,
	   ACE.TM03,
	   ACE.QUARTER1,
	   ACE.TM04,
	   ACE.TM05,
	   ACE.TM06,
	   ACE.QUARTER2,
	   ACE.TM07,
	   ACE.TM08,
	   ACE.TM09,
	   ACE.QUARTER3,
	   ACE.TM10,
	   ACE.TM11,
	   ACE.TM12,
	   ACE.QUARTER4,
	   ACE.TOTAL

FROM BP_PERIODAPP A,
	 VW_BG_BUDGETGROUP AF,
	 VW_BG_PLAN D,
	 VW_BG_PLANPRD F,
	 VW_BG_PLANPRDPRJ B,

	 VW_BG_USTRATEGY US,
	 VW_BG_UPLAN UP,
	 VW_MT_DEPARTMENT I,
	 (

	  SELECT EA.BP_PERIODAPP_ID,
			  1 AS GROUPNO,
			  NULL AS BG_ACTIVITY_ID,
			  NULL AS ACTIVITYORDER,
			  '-' AS ACTIVITYCODE,
			  '(รวม)' AS ACTIVITYNAME,

			  EA.INVESTMENTTYPEORDER,
			  EA.INVESTMENTTYPECODE,
			  EA.INVESTMENTTYPENAME,

			  EA.ACCOUNTTYPECODE,
			  EA.ACCOUNTTYPENAME,

			  SUM(EA.MONTH01) AS TM01,
			  SUM(EA.MONTH02) AS TM02,
			  SUM(EA.MONTH03) AS TM03,
			  SUM(EA.QUARTER1) AS QUARTER1,
			  SUM(EA.MONTH04) AS TM04,
			  SUM(EA.MONTH05) AS TM05,
			  SUM(EA.MONTH06) AS TM06,
			  SUM(EA.QUARTER2) AS QUARTER2,
			  SUM(EA.MONTH07) AS TM07,
			  SUM(EA.MONTH08) AS TM08,
			  SUM(EA.MONTH09) AS TM09,
			  SUM(EA.QUARTER3) AS QUARTER3,
			  SUM(EA.MONTH10) AS TM10,
			  SUM(EA.MONTH11) AS TM11,
			  SUM(EA.MONTH12) AS TM12,
			  SUM(EA.QUARTER4) AS QUARTER4,
			  SUM(EA.TOTAL) AS TOTAL
	  FROM VR_BP_PERIODAPPACTEXP EA
	  WHERE EA.BG_ACTIVITY_ID = FN_SS_PARAMETER_GETNUMBER('VR_BP_PERIODAPP_INFO_ACTIVITY', 0)
			OR FN_SS_PARAMETER_GETNUMBER('VR_BP_PERIODAPP_INFO_ACTIVITY') IS NULL
	  GROUP BY EA.BP_PERIODAPP_ID,

				EA.INVESTMENTTYPEORDER,
				EA.INVESTMENTTYPECODE,
				EA.INVESTMENTTYPENAME,

				EA.ACCOUNTTYPECODE,
				EA.ACCOUNTTYPENAME
	  UNION
	  SELECT EB.BP_PERIODAPP_ID,
			  2 AS GROUPNO,
			  EB.BG_ACTIVITY_ID,
			  EB.ACTIVITYORDER,
			  EB.ACTIVITYCODE,
			  EB.ACTIVITYNAME || ' (' || EB.ACTIVITYCODE || ')' AS ACTIVITYNAME,

			  EB.INVESTMENTTYPEORDER,
			  EB.INVESTMENTTYPECODE,
			  EB.INVESTMENTTYPENAME,

			  EB.ACCOUNTTYPECODE,
			  EB.ACCOUNTTYPENAME,

			  SUM(EB.MONTH01) AS TM01,
			  SUM(EB.MONTH02) AS TM02,
			  SUM(EB.MONTH03) AS TM03,
			  SUM(EB.QUARTER1) AS QUARTER1,
			  SUM(EB.MONTH04) AS TM04,
			  SUM(EB.MONTH05) AS TM05,
			  SUM(EB.MONTH06) AS TM06,
			  SUM(EB.QUARTER2) AS QUARTER2,
			  SUM(EB.MONTH07) AS TM07,
			  SUM(EB.MONTH08) AS TM08,
			  SUM(EB.MONTH09) AS TM09,
			  SUM(EB.QUARTER3) AS QUARTER3,
			  SUM(EB.MONTH10) AS TM10,
			  SUM(EB.MONTH11) AS TM11,
			  SUM(EB.MONTH12) AS TM12,
			  SUM(EB.QUARTER4) AS QUARTER4,
			  SUM(EB.TOTAL) AS TOTAL
	  FROM VR_BP_PERIODAPPACTEXP EB
	  WHERE EB.BG_ACTIVITY_ID = FN_SS_PARAMETER_GETNUMBER('VR_BP_PERIODAPP_INFO_ACTIVITY', 0)
			OR FN_SS_PARAMETER_GETNUMBER('VR_BP_PERIODAPP_INFO_ACTIVITY') IS NULL
	  GROUP BY EB.BP_PERIODAPP_ID,
				EB.BG_ACTIVITY_ID,
				EB.ACTIVITYORDER,
				EB.ACTIVITYCODE,
				EB.ACTIVITYNAME,

				EB.INVESTMENTTYPEORDER,
				EB.INVESTMENTTYPECODE,
				EB.INVESTMENTTYPENAME,

				EB.ACCOUNTTYPECODE,
				EB.ACCOUNTTYPENAME) ACE
WHERE A.BG_BUDGETGROUP_ID = AF.ID
	  AND A.BG_PLAN_ID = D.ID
	  AND A.BG_PLANPRD_ID = F.ID
	  AND A.BG_PLANPRDPRJ_ID = B.ID
	  AND A.BG_USTRATEGY_ID = US.ID
	  AND A.BG_UPLAN_ID = UP.ID
	  AND A.MT_DEPARTMENT_ID = I.ID
	  AND A.ID = ACE.BP_PERIODAPP_ID;

-- ----------------------------
-- View structure for VR_BP_PERIODAPP_INFO_TMP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_BP_PERIODAPP_INFO_TMP" AS SELECT A.BUDGETYEAR,
     AF.ID AS BG_BUDGETGROUP_ID,
     A.MT_DEPARTMENT_ID,
     A.STATUS_ID,

     AF.BUDGETGROUPCODE,
     AF.BUDGETGROUPNAME,
     I.DEPARTMENTCODE,
     I.DEPARTMENTNAME,

     --แผนงาน
     D.ID AS BG_PLAN_ID,
     D.PLANCODE,
     D.PLANNAME,
     --ยุทธศาสตร์มหาวิทยาลัย
     US.USTRATEGYCODE,
     US.USTRATEGYNAME,

     --ผลผลิต
     F.ID AS BG_PRODUCT_ID,
     F.PRODUCTCODE,
     F.PRODUCTNAME,

     --โครงการหลัก
     UP.UPLANCODE,
     UP.UPLANNAME,

     --โครงการ
     B.ID AS BG_PROJECT_ID,
     A.PROJECTNO,
     B.PROJECTCODE,
     B.PROJECTNAME || ' (' || B.PROJECTCODE || ')' AS PROJECTNAME,

     --กิจกรรม
     ACE.BG_ACTIVITY_ID,
     ACE.ACTIVITYORDER,
     ACE.ACTIVITYCODE,
     ACE.ACTIVITYNAME,

     ACE.INVESTMENTTYPEORDER,
     ACE.INVESTMENTTYPECODE,
     ACE.INVESTMENTTYPENAME,

     ACE.ACCOUNTTYPECODE,
     ACE.ACCOUNTTYPENAME,

     ACE.TM01,
     ACE.TM02,
     ACE.TM03,
     ACE.QUARTER1,
     ACE.TM04,
     ACE.TM05,
     ACE.TM06,
     ACE.QUARTER2,
     ACE.TM07,
     ACE.TM08,
     ACE.TM09,
     ACE.QUARTER3,
     ACE.TM10,
     ACE.TM11,
     ACE.TM12,
     ACE.QUARTER4,
     ACE.TOTAL

FROM BP_PERIODAPP A,
   VW_BG_BUDGETGROUP AF,
   VW_BG_PLAN D,
   VW_BG_PLANPRD F,
   VW_BG_PLANPRDPRJ B,

   VW_BG_USTRATEGY US,
   VW_BG_UPLAN UP,
   VW_MT_DEPARTMENT I,
   (

    SELECT EA.BP_PERIODAPP_ID,
        1 AS GROUPNO,
        NULL AS BG_ACTIVITY_ID,
        NULL AS ACTIVITYORDER,
        '-' AS ACTIVITYCODE,
        '(รวม)' AS ACTIVITYNAME,

        EA.INVESTMENTTYPEORDER,
        EA.INVESTMENTTYPECODE,
        EA.INVESTMENTTYPENAME,

        EA.ACCOUNTTYPECODE,
        EA.ACCOUNTTYPENAME,

        SUM(EA.MONTH01) AS TM01,
        SUM(EA.MONTH02) AS TM02,
        SUM(EA.MONTH03) AS TM03,
        SUM(EA.QUARTER1) AS QUARTER1,
        SUM(EA.MONTH04) AS TM04,
        SUM(EA.MONTH05) AS TM05,
        SUM(EA.MONTH06) AS TM06,
        SUM(EA.QUARTER2) AS QUARTER2,
        SUM(EA.MONTH07) AS TM07,
        SUM(EA.MONTH08) AS TM08,
        SUM(EA.MONTH09) AS TM09,
        SUM(EA.QUARTER3) AS QUARTER3,
        SUM(EA.MONTH10) AS TM10,
        SUM(EA.MONTH11) AS TM11,
        SUM(EA.MONTH12) AS TM12,
        SUM(EA.QUARTER4) AS QUARTER4,
        SUM(EA.TOTAL) AS TOTAL
    FROM VR_BP_PERIODAPPACTEXP EA
    WHERE EA.BG_ACTIVITY_ID = FN_SS_PARAMETER_GETNUMBER('VR_BP_PERIODAPP_INFO_ACTIVITY', 0)
      OR FN_SS_PARAMETER_GETNUMBER('VR_BP_PERIODAPP_INFO_ACTIVITY') IS NULL
    GROUP BY EA.BP_PERIODAPP_ID,

        EA.INVESTMENTTYPEORDER,
        EA.INVESTMENTTYPECODE,
        EA.INVESTMENTTYPENAME,

        EA.ACCOUNTTYPECODE,
        EA.ACCOUNTTYPENAME
    UNION
    SELECT EB.BP_PERIODAPP_ID,
        2 AS GROUPNO,
        EB.BG_ACTIVITY_ID,
        EB.ACTIVITYORDER,
        EB.ACTIVITYCODE,
        EB.ACTIVITYNAME || ' (' || EB.ACTIVITYCODE || ')' AS ACTIVITYNAME,

        EB.INVESTMENTTYPEORDER,
        EB.INVESTMENTTYPECODE,
        EB.INVESTMENTTYPENAME,

        EB.ACCOUNTTYPECODE,
        EB.ACCOUNTTYPENAME,

        SUM(EB.MONTH01) AS TM01,
        SUM(EB.MONTH02) AS TM02,
        SUM(EB.MONTH03) AS TM03,
        SUM(EB.QUARTER1) AS QUARTER1,
        SUM(EB.MONTH04) AS TM04,
        SUM(EB.MONTH05) AS TM05,
        SUM(EB.MONTH06) AS TM06,
        SUM(EB.QUARTER2) AS QUARTER2,
        SUM(EB.MONTH07) AS TM07,
        SUM(EB.MONTH08) AS TM08,
        SUM(EB.MONTH09) AS TM09,
        SUM(EB.QUARTER3) AS QUARTER3,
        SUM(EB.MONTH10) AS TM10,
        SUM(EB.MONTH11) AS TM11,
        SUM(EB.MONTH12) AS TM12,
        SUM(EB.QUARTER4) AS QUARTER4,
        SUM(EB.TOTAL) AS TOTAL
    FROM VR_BP_PERIODAPPACTEXP EB
    WHERE EB.BG_ACTIVITY_ID = FN_SS_PARAMETER_GETNUMBER('VR_BP_PERIODAPP_INFO_ACTIVITY', 0)
      OR FN_SS_PARAMETER_GETNUMBER('VR_BP_PERIODAPP_INFO_ACTIVITY') IS NULL
    GROUP BY EB.BP_PERIODAPP_ID,
        EB.BG_ACTIVITY_ID,
        EB.ACTIVITYORDER,
        EB.ACTIVITYCODE,
        EB.ACTIVITYNAME,

        EB.INVESTMENTTYPEORDER,
        EB.INVESTMENTTYPECODE,
        EB.INVESTMENTTYPENAME,

        EB.ACCOUNTTYPECODE,
        EB.ACCOUNTTYPENAME) ACE
WHERE A.BG_BUDGETGROUP_ID = AF.ID
    AND A.BG_PLAN_ID = D.ID
    AND A.BG_PLANPRD_ID = F.ID
    AND A.BG_PLANPRDPRJ_ID = B.ID
    AND A.BG_USTRATEGY_ID = US.ID
    AND A.BG_UPLAN_ID = UP.ID
    AND A.MT_DEPARTMENT_ID = I.ID
    AND A.ID = ACE.BP_PERIODAPP_ID;

-- ----------------------------
-- View structure for VR_HR_EVAPP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP" AS SELECT cast(rownum as number(12)) as ID,
	A.ID AS HR_EVAPP_ID,
	B.SNAMEFULL,
	C.POSITIONNAME,
	D.DEPARTMENTNAME,
	ST.STAFFTYPENAME,
	L.ROUNDNO,
	L.DATEFROM,
	L.DATETO,
	H.SNAMEFULL AS HEADERNAME,
	HP.POSITIONNAME AS HEADERPOSITIONNAME,

	LPG.ORDERNO AS WORKGROUPORDERNO,
	LPG.WORKGROUPNAME,
	LPGW.ORDERNO AS WORKORDERNO,
	TRIM(LPGM.MAINNAME || ' ' || LPGW.WORKNAME) AS WORKNAME,
	LPGW.MAXSCORE,
	NVL(AW.SUM_SCORE,0) AS SUM_SCORE,
	CASE WHEN LPGW.MAXSCORE>0 THEN ROUND(NVL(AW.SUM_SCORE,0)*100/LPGW.MAXSCORE,2) ELSE 0 END AS PERCENTAGE
FROM HR_EVAPP A
	INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
	LEFT JOIN VW_HR_STAFF_NAME H ON A.HR_STAFFHEADER_ID=H.ID
	LEFT JOIN VW_HR_POSITION HP ON H.HR_POSITION_ID=HP.ID
	INNER JOIN VW_HR_POSITION C ON A.HR_POSITION_ID=C.ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	INNER JOIN VW_HR_STAFFTYPE ST ON A.HR_STAFFTYPE_ID=ST.ID
	INNER JOIN HR_EVLOTWLPOS LP ON L.HR_EVLOTWL_ID=LP.HR_EVLOTWL_ID AND LP.HR_EVPOSITION_ID=A.HR_EVPOSITION_ID
	INNER JOIN HR_EVLOTWLPOSGRP LPG ON LP.ID=LPG.HR_EVLOTWLPOS_ID
	INNER JOIN HR_EVLOTWLPOSGRPWL LPGW ON LPG.ID=LPGW.HR_EVLOTWLPOSGRP_ID
	LEFT JOIN HR_EVLOTWLPOSGRPMAIN LPGM ON LPGM.ID=LPGW.HR_EVLOTWLPOSGRPMAIN_ID
	LEFT JOIN (
		SELECT W.HR_EVAPP_ID, W.HR_EVLOTWLPOSGRPWL_ID, SUM(W.TOTALWORK) AS SUM_WORK, CASE WHEN WW.SCORETYPE_ID=4 THEN CASE WHEN NVL(SUM(W.TOTALWORK),0)>=WW.MINTOTAL THEN WW.MAXSCORE ELSE 0 END ELSE NVL(SUM(W.SCORE),0) END AS SUM_SCORE
		FROM HR_EVAPPWORK W
			INNER JOIN  HR_EVLOTWLPOSGRPWL WW ON W.HR_EVLOTWLPOSGRPWL_ID=WW.ID
			INNER JOIN HR_EVAPP A ON W.HR_EVAPP_ID=A.ID
		WHERE A.GUID=fn_ss_parameter_gettext('VR_HR_EVAPP.HR_EVAPP_GUID')
		GROUP BY W.HR_EVAPP_ID, W.HR_EVLOTWLPOSGRPWL_ID,WW.SCORETYPE_ID,WW.MINTOTAL,WW.MAXSCORE
	) AW ON A.ID=AW.HR_EVAPP_ID AND LPGW.ID=AW.HR_EVLOTWLPOSGRPWL_ID
WHERE A.GUID=fn_ss_parameter_gettext('VR_HR_EVAPP.HR_EVAPP_GUID');

-- ----------------------------
-- View structure for VR_HR_EVAPPPOS_STAT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPPPOS_STAT" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	P.ID AS HR_EVLOTAPP_ID,
	LP.HR_EVPOSITION_ID,
	LPGW.ID AS HR_EVLOTWLPOSGRPWL_ID,
	P.EVLOTAPPNAME,
	PO.EVPOSITIONNAME,
	LPG.ORDERNO AS WORKGROUPORDERNO,
	LPG.WORKGROUPNAME,
	LPG.MAXSCORE AS WORKGROUPMAXSCORE, --คะแนนเต็มของกลุ่มภาระงาน
	NVL(LPGM.ORDERNO,999) AS MAINORDER,
	NVL(LPGM.MAINNAME,'ไม่ระบุ') AS MAINNAME,
	LPGW.ORDERNO AS WORKORDERNO,
	TRIM(LPGW.WORKNAME) AS WORKNAME,
	CASE WHEN LPGW.SCORETYPE_ID=2 THEN LPGM.EACHSCORE ELSE LPGW.EACHSCORE END AS EACHSCORE, -- คะแนนต่อหน่วย
	NVL(A.SUM_TOTALWORK,0) AS TOTALWORK, -- จำนวนรวม (ชิ้น)
	NVL(A.SUM_SCORE,0) AS TOTALSCORE,-- คะแนนรวมทั้งหมด
	NVL(MAI.TOTALWORK,0) AS MAXTOTAL, -- จำนวนรวม (ชิ้น) ของบุคคลที่ได้คะแนนสูงสุด
	NVL(MAI.SCORE,0) AS MAXSCORE, -- คะแนนรวม ของบุคคลที่ได้คะแนนสูงสุด
	MAI.SNAME,
	MAI.SNAMEFULL || CASE WHEN MAID.ID IS NOT NULL THEN ' (' || MAID.DEPARTMENTCODE || ': ' || MAID.DEPARTMENTNAME || ')' END AS SNAMEFULL
FROM HR_EVLOTAPP P
	INNER JOIN HR_EVLOTWLPOS LP ON P.HR_EVLOTWL_ID=LP.HR_EVLOTWL_ID
	INNER JOIN VW_HR_EVPOSITION PO ON LP.HR_EVPOSITION_ID=PO.ID
	INNER JOIN HR_EVLOTWLPOSGRP LPG ON LP.ID=LPG.HR_EVLOTWLPOS_ID
	INNER JOIN HR_EVLOTWLPOSGRPWL LPGW ON LPG.ID=LPGW.HR_EVLOTWLPOSGRP_ID
	LEFT JOIN HR_EVLOTWLPOSGRPMAIN LPGM ON LPGM.ID=LPGW.HR_EVLOTWLPOSGRPMAIN_ID
	LEFT JOIN (
		SELECT AP.HR_EVLOTAPP_ID, AW.HR_EVLOTWLPOSGRPWL_ID, SUM(AW.TOTALWORK) AS SUM_TOTALWORK, SUM(AW.SCORE) AS SUM_SCORE
		FROM HR_EVAPPWORK AW
			INNER JOIN HR_EVAPP AP ON AW.HR_EVAPP_ID=AP.ID
			INNER JOIN VW_MT_DEPARTMENT D ON AP.MT_DEPARTMENT_ID=D.ID
		WHERE AP.HR_EVLOTAPP_ID = FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.HR_EVLOTAPP_ID') AND
			AP.HR_EVPOSITION_ID =  FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.HR_EVPOSITION_ID') AND
			D.DEPARTMENTCODE >= FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPPPOS_STAT.DEPARTMENTCODEFROM') AND
			D.DEPARTMENTCODE <= FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPPPOS_STAT.DEPARTMENTCODETO') AND
			AP.APPSTATUS_ID >= FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.APSTATUSFROM_ID') AND
			AP.APPSTATUS_ID <= FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.APSTATUSTO_ID')
		GROUP BY AP.HR_EVLOTAPP_ID, AW.HR_EVLOTWLPOSGRPWL_ID
	) A ON P.ID=A.HR_EVLOTAPP_ID AND LPGW.ID=A.HR_EVLOTWLPOSGRPWL_ID
	LEFT JOIN (
		SELECT AP.HR_EVLOTAPP_ID, AW.HR_EVLOTWLPOSGRPWL_ID, MAX(AW.SCORE) AS MAX_SCORE
		FROM HR_EVAPPWORK AW
			INNER JOIN HR_EVAPP AP ON AW.HR_EVAPP_ID=AP.ID
			INNER JOIN VW_MT_DEPARTMENT D ON AP.MT_DEPARTMENT_ID=D.ID
		WHERE AW.SCORE>0 AND
			AP.HR_EVLOTAPP_ID = FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.HR_EVLOTAPP_ID') AND
			AP.HR_EVPOSITION_ID =  FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.HR_EVPOSITION_ID') AND
			D.DEPARTMENTCODE >= FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPPPOS_STAT.DEPARTMENTCODEFROM') AND
			D.DEPARTMENTCODE <= FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPPPOS_STAT.DEPARTMENTCODETO') AND
			AP.APPSTATUS_ID >= FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.APSTATUSFROM_ID') AND
			AP.APPSTATUS_ID <= FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.APSTATUSTO_ID')
		GROUP BY AP.HR_EVLOTAPP_ID, AW.HR_EVLOTWLPOSGRPWL_ID
	) MA ON P.ID=MA.HR_EVLOTAPP_ID AND LPGW.ID=MA.HR_EVLOTWLPOSGRPWL_ID
	LEFT JOIN (
		SELECT AP.HR_EVLOTAPP_ID, AW.HR_EVLOTWLPOSGRPWL_ID, AW.TOTALWORK, AW.SCORE, S.SNAMEFULL, S.SNAME, S.MT_DEPARTMENT_ID
		FROM HR_EVAPPWORK AW
			INNER JOIN HR_EVAPP AP ON AW.HR_EVAPP_ID=AP.ID
			INNER JOIN VW_MT_DEPARTMENT D ON AP.MT_DEPARTMENT_ID=D.ID
			INNER JOIN VW_HR_STAFF_NAME S ON AP.HR_STAFF_ID=S.ID
		WHERE AW.SCORE>0 AND
			AP.HR_EVLOTAPP_ID = FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.HR_EVLOTAPP_ID') AND
			AP.HR_EVPOSITION_ID =  FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.HR_EVPOSITION_ID') AND
			D.DEPARTMENTCODE >= FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPPPOS_STAT.DEPARTMENTCODEFROM') AND
			D.DEPARTMENTCODE <= FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPPPOS_STAT.DEPARTMENTCODETO') AND
			AP.APPSTATUS_ID >= FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.APSTATUSFROM_ID') AND
			AP.APPSTATUS_ID <= FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.APSTATUSTO_ID')
	) MAI ON MAI.HR_EVLOTAPP_ID=MA.HR_EVLOTAPP_ID AND MAI.HR_EVLOTWLPOSGRPWL_ID=MA.HR_EVLOTWLPOSGRPWL_ID AND MAI.SCORE =MA.MAX_SCORE
	LEFT JOIN VW_MT_DEPARTMENT MAID ON MAI.MT_DEPARTMENT_ID=MAID.ID
WHERE P.ID = FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.HR_EVLOTAPP_ID') AND
	LP.HR_EVPOSITION_ID = FN_SS_PARAMETER_GETNUMBER('VR_HR_EVAPPPOS_STAT.HR_EVPOSITION_ID');

-- ----------------------------
-- View structure for VR_HR_EVAPPSCORE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPPSCORE" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	SC.LEVELNAME,
	SC.DESCRIPTION,
	SC.MINSCORE,
	DECODE(A.HR_EVLOTSCOREITEM_ID, SC.ID,1,0) AS CHECKED_ID
FROM HR_EVAPP A
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	INNER JOIN VW_HR_EVLOTSCOREITEM SC ON L.HR_EVLOTSCORE_ID=SC.HR_EVLOTSCORE_ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
WHERE A.GUID=FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPP.HR_EVAPP_GUID');

-- ----------------------------
-- View structure for VR_HR_EVAPPWORK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPPWORK" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.ID AS HR_EVAPP_ID,
	LPG.ORDERNO AS WORKGROUPORDERNO,
	LPG.WORKGROUPNAME,
	LPG.MAXSCORE AS WORKGROUPMAXSCORE, --คะแนนเต็มของกลุ่มภาระงาน
	NVL(G.SUM_TOTALSCORE,0) AS GROUPSCORE, --คะแนนที่บันทึกของกลุ่มภาระงาน
	NVL(G.SUM_WORKGROUPSCORE,0) AS SUM_GROUPSCORE, --คะแนนที่ได้ของกลุ่มภาระงาน
	LPGW.ORDERNO AS WORKORDERNO,
	NVL(LPGM.ORDERNO,999) AS MAINORDER,
	NVL(LPGM.MAINNAME,'ไม่ระบุ') AS MAINNAME,
	TRIM(LPGW.WORKNAME) AS WORKNAME,
	NVL(AW.SUM_SCORE,0) AS WORKSCORE, --คะแนนที่บันทึกของภาระงาน
	CAST(FN_HR_EVLOTWLPOSGRPWL_SCORE(LPGW.SCORETYPE_ID,LPGW.EACHSCORE,LPGM.EACHSCORE,LPGW.MINTOTAL,LPGW.MAXSCORE,NVL(AW.SUM_TOTALWORK,0),NVL(AW.SUM_SCORE,0)) AS NUMBER(15,2)) AS SUM_SCORE, --คะแนนที่ได้ของภาระงาน
	LPGW.MAXSCORE, --คะแนนเต็มของภาระงาน
	W.ORDERNO AS ITEMORDERNO,
	CASE WHEN LPGW.SCORETYPE_ID=5 THEN NULL ELSE W.WORKNAME END AS ITEMDESCRIPTION,
	W.SCORE AS ITEMSCORE, --คะแนนของรายละเอียดภาระงาน
	0 AS PERCENTAGE,
	L.TOTALSCORE,
	SM.CONFIGVALUE AS SCOREMODE
FROM HR_EVAPP A
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	INNER JOIN HR_EVLOTWLPOS LP ON L.HR_EVLOTWL_ID=LP.HR_EVLOTWL_ID AND LP.HR_EVPOSITION_ID=A.HR_EVPOSITION_ID
	INNER JOIN HR_EVLOTWLPOSGRP LPG ON LP.ID=LPG.HR_EVLOTWLPOS_ID
	INNER JOIN HR_EVLOTWLPOSGRPWL LPGW ON LPG.ID=LPGW.HR_EVLOTWLPOSGRP_ID
	LEFT JOIN VW_HR_EVAPPWORK_SUMGROUP G ON A.ID=G.HR_EVAPP_ID AND G.HR_EVLOTWLPOSGRP_ID=LPGW.HR_EVLOTWLPOSGRP_ID
	LEFT JOIN HR_EVLOTWLPOSGRPMAIN LPGM ON LPGM.ID=LPGW.HR_EVLOTWLPOSGRPMAIN_ID
	LEFT JOIN (
		SELECT AA.HR_EVAPP_ID,
			AA.HR_EVLOTWLPOSGRPWL_ID,
			SUM(AA.TOTALWORK) AS SUM_TOTALWORK,
			SUM(NVL(AA.SCORE,0)) AS SUM_SCORE
        FROM HR_EVAPPWORK AA
        GROUP BY AA.HR_EVAPP_ID, AA.HR_EVLOTWLPOSGRPWL_ID
	)  AW ON A.ID=AW.HR_EVAPP_ID AND LPGW.ID=AW.HR_EVLOTWLPOSGRPWL_ID
	LEFT JOIN VW_HR_EVAPPWORK W ON A.ID=W.HR_EVAPP_ID AND W.SCORE>0 AND W.HR_EVLOTWLPOSGRPWL_ID=LPGW.ID AND W.HR_EVLOTWLPOSGRPWL_ID=AW.HR_EVLOTWLPOSGRPWL_ID
	CROSS JOIN (SELECT * FROM SS_CONFIG WHERE CONFIGCODE='HR_EV.MAXSCORE.MODE') SM
WHERE A.GUID=FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPP.HR_EVAPP_GUID');

-- ----------------------------
-- View structure for VR_HR_EVAPPWORKBRDREMARK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPPWORKBRDREMARK" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	   A.ID AS HR_EVAPP_ID,
	   LPG.ORDERNO AS WORKGROUPORDERNO,
	   LPG.WORKGROUPNAME,
	   LPGW.ORDERNO AS WORKORDERNO,
	   NVL(LPGM.ORDERNO, 999) AS MAINORDER,
	   NVL(LPGM.MAINNAME, 'ไม่ระบุ') AS MAINNAME,
	   TRIM(LPGW.WORKNAME) AS WORKNAME,
	   W.ORDERNO AS ITEMORDERNO,
	   CASE
		   WHEN LPGW.SCORETYPE_ID = 5 THEN
			NULL
		   ELSE
			W.WORKNAME
	   END AS ITEMDESCRIPTION,
	   W.SCORE AS ITEMSCORE, --คะแนนของรายละเอียดภาระงาน
	   AB.ORDERNO AS BOARDORDERNO,
	   AB.BOARDREMARK,
	   NVL(AB.UPDATEBY, AB.CREATEBY) AS BOARDUPDATEBY,
	   NVL(AB.UPDATEDATETIME, AB.CREATEDATETIME) AS BOARDUPDATEDATETIME
FROM   HR_EVAPP A
INNER  JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID = L.ID
INNER  JOIN HR_EVLOTWLPOS LP ON L.HR_EVLOTWL_ID = LP.HR_EVLOTWL_ID
								AND LP.HR_EVPOSITION_ID = A.HR_EVPOSITION_ID
INNER  JOIN HR_EVLOTWLPOSGRP LPG ON LP.ID = LPG.HR_EVLOTWLPOS_ID
INNER  JOIN HR_EVLOTWLPOSGRPWL LPGW ON LPG.ID = LPGW.HR_EVLOTWLPOSGRP_ID
LEFT   JOIN HR_EVLOTWLPOSGRPMAIN LPGM ON LPGM.ID = LPGW.HR_EVLOTWLPOSGRPMAIN_ID
INNER  JOIN VW_HR_EVAPPWORK W ON A.ID = W.HR_EVAPP_ID
								 AND W.SCORE > 0
								 AND W.HR_EVLOTWLPOSGRPWL_ID = LPGW.ID
LEFT   JOIN HR_EVAPPWORKBRDREM AB ON W.ID = AB.HR_EVAPPWORK_ID
WHERE  A.GUID = FN_SS_PARAMETER_GETTEXT('VR_HR_EVAPP.HR_EVAPP_GUID');

-- ----------------------------
-- View structure for VR_HR_EVAPPWORK_BAK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPPWORK_BAK" AS SELECT cast(rownum as number(12)) as ID,
	A.ID AS HR_EVAPP_ID,
	LPG.ORDERNO AS WORKGROUPORDERNO,
	LPG.WORKGROUPNAME,
	LPG.MAXSCORE AS WORKGROUPMAXSCORE,
	LPGW.ORDERNO AS WORKORDERNO,
	NVL(LPGM.ORDERNO,999) AS MAINORDER,
	NVL(LPGM.MAINNAME,'ไม่ระบุ') AS MAINNAME,
	TRIM(LPGW.WORKNAME) AS WORKNAME,
	LPGW.MAXSCORE,
	CASE WHEN NVL(AW.SUM_SCORE,0)>LPGW.MAXSCORE AND LPGW.MAXSCORE>0 THEN LPGW.MAXSCORE ELSE NVL(AW.SUM_SCORE,0) END AS SUM_SCORE,
	CASE WHEN LPGW.MAXSCORE>0 THEN ROUND(CASE WHEN NVL(AW.SUM_SCORE,0)>LPGW.MAXSCORE AND LPGW.MAXSCORE>0 THEN LPGW.MAXSCORE ELSE NVL(AW.SUM_SCORE,0) END*100/LPGW.MAXSCORE,2) ELSE 0 END AS PERCENTAGE,
	W.ORDERNO AS ITEMORDERNO,
	W.WORKNAME AS ITEMDESCRIPTION,
	W.SCORE AS ITEMSCORE
FROM HR_EVAPP A
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	INNER JOIN HR_EVLOTWLPOS LP ON L.HR_EVLOTWL_ID=LP.HR_EVLOTWL_ID AND LP.HR_EVPOSITION_ID=A.HR_EVPOSITION_ID
	INNER JOIN HR_EVLOTWLPOSGRP LPG ON LP.ID=LPG.HR_EVLOTWLPOS_ID
	INNER JOIN HR_EVLOTWLPOSGRPWL LPGW ON LPG.ID=LPGW.HR_EVLOTWLPOSGRP_ID
	LEFT JOIN HR_EVLOTWLPOSGRPMAIN LPGM ON LPGM.ID=LPGW.HR_EVLOTWLPOSGRPMAIN_ID
	LEFT JOIN (
		SELECT W.HR_EVAPP_ID, W.HR_EVLOTWLPOSGRPWL_ID, SUM(W.TOTALWORK) AS SUM_WORK,
		CASE WHEN WW.SCORETYPE_ID=4 THEN CASE WHEN NVL(SUM(W.TOTALWORK),0)>=WW.MINTOTAL THEN WW.MAXSCORE ELSE 0 END ELSE NVL(SUM(W.SCORE),0) END AS SUM_SCORE
		FROM HR_EVAPPWORK W
			INNER JOIN  HR_EVLOTWLPOSGRPWL WW ON W.HR_EVLOTWLPOSGRPWL_ID=WW.ID
			INNER JOIN HR_EVAPP A ON W.HR_EVAPP_ID=A.ID
		WHERE A.GUID=fn_ss_parameter_gettext('VR_HR_EVAPP.HR_EVAPP_GUID')
		GROUP BY W.HR_EVAPP_ID, W.HR_EVLOTWLPOSGRPWL_ID,WW.SCORETYPE_ID,WW.MINTOTAL,WW.MAXSCORE
	) AW ON A.ID=AW.HR_EVAPP_ID AND LPGW.ID=AW.HR_EVLOTWLPOSGRPWL_ID
	LEFT JOIN VW_HR_EVAPPWORK W ON A.ID=W.HR_EVAPP_ID AND W.SCORE>0 AND W.HR_EVLOTWLPOSGRPWL_ID=LPGW.ID
WHERE A.GUID=fn_ss_parameter_gettext('VR_HR_EVAPP.HR_EVAPP_GUID');

-- ----------------------------
-- View structure for VR_HR_EVAPP_COURSE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_COURSE" AS SELECT A.ID,
	A.HR_EVLOTAPP_ID,
	A.EVPOSITIONCODE,
	A.DEPARTMENTCODE,
	A.EVLOTAPPNAME,
	A.ISACTIVE_ID,

	A.STAFFCODE,
	A.SNAME,
	A.SNAMEENG,
	A.SNAMEFULL,
	A.EVPOSITIONNAME,
	A.DEPARTMENTFULLNAME,
	A.POSITIONCODE,
	A.POSITIONNAME,
	A.TOTALCOURSE
FROM VW_HR_EVAPP A
	INNER JOIN VG_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.VALUE AND D.SS_APPLICATION_ID=160;

-- ----------------------------
-- View structure for VR_HR_EVAPP_GROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_GROUP" AS SELECT A.HR_EVLOTAPP_ID,
	A.HR_EVPOSITION_ID,
	D.DEPARTMENTCODE,
	A.APPSTATUS_ID,
	A.ID,
	S.STAFFCODE,
	S.SNAME,
	S.SNAMEFULL,
	AGI.ORDERNO,
	AGI.WORKGROUPNAME,
	LAG.SCORE,
	LPAD(AGI.ORDERNO,2,'0') || ': ' || AGI.WORKGROUPNAME || ' (' || TRIM(TO_CHAR(AGI.MAXSCORE,'999,999,999,999.99')) || ' คะแนน)' AS WORKGROUPNAME_DISPLAY,
	G.GROUPNAME || ' (' || TRIM(TO_CHAR(LAG.SCORE,'999,999,999,999.99')) || ' คะแนน)' AS GROUPNAME_MAIN,
	LAG.SCORE*100/LGS.SUM_SCORE AS GROUPNAME_PERCENT,
	AGI.GROUPNAME,
	AGI.SCORE AS WORKSCORE,
	--AGI.SCORE_ACTUAL,
	--AGI.SCORE_APPROVE,
	AG.TOTALSCORE_ACTUAL,
	CASE WHEN AG.TOTALSCORE_APPROVE>LAG.SCORE THEN LAG.SCORE ELSE AG.TOTALSCORE_APPROVE END AS TOTALSCORE_APPROVE,
	CASE WHEN AG.TOTALSCORE_APPROVE>LAG.SCORE THEN LAG.SCORE ELSE AG.TOTALSCORE_APPROVE END * (LAG.SCORE*100/LGS.SUM_SCORE) / LAG.SCORE AS SCORE_PERCENT
FROM HR_EVAPP A
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
	INNER JOIN VW_HR_STAFF_NAME S ON A.HR_STAFF_ID=S.ID
	INNER JOIN (
		SELECT HR_EVAPP_ID,
			HR_EVGROUP_ID,
            ORDERNO,
            WORKGROUPNAME,
            MAXSCORE,
			'1: คะแนนที่บันทึก' AS GROUPNAME,
			SCORE_ACTUAL AS SCORE
		FROM VR_HR_EVAPP_GROUP_ITEM
		UNION ALL
		SELECT HR_EVAPP_ID,
			HR_EVGROUP_ID,
            ORDERNO,
            WORKGROUPNAME,
            MAXSCORE,
			'2: คะแนนที่ได้' AS GROUPNAME,
			SCORE_APPROVE AS SCORE
		FROM VR_HR_EVAPP_GROUP_ITEM
	) AGI ON A.ID=AGI.HR_EVAPP_ID
	INNER JOIN HR_EVGROUP G ON AGI.HR_EVGROUP_ID=G.ID
	INNER JOIN HR_EVLOTAPPGROUP LAG ON LAG.HR_EVLOTAPP_ID=A.HR_EVLOTAPP_ID AND LAG.HR_EVGROUP_ID=G.ID
	INNER JOIN (
		SELECT HR_EVLOTAPP_ID,
			SUM(SCORE) AS SUM_SCORE
		FROM HR_EVLOTAPPGROUP
		GROUP BY HR_EVLOTAPP_ID
	) LGS ON LGS.HR_EVLOTAPP_ID=A.HR_EVLOTAPP_ID
	INNER JOIN (
		SELECT I.HR_EVAPP_ID,
			SUM(I.SCORE_ACTUAL) AS TOTALSCORE_ACTUAL,
			SUM(I.SCORE_APPROVE) AS TOTALSCORE_APPROVE
		FROM VR_HR_EVAPP_GROUP_ITEM I
		GROUP BY I.HR_EVAPP_ID
	) AG ON A.ID=AG.HR_EVAPP_ID;

-- ----------------------------
-- View structure for VR_HR_EVAPP_GROUP_BAK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_GROUP_BAK" AS SELECT R.ID,
	R.HR_EVLOTAPP_ID,
	R.APPSTATUS_ID,
	R.EVPOSITIONCODE,
	R.EVPOSITIONNAME,
	R.DEPARTMENTCODE,
	R.DEPARTMENTFULLNAME,
	R.STAFFCODE,
	R.SNAME,
	R.SNAMEFULL,
	R.ISACTIVE_ID,
    R.BUDGETYEAR,
    R.ROUNDNO,
    R.EVLOTAPPNAME,

	R.MAXSCORE_MAIN, -- รวมคะแนนภาระงานหลัก
	--R.MAXSCORE_MAIN_PC, --รวมคะแนนภาระงานหลัก (%)
	R.MAXSCORE_WORK, -- รวมคะแนนงานที่ได้รับมอบหมาย
	--R.MAXSCORE_WORK_PC, --รวมคะแนนงานที่ได้รับมอบหมาย (%)
	R.MAXSCORE_PROJECT, -- รวมคะแนนโครงการ
	--R.MAXSCORE_PROJECT_PC, --รวมคะแนนโครงการ (%)
	R.MAXSCORE, --รวมคะแนนทั้งหมด
	--R.MAXSCORE_PC, --รวมคะแนนทั้งหมด (%)
	--90 AS MAXBASE_PC,

	R.INPUTSCORE_MAIN, --คะแนนภาระงานหลักที่บันทึก
	R.SCORE_MAIN, --คะแนนภาระงานหลักที่ได้
	--CASE WHEN R.MAXSCORE_MAIN=0 THEN 0 ELSE CASE WHEN R.SCORE_MAIN>R.MAXSCORE_MAIN THEN R.MAXSCORE_MAIN_PC ELSE R.SCORE_MAIN*R.MAXSCORE_MAIN_PC/R.MAXSCORE_MAIN END END AS SCORE_MAIN_PC,
	R.INPUTSCORE_WORK, --คะแนนงานที่ได้รับมอบหมายที่บันทึก
	R.SCORE_WORK, --คะแนนงานที่ได้รับมอบหมายที่ได้
	--CASE WHEN R.MAXSCORE_WORK=0 THEN 0 ELSE CASE WHEN R.SCORE_WORK>R.MAXSCORE_WORK THEN R.MAXSCORE_WORK_PC ELSE R.SCORE_WORK*R.MAXSCORE_WORK_PC/R.MAXSCORE_WORK END END AS SCORE_WORK_PC,
	R.INPUTSCORE_PROJECT, --คะแนนโครงการที่บันทึก
	R.SCORE_PROJECT, --คะแนนโครงการที่ได้
	--CASE WHEN R.MAXSCORE_PROJECT=0 THEN 0 ELSE CASE WHEN R.SCORE_PROJECT>R.MAXSCORE_PROJECT THEN R.MAXSCORE_PROJECT_PC ELSE R.SCORE_PROJECT*R.MAXSCORE_PROJECT_PC/R.MAXSCORE_PROJECT END END AS SCORE_PROJECT_PC,

	R.INPUTSCORE_MAIN + R.INPUTSCORE_WORK + R.INPUTSCORE_PROJECT AS INPUTSCORE, --คะแนนที่บันทึก
	R.SCORE_MAIN + R.SCORE_WORK + R.SCORE_PROJECT AS SCORE, --คะแนนที่ได้

	CAST(CASE WHEN R.MAXSCORE_MAIN=0 THEN 0 ELSE CASE WHEN R.SCORE_MAIN>R.MAXSCORE_MAIN THEN R.MAXSCORE_MAIN_PC ELSE R.SCORE_MAIN*R.MAXSCORE_MAIN_PC/R.MAXSCORE_MAIN END END +
	CASE WHEN R.MAXSCORE_WORK=0 THEN 0 ELSE CASE WHEN R.SCORE_WORK>R.MAXSCORE_WORK THEN R.MAXSCORE_WORK_PC ELSE R.SCORE_WORK*R.MAXSCORE_WORK_PC/R.MAXSCORE_WORK END END +
	CASE WHEN R.MAXSCORE_PROJECT=0 THEN 0 ELSE CASE WHEN R.SCORE_PROJECT>R.MAXSCORE_PROJECT THEN R.MAXSCORE_PROJECT_PC ELSE R.SCORE_PROJECT*R.MAXSCORE_PROJECT_PC/R.MAXSCORE_PROJECT END END AS NUMBER(15,2)) AS SCORE_PC
FROM (
        SELECT A.ID,
            A.HR_EVLOTAPP_ID,
            A.APPSTATUS_ID,
            A.RATIOACHIEVEMENT,--ร้อยละคะแนนผลสัมฤทธิ์ของงาน
            A.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
            A.RATIOSCORE, --ร้อยละคะแนนรวมทั้งหมดที่ได้

            B.STAFFCODE,
            B.SNAME,
            B.SNAMEENG,
            B.SNAMEFULL,

            D.DEPARTMENTCODE,
            D.DEPARTMENTFULLNAME,
            E.EVPOSITIONCODE,
            E.EVPOSITIONNAME,
            E.ISACTIVE_ID,
            LG.MAXSCORE_MAIN,
            CASE WHEN LG.MAXSCORE_TOTAL>0 THEN LG.MAXSCORE_MAIN*100/LG.MAXSCORE_TOTAL ELSE 0 END AS MAXSCORE_MAIN_PC,
            LG.MAXSCORE_WORK,
            CASE WHEN LG.MAXSCORE_TOTAL>0 THEN LG.MAXSCORE_WORK*100/LG.MAXSCORE_TOTAL ELSE 0 END AS MAXSCORE_WORK_PC,
            LG.MAXSCORE_PROJECT,
            CASE WHEN LG.MAXSCORE_TOTAL>0 THEN LG.MAXSCORE_PROJECT*100/LG.MAXSCORE_TOTAL ELSE 0 END AS MAXSCORE_PROJECT_PC,
			LG.MAXSCORE_TOTAL AS MAXSCORE,
			100 AS MAXSCORE_PC,

            WG.INPUTSCORE_MAIN AS INPUTSCORE_MAIN,
            CAST(CASE WHEN NVL(LG.MAXSCORE_MAIN, 0)<WG.INPUTSCORE_MAIN THEN NVL(LG.MAXSCORE_MAIN, 0) ELSE WG.INPUTSCORE_MAIN END AS NUMBER(15,2)) AS SCORE_MAIN,
            WG.INPUTSCORE_WORK AS INPUTSCORE_WORK,
            CAST(CASE WHEN NVL(LG.MAXSCORE_WORK, 0)<WG.INPUTSCORE_WORK THEN NVL(LG.MAXSCORE_WORK, 0) ELSE WG.INPUTSCORE_WORK END AS NUMBER(15,2)) AS SCORE_WORK,
            WG.INPUTSCORE_PROJECT AS INPUTSCORE_PROJECT,
            CAST(CASE WHEN NVL(LG.MAXSCORE_PROJECT, 0)<WG.INPUTSCORE_PROJECT THEN NVL(LG.MAXSCORE_PROJECT, 0) ELSE WG.INPUTSCORE_PROJECT END AS NUMBER(15,2)) AS SCORE_PROJECT,
            L.TOTALSCORE, --คะแนนเต็มแต่ละตำแหน่ง
            --CAST(NVL(WG.INPUTSCORE, 0) AS NUMBER(10, 2)) AS SCOREACTUAL, --คะแนนผลสัมฤทธิ์ของงานที่บันทึก
            --CAST(NVL(WG.SCORE, 0) AS NUMBER(10, 2)) AS SCORE, --คะแนนผลสัมฤทธิ์ของงานที่ได้
            A.SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
            L.BUDGETYEAR,
            L.ROUNDNO,
            L.EVLOTAPPNAME
        FROM HR_EVAPP A
            INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
            INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
            INNER JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID=E.ID
            INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
            LEFT JOIN (
                SELECT A.HR_EVLOTAPP_ID,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '01' THEN A.SCORE ELSE 0 END) AS MAXSCORE_MAIN,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '02' THEN A.SCORE ELSE 0 END) AS MAXSCORE_WORK,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '03' THEN A.SCORE ELSE 0 END) AS MAXSCORE_PROJECT,
                    SUM(NVL(A.SCORE,0)) AS MAXSCORE_TOTAL
                FROM HR_EVLOTAPPGROUP A
                    LEFT JOIN HR_EVGROUP EG ON A.HR_EVGROUP_ID=EG.ID
                GROUP BY A.HR_EVLOTAPP_ID
            ) LG ON A.HR_EVLOTAPP_ID=LG.HR_EVLOTAPP_ID
            LEFT JOIN
             (SELECT G.HR_EVAPP_ID,
                SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '01' THEN G.SUM_WORKGROUPSCORE ELSE 0 END) AS SCORE_MAIN,
                SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '02' THEN G.SUM_WORKGROUPSCORE ELSE 0 END) AS SCORE_WORK,
                SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '03' THEN G.SUM_WORKGROUPSCORE ELSE 0 END) AS SCORE_PROJECT,
                SUM(SUM_WORKGROUPSCORE) AS SCORE,
                SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '01' THEN G.SUM_TOTALSCORE ELSE 0 END) AS INPUTSCORE_MAIN,
                SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '02' THEN G.SUM_TOTALSCORE ELSE 0 END) AS INPUTSCORE_WORK,
                SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '03' THEN G.SUM_TOTALSCORE ELSE 0 END) AS INPUTSCORE_PROJECT
              FROM VW_HR_EVAPPWORK_SUMGROUP G
                LEFT JOIN HR_EVGROUP EG ON G.HR_EVGROUP_ID=EG.ID
              GROUP BY G.HR_EVAPP_ID) WG ON A.ID=WG.HR_EVAPP_ID
            INNER JOIN
            (
                SELECT P.HR_EVLOTWL_ID, P.HR_EVPOSITION_ID,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '01' THEN GG.MAXSCORE ELSE 0 END) AS MAXSCORE_MAIN,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '02' THEN GG.MAXSCORE ELSE 0 END) AS MAXSCORE_WORK,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '03' THEN GG.MAXSCORE ELSE 0 END) AS MAXSCORE_PROJECT,
                    SUM(MAXSCORE) AS MAXSCORE
                FROM HR_EVLOTWLPOSGRP GG
                    INNER JOIN HR_EVLOTWLPOS P ON GG.HR_EVLOTWLPOS_ID=P.ID
                    LEFT JOIN HR_EVGROUP EG ON GG.HR_EVGROUP_ID=EG.ID
                GROUP BY P.HR_EVLOTWL_ID, P.HR_EVPOSITION_ID
            ) LWP ON L.HR_EVLOTWL_ID=LWP.HR_EVLOTWL_ID AND A.HR_EVPOSITION_ID=LWP.HR_EVPOSITION_ID
            CROSS JOIN (SELECT * FROM SS_CONFIG WHERE CONFIGCODE='HR_EV.MAXSCORE.MODE') SM
	) R;

-- ----------------------------
-- View structure for VR_HR_EVAPP_GROUP_ITEM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_GROUP_ITEM" AS SELECT AW.HR_EVAPP_ID,
	LG.ORDERNO,
	LG.WORKGROUPNAME,
	LG.MAXSCORE,
	LG.HR_EVGROUP_ID,
	SUM(AW.SUM_TOTALSCORE) AS SCORE_ACTUAL, --คะแนนที่บันทึก
	CASE WHEN NVL(SUM(AW.SUM_SCOREINPUT),0)>LG.MAXSCORE THEN LG.MAXSCORE ELSE NVL(SUM(AW.SUM_SCOREINPUT),0) END AS SCORE_APPROVE --คะแนนที่ได้
FROM VW_HR_EVAPPWORK_SUMGROUP AW
	INNER JOIN HR_EVLOTWLPOSGRP LG ON LG.ID=AW.HR_EVLOTWLPOSGRP_ID
WHERE LG.HR_EVGROUP_ID=1
GROUP BY AW.HR_EVAPP_ID,
	LG.ORDERNO,
	LG.WORKGROUPNAME,
	LG.MAXSCORE,
	LG.HR_EVGROUP_ID;

-- ----------------------------
-- View structure for VR_HR_EVAPP_GROUP_ITEM_BAK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_GROUP_ITEM_BAK" AS SELECT AW.HR_EVAPP_ID,
	LG.ORDERNO,
	LG.WORKGROUPNAME,
	LG.MAXSCORE,
	LG.HR_EVGROUP_ID,
	SUM(AW.SCORE) AS SCORE_ACTUAL,
	CASE WHEN NVL(SUM(AW.SCORE),0)>LG.MAXSCORE THEN LG.MAXSCORE ELSE NVL(SUM(AW.SCORE),0) END AS SCORE_APPROVE
FROM HR_EVAPPWORK AW
	INNER JOIN HR_EVLOTWLPOSGRPWL LGW ON AW.HR_EVLOTWLPOSGRPWL_ID=LGW.ID
	INNER JOIN HR_EVLOTWLPOSGRP LG ON LG.ID=LGW.HR_EVLOTWLPOSGRP_ID
WHERE LG.HR_EVGROUP_ID=1
GROUP BY AW.HR_EVAPP_ID,
	LG.ORDERNO,
	LG.WORKGROUPNAME,
	LG.MAXSCORE,
	LG.HR_EVGROUP_ID;

-- ----------------------------
-- View structure for VR_HR_EVAPP_GROUP_RATIO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_GROUP_RATIO" AS SELECT R.ID,
	R.HR_EVLOTAPP_ID,
	R.APPSTATUS_ID,
	R.EVPOSITIONCODE,
	R.EVPOSITIONNAME,
	R.DEPARTMENTCODE,
	R.DEPARTMENTFULLNAME,
	R.STAFFCODE,
	R.SNAME,
	R.SNAMEFULL,
	R.ISACTIVE_ID,
    R.BUDGETYEAR,
    R.ROUNDNO,
    R.EVLOTAPPNAME,

	R.MAXSCORE_MAIN, -- รวมคะแนนภาระงานหลัก
	R.MAXSCORE_MAIN_PC, --รวมคะแนนภาระงานหลัก (%)
	R.MAXSCORE_WORK, -- รวมคะแนนงานที่ได้รับมอบหมาย
	R.MAXSCORE_WORK_PC, --รวมคะแนนงานที่ได้รับมอบหมาย (%)
	R.MAXSCORE_PROJECT, -- รวมคะแนนโครงการ
	R.MAXSCORE_PROJECT_PC, --รวมคะแนนโครงการ (%)
	R.MAXSCORE, --รวมคะแนนทั้งหมด
	R.MAXSCORE_PC, --รวมคะแนนทั้งหมด (%)
	90 AS MAXBASE_PC,

	R.RATIOACHIEVEMENT,
	R.RATIOBEHAVIOR,
	R.RATIOSCORE,
	R.TOTALSCORE,
	R.HR_EVLOTSCOREITEM_ID,
	R.HR_POSITION_ID,

	R.INPUTSCORE_MAIN,
	R.SCORE_MAIN, --คะแนนภาระงานหลักที่ได้
	CASE WHEN R.MAXSCORE_MAIN=0 THEN 0 ELSE CASE WHEN R.SCORE_MAIN>R.MAXSCORE_MAIN THEN R.MAXSCORE_MAIN_PC ELSE R.SCORE_MAIN*R.MAXSCORE_MAIN_PC/R.MAXSCORE_MAIN END END AS SCORE_MAIN_PC,
	R.INPUTSCORE_WORK,
	R.SCORE_WORK, --คะแนนงานที่ได้รับมอบหมายที่ได้
	CASE WHEN R.MAXSCORE_WORK=0 THEN 0 ELSE CASE WHEN R.SCORE_WORK>R.MAXSCORE_WORK THEN R.MAXSCORE_WORK_PC ELSE R.SCORE_WORK*R.MAXSCORE_WORK_PC/R.MAXSCORE_WORK END END AS SCORE_WORK_PC,
	R.INPUTSCORE_PROJECT,
	R.SCORE_PROJECT, --คะแนนโครงการที่ได้
	CASE WHEN R.MAXSCORE_PROJECT=0 THEN 0 ELSE CASE WHEN R.SCORE_PROJECT>R.MAXSCORE_PROJECT THEN R.MAXSCORE_PROJECT_PC ELSE R.SCORE_PROJECT*R.MAXSCORE_PROJECT_PC/R.MAXSCORE_PROJECT END END AS SCORE_PROJECT_PC,

	--R.SCOREINPUT AS INPUTSCORE,
	R.SCOREGROUP,
	R.INPUTSCORE_MAIN + R.INPUTSCORE_WORK + R.INPUTSCORE_PROJECT AS INPUTSCORE,
	R.SCORE_MAIN + R.SCORE_WORK + R.SCORE_PROJECT AS SCORE,
	CAST(CASE WHEN R.MAXSCORE_MAIN=0 THEN 0 ELSE CASE WHEN R.SCORE_MAIN>R.MAXSCORE_MAIN THEN R.MAXSCORE_MAIN_PC ELSE R.SCORE_MAIN*R.MAXSCORE_MAIN_PC/R.MAXSCORE_MAIN END END +
	CASE WHEN R.MAXSCORE_WORK=0 THEN 0 ELSE CASE WHEN R.SCORE_WORK>R.MAXSCORE_WORK THEN R.MAXSCORE_WORK_PC ELSE R.SCORE_WORK*R.MAXSCORE_WORK_PC/R.MAXSCORE_WORK END END +
	CASE WHEN R.MAXSCORE_PROJECT=0 THEN 0 ELSE CASE WHEN R.SCORE_PROJECT>R.MAXSCORE_PROJECT THEN R.MAXSCORE_PROJECT_PC ELSE R.SCORE_PROJECT*R.MAXSCORE_PROJECT_PC/R.MAXSCORE_PROJECT END END AS NUMBER(15,2)) AS SCORE_PC,
	CAST(90* (CASE WHEN R.MAXSCORE_MAIN=0 THEN 0 ELSE CASE WHEN R.SCORE_MAIN>R.MAXSCORE_MAIN THEN R.MAXSCORE_MAIN_PC ELSE R.SCORE_MAIN*R.MAXSCORE_MAIN_PC/R.MAXSCORE_MAIN END END +
	CASE WHEN R.MAXSCORE_WORK=0 THEN 0 ELSE CASE WHEN R.SCORE_WORK>R.MAXSCORE_WORK THEN R.MAXSCORE_WORK_PC ELSE R.SCORE_WORK*R.MAXSCORE_WORK_PC/R.MAXSCORE_WORK END END +
	CASE WHEN R.MAXSCORE_PROJECT=0 THEN 0 ELSE CASE WHEN R.SCORE_PROJECT>R.MAXSCORE_PROJECT THEN R.MAXSCORE_PROJECT_PC ELSE R.SCORE_PROJECT*R.MAXSCORE_PROJECT_PC/R.MAXSCORE_PROJECT END END)/R.MAXSCORE_PC AS NUMBER(15,2)) AS BASE_PC
FROM (
        SELECT A.ID,
            A.HR_EVLOTAPP_ID,
            A.APPSTATUS_ID,
            A.RATIOACHIEVEMENT,--ร้อยละคะแนนผลสัมฤทธิ์ของงาน
            A.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
            A.RATIOSCORE, --ร้อยละคะแนนรวมทั้งหมดที่ได้

            B.STAFFCODE,
            B.SNAME,
            B.SNAMEENG,
            B.SNAMEFULL,

            D.DEPARTMENTCODE,
            D.DEPARTMENTFULLNAME,
            E.EVPOSITIONCODE,
            E.EVPOSITIONNAME,
            E.ISACTIVE_ID,
            LG.MAXSCORE_MAIN,
            CASE WHEN LG.MAXSCORE_TOTAL>0 THEN LG.MAXSCORE_MAIN*100/LG.MAXSCORE_TOTAL ELSE 0 END AS MAXSCORE_MAIN_PC,
            LG.MAXSCORE_WORK,
            CASE WHEN LG.MAXSCORE_TOTAL>0 THEN LG.MAXSCORE_WORK*100/LG.MAXSCORE_TOTAL ELSE 0 END AS MAXSCORE_WORK_PC,
            LG.MAXSCORE_PROJECT,
            CASE WHEN LG.MAXSCORE_TOTAL>0 THEN LG.MAXSCORE_PROJECT*100/LG.MAXSCORE_TOTAL ELSE 0 END AS MAXSCORE_PROJECT_PC,
			LG.MAXSCORE_TOTAL AS MAXSCORE,
			100 AS MAXSCORE_PC,

			WG.INPUTSCORE_MAIN,
			WG.INPUTSCORE_WORK,
			WG.INPUTSCORE_PROJECT,
            CAST(CASE WHEN NVL(LG.MAXSCORE_MAIN, 0)<WG.SCORE_MAIN THEN NVL(LG.MAXSCORE_MAIN, 0) ELSE WG.SCORE_MAIN END AS NUMBER(15,2)) AS SCORE_MAIN,
            CAST(CASE WHEN NVL(LG.MAXSCORE_WORK, 0)<WG.SCORE_WORK THEN NVL(LG.MAXSCORE_WORK, 0) ELSE WG.SCORE_WORK END AS NUMBER(15,2)) AS SCORE_WORK,
            CAST(CASE WHEN NVL(LG.MAXSCORE_PROJECT, 0)<WG.SCORE_PROJECT THEN NVL(LG.MAXSCORE_PROJECT, 0) ELSE WG.SCORE_PROJECT END AS NUMBER(15,2)) AS SCORE_PROJECT,
            L.TOTALSCORE, --คะแนนเต็มแต่ละตำแหน่ง
            --CAST(NVL(WG.INPUTSCORE, 0) AS NUMBER(10, 2)) AS SCOREACTUAL, --คะแนนผลสัมฤทธิ์ของงานที่บันทึก
            --CAST(NVL(WG.SCORE, 0) AS NUMBER(10, 2)) AS SCORE, --คะแนนผลสัมฤทธิ์ของงานที่ได้
            A.SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
			A.SCOREINPUT,
			A.SCOREGROUP,
            L.BUDGETYEAR,
            L.ROUNDNO,
            L.EVLOTAPPNAME,
			A.HR_EVLOTSCOREITEM_ID,
			A.HR_POSITION_ID
        FROM HR_EVAPP A
            INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
--INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
            INNER JOIN VG_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.VALUE AND D.SS_APPLICATION_ID=160
            INNER JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID=E.ID
            INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
            LEFT JOIN VW_HR_EVLOTAPPGROUP_SCORE LG ON A.HR_EVLOTAPP_ID=LG.HR_EVLOTAPP_ID
            LEFT JOIN VW_HR_EVAPPGROUP_SCORE WG ON A.ID=WG.HR_EVAPP_ID
            INNER JOIN
            (
                SELECT P.HR_EVLOTWL_ID, P.HR_EVPOSITION_ID,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '01' THEN GG.MAXSCORE ELSE 0 END) AS MAXSCORE_MAIN,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '02' THEN GG.MAXSCORE ELSE 0 END) AS MAXSCORE_WORK,
                    SUM(CASE NVL(TO_CHAR(EG.GROUPCODE),'-') WHEN '03' THEN GG.MAXSCORE ELSE 0 END) AS MAXSCORE_PROJECT,
                    SUM(MAXSCORE) AS MAXSCORE
                FROM HR_EVLOTWLPOSGRP GG
                    INNER JOIN HR_EVLOTWLPOS P ON GG.HR_EVLOTWLPOS_ID=P.ID
                    LEFT JOIN HR_EVGROUP EG ON GG.HR_EVGROUP_ID=EG.ID
                GROUP BY P.HR_EVLOTWL_ID, P.HR_EVPOSITION_ID
            ) LWP ON L.HR_EVLOTWL_ID=LWP.HR_EVLOTWL_ID AND A.HR_EVPOSITION_ID=LWP.HR_EVPOSITION_ID
            CROSS JOIN (SELECT * FROM SS_CONFIG WHERE CONFIGCODE='HR_EV.MAXSCORE.MODE') SM
	) R;

-- ----------------------------
-- View structure for VR_HR_EVAPP_HEAD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_HEAD" AS SELECT A.ID,
	A.ID AS HR_EVAPP_ID,
	B.SNAMEFULL,
	C.POSITIONNAME,
	D.DEPARTMENTNAME,
	ST.STAFFTYPENAME,
	L.ROUNDNO,
	L.DATEFROM,
	L.DATETO,
	H.SNAMEFULL AS HEADERNAME,
	A.HEADERPOSITION,
	A.HEADERADDITION,
	A.HEADERFINISHDATE,
	A.SELFFINISHDATE,
	CASE WHEN A.APPSTATUS_ID>=50 THEN A.TOTALACHIEVEMENT ELSE 0 END AS TOTALACHIEVEMENT,
	L.RATIOACHIEVEMENT AS BASISACHIEVEMENT,
	A.RATIOACHIEVEMENT,
	CASE WHEN A.APPSTATUS_ID>=50 THEN A.TOTALBEHAVIOR ELSE 0 END AS TOTALBEHAVIOR,
	L.RATIOBEHAVIOR AS BASISBEHAVIOR,
	CASE WHEN A.APPSTATUS_ID>=50 THEN A.RATIOBEHAVIOR ELSE 0 END AS RATIOBEHAVIOR,
	DECODE(A.HEADERFINISHDATE,NULL,0,1) AS HEADERFINISH_ID,
	DECODE(A.SELFFINISHDATE,NULL,0,1) AS SELFFINISH_ID,
	A.SCOREINPUT,
	A.SCOREAPPROVE
FROM HR_EVAPP A
	INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
	LEFT JOIN VW_HR_STAFF_NAME H ON A.HR_STAFFHEADER_ID=H.ID
	INNER JOIN VW_HR_POSITION C ON A.HR_POSITION_ID=C.ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	INNER JOIN VW_HR_STAFFTYPE ST ON A.HR_STAFFTYPE_ID=ST.ID
	INNER JOIN HR_EVLOTWLPOS LP ON L.HR_EVLOTWL_ID=LP.HR_EVLOTWL_ID AND LP.HR_EVPOSITION_ID=A.HR_EVPOSITION_ID
WHERE A.GUID=fn_ss_parameter_gettext('VR_HR_EVAPP.HR_EVAPP_GUID');

-- ----------------------------
-- View structure for VR_HR_EVAPP_ORDER
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_ORDER" AS SELECT A.ID,
	A.HR_EVLOTAPP_ID,
	A.APPSTATUS_ID,
	A.BASE_PC AS RATIOACHIEVEMENT,--ร้อยละคะแนนผลสัมฤทธิ์ของงาน
	A.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
	A.BASE_PC+A.RATIOBEHAVIOR AS RATIOSCORE, --ร้อยละคะแนนรวมทั้งหมดที่ได้

	A.STAFFCODE,
	A.SNAME,
	A.SNAMEFULL,

	P.POSITIONCODE,
	P.POSITIONNAME,
	A.DEPARTMENTCODE,
	A.DEPARTMENTFULLNAME,
	A.EVPOSITIONCODE,
	A.EVPOSITIONNAME,
	A.ISACTIVE_ID,
	A.TOTALSCORE AS MAXSCORE,
	A.TOTALSCORE, --คะแนนเต็มแต่ละตำแหน่ง
	A.INPUTSCORE AS SCOREACTUAL, --คะแนนผลสัมฤทธิ์ของงานที่บันทึก
	A.SCOREGROUP AS SCORE, --คะแนนผลสัมฤทธิ์ของงานที่ได้
	A.SCORE AS SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
	A.BUDGETYEAR,
	A.EVLOTAPPNAME,
	B.LEVELNAME --ระดับคะแนนการประเมิน
FROM VR_HR_EVAPP_GROUP_RATIO A
	INNER JOIN HR_EVLOTSCOREITEM B ON A.HR_EVLOTSCOREITEM_ID=B.ID
	INNER JOIN VW_HR_POSITION P ON A.HR_POSITION_ID=P.ID;

-- ----------------------------
-- View structure for VR_HR_EVAPP_ORDER_BAK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_ORDER_BAK" AS SELECT A.ID,
	A.HR_EVLOTAPP_ID,
	A.APPSTATUS_ID,
	CASE WHEN NVL(WG.SCORE, 0)>L.TOTALSCORE THEN L.TOTALSCORE ELSE NVL(WG.SCORE, 0) END*90/ L.TOTALSCORE AS RATIOACHIEVEMENT,--ร้อยละคะแนนผลสัมฤทธิ์ของงาน
	A.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
	A.RATIOSCORE, --ร้อยละคะแนนรวมทั้งหมดที่ได้

	B.STAFFCODE,
	B.SNAME,
	B.SNAMEFULL,

	C.POSITIONCODE,
	C.POSITIONNAME,
	D.DEPARTMENTCODE,
	D.DEPARTMENTFULLNAME,
	E.EVPOSITIONCODE,
	E.EVPOSITIONNAME,
	E.ISACTIVE_ID,
	CAST(NVL(DECODE(SM.CONFIGVALUE,'1',LWP.MAXSCORE,L.TOTALSCORE), 0) AS NUMBER(15, 2)) AS MAXSCORE,
	L.TOTALSCORE, --คะแนนเต็มแต่ละตำแหน่ง
	CAST(NVL(WG.INPUTSCORE, 0) AS NUMBER(10, 2)) AS SCOREACTUAL, --คะแนนผลสัมฤทธิ์ของงานที่บันทึก
	CAST(NVL(WG.SCORE, 0) AS NUMBER(10, 2)) AS SCORE, --คะแนนผลสัมฤทธิ์ของงานที่ได้
	CASE WHEN NVL(WG.SCORE, 0)>L.TOTALSCORE THEN L.TOTALSCORE ELSE NVL(WG.SCORE, 0) END AS SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
	L.BUDGETYEAR,
	L.EVLOTAPPNAME,
	LS.LEVELNAME --ระดับคะแนนการประเมิน
FROM HR_EVAPP A
	INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
	INNER JOIN VW_HR_POSITION C ON A.HR_POSITION_ID=C.ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
	INNER JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID=E.ID
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	LEFT JOIN HR_EVLOTSCOREITEM LS ON A.HR_EVLOTSCOREITEM_ID=LS.ID
	LEFT JOIN
	 (SELECT HR_EVAPP_ID, SUM(SUM_WORKGROUPSCORE) AS SCORE,  SUM(SUM_TOTALSCORE) AS INPUTSCORE
	  FROM VW_HR_EVAPPWORK_SUMGROUP
	  GROUP BY HR_EVAPP_ID) WG ON A.ID=WG.HR_EVAPP_ID
	INNER JOIN
	(
		SELECT P.HR_EVLOTWL_ID, P.HR_EVPOSITION_ID, SUM(MAXSCORE) AS MAXSCORE
		FROM HR_EVLOTWLPOSGRP GG
			INNER JOIN HR_EVLOTWLPOS P ON GG.HR_EVLOTWLPOS_ID=P.ID
		GROUP BY P.HR_EVLOTWL_ID, P.HR_EVPOSITION_ID
	) LWP ON L.HR_EVLOTWL_ID=LWP.HR_EVLOTWL_ID AND A.HR_EVPOSITION_ID=LWP.HR_EVPOSITION_ID
	CROSS JOIN (SELECT * FROM SS_CONFIG WHERE CONFIGCODE='HR_EV.MAXSCORE.MODE') SM;

-- ----------------------------
-- View structure for VR_HR_EVAPP_PERSON
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_PERSON" AS SELECT A.HR_EVLOTAPP_ID,
	A.MT_DEPARTMENT_ID,
	A.POSITIONTYPE_ID,
	A.DEPARTMENTCODE,
	A.STAFFTYPECODE,
	A.STAFFTYPENAME,
	A.POSITIONTYPENAME,
	COUNT(ID) AS TOTAL,
	B.TOTAL AS GROUPTOTAL
FROM VR_HR_EVAPP_SCORE A
	INNER JOIN (
		SELECT HR_EVLOTAPP_ID, MT_DEPARTMENT_ID, POSITIONTYPE_ID,COUNT(ID) AS TOTAL
		FROM VR_HR_EVAPP_SCORE
		GROUP BY HR_EVLOTAPP_ID,MT_DEPARTMENT_ID,POSITIONTYPE_ID)
	B ON A.HR_EVLOTAPP_ID=B.HR_EVLOTAPP_ID AND A.MT_DEPARTMENT_ID=B.MT_DEPARTMENT_ID AND A.POSITIONTYPE_ID=B.POSITIONTYPE_ID
GROUP BY A.HR_EVLOTAPP_ID,
	A.MT_DEPARTMENT_ID,
	A.POSITIONTYPE_ID,
	A.POSITIONTYPENAME,
	A.DEPARTMENTCODE,
	A.STAFFTYPECODE,
	A.STAFFTYPENAME,
	B.TOTAL;

-- ----------------------------
-- View structure for VR_HR_EVAPP_PERSONACADEMIC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_PERSONACADEMIC" AS SELECT HR_EVLOTAPP_ID,
	MT_DEPARTMENT_ID,
	STAFFTYPECODE,
	STAFFTYPENAME,
	COUNT(ID) AS TOTAL
FROM VR_HR_EVAPP_SCOREACADEMIC
GROUP BY HR_EVLOTAPP_ID,
	MT_DEPARTMENT_ID,
	STAFFTYPECODE,
	STAFFTYPENAME;

-- ----------------------------
-- View structure for VR_HR_EVAPP_ROUND
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_ROUND" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	A.HR_EVLOTAPP_ID,
	DM.ID AS MT_DEPARTMENT_ID,
	L.ROUNDNO,
	L.DATEFROM,
	L.DATETO,
	DM.DEPARTMENTCODE,
	DM.DEPARTMENTNAME,
	ST.STAFFTYPECODE,
	ST.STAFFTYPENAME,
	E.POSITIONTYPE_ID,
	PT.BYTEDES AS POSITIONTYPENAME
FROM HR_EVAPP A
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
	INNER JOIN VW_MT_DEPARTMENT DM ON D.DEPARTMENTCODE1=DM.DEPARTMENTCODE
	INNER JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID=E.ID
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	INNER JOIN SS_BYTEDES PT ON PT.TABLENAME='HR_EVPOSITIONGROUP' AND PT.COLUMNNAME='POSITIONTYPE_ID' AND PT.BYTEID=E.POSITIONTYPE_ID
	INNER JOIN VW_HR_STAFFTYPE ST ON A.HR_STAFFTYPE_ID=ST.ID
--WHERE E.POSITIONTYPE_ID=2
GROUP BY
	A.HR_EVLOTAPP_ID,
	DM.ID,
	L.ROUNDNO,
	L.DATEFROM,
	L.DATETO,
	DM.DEPARTMENTCODE,
	DM.DEPARTMENTNAME,
	ST.STAFFTYPECODE,
	ST.STAFFTYPENAME,
	E.POSITIONTYPE_ID,
	PT.BYTEDES;

-- ----------------------------
-- View structure for VR_HR_EVAPP_ROUNDACADEMIC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_ROUNDACADEMIC" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	A.HR_EVLOTAPP_ID,
	DM.ID AS MT_DEPARTMENT_ID,
	L.ROUNDNO,
	L.DATEFROM,
	L.DATETO,
	DM.DEPARTMENTNAME
FROM HR_EVAPP A
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
	INNER JOIN VW_MT_DEPARTMENT DM ON D.DEPARTMENTCODE1=DM.DEPARTMENTCODE
	INNER JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID=E.ID
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
--WHERE E.POSITIONTYPE_ID=2
GROUP BY
	A.HR_EVLOTAPP_ID,
	DM.ID,
	L.ROUNDNO,
	L.DATEFROM,
	L.DATETO,
	DM.DEPARTMENTNAME;

-- ----------------------------
-- View structure for VR_HR_EVAPP_SCORE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_SCORE" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.HR_EVLOTAPP_ID,
	DM.ID AS MT_DEPARTMENT_ID,
	E.POSITIONTYPE_ID,
	PT.BYTEDES AS POSITIONTYPENAME,
	L.ROUNDNO,
	L.DATEFROM,
	L.DATETO,
	DM.DEPARTMENTCODE,
	DM.DEPARTMENTNAME,
	ST.STAFFTYPECODE,
	ST.STAFFTYPENAME,
	E.EVPOSITIONCODE,
	E.EVPOSITIONGROUPNAME,
	E.EVPOSITIONNAME,
	E.EVPOSITIONLEVELNAME,
	B.SNAME,
	B.SNAMEFULL,
	C.POSITIONCODE,
	C.POSITIONNAME,
	PL.LEVEL_NAME AS POSITIONLEVELNAME,
	D.DEPARTMENTCODE AS DEPARTMENTSUBCODE,
	D.DEPARTMENTNAME AS DEPARTMENTSUBNAME,
	L.TOTALSCORE/*G.SUM_SCORE */AS MAXSCORE,
	A.SCOREAPPROVE AS SUM_SCORE,
	--CASE WHEN G.SUM_SCORE>0 THEN ROUND(A.SCOREAPPROVE*100/G.SUM_SCORE,2) ELSE 0 END AS PERCENTAGE,
	CASE WHEN A.SCOREAPPROVE>=L.TOTALSCORE THEN 100 ELSE ROUND(A.SCOREAPPROVE*100/L.TOTALSCORE,2) END AS PERCENTAGE,
	SL.LEVELNAME,
	A.ORDERSCORE
FROM HR_EVAPP A
	LEFT JOIN VW_HR_EVLOTSCOREITEM SL ON A.HR_EVLOTSCOREITEM_ID=SL.ID
	INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
	INNER JOIN VW_HR_POSITION C ON A.HR_POSITION_ID=C.ID
	INNER JOIN VG_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.VALUE AND D.SS_APPLICATION_ID=160
	INNER JOIN VW_MT_DEPARTMENT DM ON D.DEPARTMENTCODE1=DM.DEPARTMENTCODE
	INNER JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID=E.ID
	LEFT JOIN PROMIS.POSITIONLEVEL PL ON C.HR_POSITIONLEVEL_ID=PL.POSITIONLEVELID
	INNER JOIN SS_BYTEDES PT ON PT.TABLENAME='HR_EVPOSITIONGROUP' AND PT.COLUMNNAME='POSITIONTYPE_ID' AND PT.BYTEID=E.POSITIONTYPE_ID
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	INNER JOIN VW_HR_STAFFTYPE ST ON A.HR_STAFFTYPE_ID=ST.ID
	INNER JOIN (
		SELECT LP.HR_EVLOTWL_ID, LP.HR_EVPOSITION_ID, SUM(LPG.MAXSCORE) AS SUM_SCORE
		FROM HR_EVLOTWLPOS LP --ON L.HR_EVLOTWL_ID=LP.HR_EVLOTWL_ID AND LP.HR_EVPOSITION_ID=A.HR_EVPOSITION_ID
				INNER JOIN HR_EVLOTWLPOSGRP LPG ON LP.ID=LPG.HR_EVLOTWLPOS_ID
		GROUP BY LP.HR_EVLOTWL_ID, LP.HR_EVPOSITION_ID
	) G ON L.HR_EVLOTWL_ID=G.HR_EVLOTWL_ID AND G.HR_EVPOSITION_ID=A.HR_EVPOSITION_ID
--WHERE E.POSITIONTYPE_ID=2;

-- ----------------------------
-- View structure for VR_HR_EVAPP_SCOREACADEMIC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVAPP_SCOREACADEMIC" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.HR_EVLOTAPP_ID,
	DM.ID AS MT_DEPARTMENT_ID,
	L.ROUNDNO,
	L.DATEFROM,
	L.DATETO,
	DM.DEPARTMENTNAME,
	ST.STAFFTYPECODE,
	ST.STAFFTYPENAME,
	C.POSITIONNAME,
	B.SNAME AS SNAMEFULL,
	E.POSITIONTYPE_ID,
	PT.BYTEDES AS POSITIONTYPENAME,
	G.SUM_SCORE AS MAXSCORE,
	CASE WHEN A.APPSTATUS_ID>=50 THEN A.SCOREAPPROVE ELSE 0 END AS SUM_SCORE,
	CASE WHEN G.SUM_SCORE>0 THEN ROUND(CASE WHEN A.APPSTATUS_ID>=50 THEN A.SCOREAPPROVE ELSE 0 END*100/G.SUM_SCORE,2) ELSE 0 END AS PERCENTAGE,
	A.ORDERSCORE
FROM HR_EVAPP A
	INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
	INNER JOIN VW_HR_POSITION C ON A.HR_POSITION_ID=C.ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
	INNER JOIN VW_MT_DEPARTMENT DM ON D.DEPARTMENTCODE1=DM.DEPARTMENTCODE
	INNER JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID=E.ID
	INNER JOIN SS_BYTEDES PT ON PT.TABLENAME='HR_EVPOSITIONGROUP' AND PT.COLUMNNAME='POSITIONTYPE_ID' AND PT.BYTEID=E.POSITIONTYPE_ID
	INNER JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID=L.ID
	INNER JOIN VW_HR_STAFFTYPE ST ON A.HR_STAFFTYPE_ID=ST.ID
	INNER JOIN (
		SELECT LP.HR_EVLOTWL_ID, LP.HR_EVPOSITION_ID, SUM(LPG.MAXSCORE) AS SUM_SCORE
		FROM HR_EVLOTWLPOS LP --ON L.HR_EVLOTWL_ID=LP.HR_EVLOTWL_ID AND LP.HR_EVPOSITION_ID=A.HR_EVPOSITION_ID
				INNER JOIN HR_EVLOTWLPOSGRP LPG ON LP.ID=LPG.HR_EVLOTWLPOS_ID
		GROUP BY LP.HR_EVLOTWL_ID, LP.HR_EVPOSITION_ID
	) G ON L.HR_EVLOTWL_ID=G.HR_EVLOTWL_ID AND G.HR_EVPOSITION_ID=A.HR_EVPOSITION_ID
--WHERE E.POSITIONTYPE_ID=2;

-- ----------------------------
-- View structure for VR_HR_EVCOMMANDKEY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVCOMMANDKEY" AS SELECT B.ID,
	B.HR_EVCOMMAND_ID,
	A.BUDGETYEAR,
	A.COMMANDNAME,
	B.LOTCODE,
	'"' || B.SECRETKEY || '"' AS SECRETKEY,
	A.REGISTERURL,
	NVL(C.COMMANDTYPENAMESHOW, C.COMMANDTYPENAME) AS COMMANDTYPE
FROM VW_HR_EVCOMMAND A
	INNER JOIN HR_EVCOMMANDKEY B ON A.ID=B.HR_EVCOMMAND_ID
	INNER JOIN HR_EVCOMMANDTYPE C ON A.HR_EVCOMMANDTYPE_ID=C.ID
WHERE B.ISACTIVE_ID=0;

-- ----------------------------
-- View structure for VR_HR_EVLOTWLPOS
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVLOTWLPOS" AS SELECT A.ID,
	A.GUID,
	A.EVLOTWLCODE,
	A.EVLOTWLNAME,
	A.EVPOSITIONCODE,
	A.EVPOSITIONNAME,
	B.HR_EVLOTWLPOS_ID,
	B.GROUPORDERNO,
	B.WORKGROUPNAME,
	B.GROUPMAXSCORE,
	B.ORDERNO AS WORKORDERNO,
	B.MAINORDER,
	B.MAINNAME,
	B.WORKNAME,
	B.MINTOTAL,
	B.DISPLAY_EACHSCORE,
	B.MAXSCORE,
	B.FILENAME
FROM VW_HR_EVLOTWLPOS A
	INNER JOIN VW_HR_EVLOTWLPOSGRPWL B ON A.ID=B.HR_EVLOTWLPOS_ID;

-- ----------------------------
-- View structure for VR_HR_EVPROJECTKEY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVPROJECTKEY" AS SELECT B.ID,
	B.HR_EVPROJECT_ID,
	A.BUDGETYEAR,
	A.PROJECTNAME,
	B.LOTCODE,
	'"' || B.SECRETKEY || '"' AS SECRETKEY,
	A.REGISTERURL,
	A.REGISTERDESC,
	NVL(C.PROJECTTYPENAMESHOW, C.PROJECTTYPENAME) AS PROJECTTYPE
FROM VW_HR_EVPROJECT A
	INNER JOIN HR_EVPROJECTKEY B ON A.ID=B.HR_EVPROJECT_ID
	INNER JOIN HR_EVPROJECTTYPE C ON A.HR_EVPROJECTTYPE_ID=C.ID
WHERE B.ISACTIVE_ID=0;

-- ----------------------------
-- View structure for VR_HR_EVPROJECTMEMBER_APP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVPROJECTMEMBER_APP" AS SELECT A.ID,
	A.ORDERNO,
	A.HR_STAFF_ID,
	A.HR_EVPRJPOSITION_ID,
	A.PROPORTION,
	A.HR_EVPROJECTKEY_ID,
	A.HR_EVPROJECT_ID,

	A.STAFFCODE,
	A.STAFFSTATUSNAME,
	A.SNAME,
	A.SNAMEENG,
	A.SNAMEFULL,
	A.SNAMEFULLENG,
	A.MT_DEPARTMENT_ID,
	A.PRJPOSITIONNAME,
	A.BUDGETYEAR,
	A.PROJECTNAME,
	A.PROJECTSTATUSNAME,
	A.PROJECTGUID,
	A.WORKTYPE_ID,
	A.PLACE,
	A.PERIOD,
	A.SCORE,
	A.ISACTIVE_ID,
	A.ISSUBMITAPP_ID,
	A.DEPARTMENTCODE,
	A.DEPARTMENTNAME,
	A.DEPARTMENTFULLNAME,
	A.PROJECTTYPECODE,
	A.PROJECTTYPENAME,
	A.POSITIONNAME,
	A.MEMBERDATETIME,
	AP.HR_EVLOTAPP_ID
FROM VW_HR_EVPROJECTMEMBER A
	INNER JOIN HR_EVAPPWORK AW ON A.ID=AW.HR_EVPROJECTMEMBER_ID
	INNER JOIN HR_EVAPP AP ON AW.HR_EVAPP_ID=AP.ID;

-- ----------------------------
-- View structure for VR_HR_EVPROJECT_STAFFSUM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVPROJECT_STAFFSUM" AS SELECT
	A.STAFFCODE,
	A.SNAME,
	A.SNAMEFULL,
	A.POSITIONNAME,
	A.DEPARTMENTCODE,
	A.DEPARTMENTNAME,
	A.DEPARTMENTFULLNAME,

	A.HR_EVLOTAPP_ID,
	COUNT(A.ID) AS TOTALPROJECT
FROM VR_HR_EVPROJECTMEMBER_APP A
WHERE A.ISACTIVE_ID=1
GROUP BY
	A.STAFFCODE,
	A.SNAME,
	A.SNAMEFULL,
	A.POSITIONNAME,
	A.DEPARTMENTCODE,
	A.DEPARTMENTNAME,
	A.DEPARTMENTFULLNAME,

	A.HR_EVLOTAPP_ID;

-- ----------------------------
-- View structure for VR_HR_EVPROJECT_SUM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VR_HR_EVPROJECT_SUM" AS SELECT A.ID,
	A.BUDGETYEAR,
	A.HR_EVPROJECTTYPE_ID,
	B.PROJECTTYPENAME,
	A.PROJECTNAME,
	A.SCORE,
	A.PROJECTSTATUS_ID,
	CAST(NVL(M.CNT_MEMBER,0) AS NUMBER(6)) AS CNT_MEMBER,
	B.PROJECTTYPECODE,
	D1.DEPARTMENTCODE AS DEPARTMENTCODE1,
	D2.DEPARTMENTCODE AS DEPARTMENTCODE2
FROM VW_HR_EVPROJECT A
	INNER JOIN HR_EVPROJECTTYPE B ON A.HR_EVPROJECTTYPE_ID=B.ID
	INNER JOIN VG_MT_DEPARTMENT D1 ON A.MT_DEPARTMENT1_ID=D1.VALUE AND D1.SS_APPLICATION_ID=160
	LEFT JOIN VG_MT_DEPARTMENT D2 ON A.MT_DEPARTMENT2_ID=D2.VALUE AND D2.SS_APPLICATION_ID=160
	LEFT JOIN (SELECT HR_EVPROJECT_ID, COUNT(ID) AS CNT_MEMBER FROM HR_EVPROJECTMEMBER GROUP BY HR_EVPROJECT_ID) M ON A.ID=M.HR_EVPROJECT_ID;

-- ----------------------------
-- View structure for VW_AC_ACCOUNT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_AC_ACCOUNT" AS SELECT ACCOUNTID AS ID,
  ACCOUNTNAME,
  BANKCODE,
  ACCOUNTLEVEL
FROM PROMIS.ACCOUNT A;

-- ----------------------------
-- View structure for VW_AC_BOOK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_AC_BOOK" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
  A.BOOKCODE,
  A.BOOKNAME,
  A.BOOKNAMEENG,
    A.REFID1NAME,
    A.REFID2NAME,
    A.REFDATE1NAME,
    A.REFDATE2NAME,
  A.REFAMOUNT1NAME,
    A.REFAMOUNT2NAME,
    A.CAMPUSID AS MT_CAMPUS_ID,
    A.SORTBY AS ORDERNO
FROM PROMIS.GLBOOK A;

-- ----------------------------
-- View structure for VW_BG_ACCOUNTTYPE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_ACCOUNTTYPE" AS SELECT A.ACCOUNTTYPEID AS ID,
	A.ACCOUNTTYPECODE,
	A.ACCOUNTTYPENAME,
	A.ACCOUNTTYPENAMEENG,
	CAST(A.INVESTMENTFLAG AS NUMBER(2)) AS INVESTMENTTYPE_ID,
	--DECODE(A.INVESTMENTFLAG,3,1,0) AS ISREQUIREFILE_ID,
	0 AS ISREQUIREFILE_ID,

	B.BYTEORDER AS INVESTMENTTYPEORDER,
	B.BYTECODE AS INVESTMENTTYPECODE,
	B.BYTEDES AS INVESTMENTTYPENAME,
	B.BYTEDESENG AS INVESTMENTTYPENAMEENG
FROM PROMIS.ACCOUNTTYPE A
	INNER JOIN VW_MIS_BYTEDES B ON A.INVESTMENTFLAG=B.BYTECODE AND B.TABLENAME='ACCOUNTTYPE' AND B.COLUMNNAME='INVESTMENTFLAG';

-- ----------------------------
-- View structure for VW_BG_ACTIVITY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_ACTIVITY" AS SELECT A.ACTIVITYID AS ID,
	A.ACTIVITYCODE,
	A.ACTIVITYNAME,
	A.ACTIVITYNAMEENG,
	A.DEPARTMENTID AS MT_DEPARTMENT_ID
FROM PROMIS.ACTIVITY A;

-- ----------------------------
-- View structure for VW_BG_BUDGET
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_BUDGET" AS SELECT A.BUDGETID AS ID,
	A.BUDGETCODE,
	A.BUDGETNAME,
	A.BP_PERIODAPPACTEXP_ID
FROM PROMIS.BUDGET A;

-- ----------------------------
-- View structure for VW_BG_BUDGETGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_BUDGETGROUP" AS SELECT A.BUDGETGROUPID AS ID,
	   A.BUDGETGROUPCODE,
	   A.BUDGETGROUPNAME,
	   A.BUDGETGROUPNAMEENG,
	   A.BUDGETTYPE AS BUDGETGROUPTYPE_ID,
	   --A.GROUPTYPE AS GROUPTYPE_ID,
	   --A.FORPLANID AS FORPLAN_ID,
	   A.BUDGETGROUPLEVEL AS LEVEL_ID,
	   A.SORTBY,

	   BT.BYTECODE AS BUDGETGROUPTYPECODE,
	   BT.BYTEDES AS BUDGETGROUPTYPENAME,
	   BT.BYTEDESENG AS BUDGETGROUPTYPENAMEENG

--GT.BYTECODE AS GROUPTYPECODE,
--GT.BYTEDES AS GROUPTYPENAME,

/*CASE
    WHEN NVL(A.SHOWFLAG, 'Y') = 'Y' THEN
     1
    ELSE
     0
END AS ISACTIVE_ID*/
FROM PROMIS.BUDGETGROUP A
INNER JOIN (SELECT *
			FROM VW_MIS_BYTEDES
			WHERE TABLENAME = 'BUDGETGROUP'
				  AND COLUMNNAME = 'BUDGETTYPE') BT ON TO_CHAR(A.BUDGETTYPE) = BT.BYTECODE
--INNER JOIN (SELECT * FROM VW_MIS_BYTEDES WHERE TABLENAME='BUDGETGROUP' AND COLUMNNAME='GROUPTYPE') GT ON TO_CHAR(A.GROUPTYPE)=GT.BYTECODE;

-- ----------------------------
-- View structure for VW_BG_PERIOD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_PERIOD" AS SELECT A.BUDGETPERIODID AS ID,
       A.VALIDDATEFROM,
       A.VALIDDATETO,
       A.BUDGETPERIODSTATUS
FROM   PROMIS.BUDGETPERIOD@MISLINK A;

-- ----------------------------
-- View structure for VW_BG_PLAN
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_PLAN" AS SELECT A.PLANID AS ID,
	A.PLANCODE,
	A.PLANNAME,
	A.PLANNAMEENG,
	DECODE(A.ISACTIVE_ID,0,0,-1,1) AS ISACTIVE_ID
FROM PROMIS.PLAN A;

-- ----------------------------
-- View structure for VW_BG_PLANPRD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_PLANPRD" AS SELECT A.PRODUCTID AS ID,
	A.PRODUCTCODE,
	A.PRODUCTNAME,
	A.PLANID AS BG_PLAN_ID
FROM PROMIS.PRODUCT A;

-- ----------------------------
-- View structure for VW_BG_PLANPRDPRJ
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_PLANPRDPRJ" AS SELECT A.PROJECTID AS ID,
	A.PROJECTCODE,
	A.PROJECTNAME,
	A.PRODUCTID AS BG_PLANPRD_ID,
	A.STRATEGYUID AS BG_USTRATEGY_ID,
	A.PLANUID AS BG_UPLAN_ID,
	A.DEPARTMENTID AS MT_DEPARTMENT_ID
FROM PROMIS.PROJECT A;

-- ----------------------------
-- View structure for VW_BG_PLANPRDPRJACT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_PLANPRDPRJACT" AS SELECT A.PROJECTACTIVITYID AS ID,
	A.PROJECTID AS BG_PLANPRDPRJ_ID,
	A.ACTIVITYID AS BG_ACTIVITY_ID,
	B.ACTIVITYCODE,
	B.ACTIVITYNAME,
	B.ACTIVITYNAMEENG,
	B.MT_DEPARTMENT_ID
FROM PROMIS.PROJECTACTIVITY A
	INNER JOIN VW_BG_ACTIVITY B ON A.ACTIVITYID=B.ID
	INNER JOIN VW_BG_PLANPRDPRJ C ON A.PROJECTID=C.ID AND B.MT_DEPARTMENT_ID=C.MT_DEPARTMENT_ID;

-- ----------------------------
-- View structure for VW_BG_ST
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_ST" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.BUDGETGROUPID AS BG_BUDGETGROUP_ID,
	A.BUDGETPERIODID AS BUDGETYEAR,
	SP.PLANID AS BG_PLAN_ID,
	PD.PRODUCTID AS BG_PRODUCT_ID,
	PD.PRODUCTCODE,
	PD.PRODUCTNAME,
	SPPP.PROJECTID AS BG_PROJECT_ID,
	P.PROJECTCODE,
	P.PROJECTNAME,
	P.DEPARTMENTID AS MT_DEPARTMENT_ID,
	SPPPA.ACTIVITYID AS BG_ACTIVITY_ID
FROM PROMIS.BUDGETPERIOD A
	INNER JOIN PROMIS.BUDGETSTRUCPLAN SP ON A.BUDGETGROUPID=SP.BUDGETGROUPID AND A.BUDGETPERIODID=SP.BUDGETPERIODID
	INNER JOIN PROMIS.BUDGETSTRUCPRODUCT SPP ON SP.BUDGETSTRUCPLANID=SPP.BUDGETSTRUCPLANID
	INNER JOIN PROMIS.PRODUCT PD ON SPP.PRODUCTID=PD.PRODUCTID
	INNER JOIN PROMIS.BUDGETSTRUCPROJECT SPPP ON SP.BUDGETSTRUCPLANID=SPPP.BUDGETSTRUCPLANID AND SPPP.PRODUCTID=PD.PRODUCTID
	INNER JOIN PROMIS.PROJECT P ON SPPP.PROJECTID=P.PROJECTID
	INNER JOIN  PROMIS.BUDGETSTRUCPROJECTACTIVITY SPPPA ON SPPP.BUDGETSTRUCPROJECTID=SPPPA.BUDGETSTRUCPROJECTID;

-- ----------------------------
-- View structure for VW_BG_STBGGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_STBGGROUP" AS SELECT CAST(MIN(ID) AS NUMBER(12)) AS ID,
	A.BG_BUDGETGROUP_ID,
	B.BUDGETGROUPCODE,
	B.BUDGETGROUPNAME,
	B.SORTBY AS SORTORDER,
	A.BUDGETYEAR
FROM VW_BG_ST A
	INNER JOIN PROMIS.BUDGETGROUP B ON A.BG_BUDGETGROUP_ID=B.BUDGETGROUPID
GROUP BY A.BG_BUDGETGROUP_ID,
	B.BUDGETGROUPCODE,
	B.BUDGETGROUPNAME,
	B.SORTBY,
	A.BUDGETYEAR;

-- ----------------------------
-- View structure for VW_BG_STBGGROUPDEPT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_STBGGROUPDEPT" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.DEPARTMENTID AS MT_DEPARTMENT_ID,
	B.DEPARTMENTCODE,
	B.DEPARTMENTNAME,
	A.BUDGETPERIODID AS BUDGETYEAR,
	A.BUDGETGROUPID AS BG_BUDGETGROUP_ID
FROM PROMIS.BUDGETSTRUCDEPARTMENT A
	INNER JOIN VW_MT_DEPARTMENT B ON A.DEPARTMENTID=B.ID;

-- ----------------------------
-- View structure for VW_BG_STBGGROUPPLAN
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_STBGGROUPPLAN" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	A.BG_PLAN_ID,
	B.PLANCODE,
	B.PLANNAME,
	A.BUDGETYEAR,
	A.BG_BUDGETGROUP_ID,
	D.DEPARTMENTCODE
FROM VW_BG_ST A
	INNER JOIN VW_BG_PLAN B ON A.BG_PLAN_ID=B.ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
GROUP BY
	A.BG_PLAN_ID,
	B.PLANCODE,
	B.PLANNAME,
	A.BUDGETYEAR,
	A.BG_BUDGETGROUP_ID,
	D.DEPARTMENTCODE;

-- ----------------------------
-- View structure for VW_BG_STBGGROUPPLANPRD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_STBGGROUPPLANPRD" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	A.BG_PRODUCT_ID,
	A.PRODUCTCODE,
	A.PRODUCTNAME,
	A.BUDGETYEAR,
	A.BG_BUDGETGROUP_ID,
	A.BG_PLAN_ID,
	D.DEPARTMENTCODE
FROM VW_BG_ST A
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
GROUP BY A.BG_PRODUCT_ID,
	A.PRODUCTCODE,
	A.PRODUCTNAME,
	A.BUDGETYEAR,
	A.BG_BUDGETGROUP_ID,
	A.BG_PLAN_ID,
	D.DEPARTMENTCODE;

-- ----------------------------
-- View structure for VW_BG_STBGGROUPPLANPRDPRJ
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_STBGGROUPPLANPRDPRJ" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	A.BG_PROJECT_ID,
	A.PROJECTCODE,
	A.PROJECTNAME,
	A.BUDGETYEAR,
	A.BG_BUDGETGROUP_ID,
	A.BG_PLAN_ID,
	A.BG_PRODUCT_ID,
	D.DEPARTMENTCODE
FROM VW_BG_ST A
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
GROUP BY A.BG_PROJECT_ID,
	A.PROJECTCODE,
	A.PROJECTNAME,
	A.BUDGETYEAR,
	A.BG_BUDGETGROUP_ID,
	A.BG_PLAN_ID,
	A.BG_PRODUCT_ID,
	D.DEPARTMENTCODE;

-- ----------------------------
-- View structure for VW_BG_STBGGROUPPLANPRDPRJACT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_STBGGROUPPLANPRDPRJACT" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	A.BG_ACTIVITY_ID,
	B.ACTIVITYCODE,
	B.ACTIVITYNAME,
	A.BUDGETYEAR,
	A.BG_BUDGETGROUP_ID,
	A.BG_PLAN_ID,
	A.BG_PRODUCT_ID,
	A.BG_PROJECT_ID,
	D.DEPARTMENTCODE
FROM VW_BG_ST A
	INNER JOIN PROMIS.ACTIVITY B ON A.BG_ACTIVITY_ID=B.ACTIVITYID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
GROUP BY A.BG_ACTIVITY_ID,
	B.ACTIVITYCODE,
	B.ACTIVITYNAME,
	A.BUDGETYEAR,
	A.BG_BUDGETGROUP_ID,
	A.BG_PLAN_ID,
	A.BG_PRODUCT_ID,
	A.BG_PROJECT_ID,
	D.DEPARTMENTCODE;

-- ----------------------------
-- View structure for VW_BG_UPLAN
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_UPLAN" AS SELECT A.PLANUID AS ID,
	A.PLANUCODE AS UPLANCODE,
	A.PLANUNAME AS UPLANNAME,
	A.SORTBY
FROM PROMIS.PLANU A;

-- ----------------------------
-- View structure for VW_BG_USTRATEGY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_USTRATEGY" AS SELECT A.STRATEGYUID AS ID,
	A.STRATEGYUCODE AS USTRATEGYCODE,
	A.STRATEGYUNAME AS USTRATEGYNAME,
	A.SORTBY,
	DECODE(A.ISACTIVE_ID,0,0,-1,1) AS ISACTIVE_ID
FROM PROMIS.STRATEGYU A;

-- ----------------------------
-- View structure for VW_BG_USTRATEGYPLAN
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BG_USTRATEGYPLAN" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	B.PLANUID AS BG_UPLAN_ID,
	B.PLANUCODE AS UPLANCODE,
	B.PLANUNAME AS UPLANNAME,
	B.SORTBY,
	A.STRATEGYUID AS BG_USTRATEGY_ID
FROM PROMIS.STRATEGYPLANU A
	INNER JOIN PROMIS.PLANU B ON A.PLANUID=B.PLANUID;

-- ----------------------------
-- View structure for VW_BP_BGGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_BGGROUP" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID, A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, B.BUDGETGROUPCODE, B.BUDGETGROUPNAME
FROM BP_PERIODAPP A
	INNER JOIN VW_BG_BUDGETGROUP B ON A.BG_BUDGETGROUP_ID=B.ID
GROUP BY A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, B.BUDGETGROUPCODE, B.BUDGETGROUPNAME;

-- ----------------------------
-- View structure for VW_BP_BGGROUPPLAN
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_BGGROUPPLAN" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID, A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.BG_PLAN_ID, B.PLANCODE, B.PLANNAME, D.DEPARTMENTCODE
FROM BP_PERIODAPP A
	INNER JOIN VW_BG_PLAN B ON A.BG_PLAN_ID=B.ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
GROUP BY A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.BG_PLAN_ID, B.PLANCODE, B.PLANNAME, D.DEPARTMENTCODE;

-- ----------------------------
-- View structure for VW_BP_BGGROUPPLANPRD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_BGGROUPPLANPRD" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID, A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.BG_PLAN_ID, A.BG_PLANPRD_ID AS BG_PRODUCT_ID, B.PRODUCTCODE, B.PRODUCTNAME, D.DEPARTMENTCODE
FROM BP_PERIODAPP A
	INNER JOIN VW_BG_PLANPRD B ON A.BG_PLANPRD_ID=B.ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
GROUP BY A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.BG_PLAN_ID, A.BG_PLANPRD_ID, B.PRODUCTCODE, B.PRODUCTNAME, D.DEPARTMENTCODE;

-- ----------------------------
-- View structure for VW_BP_BGGROUPPLANPRDPRJ
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_BGGROUPPLANPRDPRJ" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID, A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.BG_PLAN_ID, A.BG_PLANPRD_ID AS BG_PRODUCT_ID, D.DEPARTMENTCODE, A.BG_PLANPRDPRJ_ID AS BG_PROJECT_ID, B.PROJECTCODE, B.PROJECTNAME
FROM BP_PERIODAPP A
	INNER JOIN VW_BG_PLANPRDPRJ B ON A.BG_PLANPRDPRJ_ID=B.ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
GROUP BY A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.BG_PLAN_ID, A.BG_PLANPRD_ID, D.DEPARTMENTCODE, A.BG_PLANPRDPRJ_ID, B.PROJECTCODE, B.PROJECTNAME;

-- ----------------------------
-- View structure for VW_BP_BGGROUPPLANPRDPRJACT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_BGGROUPPLANPRDPRJACT" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID, A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.BG_PLAN_ID, A.BG_PLANPRD_ID AS BG_PRODUCT_ID, D.DEPARTMENTCODE, A.BG_PLANPRDPRJ_ID AS BG_PROJECT_ID, B.BG_ACTIVITY_ID, B.ACTIVITYCODE, B.ACTIVITYNAME
FROM BP_PERIODAPP A
	INNER JOIN VW_BP_PERIODAPPACT B ON A.ID=B.BP_PERIODAPP_ID
	INNER JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID=D.ID
GROUP BY A.BUDGETYEAR, A.BG_BUDGETGROUP_ID, A.BG_PLAN_ID, A.BG_PLANPRD_ID, D.DEPARTMENTCODE, A.BG_PLANPRDPRJ_ID, B.BG_ACTIVITY_ID, B.ACTIVITYCODE, B.ACTIVITYNAME;

-- ----------------------------
-- View structure for VW_BP_BUDGETGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_BUDGETGROUP" AS SELECT A.ID,
	   A.BG_BUDGETGROUP_ID,
	   A.BUDGETTYPE_ID,

	   B.BUDGETGROUPCODE,
	   B.BUDGETGROUPNAME,
	   B.BUDGETGROUPNAMEENG,
	   B.BUDGETGROUPTYPE_ID,
	   B.SORTBY,

	   C.BYTECODE AS BUDGETTYPECODE,
	   C.BYTEDES AS BUDGETTYPENAME,
	   C.BYTEDESENG AS BUDGETTYPENAMEENG
FROM BP_BUDGETGROUP A,
	 VW_BG_BUDGETGROUP B,
	 (SELECT *
	  FROM SS_BYTEDES
	  WHERE TABLENAME = 'BP_BUDGETGROUP'
			AND COLUMNNAME = 'BUDGETTYPE_ID') C
WHERE A.BG_BUDGETGROUP_ID = B.ID
	  AND A.BUDGETTYPE_ID = C.BYTEID(+) AND B.LEVEL_ID=4;

-- ----------------------------
-- View structure for VW_BP_KPIACTIVITY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_KPIACTIVITY" AS SELECT A.ID,
	A.KPIACTIVITYCODE,
  A.KPIACTIVITYNAME,
  A.MT_DEPARTMENT_ID,
  A.UNIT,
  A.CREATEDATETIME,
  A.CREATEBY,
  A.UPDATEDATETIME,
  A.UPDATEBY
FROM BP_KPIACTIVITY A;

-- ----------------------------
-- View structure for VW_BP_LOTINDICATORITEM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_LOTINDICATORITEM" AS SELECT A.ID,
	A.INDICATORCODE,
  A.INDICATORLEVEL_ID,
  A.INDICATORNAME,
  A.BP_LOTINDICATOR_ID,
  A.CREATEDATETIME,
  A.CREATEBY,
  A.UPDATEDATETIME,
  A.UPDATEBY
FROM BP_LOTINDICATORITEM A;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACT" AS SELECT A.ID,
	A.BP_PERIODAPP_ID,
  A.ORDERNO,
  A.BG_PLANPRDPRJACT_ID,
  A.PERSON,
  A.USEBUDGET_ID,
	B.BG_ACTIVITY_ID,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG
FROM BP_PERIODAPPACT A,
	VW_BG_PLANPRDPRJACT B
WHERE A.BG_PLANPRDPRJACT_ID=B.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTBENEFIT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTBENEFIT" AS SELECT A.ID,
	A.BP_PERIODAPPACT_ID,
  A.ORDERNO,
  A.BENEFIT,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG,
  B.ORDERNO AS ACTIVITYORDER,
  B.BP_PERIODAPP_ID
FROM BP_PERIODAPPACTBENEFIT A,
	VW_BP_PERIODAPPACT B
WHERE A.BP_PERIODAPPACT_ID=B.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTBUDQTR
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTBUDQTR" AS SELECT A.ID,
	A.BP_PERIODAPPACT_ID,
  A.QUATER1,
  A.QUATER2,
  A.QUATER3,
  A.QUATER4,
  A.TOTAL,
  A.MONTH01,
  A.MONTH02,
  A.MONTH03,
  A.MONTH04,
  A.MONTH05,
  A.MONTH06,
  A.MONTH07,
  A.MONTH08,
  A.MONTH09,
  A.MONTH10,
  A.MONTH11,
  A.MONTH12,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG,
  B.ORDERNO AS ACTIVITYORDER,
  B.BP_PERIODAPP_ID
FROM BP_PERIODAPPACTBUDQTR A,
	VW_BP_PERIODAPPACT B
WHERE A.BP_PERIODAPPACT_ID=B.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTEXP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTEXP" AS SELECT A.ID,
	   A.BP_PERIODAPPACT_ID,
	   A.ORDERNO,
	   A.BG_ACCOUNTTYPE_ID,
	   A.EXPENSE,
	   A.TOTAL,
	   A.MONTH01,
	   A.MONTH02,
	   A.MONTH03,
	   A.MONTH04,
	   A.MONTH05,
	   A.MONTH06,
	   A.MONTH07,
	   A.MONTH08,
	   A.MONTH09,
	   A.MONTH10,
	   A.MONTH11,
	   A.MONTH12,
	   A.BG_BUDGET_ID,
	   A.REFCODE,
	   A.STRUCTYPE_CODE,
	   B.ACTIVITYCODE,
	   B.ACTIVITYNAME,
	   B.ACTIVITYNAMEENG,
	   B.ORDERNO AS ACTIVITYORDER,
	   E.ACCOUNTTYPECODE,
	   E.ACCOUNTTYPENAME,
	   E.ACCOUNTTYPENAMEENG,
	   E.INVESTMENTTYPEORDER,
	   E.INVESTMENTTYPECODE,
	   E.INVESTMENTTYPENAME,
	   E.INVESTMENTTYPENAMEENG,
	   B.BP_PERIODAPP_ID,
	   G.BYTEORDER AS STUCTYPEORDER,
	   G.BYTECODE AS STUCTYPECODE,
	   G.BYTEDES AS STUCTYPENAME,
	   G.BYTEDESENG AS STUCTYPENAMEENG,
	   NVL(H.CNT, 0) AS HASFILE_ID,
	   E.ISREQUIREFILE_ID
FROM BP_PERIODAPPACTEXP A,
	 VW_BP_PERIODAPPACT B,
	 VW_BG_ACCOUNTTYPE E,
	 (SELECT *
	  FROM VW_MIS_BYTEDES
	  WHERE TABLENAME = 'BUDGET'
			AND COLUMNNAME = 'BUDGETSTATUS') G,
	 (SELECT BP_PERIODAPPACTEXP_ID,
			 COUNT(ID) AS CNT
	  FROM BP_PERIODAPPACTEXPFILE
	  GROUP BY BP_PERIODAPPACTEXP_ID) H
WHERE A.BP_PERIODAPPACT_ID = B.ID
	  AND A.BG_ACCOUNTTYPE_ID = E.ID
	  AND A.STRUCTYPE_CODE = G.BYTECODE
	  AND A.ID = H.BP_PERIODAPPACTEXP_ID(+);

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTEXPFILE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTEXPFILE" AS SELECT A.ID,
	A.BP_PERIODAPPACTEXP_ID,
	A.ORDERNO,
	A.FL_STORAGE_ID,
	A.DESCRIPTION,

	B.FILENAME,
	B.GUID AS FILEGUID
FROM BP_PERIODAPPACTEXPFILE A,
	FL_STORAGE B
WHERE A.FL_STORAGE_ID=B.ID(+);

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTEXPITEM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTEXPITEM" AS SELECT A.ID,
	A.BP_PERIODAPPACTEXP_ID,
  A.ORDERNO,
  A.EXPENSE,
  A.TOTAL,
  A.MONTH01,
  A.MONTH02,
  A.MONTH03,
  A.MONTH04,
  A.MONTH05,
  A.MONTH06,
  A.MONTH07,
  A.MONTH08,
  A.MONTH09,
  A.MONTH10,
  A.MONTH11,
  A.MONTH12,
  A.REMARK,
  B.ORDERNO AS EXPORDERNO,
  B.EXPENSE AS EXPEXPENSE,
  B.TOTAL AS EXPTOTAL,
  B.BG_BUDGET_ID,
  B.REFCODE,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG,
  B.ACTIVITYORDER,
  B.ACCOUNTTYPECODE,
  B.ACCOUNTTYPENAME,
  B.ACCOUNTTYPENAMEENG,
  B.INVESTMENTTYPEORDER,
  B.INVESTMENTTYPECODE,
  B.INVESTMENTTYPENAME,
  B.INVESTMENTTYPENAMEENG,
  B.BP_PERIODAPP_ID,
  B.BP_PERIODAPPACT_ID
FROM BP_PERIODAPPACTEXPITEM A,
	VW_BP_PERIODAPPACTEXP B
WHERE A.BP_PERIODAPPACTEXP_ID=B.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTKPI
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTKPI" AS SELECT A.ID,
	A.BP_PERIODAPPACT_ID,
	A.ORDERNO,
  A.BP_PERIODKPIACTIVITY_ID,
  A.TARGET,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG,
  B.ORDERNO AS ACTIVITYORDER,
  C.KPIACTIVITYCODE,
  C.KPIACTIVITYNAME,
  C.KPIGROUPCODE,
  C.KPIGROUPNAME,
  C.KPIGROUPNAMEENG,
  C.KPIGROUPORDER,
  C.KPITYPECODE,
  C.KPITYPENAME,
  C.KPITYPENAMEENG,
  C.KPITYPEORDER,
  C.UNIT,
  B.BP_PERIODAPP_ID
FROM BP_PERIODAPPACTKPI A,
	VW_BP_PERIODAPPACT B,
  VW_BP_PERIODKPIACTIVITY C
WHERE A.BP_PERIODAPPACT_ID=B.ID
  AND A.BP_PERIODKPIACTIVITY_ID=C.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTMONITOR
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTMONITOR" AS SELECT A.ID,
	   A.BP_PERIODAPPACT_ID,
	   A.ORDERNO,
	   A.METHOD,
	   A.TOOLS,
	   B.ORDERNO AS ACTIVITYORDER,
	   B.ACTIVITYCODE,
	   B.ACTIVITYNAME,
	   B.BP_PERIODAPP_ID
FROM BP_PERIODAPPACTMONITOR A
INNER JOIN VW_BP_PERIODAPPACT B ON A.BP_PERIODAPPACT_ID = B.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTRISK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTRISK" AS SELECT A.ID,
	A.BP_PERIODAPPACT_ID,
  A.ORDERNO,
  A.RISK,
  A.SOLUTION,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG,
  B.ORDERNO AS ACTIVITYORDER,
  B.BP_PERIODAPP_ID
FROM BP_PERIODAPPACTRISK A,
	VW_BP_PERIODAPPACT B
WHERE A.BP_PERIODAPPACT_ID=B.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTSTEP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTSTEP" AS SELECT A.ID,
	A.BP_PERIODAPPACT_ID,
  A.STEPTYPE_ID,
  A.ORDERNO,
  A.PROCESS,
  A.MONTH01_ID,
  A.MONTH02_ID,
  A.MONTH03_ID,
  A.MONTH04_ID,
  A.MONTH05_ID,
  A.MONTH06_ID,
  A.MONTH07_ID,
  A.MONTH08_ID,
  A.MONTH09_ID,
  A.MONTH10_ID,
  A.MONTH11_ID,
  A.MONTH12_ID,
  A.PERSON,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG,
  B.ORDERNO AS ACTIVITYORDER,
  C.BYTECODE AS STEPTYPECODE,
  C.BYTEDES AS STEPTYPENAME,
  C.BYTEDESENG AS STEPTYPENAMEENG,
  C.ORDERNO AS STEPTYPEORDER,
  B.BP_PERIODAPP_ID
FROM BP_PERIODAPPACTSTEP A,
	VW_BP_PERIODAPPACT B,
  (SELECT * FROM SS_BYTEDES WHERE TABLENAME='BP_PERIODAPPACTSTEP' AND COLUMNNAME='STEPTYPE_ID') C
WHERE A.BP_PERIODAPPACT_ID=B.ID
  AND A.STEPTYPE_ID=C.BYTEID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPACTTARGET
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPACTTARGET" AS SELECT A.ID,
	A.BP_PERIODAPPACT_ID,
  A.ORDERNO,
  A.TARGET,
  A.TOTAL,
  A.UNIT,
  A.PLACE,
  A.PERIOD,
  B.ACTIVITYCODE,
  B.ACTIVITYNAME,
  B.ACTIVITYNAMEENG,
  B.ORDERNO AS ACTIVITYORDER,
  B.BP_PERIODAPP_ID
FROM BP_PERIODAPPACTTARGET A,
	VW_BP_PERIODAPPACT B
WHERE A.BP_PERIODAPPACT_ID=B.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPBENEFIT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPBENEFIT" AS SELECT ID,
	BP_PERIODAPP_ID,
  ORDERNO,
  BENEFIT
FROM BP_PERIODAPPBENEFIT;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPDATAGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPDATAGROUP" AS SELECT A.ID,
	A.BP_PERIODAPP_ID,
	A.BP_MTAPPDATAGROUP_ID,
	A.COMPLETE_ID,
  A.DESCRIPTION,

	DG.MTAPPDATAGROUPCODE,
	DG.MTAPPDATAGROUPNAME,
	DG.MTAPPDATAGROUPNAMEENG,
	DG.CALLING,
	DG.DATA_ID
FROM BP_PERIODAPPDATAGROUP A,
	BP_MTAPPDATAGROUP DG
WHERE A.BP_MTAPPDATAGROUP_ID=DG.ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPEDIT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPEDIT" AS SELECT A.ID,
	A.GUID,
	A.BUDGETYEAR,
  A.MT_DEPARTMENT_ID,
  A.STATUS_ID,
  A.BP_PROJECTTYPE_ID,
  A.PROJECTNO,
  A.BUDGETTOTAL,
  A.DEPARTMENTCODE,
  A.DEPARTMENTNAME,
  A.DEPARTMENTNAMEENG,
  A.STATUSCODE,
  A.STATUSNAME,
  A.STATUSNAMEENG,
  A.PROJECTTYPECODE,
  A.PROJECTTYPENAME,
  A.PROJECTCODE,
  A.PROJECTNAME
FROM VW_BP_PERIODAPPINFO A
WHERE STATUS_ID=1 AND A.ID IN (SELECT BP_PERIODAPP_ID FROM BP_PERIODAPPREMARK);

-- ----------------------------
-- View structure for VW_BP_PERIODAPPEXP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPEXP" AS SELECT MIN(A.ID) AS ID,
	A.BP_PERIODAPP_ID,
  A.INVESTMENTTYPEORDER,
  A.INVESTMENTTYPECODE,
  A.INVESTMENTTYPENAME,
  A.INVESTMENTTYPENAMEENG,
  A.ACCOUNTTYPECODE,
  A.ACCOUNTTYPENAME,
  A.ACCOUNTTYPENAMEENG,
  SUM(A.TOTAL) AS TOTAL
FROM VW_BP_PERIODAPPACTEXP A
GROUP BY BP_PERIODAPP_ID,
  A.INVESTMENTTYPEORDER,
  A.INVESTMENTTYPECODE,
  A.INVESTMENTTYPENAME,
  A.INVESTMENTTYPENAMEENG,
  A.ACCOUNTTYPECODE,
  A.ACCOUNTTYPENAME,
  A.ACCOUNTTYPENAMEENG;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPINFO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPINFO" AS SELECT A.ID,
	   A.BUDGETYEAR,
	   A.STRUCTYPE_CODE,
	   A.MT_DEPARTMENT_ID,
	   A.STATUS_ID,
	   A.BP_PERIODPROJECTTYPE_ID,
	   A.PROJECTNO,
	   A.BUDGETTOTAL,
	   A.GUID,
	   B.DEPARTMENTCODE,
	   B.DEPARTMENTNAME,
	   B.DEPARTMENTNAMEENG,
	   C.BYTECODE AS STATUSCODE,
	   C.BYTEDES AS STATUSNAME,
	   C.BYTEDESENG AS STATUSNAMEENG,
	   DT.BP_PROJECTTYPE_ID,
	   D.PROJECTTYPECODE,
	   D.PROJECTTYPENAME,
	   E.PROJECTCODE,
	   E.PROJECTNAME,
	   G.BUDGETTYPE_ID,
	   G.BUDGETTYPECODE,
	   G.BUDGETTYPENAME,
	   G.BUDGETTYPENAMEENG,
	   G.BUDGETGROUPCODE
FROM BP_PERIODAPP A,
	 VW_MT_DEPARTMENT B,
	 (SELECT *
	  FROM SS_BYTEDES
	  WHERE TABLENAME = 'BP_PERIODAPP'
			AND COLUMNNAME = 'STATUS_ID') C,
	 BP_PERIODPROJECTTYPE DT,
	 BP_PROJECTTYPE D,
	 VW_BG_PLANPRDPRJ E,
	 VW_BP_BUDGETGROUP G
WHERE A.MT_DEPARTMENT_ID = B.ID
	  AND A.STATUS_ID = C.BYTEID
	  AND A.BP_PERIODPROJECTTYPE_ID = DT.ID
	  AND DT.BP_PROJECTTYPE_ID = D.ID
	  AND A.BG_PLANPRDPRJ_ID = E.ID
	  AND A.BG_BUDGETGROUP_ID = G.BG_BUDGETGROUP_ID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPMONITOR
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPMONITOR" AS SELECT A.ID,
	A.BP_PERIODAPP_ID,
  A.ORDERNO,
  A.METHOD,
  A.TOOLS
FROM BP_PERIODAPPMONITOR A;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPPERSON
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPPERSON" AS SELECT A.ID,
	A.BP_PERIODAPP_ID,
  A.ORDERNO,
  A.PERSONTYPE_ID,
  A.PERSON,
  A.POSITION,
  A.TEL,
  B.BYTECODE AS PERSONTYPECODE,
  B.BYTEDES AS PERSONTYPENAME,
  B.BYTEDESENG AS PERSONTYPENAMEENG,
  B.ORDERNO AS PERSONTYPEORDER
FROM BP_PERIODAPPPERSON A,
	(SELECT * FROM SS_BYTEDES WHERE TABLENAME='BP_PERIODAPPPERSON' AND COLUMNNAME='PERSONTYPE_ID') B
WHERE A.PERSONTYPE_ID=B.BYTEID;

-- ----------------------------
-- View structure for VW_BP_PERIODAPPREMARK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPREMARK" AS SELECT A.ID,
	A.BP_PERIODAPP_ID,
	A.MESSAGE,
	A.FL_STORAGE_ID,
	A.INFORMBY,
	A.EDIT_ID,
	A.APPROVE_ID,
	A.DESCRIPTION,
	NVL(A.UPDATEDATETIME,A.CREATEDATETIME) AS UPDATEDATETIME,

	B.FILENAME,
	B.GUID AS FILEGUID
FROM BP_PERIODAPPREMARK A,
	FL_STORAGE B
WHERE A.FL_STORAGE_ID=B.ID(+);

-- ----------------------------
-- View structure for VW_BP_PERIODAPPRISK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPPRISK" AS SELECT ID,
	BP_PERIODAPP_ID,
	ORDERNO,
	RISK,
	SOLUTION
FROM BP_PERIODAPPRISK;

-- ----------------------------
-- View structure for VW_BP_PERIODAPP_BG
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODAPP_BG" AS SELECT BP_PERIODAPP.ID,
	   BP_PERIODAPP.BUDGETYEAR,
	   BP_PERIODAPP.MT_DEPARTMENT_ID,
	   BP_PERIODAPP.BG_BUDGETGROUP_ID,
	   VW_MT_DEPARTMENT.DEPARTMENTNAME,
	   BP_PERIODAPP.PROJECTNO,
	   BP_PERIODAPP.BG_PLANPRDPRJ_ID,
	   VW_BG_PLANPRDPRJ.PROJECTCODE,
	   VW_BG_PLANPRDPRJ.PROJECTCODE || ': ' || VW_BG_PLANPRDPRJ.PROJECTNAME AS PROJECTNAME,
	   BP_PERIODAPP.BUDGETTOTAL,
	   BP_PERIODAPP.STATUS_ID
FROM VW_MT_DEPARTMENT
INNER JOIN BP_PERIODAPP ON VW_MT_DEPARTMENT.ID = BP_PERIODAPP.MT_DEPARTMENT_ID
INNER JOIN VW_BG_PLANPRDPRJ ON BP_PERIODAPP.BG_PLANPRDPRJ_ID = VW_BG_PLANPRDPRJ.ID
WHERE BP_PERIODAPP.STATUS_ID = 60;

