-- View structure for VW_BP_PERIODKPIACTIVITY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_BP_PERIODKPIACTIVITY" AS SELECT E.ID,
	E.BUDGETYEAR,
	E.BP_KPIACTIVITY_ID,
	E.MT_DEPARTMENT_ID,
    E.KPIGROUP_ID,
    E.KPIATYPE_ID,
    E.CREATEDATETIME,
    E.CREATEBY,
    E.UPDATEDATETIME,
    E.UPDATEBY,
    E.GUID,

	F.KPIACTIVITYCODE,
	F.KPIACTIVITYNAME,
	G.BYTECODE AS KPIGROUPCODE,
    G.BYTEDES AS KPIGROUPNAME,
	G.BYTEDESENG AS KPIGROUPNAMEENG,
	G.ORDERNO AS KPIGROUPORDER,
	H.BYTECODE AS KPITYPECODE,
	H.BYTEDES AS KPITYPENAME,
	H.BYTEDESENG AS KPITYPENAMEENG,
	H.ORDERNO AS KPITYPEORDER,
	F.UNIT
FROM BP_PERIODKPIACTIVITY E,
  BP_KPIACTIVITY F,
  (SELECT * FROM SS_BYTEDES WHERE TABLENAME='BP_KPIACTIVITY' AND COLUMNNAME='KPIGROUP_ID') G,
  (SELECT * FROM SS_BYTEDES WHERE TABLENAME='BP_KPIACTIVITY' AND COLUMNNAME='KPITYPE_ID') H
WHERE E.BP_KPIACTIVITY_ID=F.ID
  AND E.KPIGROUP_ID=G.BYTEID
  AND E.KPIATYPE_ID=H.BYTEID;

