-- ----------------------------
-- View structure for VW_HR_EVAPP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPP" AS SELECT A.ID,
	   A.HR_EVLOTAPP_ID,
	   A.HR_STAFF_ID,
	   A.MT_DEPARTMENT_ID,
	   A.HR_POSITION_ID,
	   A.HR_POSITIONEX_ID,
	   A.HR_EVPOSITION_ID,
	   A.HR_STAFFTYPE_ID,
	   A.APPSTATUS_ID,
	   A.HR_STAFFHEADER_ID,
	   A.HEADERSTATUS_ID,
	   A.HEADERSUBMITDATE,
	   A.RATIOACHIEVEMENT, --ร้อยละคะแนนผลสัมฤทธิ์ของงาน
	   A.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
	   A.RATIOSCORE, --ร้อยละคะแนนรวมทั้งหมดที่ได้
	   A.HR_EVLOTSCOREITEM_ID,
	   A.HEADERFINISHDATE,
	   A.SELFFINISHDATE,
	   A.HEADERADDITION,
	   A.TOTALCOURSE,
	   A.HR_STAFFBOARD1_ID,
	   A.HR_STAFFBOARD2_ID,
	   A.HR_STAFFBOARD3_ID,
	   A.HR_STAFFBOARD4_ID,
	   A.HR_STAFFBOARD5_ID,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.GUID,

	   B.STAFFCODE,
	   B.SNAME,
	   B.SNAMEENG,
	   B.SNAMEFULL,
	   B.STAFFSTATUS_ID,
	   B.STAFFSTATUSNAME,

	   H.STAFFCODE AS HEADERCODE,
	   H.SNAME AS HEADERNAME,
	   H.SNAMEENG AS HEADERNAMEENG,
	   H.SNAMEFULL AS HEADERNAMEFULL,
	   H.STAFFSTATUSNAME AS HEADERSTATUSNAME,

	   C.POSITIONCODE,
	   C.POSITIONNAME,
	   D.DEPARTMENTCODE,
	   D.DEPARTMENTFULLNAME,
	   E.EVPOSITIONCODE,
	   E.EVPOSITIONNAME,
	   E.ISACTIVE_ID,
	   F.POSITIONEXNAME,
	   CAST(NVL(DECODE(SM.CONFIGVALUE, '1', LWP.MAXSCORE, L.TOTALSCORE), 0) AS NUMBER(15, 2)) AS MAXSCORE,
	   L.TOTALSCORE, --คะแนนเต็มแต่ละตำแหน่ง
	   CAST(NVL(WG.INPUTSCORE, 0) AS NUMBER(10, 2)) AS SCOREACTUAL, --คะแนนผลสัมฤทธิ์ของงานที่บันทึก
	   CAST(NVL(WG.SCORE, 0) AS NUMBER(10, 2)) AS SCORE, --คะแนนผลสัมฤทธิ์ของงานที่ได้
	   A.SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
	   L.BUDGETYEAR,
	   L.ROUNDNO,
	   L.EVLOTAPPNAME,
	   A.LEVELNAME, --ระดับคะแนนการประเมิน
	   L.HR_EVLOTWL_ID
FROM   VW_HR_EVAPP_INFO A
INNER  JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID = B.ID
LEFT   JOIN VW_HR_STAFF_NAME H ON A.HR_STAFFHEADER_ID = H.ID
INNER  JOIN VW_HR_POSITION C ON A.HR_POSITION_ID = C.ID
INNER  JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID = D.ID
INNER  JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID = E.ID
INNER  JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID = L.ID
LEFT   JOIN VW_HR_POSITIONEX F ON A.HR_POSITIONEX_ID = F.ID
LEFT   JOIN (SELECT HR_EVAPP_ID,
					SUM(SUM_WORKGROUPSCORE) AS SCORE,
					SUM(SUM_TOTALSCORE) AS INPUTSCORE
			 FROM   VW_HR_EVAPPWORK_SUMGROUP
			 GROUP  BY HR_EVAPP_ID) WG ON A.ID = WG.HR_EVAPP_ID
INNER  JOIN (SELECT P.HR_EVLOTWL_ID,
					P.HR_EVPOSITION_ID,
					SUM(MAXSCORE) AS MAXSCORE
			 FROM   HR_EVLOTWLPOSGRP GG
			 INNER  JOIN HR_EVLOTWLPOS P ON GG.HR_EVLOTWLPOS_ID = P.ID
			 GROUP  BY P.HR_EVLOTWL_ID,
					   P.HR_EVPOSITION_ID) LWP ON L.HR_EVLOTWL_ID = LWP.HR_EVLOTWL_ID
												  AND A.HR_EVPOSITION_ID = LWP.HR_EVPOSITION_ID
CROSS  JOIN (SELECT * FROM SS_CONFIG WHERE CONFIGCODE = 'HR_EV.MAXSCORE.MODE') SM;

-- ----------------------------
-- View structure for VW_HR_EVAPPBOARD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPBOARD" AS SELECT A.ID,
	A.HR_EVAPP_ID,
	A.ORDERNO,
	A.HR_STAFF_ID,
	A.BOARDSTATUS_ID
FROM HR_EVAPPBOARD A;

-- ----------------------------
-- View structure for VW_HR_EVAPPGROUP_SCORE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPGROUP_SCORE" AS SELECT G.HR_EVAPP_ID,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '01' THEN
				G.SUM_WORKGROUPSCORE
			   ELSE
				0
		   END) AS SCORE_MAIN,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '02' THEN
				G.SUM_WORKGROUPSCORE
			   ELSE
				0
		   END) AS SCORE_WORK,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '03' THEN
				G.SUM_WORKGROUPSCORE
			   ELSE
				0
		   END) AS SCORE_PROJECT,
	   SUM(SUM_WORKGROUPSCORE) AS SCORE,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '01' THEN
				G.SUM_TOTALSCORE
			   ELSE
				0
		   END) AS INPUTSCORE_MAIN,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '02' THEN
				G.SUM_TOTALSCORE
			   ELSE
				0
		   END) AS INPUTSCORE_WORK,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '03' THEN
				G.SUM_TOTALSCORE
			   ELSE
				0
		   END) AS INPUTSCORE_PROJECT
FROM   VW_HR_EVAPPWORK_SUMGROUP G
LEFT   JOIN HR_EVGROUP EG ON G.HR_EVGROUP_ID = EG.ID
GROUP  BY G.HR_EVAPP_ID;

-- ----------------------------
-- View structure for VW_HR_EVAPPREMARK
