	A.HR_EVLOTWLPOSGRPWL_ID,
	A.REMARK,
	E.GUID AS EVAPPGUID,
	EW.GUID AS EVLOTWLPOSGRPWLGUID
FROM HR_EVAPPWLPOSGRPWLREM A
