-- ----------------------------
-- View structure for VW_HR_EVAPPWORK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORK" AS SELECT A.ID,
	A.HR_EVAPP_ID,
	A.HR_EVLOTWLPOSGRPWL_ID,
	A.HR_EVPROJECTMEMBER_ID,
	A.HR_EVCOMMANDMEMBER_ID,
	A.ORDERNO,
	A.DESCRIPTION,
	A.TOTALWORK,
	A.SCORE,
	A.HEADERSTATUS_ID,
	A.ISHEADERADD_ID,
	A.URL,
	A.HEADERREMARK,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,

	B.SCORETYPE_ID,

	COALESCE(A.DESCRIPTION, E.PROJECTNAME || ' (' || D.PROJECTSTATUSNAME || ') [ตำแหน่ง' || D.PRJPOSITIONNAME || ']', C.COMMANDNAME || ' (' || CM.COMMANDSTATUSNAME || ')') AS WORKNAME,
	E.PROJECTNAME,
	C.COMMANDNAME,

	I1.ID AS VW_HR_EVAPPWORKITEM1_ID,
	I1.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL1_ID,
	I1.ISREQUIRE_ID AS ISREQUIRE1_ID,
	I1.FL_STORAGE_ID AS FL_STORAGE1_ID,
	I1.FILEGUID AS FILEGUID1,
	I1.WLFILENAME AS WLFILENAME1,
	I1.URL AS FILEURL1,

	I2.ID AS VW_HR_EVAPPWORKITEM2_ID,
	I2.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL2_ID,
	I2.ISREQUIRE_ID AS ISREQUIRE2_ID,
	I2.FL_STORAGE_ID AS FL_STORAGE2_ID,
	I2.FILEGUID AS FILEGUID2,
	I2.WLFILENAME AS WLFILENAME2,
	I2.URL AS FILEURL2,

	I3.ID AS VW_HR_EVAPPWORKITEM3_ID,
	I3.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL3_ID,
	I3.ISREQUIRE_ID AS ISREQUIRE3_ID,
	I3.FL_STORAGE_ID AS FL_STORAGE3_ID,
	I3.FILEGUID AS FILEGUID3,
	I3.WLFILENAME AS WLFILENAME3,
	I3.URL AS FILEURL3,

	I4.ID AS VW_HR_EVAPPWORKITEM4_ID,
	I4.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL4_ID,
	I4.ISREQUIRE_ID AS ISREQUIRE4_ID,
	I4.FL_STORAGE_ID AS FL_STORAGE4_ID,
	I4.FILEGUID AS FILEGUID4,
	I4.WLFILENAME AS WLFILENAME4,
	I4.URL AS FILEURL4,

	I5.ID AS VW_HR_EVAPPWORKITEM5_ID,
	I5.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL5_ID,
	I5.ISREQUIRE_ID AS ISREQUIRE5_ID,
	I5.FL_STORAGE_ID AS FL_STORAGE5_ID,
	I5.FILEGUID AS FILEGUID5,
	I5.WLFILENAME AS WLFILENAME5,
	I5.URL AS FILEURL5,

	I6.ID AS VW_HR_EVAPPWORKITEM6_ID,
	I6.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL6_ID,
	I6.ISREQUIRE_ID AS ISREQUIRE6_ID,
	I6.FL_STORAGE_ID AS FL_STORAGE6_ID,
	I6.FILEGUID AS FILEGUID6,
	I6.WLFILENAME AS WLFILENAME6,
	I6.URL AS FILEURL6,

	I7.ID AS VW_HR_EVAPPWORKITEM7_ID,
	I7.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL7_ID,
	I7.ISREQUIRE_ID AS ISREQUIRE7_ID,
	I7.FL_STORAGE_ID AS FL_STORAGE7_ID,
	I7.FILEGUID AS FILEGUID7,
	I7.WLFILENAME AS WLFILENAME7,
	I7.URL AS FILEURL7,

	I8.ID AS VW_HR_EVAPPWORKITEM8_ID,
	I8.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL8_ID,
	I8.ISREQUIRE_ID AS ISREQUIRE8_ID,
	I8.FL_STORAGE_ID AS FL_STORAGE8_ID,
	I8.FILEGUID AS FILEGUID8,
	I8.WLFILENAME AS WLFILENAME8,
	I8.URL AS FILEURL8,

	I9.ID AS VW_HR_EVAPPWORKITEM9_ID,
	I9.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL9_ID,
	I9.ISREQUIRE_ID AS ISREQUIRE9_ID,
	I9.FL_STORAGE_ID AS FL_STORAGE9_ID,
	I9.FILEGUID AS FILEGUID9,
	I9.WLFILENAME AS WLFILENAME9,
	I9.URL AS FILEURL9,

	I10.ID AS VW_HR_EVAPPWORKITEM10_ID,
	I10.HR_EVLOTWLPOSGRPWLFL_ID AS HR_EVLOTWLPOSGRPWLFL10_ID,
	I10.ISREQUIRE_ID AS ISREQUIRE10_ID,
	I10.FL_STORAGE_ID AS FL_STORAGE10_ID,
	I10.FILEGUID AS FILEGUID10,
	I10.WLFILENAME AS WLFILENAME10,
	I10.URL AS FILEURL10,

	CASE WHEN BR.HR_EVAPPWORK_ID IS NULL THEN 0 ELSE 1 END AS HASBOARDREMARK_ID
FROM HR_EVAPPWORK A
	INNER JOIN HR_EVLOTWLPOSGRPWL B ON A.HR_EVLOTWLPOSGRPWL_ID=B.ID
	LEFT JOIN VW_HR_EVPROJECTMEMBER D ON A.HR_EVPROJECTMEMBER_ID=D.ID
	LEFT JOIN HR_EVPROJECT E ON D.HR_EVPROJECT_ID=E.ID
	LEFT JOIN VW_HR_EVCOMMANDMEMBER CM ON A.HR_EVCOMMANDMEMBER_ID=CM.ID
	LEFT JOIN HR_EVCOMMAND C ON CM.HR_EVCOMMAND_ID=C.ID
	LEFT JOIN VW_HR_EVAPPWORKITEM I1 ON A.ID=I1.HR_EVAPPWORK_ID AND I1.WLFILEORDERNO=1
	LEFT JOIN VW_HR_EVAPPWORKITEM I2 ON A.ID=I2.HR_EVAPPWORK_ID AND I2.WLFILEORDERNO=2
	LEFT JOIN VW_HR_EVAPPWORKITEM I3 ON A.ID=I3.HR_EVAPPWORK_ID AND I3.WLFILEORDERNO=3
	LEFT JOIN VW_HR_EVAPPWORKITEM I4 ON A.ID=I4.HR_EVAPPWORK_ID AND I4.WLFILEORDERNO=4
	LEFT JOIN VW_HR_EVAPPWORKITEM I5 ON A.ID=I5.HR_EVAPPWORK_ID AND I5.WLFILEORDERNO=5
	LEFT JOIN VW_HR_EVAPPWORKITEM I6 ON A.ID=I6.HR_EVAPPWORK_ID AND I6.WLFILEORDERNO=6
	LEFT JOIN VW_HR_EVAPPWORKITEM I7 ON A.ID=I7.HR_EVAPPWORK_ID AND I7.WLFILEORDERNO=7
	LEFT JOIN VW_HR_EVAPPWORKITEM I8 ON A.ID=I8.HR_EVAPPWORK_ID AND I8.WLFILEORDERNO=8
	LEFT JOIN VW_HR_EVAPPWORKITEM I9 ON A.ID=I9.HR_EVAPPWORK_ID AND I9.WLFILEORDERNO=9
	LEFT JOIN VW_HR_EVAPPWORKITEM I10 ON A.ID=I10.HR_EVAPPWORK_ID AND I10.WLFILEORDERNO=10
	LEFT JOIN (SELECT HR_EVAPPWORK_ID
		FROM HR_EVAPPWORKBRDREM
		WHERE BOARDREMARK IS NOT NULL
		GROUP BY HR_EVAPPWORK_ID
	) BR ON A.ID=BR.HR_EVAPPWORK_ID;

-- ----------------------------
-- View structure for VW_HR_EVAPPWORKBRDREM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORKBRDREM" AS SELECT A.ID,
	   A.HR_EVAPP_ID,
	   A.HR_EVAPPWORK_ID,
	   A.ORDERNO,
	   A.BOARDREMARK,
	   E.GUID AS EVAPPGUID,
	   EW.GUID AS EVAPPWORKGUID,
	   B.BOARDSTATUS_ID,
	   B.HR_STAFF_ID,
	   B.ID AS HR_EVAPPBOARD_ID,
	   A.CREATEBY,
	   A.CREATEDATETIME,
	   A.UPDATEBY,
	   A.UPDATEDATETIME
FROM   HR_EVAPPWORKBRDREM A
INNER  JOIN HR_EVAPP E ON A.HR_EVAPP_ID = E.ID
INNER  JOIN HR_EVAPPWORK EW ON A.HR_EVAPPWORK_ID = EW.ID
INNER  JOIN HR_EVAPPBOARD B ON A.ORDERNO = B.ORDERNO
							   AND A.HR_EVAPP_ID = B.HR_EVAPP_ID;

-- ----------------------------
-- View structure for VW_HR_EVAPPWORKGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORKGROUP" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	A.HR_EVAPP_ID,
	B.ID AS HR_EVLOTWLPOSGRP_ID,

	B.ORDERNO AS WORKGROUPORDERNO,
	B.WORKGROUPNAME,
	B.MAXSCORE AS WORKGROUPMAXSCORE,
	CAST(SUM(A.SCORE) AS NUMBER(15,2)) AS WORKGROUPACTUALSCORE,
	CAST(CASE WHEN B.MAXSCORE>0 AND SUM(A.SCORE)>B.MAXSCORE THEN B.MAXSCORE ELSE SUM(A.SCORE) END AS NUMBER(15,2)) AS WORKGROUPSCORE
FROM HR_EVAPPWORK A
	INNER JOIN HR_EVLOTWLPOSGRPWL W ON A.HR_EVLOTWLPOSGRPWL_ID=W.ID
	INNER JOIN HR_EVLOTWLPOSGRP B ON W.HR_EVLOTWLPOSGRP_ID=B.ID
GROUP BY A.HR_EVAPP_ID,
	B.ID,
	B.ORDERNO,
	B.WORKGROUPNAME,
	B.MAXSCORE;

-- ----------------------------
-- View structure for VW_HR_EVAPPWORKITEM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORKITEM" AS SELECT A.ID,
	A.HR_EVAPPWORK_ID,
	A.ORDERNO,
	A.DESCRIPTION,
	A.FL_STORAGE_ID,
	A.HR_EVLOTWLPOSGRPWLFL_ID,
	A.URL,
	A.HR_EVCOMMAND_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,
	C.GUID AS EVAPPWORKGUID,

	D.ORDERNO AS WLFILEORDERNO,
	D.FILENAME AS WLFILENAME,
	D.EXTENSION,
	D.ISREQUIRE_ID,
	B.FILENAME,
	B.GUID AS FILEGUID
FROM HR_EVAPPWORKITEM A
	INNER JOIN HR_EVAPPWORK C ON A.HR_EVAPPWORK_ID=C.ID
	INNER JOIN HR_EVLOTWLPOSGRPWLFL D ON A.HR_EVLOTWLPOSGRPWLFL_ID=D.ID
	LEFT JOIN FL_STORAGE B ON A.FL_STORAGE_ID=B.ID;

-- ----------------------------
-- View structure for VW_HR_EVAPPWORK_BRD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORK_BRD" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	   A.HR_EVAPP_ID,
	   A.HR_EVLOTWLPOSGRPWL_ID,
	   A.HR_EVPROJECTMEMBER_ID,
	   A.HR_EVCOMMANDMEMBER_ID,
	   A.ORDERNO,
	   A.DESCRIPTION,
	   A.TOTALWORK,
	   A.SCORE,
	   A.HEADERSTATUS_ID,
	   A.ISHEADERADD_ID,
	   A.URL,
	   A.HEADERREMARK,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.GUID,

	   A.SCORETYPE_ID,

	   A.WORKNAME,
	   A.PROJECTNAME,
	   A.COMMANDNAME,

	   A.VW_HR_EVAPPWORKITEM1_ID,
	   A.HR_EVLOTWLPOSGRPWLFL1_ID,
	   A.ISREQUIRE1_ID,
	   A.FL_STORAGE1_ID,
	   A.FILEGUID1,
	   A.WLFILENAME1,
	   A.FILEURL1,

	   A.VW_HR_EVAPPWORKITEM2_ID,
	   A.HR_EVLOTWLPOSGRPWLFL2_ID,
	   A. ISREQUIRE2_ID,
	   A.FL_STORAGE2_ID,
	   A.FILEGUID2,
	   A.WLFILENAME2,
	   A.FILEURL2,

	   A.VW_HR_EVAPPWORKITEM3_ID,
	   A.HR_EVLOTWLPOSGRPWLFL3_ID,
	   A.ISREQUIRE3_ID,
	   A.FL_STORAGE3_ID,
	   A.FILEGUID3,
	   A.WLFILENAME3,
	   A.FILEURL3,

	   A.VW_HR_EVAPPWORKITEM4_ID,
	   A.HR_EVLOTWLPOSGRPWLFL4_ID,
	   A.ISREQUIRE4_ID,
	   A.FL_STORAGE4_ID,
	   A.FILEGUID4,
	   A.WLFILENAME4,
	   A.FILEURL4,

	   A.VW_HR_EVAPPWORKITEM5_ID,
	   A.HR_EVLOTWLPOSGRPWLFL5_ID,
	   A.ISREQUIRE5_ID,
	   A.FL_STORAGE5_ID,
	   A.FILEGUID5,
	   A.WLFILENAME5,
	   A.FILEURL5,

	   A.VW_HR_EVAPPWORKITEM6_ID,
	   A.HR_EVLOTWLPOSGRPWLFL6_ID,
	   A.ISREQUIRE6_ID,
	   A.FL_STORAGE6_ID,
	   A.FILEGUID6,
	   A.WLFILENAME6,
	   A.FILEURL6,

	   A.VW_HR_EVAPPWORKITEM7_ID,
	   A.HR_EVLOTWLPOSGRPWLFL7_ID,
	   A.ISREQUIRE7_ID,
	   A.FL_STORAGE7_ID,
	   A.FILEGUID7,
	   A.WLFILENAME7,
	   A.FILEURL7,

	   A.VW_HR_EVAPPWORKITEM8_ID,
	   A.HR_EVLOTWLPOSGRPWLFL8_ID,
	   A.ISREQUIRE8_ID,
	   A.FL_STORAGE8_ID,
	   A.FILEGUID8,
	   A.WLFILENAME8,
	   A.FILEURL8,

	   A.VW_HR_EVAPPWORKITEM9_ID,
	   A.HR_EVLOTWLPOSGRPWLFL9_ID,
	   A.ISREQUIRE9_ID,
	   A.FL_STORAGE9_ID,
	   A.FILEGUID9,
	   A.WLFILENAME9,
	   A.FILEURL9,

	   A.VW_HR_EVAPPWORKITEM10_ID,
	   A.HR_EVLOTWLPOSGRPWLFL10_ID,
	   A.ISREQUIRE10_ID,
	   A.FL_STORAGE10_ID,
	   A.FILEGUID10,
	   A.WLFILENAME10,
	   A.FILEURL10,

	   A.HASBOARDREMARK_ID,

	   A.ID AS HR_EVAPPWORK_ID,
	   --AB.GUID,
	   AB.HR_STAFF_ID AS HR_STAFFBOARD_ID,
	   AW.ORDERNO AS BOARDORDERNO,
	   AW.BOARDREMARK AS BOARDREMARK,
	   NVL(AW.UPDATEBY, AW.CREATEBY) AS BOARDUPDATEBY,
	   NVL(AW.UPDATEDATETIME, AW.CREATEDATETIME) AS BOARDUPDATEDATETIME
FROM   VW_HR_EVAPPWORK A
INNER  JOIN HR_EVAPPBOARD AB ON A.HR_EVAPP_ID = AB.HR_EVAPP_ID
LEFT   JOIN HR_EVAPPWORKBRDREM AW ON A.HR_EVAPP_ID = AW.HR_EVAPP_ID
									 AND A.ID = AW.HR_EVAPPWORK_ID
									 AND AW.ORDERNO = AB.ORDERNO;

-- ----------------------------
-- View structure for VW_HR_EVAPPWORK_SUM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORK_SUM" AS SELECT A.ID,
	   A.HR_EVAPP_ID,
	   A.HR_EVLOTWLPOSGRPWL_ID,
	   A.GUID,
	   A.WORKGROUPORDERNO,
	   A.WORKGROUPNAME,
	   A.WORKGROUPMAXSCORE,
	   A.WORKORDERNO,
	   A.MAXSCORE,
	   A.WORKNAME,
	   A.UNITNAME,
	   A.SCORETYPE_ID,
	   A.SCORETYPENAME,
	   A.MINTOTAL,
	   A.EVLOTWLPOSGRPWLGUID,
	   A.MAINORDER,
	   A.MAINNAME,
	   A.SUM_WORKGROUPSCORE,
	   0 AS SUM_WORKGROUPSCOREVERIFY,--A.SUM_WORKGROUPSCOREVERIFY,
	   A.EACHSCORE,
	   A.SUM_TOTALWORK,
	   A.SUM_TOTALSCORE,
	   A.SUM_TOTALHEADERVERIFY,
	   A. SUM_SCORE,
	   A.CANHEADERADD_ID,
	   A.INPUTTYPE_ID,
	   AW.REMARK,
	CASE WHEN WR.HR_EVAPP_ID IS NULL THEN 0 ELSE 1 END AS HASBOARDREMARK_ID
FROM   VW_HR_EVAPPWORK_SUM_I A
LEFT   JOIN HR_EVAPPWLPOSGRPWLREM AW ON A.HR_EVAPP_ID = AW.HR_EVAPP_ID
										AND A.ID = AW.HR_EVLOTWLPOSGRPWL_ID
LEFT JOIN (SELECT W.HR_EVAPP_ID, W.HR_EVLOTWLPOSGRPWL_ID
FROM HR_EVAPPWORK W
	INNER JOIN HR_EVAPPWORKBRDREM R ON W.ID=R.HR_EVAPPWORK_ID
WHERE R.BOARDREMARK IS NOT NULL GROUP BY W.HR_EVAPP_ID, W.HR_EVLOTWLPOSGRPWL_ID) WR ON A.HR_EVAPP_ID=WR.HR_EVAPP_ID AND WR.HR_EVLOTWLPOSGRPWL_ID=A.HR_EVLOTWLPOSGRPWL_ID;

-- ----------------------------
-- View structure for VW_HR_EVAPPWORK_SUMGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORK_SUMGROUP" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	A.HR_EVAPP_ID,
	A.HR_EVLOTWLPOSGRP_ID,
	B.HR_EVGROUP_ID,
	CAST(NVL(SUM(A.SCORE),0)  AS NUMBER(15,2)) AS SUM_SCOREINPUT, --คะแนนที่ได้
	CAST(SUM(A.SUM_TOTALWORK) AS NUMBER(15,2)) AS SUM_TOTALWORK,
	CAST(SUM(A.SUM_TOTALSCORE) AS NUMBER(15,2)) AS SUM_TOTALSCORE, --คะแนนที่บันทึก
	--CAST(SUM(A.SUM_TOTALHEADERVERIFY) AS NUMBER(15,2)) AS SUM_TOTALHEADERVERIFY,
	CAST(FN_HR_EVLOTWLPOSGRP_SCORE(B.MAXSCORE, NVL(SUM(A.SCORE),0)) AS NUMBER(15,2)) AS SUM_WORKGROUPSCORE/*,
	CAST(FN_HR_EVLOTWLPOSGRP_SCORE(B.MAXSCORE, NVL(SUM(A.SCOREVERIFY),0)) AS NUMBER(15,2)) AS SUM_WORKGROUPSCOREVERIFY,
	CAST(CASE WHEN B.MAXSCORE>0 AND NVL(SUM(A.SCORE),0)>B.MAXSCORE THEN B.MAXSCORE ELSE NVL(SUM(A.SCORE),0) END AS NUMBER(15,2)) AS SUM_WORKGROUPSCORE,
	CAST(CASE WHEN B.MAXSCORE>0 AND NVL(SUM(A.SCOREVERIFY),0)>B.MAXSCORE THEN B.MAXSCORE ELSE NVL(SUM(A.SCOREVERIFY),0) END AS NUMBER(15,2)) AS SUM_WORKGROUPSCOREVERIFY*/
FROM VW_HR_EVAPPWORK_SUMWL A
	INNER JOIN HR_EVLOTWLPOSGRP B ON A.HR_EVLOTWLPOSGRP_ID=B.ID
GROUP BY A.HR_EVAPP_ID,
	A.HR_EVLOTWLPOSGRP_ID,
	B.HR_EVGROUP_ID,
	B.MAXSCORE;

-- ----------------------------
-- View structure for VW_HR_EVAPPWORK_SUMWL
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORK_SUMWL" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	W.HR_EVAPP_ID,
	W.HR_EVLOTWLPOSGRPWL_ID,
	E.HR_EVLOTWLPOSGRP_ID,
	CAST(NVL(W.SUM_TOTALWORK,0) AS NUMBER(15,2)) AS SUM_TOTALWORK, --จำนวนหน่วยที่ทำได้
	CAST(NVL(W.SUM_SCORE,0) AS NUMBER(15,2)) AS SUM_TOTALSCORE, --คะแนนที่บันทึก
	CAST(FN_HR_EVLOTWLPOSGRPWL_SCORE(E.SCORETYPE_ID,E.EACHSCORE,E.MAINEACHSCORE,E.MINTOTAL,E.MAXSCORE,NVL(W.SUM_TOTALWORK,0),NVL(W.SUM_SCORE,0)) AS NUMBER(15,2)) AS SCORE, --คะแนนที่ได้

	CAST(NVL(W.SUM_TOTALWORKVERIFY,0)  AS NUMBER(15,2))AS SUM_TOTALWORKVERIFY,
	CAST(NVL(W.SUM_TOTALSCOREVERIFY,0) AS NUMBER(15,2)) AS SUM_TOTALSCOREVERIFY,
	CAST(NVL(W.SUM_TOTALHEADERVERIFY,0) AS NUMBER(15,2)) AS SUM_TOTALHEADERVERIFY,
	CAST(FN_HR_EVLOTWLPOSGRPWL_SCORE(E.SCORETYPE_ID,E.EACHSCORE,E.MAINEACHSCORE,E.MINTOTAL,E.MAXSCORE,NVL(W.SUM_TOTALWORKVERIFY,0),NVL(W.SUM_TOTALSCOREVERIFY,0)) AS NUMBER(15,2)) AS SCOREVERIFY
FROM (
		SELECT A.ID,
			A.HR_EVLOTWLPOSGRP_ID,
			A.SCORETYPE_ID,
			A.EACHSCORE,
			NVL(C.EACHSCORE,0) AS MAINEACHSCORE,
			A.MINTOTAL,
			A.MAXSCORE
		FROM HR_EVLOTWLPOSGRPWL A
			LEFT JOIN HR_EVLOTWLPOSGRPMAIN C ON A.HR_EVLOTWLPOSGRPMAIN_ID=C.ID AND C.HR_EVLOTWLPOSGRP_ID=A.HR_EVLOTWLPOSGRP_ID
	) E
	INNER JOIN (
		SELECT AA.HR_EVAPP_ID,
			AA.HR_EVLOTWLPOSGRPWL_ID,
			SUM(AA.TOTALWORK) AS SUM_TOTALWORK,
			SUM(NVL(AA.SCORE,0)) AS SUM_SCORE,
			SUM(CASE AA.HEADERSTATUS_ID WHEN 30 THEN 1 ELSE 0 END) AS SUM_TOTALHEADERVERIFY,
			SUM(CASE WHEN AA.HEADERSTATUS_ID >=30 THEN AA.TOTALWORK ELSE 0 END) AS SUM_TOTALWORKVERIFY,
			SUM(CASE WHEN AA.HEADERSTATUS_ID >=30 THEN NVL(AA.SCORE,0) ELSE 0 END) AS SUM_TOTALSCOREVERIFY
        FROM HR_EVAPPWORK_MU AA
        GROUP BY AA.HR_EVAPP_ID, AA.HR_EVLOTWLPOSGRPWL_ID
	) W ON E.ID=W.HR_EVLOTWLPOSGRPWL_ID;

-- ----------------------------
-- View structure for VW_HR_EVAPPWORK_SUM_I
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPPWORK_SUM_I" AS SELECT E.ID,
	   A.ID AS HR_EVAPP_ID,
	   E.ID AS HR_EVLOTWLPOSGRPWL_ID,
	   E.GUID,
	   D.ORDERNO AS WORKGROUPORDERNO,
	   D.WORKGROUPNAME,
	   D.MAXSCORE AS WORKGROUPMAXSCORE,
	   E.ORDERNO AS WORKORDERNO,
	   E.MAXSCORE,
	   E.WORKNAME,
	   E.UNITNAME,
	   F.BYTEID AS SCORETYPE_ID,
	   F.BYTEDES AS SCORETYPENAME,
	   E.MINTOTAL,
	   E.GUID AS EVLOTWLPOSGRPWLGUID,
	   E.MAINORDER,
	   E.MAINNAME,
	   CAST(NVL(EG.SUM_WORKGROUPSCORE, 0) AS NUMBER(15, 2)) AS SUM_WORKGROUPSCORE,
	   --CAST(NVL(EG.SUM_WORKGROUPSCOREVERIFY, 0) AS NUMBER(15, 2)) AS SUM_WORKGROUPSCOREVERIFY,
	   CASE F.BYTEID
		   WHEN 1 THEN
			E.EACHSCORE
		   WHEN 2 THEN
			E.MAINEACHSCORE
		   WHEN 5 THEN
			E.EACHSCORE
	   END AS EACHSCORE,
	   CAST(NVL(EW.SUM_TOTALWORK, 0) AS NUMBER(15, 2)) AS SUM_TOTALWORK,
	   CAST(NVL(EW.SUM_TOTALSCORE, 0) AS NUMBER(15, 2)) AS SUM_TOTALSCORE,
	   CAST(NVL(EW.SUM_TOTALHEADERVERIFY, 0) AS NUMBER(15, 2)) AS SUM_TOTALHEADERVERIFY,
	   CAST(NVL(EW.SCORE, 0) AS NUMBER(15, 2)) AS SUM_SCORE,
	   E.CANHEADERADD_ID,
	   E.INPUTTYPE_ID
FROM   HR_EVAPP A
INNER  JOIN HR_EVLOTAPP B ON A.HR_EVLOTAPP_ID = B.ID
INNER  JOIN VW_HR_EVLOTWLPOS C ON B.HR_EVLOTWL_ID = C.HR_EVLOTWL_ID
								  AND A.HR_EVPOSITION_ID = C.HR_EVPOSITION_ID
INNER  JOIN VW_HR_EVLOTWLPOSGRP D ON C.ID = D.HR_EVLOTWLPOS_ID
INNER  JOIN VW_HR_EVLOTWLPOSGRPWL E ON D.ID = E.HR_EVLOTWLPOSGRP_ID
INNER  JOIN SS_BYTEDES F ON E.SCORETYPE_ID = F.BYTEID
							AND F.TABLENAME = 'HR_EVLOTWLPOSGRPWL'
							AND F.COLUMNNAME = 'SCORETYPE_ID'
LEFT   JOIN VW_HR_EVAPPWORK_SUMWL EW ON A.ID = EW.HR_EVAPP_ID
										AND E.ID = EW.HR_EVLOTWLPOSGRPWL_ID
LEFT   JOIN VW_HR_EVAPPWORK_SUMGROUP EG ON A.ID = EG.HR_EVAPP_ID
										   AND D.ID = EG.HR_EVLOTWLPOSGRP_ID;

-- ----------------------------
-- View structure for VW_HR_EVAPP_BRD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPP_BRD" AS SELECT A.ID,
	   A.HR_EVLOTAPP_ID,
	   A.HR_STAFF_ID,
	   A.MT_DEPARTMENT_ID,
	   A.HR_POSITION_ID,
	   A.HR_POSITIONEX_ID,
	   A.HR_EVPOSITION_ID,
	   A.HR_STAFFTYPE_ID,
	   A.APPSTATUS_ID,
	   A.HR_STAFFHEADER_ID,
	   A.HEADERSTATUS_ID,
	   A.HEADERSUBMITDATE,
	   A.RATIOACHIEVEMENT, --ร้อยละคะแนนผลสัมฤทธิ์ของงาน
	   A.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
	   A.RATIOSCORE, --ร้อยละคะแนนรวมทั้งหมดที่ได้
	   A.HR_EVLOTSCOREITEM_ID,
	   A.HEADERFINISHDATE,
	   A.SELFFINISHDATE,
	   A.HEADERADDITION,
	   A.TOTALCOURSE,
	   A.HR_STAFFBOARD1_ID,
	   A.HR_STAFFBOARD2_ID,
	   A.HR_STAFFBOARD3_ID,
	   A.HR_STAFFBOARD4_ID,
	   A.HR_STAFFBOARD5_ID,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.GUID,

	   B.STAFFCODE,
	   B.SNAME,
	   B.SNAMEENG,
	   B.SNAMEFULL,
	   B.STAFFSTATUS_ID,
	   B.STAFFSTATUSNAME,

	   C.POSITIONCODE,
	   C.POSITIONNAME,
	   D.DEPARTMENTCODE,
	   D.DEPARTMENTFULLNAME,
	   E.EVPOSITIONCODE,
	   E.EVPOSITIONNAME,
	   E.ISACTIVE_ID,
	   F.POSITIONEXNAME,
	   CAST(NVL(DECODE(SM.CONFIGVALUE, '1', LWP.MAXSCORE, L.TOTALSCORE), 0) AS NUMBER(15, 2)) AS MAXSCORE,
	   L.TOTALSCORE, --คะแนนเต็มแต่ละตำแหน่ง
	   CAST(NVL(WG.INPUTSCORE, 0) AS NUMBER(10, 2)) AS SCOREACTUAL, --คะแนนผลสัมฤทธิ์ของงานที่บันทึก
	   CAST(NVL(WG.SCORE, 0) AS NUMBER(10, 2)) AS SCORE, --คะแนนผลสัมฤทธิ์ของงานที่ได้
	   A.SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
	   A.LEVELNAME, --ระดับคะแนนการประเมิน

	   AB.ORDERNO,
	   AB.HR_STAFF_ID AS HR_STAFFBOARD_ID,
	   AB.BOARDSTATUS_ID
FROM   VW_HR_EVAPP_INFO A
INNER  JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID = B.ID
INNER  JOIN VW_HR_POSITION C ON A.HR_POSITION_ID = C.ID
INNER  JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID = D.ID
INNER  JOIN VW_HR_EVPOSITION E ON A.HR_EVPOSITION_ID = E.ID
INNER  JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID = L.ID
LEFT   JOIN VW_HR_POSITIONEX F ON A.HR_POSITIONEX_ID = F.ID
LEFT   JOIN (SELECT HR_EVAPP_ID,
					SUM(SUM_WORKGROUPSCORE) AS SCORE,
					SUM(SUM_TOTALSCORE) AS INPUTSCORE
			 FROM   VW_HR_EVAPPWORK_SUMGROUP
			 GROUP  BY HR_EVAPP_ID) WG ON A.ID = WG.HR_EVAPP_ID
INNER  JOIN (SELECT P.HR_EVLOTWL_ID,
					P.HR_EVPOSITION_ID,
					SUM(MAXSCORE) AS MAXSCORE
			 FROM   HR_EVLOTWLPOSGRP GG
			 INNER  JOIN HR_EVLOTWLPOS P ON GG.HR_EVLOTWLPOS_ID = P.ID
			 GROUP  BY P.HR_EVLOTWL_ID,
					   P.HR_EVPOSITION_ID) LWP ON L.HR_EVLOTWL_ID = LWP.HR_EVLOTWL_ID
												  AND A.HR_EVPOSITION_ID = LWP.HR_EVPOSITION_ID
CROSS  JOIN (SELECT * FROM SS_CONFIG WHERE CONFIGCODE = 'HR_EV.MAXSCORE.MODE') SM
INNER  JOIN HR_EVAPPBOARD AB ON A.ID = AB.HR_EVAPP_ID;

-- ----------------------------
-- View structure for VW_HR_EVAPP_DISPLAY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPP_DISPLAY" AS SELECT A.ID,
	   A.APPSTATUS_ID,
	   A.HR_EVLOTAPP_ID,
	   L.EVLOTAPPNAME,
	   L.INPUTMAXDATE,
	   S.STAFFCODE,
	   S.SEX_CODE,
	   B.HR_NATION_ID,
	   EP.EVPOSITIONNAME,
	   PS.POSITIONNAME,
	   DECODE(S.SEX_CODE, 'M', 'M:ชาย', 'F', 'F:หญิง', '') AS SEXNAME,
	   CASE
		   WHEN B.HR_NATION_ID = FN_SS_CONFIG_GET('HR.DEFAULT.NATION.THAI_ID') OR B.HR_NATION_ID = 1 OR B.HR_NATION_ID IS NULL THEN
			FN_HR_STAFF_GETNAME(1, PF.PREFIXNAME, S.STAFFNAME, S.STAFFMIDNAME, S.STAFFSURNAME) /* || CASE
                                                             WHEN PFR.ISHR_ID = 1 AND PFR.PREFIXCODE BETWEEN 011 AND 020 THEN
                                                              ', ' || PFR.PREFIXABB
                                                         END*/
		   ELSE
			FN_HR_STAFF_GETNAME(0,
								NVL(PF.PREFIXNAMEENG, PF.PREFIXNAME),
								NVL(S.STAFFNAMEENG, S.STAFFNAME),
								NULL, --nvl(S.STAFFMIDNAMEENG, S.STAFFMIDNAME),
								NVL(S.STAFFSURNAMEENG, S.STAFFSURNAME)) /*|| CASE
                                                             WHEN PFR.ISHR_ID = 1 AND PFR.PREFIXCODE BETWEEN 011 AND 020 THEN
                                                              ', ' || PFR.PREFIXABBENG
                                                         END*/
	   END AS SNAME,
	   STS.BYTEID || ': ' || STS.BYTEDES STAFFSTATUS,
	   CASE
		   WHEN S.HR_STAFFTYPE_ID IS NOT NULL THEN
			ST.STAFFTYPECODE || ': ' || ST.STAFFTYPENAME
		   ELSE
			ST.STAFFTYPECODE || ST.STAFFTYPENAME
	   END AS STAFFTYPE,
	   CASE
		   WHEN S.HR_POSITION_ID IS NOT NULL THEN
			PS.POSITIONCODE || ': ' || PS.POSITIONNAME
		   ELSE
			PS.POSITIONCODE || PS.POSITIONNAME
	   END AS POSITION,
	   CASE
		   WHEN S.MT_DEPARTMENT_ID IS NOT NULL THEN
		   /*D.DEPARTMENTCODE || ': ' ||*/
			D.DEPARTMENTFULLNAME
		   ELSE
		   /*D.DEPARTMENTCODE ||*/
			D.DEPARTMENTFULLNAME
	   END AS DEPARTMENT,
	   /*FN_HR_POSITIONEXECTEXTLIST(S.ID)*/
	   NULL AS POSITIONEXECTEXTLIST, -- ตำแหน่งทางบริหาร
	   /*FN_HR_GETPOSITIONEXECID(S.ID)*/
	   NULL AS HR_POSITIONEXEC_ID,
	   CASE
		   WHEN S.STAFFSTATUS_ID > 70 AND S.LEAVEDATE IS NOT NULL THEN
			TO_NUMBER(TO_CHAR(S.LEAVEDATE, 'YYYY')) + 543
		   ELSE
			S.RETIREYEAR + S.RETIREYEAREXTEND
	   END AS RETIREYEAR,
	   TO_CHAR(TO_NUMBER(TO_CHAR(S.ADMITDATE, 'dd', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))) || ' ' ||
	   TO_CHAR(S.ADMITDATE, 'mon YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') ADMITDATE,
	   TO_CHAR(TO_NUMBER(TO_CHAR(S.TRANSFERDATE, 'dd', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))) || ' ' ||
	   TO_CHAR(S.TRANSFERDATE, 'mon YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') TRANSFERDATE,
	   TRIM(TO_CHAR(TO_NUMBER(TO_CHAR(S.LEAVEDATE, 'dd', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))) || ' ' ||
			TO_CHAR(S.LEAVEDATE, 'mon YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')) LEAVEDATE,
	   TO_CHAR(TO_NUMBER(TO_CHAR(B.BIRTHDATE, 'dd', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))) || ' ' ||
	   TO_CHAR(B.BIRTHDATE, 'mon YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') BIRTHDATE,
	   NULL AS CONTRACTDURATION,
	   CASE
		   WHEN B.BIRTHDATE IS NOT NULL THEN
			GET_HRM_STIMEDIFF(B.BIRTHDATE, SYSDATE, 1, 'YEAR', 0)
		   WHEN B.BIRTHYEAR IS NOT NULL AND LENGTH(TO_CHAR(B.BIRTHYEAR)) = 4 THEN
			GET_HRM_STIMEDIFF(TO_DATE(B.BIRTHYEAR - 543 || '0101', 'YYYYMMDD'), SYSDATE, 1, 'YEAR', 0)
		   ELSE
			NULL
	   END AS BIRTHAGEYEAR,
	   CASE
		   WHEN B.BIRTHDATE IS NOT NULL THEN
			FN_HR_STIMEDIFF(B.BIRTHDATE, TRUNC(SYSDATE), 0, 'YEAR', NULL)
	   END AS BIRTHAGE,
	   CASE
		   WHEN S.LEAVEDATE IS NOT NULL THEN
			FN_HR_STIMEDIFF(S.ADMITDATE, S.LEAVEDATE, 0, 'YEAR', NULL)
		   ELSE
			FN_HR_STIMEDIFF(S.ADMITDATE, TRUNC(SYSDATE), 0, 'YEAR', NULL)
	   END AS WORKAGE,
	   A.GUID,
	   A.SCOREAPPROVE AS SCORE,
	   --CAST(NVL(WG.SCORE, 0) AS NUMBER(15, 2)) AS SCORE,

	   FN_HR_STAFF_GETNAME(1, MP.PREFIXNAME, M.STAFFNAME, M.STAFFMIDNAME, M.STAFFSURNAME) AS HEADERNAME,
	   A.HEADERSTATUS_ID,
	   A.HEADERSUBMITDATE,
	   A.SCOREAPPROVE,
	   A.RATIOACHIEVEMENT,
	   A.RATIOBEHAVIOR,
	   A.RATIOSCORE,
	   A.HEADERADDITION,
	   LS.LEVELNAME,
	   S.IMAGEFOLDER,
	   S.IMAGEFILENAME,
	   A.HR_STAFFBOARD1_ID,
	   A.HR_STAFFBOARD2_ID,
	   A.HR_STAFFBOARD3_ID,
	   A.HR_STAFFBOARD4_ID,
	   A.HR_STAFFBOARD5_ID,
	   A.BOARDSTATUS1_ID,
	   A.BOARDSTATUS2_ID,
	   A.BOARDSTATUS3_ID,
	   A.BOARDSTATUS4_ID,
	   A.BOARDSTATUS5_ID
FROM   HR_EVAPP A
INNER  JOIN VW_HR_STAFF S ON A.HR_STAFF_ID = S.ID
LEFT   JOIN VW_HR_STAFFBIO B ON S.ID = B.HR_STAFF_ID
LEFT   JOIN VW_MT_PREFIX PF ON S.MT_PREFIX_ID = PF.ID
INNER  JOIN VW_HR_STAFFTYPE ST ON A.HR_STAFFTYPE_ID = ST.ID
INNER  JOIN VW_MT_DEPARTMENT D ON A.MT_DEPARTMENT_ID = D.ID
LEFT   JOIN VW_HR_POSITION PS ON A.HR_POSITION_ID = PS.ID
LEFT   JOIN HR_EVLOTSCOREITEM LS ON A.HR_EVLOTSCOREITEM_ID = LS.ID
INNER  JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID = L.ID
INNER  JOIN VW_HR_EVPOSITION EP ON A.HR_EVPOSITION_ID = EP.ID
LEFT   JOIN (SELECT *
			 FROM   SS_BYTEDES
			 WHERE  TABLENAME = 'HR_STAFF'
					AND COLUMNNAME = 'STAFFSTATUS_ID') STS ON S.STAFFSTATUS_ID = STS.BYTEID
LEFT   JOIN (SELECT HR_EVAPP_ID,
					SUM(SUM_TOTALSCORE) AS TOTALSCORE,
					SUM(SUM_WORKGROUPSCORE) AS SCORE
			 FROM   VW_HR_EVAPPWORK_SUMGROUP
			 GROUP  BY HR_EVAPP_ID) WG ON A.ID = WG.HR_EVAPP_ID
LEFT   JOIN VW_HR_STAFF M ON A.HR_STAFFHEADER_ID = M.ID
LEFT   JOIN VW_MT_PREFIX MP ON M.MT_PREFIX_ID = MP.ID;

-- ----------------------------
-- View structure for VW_HR_EVAPP_INFO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPP_INFO" AS SELECT A.ID,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.GUID,
	   A.HR_EVLOTAPP_ID,
	   A.APPSTATUS_ID,
	   A.HR_STAFF_ID,
	   A.HR_STAFFHEADER_ID,
	   A.SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
	   A.RATIOACHIEVEMENT, --ร้อยละคะแนนผลสัมฤทธิ์ของงาน
	   A.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
	   A.RATIOSCORE, --ร้อยละคะแนนรวมทั้งหมดที่ได้
	   A.HR_EVLOTSCOREITEM_ID,
	   LS.LEVELNAME, --ระดับคะแนนการประเมิน
	   A.HR_POSITION_ID,
	   A.HR_STAFFTYPE_ID,
	   A.MT_DEPARTMENT_ID,
	   A.HR_POSITIONEX_ID,
	   A.HR_EVPOSITION_ID,
	   A.HR_STAFFBOARD1_ID,
	   A.HR_STAFFBOARD2_ID,
	   A.HR_STAFFBOARD3_ID,
	   A.HR_STAFFBOARD4_ID,
	   A.HR_STAFFBOARD5_ID,
	   A.HEADERSTATUS_ID,
	   A.HEADERSUBMITDATE,
	   A.HEADERFINISHDATE,
	   A.SELFFINISHDATE,
	   A.HEADERADDITION,
	   A.TOTALCOURSE
FROM   HR_EVAPP A
LEFT   JOIN HR_EVLOTSCOREITEM LS ON A.HR_EVLOTSCOREITEM_ID = LS.ID;

-- ----------------------------
-- View structure for VW_HR_EVAPP_RANK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPP_RANK" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.ID AS HR_EVLOTAPP_ID,
	B.HR_EVPOSITION_ID,
	B.EVPOSITIONCODE,
	B.EVPOSITIONNAME,
	B.EVPOSITIONCODE || ': ' || B.EVPOSITIONNAME AS EVPOSITION_DISPLAY,
	CAST(NVL(DECODE(SM.CONFIGVALUE,'1',B.SUM_MAXSCORE,A.TOTALSCORE), 0) AS NUMBER(15, 2)) AS SUM_MAXSCORE,
	B.ISACTIVE_ID,
	S.STAFFCODE,
	S.SNAME,
	S.SNAMEFULL,
	W.MT_DEPARTMENT_ID,
	D.DEPARTMENTCODE,
	D.DEPARTMENTNAME,
	D.DEPARTMENTFULLNAME,
	CAST(NVL(W.TOTALACHIEVEMENT, 0) AS NUMBER(10, 2)) AS SCOREACTUAL, --คะแนนผลสัมฤทธิ์ของงานที่บันทึก
	CAST(NVL(W.SCOREAPPROVE, 0) AS NUMBER(10, 2)) AS SCORE, --คะแนนผลสัมฤทธิ์ของงานที่ได้
	CAST(NVL(W.SCOREAPPROVE,0) AS NUMBER(10,2)) AS SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
	W.RATIOACHIEVEMENT,--ร้อยละคะแนนผลสัมฤทธิ์ของงาน
	W.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
	W.RATIOSCORE --ร้อยละคะแนนรวมทั้งหมดที่ได้
FROM HR_EVLOTAPP A
	INNER JOIN VW_HR_EVLOTWLPOS B ON A.HR_EVLOTWL_ID=B.HR_EVLOTWL_ID
	LEFT JOIN
	(
		SELECT O.HR_EVLOTAPP_ID, HR_EVPOSITION_ID, RATIOSCORE, SCOREAPPROVE, SCOREGROUP, SCOREINPUT, ROW_NUMBER() OVER(
                PARTITION BY HR_EVLOTAPP_ID, HR_EVPOSITION_ID
                ORDER BY RATIOSCORE DESC, SCOREAPPROVE DESC, SCOREGROUP DESC, SCOREINPUT DESC
            ) AS ORDERNO
		FROM (
				SELECT HR_EVLOTAPP_ID, HR_EVPOSITION_ID, RATIOSCORE, SCOREAPPROVE, SCOREGROUP, SCOREINPUT
				FROM HR_EVAPP
				WHERE SCOREAPPROVE>0
				GROUP BY HR_EVLOTAPP_ID, HR_EVPOSITION_ID, RATIOSCORE, SCOREAPPROVE, SCOREGROUP, SCOREINPUT
			) O
	) WI ON A.ID=WI.HR_EVLOTAPP_ID AND B.HR_EVPOSITION_ID=WI.HR_EVPOSITION_ID AND WI.ORDERNO<=1
	LEFT JOIN HR_EVAPP W ON A.ID=W.HR_EVLOTAPP_ID AND B.HR_EVPOSITION_ID=W.HR_EVPOSITION_ID AND W.RATIOSCORE=WI.RATIOSCORE AND W.SCOREAPPROVE=WI.SCOREAPPROVE AND W.SCOREGROUP=WI.SCOREGROUP AND W.SCOREINPUT=WI.SCOREINPUT AND W.SCOREAPPROVE>0
	--LEFT JOIN VW_MT_DEPARTMENT D ON W.MT_DEPARTMENT_ID=D.ID
	LEFT JOIN (SELECT * FROM VG_MT_DEPARTMENT WHERE SS_APPLICATION_ID=160) D ON W.MT_DEPARTMENT_ID=D.VALUE
	LEFT JOIN VW_HR_STAFF_NAME S ON W.HR_STAFF_ID=S.ID
	CROSS JOIN (SELECT * FROM SS_CONFIG WHERE CONFIGCODE='HR_EV.MAXSCORE.MODE') SM;

-- ----------------------------
-- View structure for VW_HR_EVAPP_RANK_BAK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPP_RANK_BAK" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.ID AS HR_EVLOTAPP_ID,
	B.HR_EVPOSITION_ID,
	B.EVPOSITIONCODE,
	B.EVPOSITIONNAME,
	B.SUM_MAXSCORE,
	CAST(NVL(W.ORDERNO,1) AS NUMBER(2)) AS ORDERNO,
	CAST(NVL(W.SCOREAPPROVE,0) AS NUMBER(10,2)) AS SCOREAPPROVE
FROM HR_EVLOTAPP A
	INNER JOIN VW_HR_EVLOTWLPOS B ON A.HR_EVLOTWL_ID=B.HR_EVLOTWL_ID
	LEFT JOIN
	(
		SELECT O.HR_EVLOTAPP_ID, HR_EVPOSITION_ID, SCOREAPPROVE, ROW_NUMBER() OVER(
                PARTITION BY HR_EVLOTAPP_ID, HR_EVPOSITION_ID
                ORDER BY SCOREAPPROVE DESC
            ) AS ORDERNO
		FROM (
				SELECT HR_EVLOTAPP_ID, HR_EVPOSITION_ID, SCOREAPPROVE
				FROM HR_EVAPP
				WHERE SCOREAPPROVE>0
				GROUP BY HR_EVLOTAPP_ID, HR_EVPOSITION_ID, SCOREAPPROVE
			) O
	) W ON A.ID=W.HR_EVLOTAPP_ID AND B.HR_EVPOSITION_ID=W.HR_EVPOSITION_ID AND W.ORDERNO<=10;

-- ----------------------------
-- View structure for VW_HR_EVAPP_RANK_BAK2
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVAPP_RANK_BAK2" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.ID AS HR_EVLOTAPP_ID,
	B.HR_EVPOSITION_ID,
	B.EVPOSITIONCODE,
	B.EVPOSITIONNAME,
	B.EVPOSITIONCODE || ': ' || B.EVPOSITIONNAME AS EVPOSITION_DISPLAY,
	CAST(NVL(DECODE(SM.CONFIGVALUE,'1',B.SUM_MAXSCORE,A.TOTALSCORE), 0) AS NUMBER(15, 2)) AS SUM_MAXSCORE,
	B.ISACTIVE_ID,
	S.STAFFCODE,
	S.SNAME,
	S.SNAMEFULL,
	W.MT_DEPARTMENT_ID,
	D.DEPARTMENTCODE,
	D.DEPARTMENTNAME,
	D.DEPARTMENTFULLNAME,
	CAST(NVL(WG.INPUTSCORE, 0) AS NUMBER(10, 2)) AS SCOREACTUAL, --คะแนนผลสัมฤทธิ์ของงานที่บันทึก
	CAST(NVL(WG.SCORE, 0) AS NUMBER(10, 2)) AS SCORE, --คะแนนผลสัมฤทธิ์ของงานที่ได้
	CAST(NVL(W.SCOREAPPROVE,0) AS NUMBER(10,2)) AS SCOREAPPROVE, --คะแนนผลสัมฤทธิ์ของงานที่ยืนยัน
	W.RATIOACHIEVEMENT,--ร้อยละคะแนนผลสัมฤทธิ์ของงาน
	W.RATIOBEHAVIOR, --ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ)
	W.RATIOSCORE --ร้อยละคะแนนรวมทั้งหมดที่ได้
FROM HR_EVLOTAPP A
	INNER JOIN VW_HR_EVLOTWLPOS B ON A.HR_EVLOTWL_ID=B.HR_EVLOTWL_ID
	LEFT JOIN HR_EVAPP W ON A.ID=W.HR_EVLOTAPP_ID AND B.HR_EVPOSITION_ID=W.HR_EVPOSITION_ID AND W.SCOREAPPROVE>0
	--LEFT JOIN HR_EVLOTAPP L ON W.HR_EVLOTAPP_ID=L.ID
	LEFT JOIN VW_MT_DEPARTMENT D ON W.MT_DEPARTMENT_ID=D.ID
	LEFT JOIN VW_HR_STAFF_NAME S ON W.HR_STAFF_ID=S.ID
	LEFT JOIN
	 (SELECT HR_EVAPP_ID, SUM(SUM_WORKGROUPSCORE) AS SCORE,  SUM(SUM_TOTALSCORE) AS INPUTSCORE
	  FROM VW_HR_EVAPPWORK_SUMGROUP
		WHERE SUM_WORKGROUPSCORE>0
	  GROUP BY HR_EVAPP_ID) WG ON W.ID=WG.HR_EVAPP_ID
	CROSS JOIN (SELECT * FROM SS_CONFIG WHERE CONFIGCODE='HR_EV.MAXSCORE.MODE') SM;

-- ----------------------------
-- View structure for VW_HR_EVCOMMAND
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVCOMMAND" AS SELECT A.ID,
	   A.TYPE_ID,
	   A.HR_EVLOTAPP_ID,
	   A.COMMANDNAME,
	   A.DESCRIPTION,
	   A.COMMANDSTATUS_ID,
	   A.SCORE,
	   A.ISSUBMITAPP_ID,
	   A.MT_DEPARTMENT_ID,
	   A.HR_EVCOMMANDTYPE_ID,
	   A.FL_STORAGE_ID,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.GUID,

	   B.BYTEDES AS COMMANDSTATUSNAME,
	   SC.CONFIGVALUE || '?guid=' || A.GUID AS REGISTERURL,
	   L.HR_EVLOTWL_ID,
	   L.BUDGETYEAR,
	   F.FILENAME,
	   F.GUID AS FILEGUID,

	   CT.COMMANDTYPECODE
FROM   HR_EVCOMMAND A
INNER  JOIN HR_EVCOMMANDTYPE CT ON A.HR_EVCOMMANDTYPE_ID = CT.ID
INNER  JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID = L.ID
INNER  JOIN SS_BYTEDES B ON B.TABLENAME = 'HR_EVCOMMAND'
							AND B.COLUMNNAME = 'COMMANDSTATUS_ID'
							AND A.COMMANDSTATUS_ID = B.BYTEID
LEFT   JOIN FL_STORAGE F ON A.FL_STORAGE_ID = F.ID, (SELECT * FROM SS_CONFIG WHERE CONFIGCODE = 'HR_EVCOMMAND.REGISTER.URL') SC;

-- ----------------------------
-- View structure for VW_HR_EVCOMMANDGRPWL
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVCOMMANDGRPWL" AS SELECT A.ID,
	A.GUID,
	A.HR_EVCOMMAND_ID,
	A.HR_EVLOTWLPOS_ID,
	A.HR_EVLOTWLPOSGRP_ID,
	A.HR_EVLOTWLPOSGRPMAIN_ID,
	A.HR_EVLOTWLPOSGRPWL_ID,
	A.CREATEBY,
	A.CREATEDATETIME,
	A.UPDATEBY,
	A.UPDATEDATETIME,

	C.HR_EVLOTAPP_ID,
	P.HR_EVLOTWL_ID,
	P.HR_EVPOSITION_ID,
	PS.EVPOSITIONCODE,
	LG.ORDERNO AS GROUPORDERNO,
	LM.ORDERNO AS MAINORDERNO,
	LW.ORDERNO AS WORKORDERNO
FROM HR_EVCOMMANDGRPWL A
	INNER JOIN HR_EVCOMMAND C ON A.HR_EVCOMMAND_ID=C.ID
	INNER JOIN HR_EVLOTWLPOS P ON A.HR_EVLOTWLPOS_ID=P.ID
	INNER JOIN HR_EVPOSITION PS ON P.HR_EVPOSITION_ID=PS.ID
	INNER JOIN HR_EVLOTWLPOSGRP LG ON A.HR_EVLOTWLPOSGRP_ID=LG.ID
	INNER JOIN HR_EVLOTWLPOSGRPMAIN LM ON A.HR_EVLOTWLPOSGRPMAIN_ID=LM.ID
	INNER JOIN HR_EVLOTWLPOSGRPWL LW ON A.HR_EVLOTWLPOSGRPWL_ID=LW.ID;

-- ----------------------------
-- View structure for VW_HR_EVCOMMANDKEY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVCOMMANDKEY" AS SELECT A.ID,
	A.HR_EVCOMMAND_ID,
	A.LOTCODE,
	A.SECRETKEY,
	A.ISACTIVE_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,

	B.HR_STAFF_ID,
	B.STAFFCODE,
	B.STAFFSTATUSNAME,
	B.SNAME,
	B.SNAMEENG,
	B.SNAMEFULL,
	B.SNAMEFULLENG
FROM HR_EVCOMMANDKEY A
	LEFT JOIN VW_HR_EVCOMMANDMEMBER B ON A.ID=B.HR_EVCOMMANDKEY_ID;

-- ----------------------------
-- View structure for VW_HR_EVCOMMANDMEMBER
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVCOMMANDMEMBER" AS SELECT A.ID,
	A.HR_EVCOMMAND_ID,
	A.ORDERNO,
	A.HR_STAFF_ID,
	A.HR_EVCOMMANDKEY_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,

	B.STAFFCODE,
	B.STAFFSTATUSNAME,
	B.SNAME,
	B.SNAMEENG,
	B.SNAMEFULL,
	B.SNAMEFULLENG,
	B.MT_DEPARTMENT_ID,
	D.FL_STORAGE_ID,
	D.HR_EVLOTAPP_ID,
	D.TYPE_ID,
	D.BUDGETYEAR,
	D.COMMANDNAME,
	D.COMMANDSTATUS_ID,
	D.COMMANDSTATUSNAME,
	D.GUID AS COMMANDGUID,
	D.SCORE,
	D.HR_EVCOMMANDTYPE_ID,
	A.ISACTIVE_ID,
	A.ISSUBMITAPP_ID,
	DP.DEPARTMENTCODE,
	DP.DEPARTMENTNAME,
	DP.DEPARTMENTFULLNAME,
	T.COMMANDTYPECODE,
	T.COMMANDTYPENAME,
	P.POSITIONNAME,
	NVL(A.UPDATEDATETIME, A.CREATEDATETIME) AS MEMBERDATETIME
FROM HR_EVCOMMANDMEMBER A
	INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
	INNER JOIN VW_HR_EVCOMMAND D ON A.HR_EVCOMMAND_ID=D.ID
	LEFT JOIN VW_MT_DEPARTMENT DP ON B.MT_DEPARTMENT_ID=DP.ID
	INNER JOIN HR_EVCOMMANDTYPE T ON D.HR_EVCOMMANDTYPE_ID=T.ID
	LEFT JOIN VW_HR_POSITION P ON B.HR_POSITION_ID=P.ID;

-- ----------------------------
-- View structure for VW_HR_EVCOMMANDTYPE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVCOMMANDTYPE" AS SELECT A.ID,
	A.COMMANDTYPECODE,
	A.COMMANDTYPENAME,
	A.COMMANDTYPENAMESHOW,
	A.DESCRIPTION,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY
FROM HR_EVCOMMANDTYPE A;

-- ----------------------------
-- View structure for VW_HR_EVGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVGROUP" AS SELECT A.ID,
	A.GROUPCODE,
	A.GROUPNAME,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY
FROM HR_EVGROUP A;

-- ----------------------------
-- View structure for VW_HR_EVLOTAPP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVLOTAPP" AS SELECT A.ID,
	   A.BUDGETYEAR,
	   A.ROUNDNO,
	   A.EVLOTAPPNAME,
	   A.DATEFROM,
	   A.DATETO,
	   A.INPUTMAXDATE,
	   A.HR_EVLOTWL_ID,
	   A.RATIOFORHEADER,
	   A.RATIOACHIEVEMENT,
	   A.RATIOBEHAVIOR,
	   A.HR_EVLOTSCORE_ID,
	   A.TOTALSCORE,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.GUID
FROM   HR_EVLOTAPP A;

-- ----------------------------
-- View structure for VW_HR_EVLOTAPPGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVLOTAPPGROUP" AS SELECT A.ID,
	A.HR_EVLOTAPP_ID,
	A.HR_EVGROUP_ID,
	A.SCORE,
	A.CREATEBY,
	A.CREATEDATETIME,
	A.UPDATEBY,
	A.UPDATEDATETIME,

	B.GROUPCODE,
	B.GROUPNAME
FROM HR_EVLOTAPPGROUP A
	INNER JOIN HR_EVGROUP B ON A.HR_EVGROUP_ID=B.ID;

-- ----------------------------
-- View structure for VW_HR_EVLOTAPPGROUP_SCORE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVLOTAPPGROUP_SCORE" AS SELECT A.HR_EVLOTAPP_ID,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '01' THEN
				A.SCORE
			   ELSE
				0
		   END) AS MAXSCORE_MAIN,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '02' THEN
				A.SCORE
			   ELSE
				0
		   END) AS MAXSCORE_WORK,
	   SUM(CASE NVL(TO_CHAR(EG.GROUPCODE), '-')
			   WHEN '03' THEN
				A.SCORE
			   ELSE
				0
		   END) AS MAXSCORE_PROJECT,
	   SUM(NVL(A.SCORE, 0)) AS MAXSCORE_TOTAL
FROM   HR_EVLOTAPPGROUP A
LEFT   JOIN HR_EVGROUP EG ON A.HR_EVGROUP_ID = EG.ID
GROUP  BY A.HR_EVLOTAPP_ID;

