-- ----------------------------
-- View structure for VW_HR_EVLOTWLPOS
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVLOTWLPOS" AS SELECT A.ID,
	A.HR_EVLOTWL_ID,
	A.HR_EVPOSITION_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,
	C.EVLOTWLCODE,
	C.EVLOTWLNAME,
	C.EVLOTWLNAMEENG,
	B.EVPOSITIONCODE,
	B.EVPOSITIONNAME,
	B.EVPOSITIONNAMEENG,
	B.ISACTIVE_ID,
	B.POSITIONTYPE_ID,
	CAST(NVL(D.SUM_MAXSCORE,0) AS NUMBER(15,2)) AS SUM_MAXSCORE,
	CAST(NVL(D.NOLIMIT_ID,0) AS NUMBER(15,2)) AS NOLIMIT_ID
FROM HR_EVLOTWLPOS A
	INNER JOIN VW_HR_EVPOSITION B ON A.HR_EVPOSITION_ID=B.ID
	INNER JOIN HR_EVLOTWL C ON A.HR_EVLOTWL_ID=C.ID
	LEFT JOIN (SELECT HR_EVLOTWLPOS_ID,SUM(MAXSCORE) AS SUM_MAXSCORE, MAX(CASE WHEN MAXSCORE=0 THEN 1 ELSE 0 END) NOLIMIT_ID FROM HR_EVLOTWLPOSGRP GROUP BY HR_EVLOTWLPOS_ID) D ON A.ID=D.HR_EVLOTWLPOS_ID;

-- ----------------------------
-- View structure for VW_HR_EVLOTWLPOSGRP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVLOTWLPOSGRP" AS SELECT A.ID,
	A.HR_EVLOTWLPOS_ID,
	A.ORDERNO,
	A.WORKGROUPNAME,
	A.DESCRIPTION,
	A.MAXSCORE,
	A.HR_EVGROUP_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID
FROM HR_EVLOTWLPOSGRP A;

-- ----------------------------
-- View structure for VW_HR_EVLOTWLPOSGRPMAIN
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVLOTWLPOSGRPMAIN" AS SELECT A.ID,
	A.HR_EVLOTWLPOSGRP_ID,
	A.ORDERNO,
	A.MAINNAME,
	A.EACHSCORE,
	A.MAXSCORE,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,
	A.MAINNAME || CASE WHEN A.EACHSCORE>0 OR A.MAXSCORE>0 THEN ' [' ||
		TRIM(CASE WHEN A.EACHSCORE>0 THEN TO_CHAR(A.EACHSCORE) || ' คะแนน/หน่วย' END || CASE WHEN A.MAXSCORE>0 THEN ' ไม่เกิน ' || TO_CHAR(A.EACHSCORE) || ' คะแนน' END)
	|| ']' END AS DISPLAY_MAINNAME,
	CASE WHEN A.EACHSCORE>0 OR A.MAXSCORE>0 THEN '[' ||
		TRIM(CASE WHEN A.EACHSCORE>0 THEN TO_CHAR(A.EACHSCORE) || ' คะแนน/หน่วย' END || CASE WHEN A.MAXSCORE>0 THEN ' ไม่เกิน ' || TO_CHAR(A.EACHSCORE) || ' คะแนน' END)
	|| ']' END AS DISPLAY_EACHSCORE
FROM HR_EVLOTWLPOSGRPMAIN A;

-- ----------------------------
-- View structure for VW_HR_EVLOTWLPOSGRPWL
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVLOTWLPOSGRPWL" AS SELECT A.ID,
	A.HR_EVLOTWLPOSGRP_ID,
	C.ID AS HR_EVLOTWLPOSGRPMAIN_ID,
	A.ORDERNO,
	A.WORKNAME,
	A.UNITNAME,
	A.TOTALBASE,
	A.EACHSCORE,
	A.MAXSCORE,
	A.ISREQUIREFILE_ID,
	A.FILENAME,
	A.INPUTDESCRIPTION,
	A.MINTOTAL,
	A.ISINCLUDEPROJECT_ID,
	A.SCORETYPE_ID,
	A.CANHEADERADD_ID,
	A.INPUTTYPE_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,

	B.HR_EVLOTWLPOS_ID,
	B.ORDERNO AS GROUPORDERNO,
	B.WORKGROUPNAME,
	B.MAXSCORE AS GROUPMAXSCORE,
	C.ORDERNO AS MAINORDER,
	C.MAINNAME,
	C.DISPLAY_EACHSCORE AS DISPLAY_MAINEACHSCORE,
	C.EACHSCORE AS MAINEACHSCORE,
	C.MAXSCORE AS MAINMAXSCORE,
	CAST(CASE WHEN A.EACHSCORE=0 THEN NVL(C.EACHSCORE,0) ELSE A.EACHSCORE END AS NUMBER(10,2)) AS DISPLAY_EACHSCORE,

	F1.ID AS HR_EVLOTWLPOSGRPWLFL1_ID,
	F1.ISREQUIRE_ID AS ISREQUIRE1_ID,
	F1.FILENAME AS FILENAME1,
	F1.EXTENSION AS EXTENSION1,

	F2.ID AS HR_EVLOTWLPOSGRPWLFL2_ID,
	F2.ISREQUIRE_ID AS ISREQUIRE2_ID,
	F2.FILENAME AS FILENAME2,
	F2.EXTENSION AS EXTENSION2,

	F3.ID AS HR_EVLOTWLPOSGRPWLFL3_ID,
	F3.ISREQUIRE_ID AS ISREQUIRE3_ID,
	F3.FILENAME AS FILENAME3,
	F3.EXTENSION AS EXTENSION3,

	F4.ID AS HR_EVLOTWLPOSGRPWLFL4_ID,
	F4.ISREQUIRE_ID AS ISREQUIRE4_ID,
	F4.FILENAME AS FILENAME4,
	F4.EXTENSION AS EXTENSION4,

	F5.ID AS HR_EVLOTWLPOSGRPWLFL5_ID,
	F5.ISREQUIRE_ID AS ISREQUIRE5_ID,
	F5.FILENAME AS FILENAME5,
	F5.EXTENSION AS EXTENSION5,

	F6.ID AS HR_EVLOTWLPOSGRPWLFL6_ID,
	F6.ISREQUIRE_ID AS ISREQUIRE6_ID,
	F6.FILENAME AS FILENAME6,
	F6.EXTENSION AS EXTENSION6,

	F7.ID AS HR_EVLOTWLPOSGRPWLFL7_ID,
	F7.ISREQUIRE_ID AS ISREQUIRE7_ID,
	F7.FILENAME AS FILENAME7,
	F7.EXTENSION AS EXTENSION7,

	F8.ID AS HR_EVLOTWLPOSGRPWLFL8_ID,
	F8.ISREQUIRE_ID AS ISREQUIRE8_ID,
	F8.FILENAME AS FILENAME8,
	F8.EXTENSION AS EXTENSION8,

	F9.ID AS HR_EVLOTWLPOSGRPWLFL9_ID,
	F9.ISREQUIRE_ID AS ISREQUIRE9_ID,
	F9.FILENAME AS FILENAME9,
	F9.EXTENSION AS EXTENSION9,

	F10.ID AS HR_EVLOTWLPOSGRPWLFL10_ID,
	F10.ISREQUIRE_ID AS ISREQUIRE10_ID,
	F10.FILENAME AS FILENAME10,
	F10.EXTENSION AS EXTENSION10

FROM HR_EVLOTWLPOSGRPWL A
	INNER JOIN HR_EVLOTWLPOSGRP B ON A.HR_EVLOTWLPOSGRP_ID=B.ID
	LEFT JOIN VW_HR_EVLOTWLPOSGRPMAIN C ON A.HR_EVLOTWLPOSGRPMAIN_ID=C.ID AND C.HR_EVLOTWLPOSGRP_ID=B.ID
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F1 ON A.ID=F1.HR_EVLOTWLPOSGRPWL_ID AND F1.ORDERNO=1
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F2 ON A.ID=F2.HR_EVLOTWLPOSGRPWL_ID AND F2.ORDERNO=2
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F3 ON A.ID=F3.HR_EVLOTWLPOSGRPWL_ID AND F3.ORDERNO=3
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F4 ON A.ID=F4.HR_EVLOTWLPOSGRPWL_ID AND F4.ORDERNO=4
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F5 ON A.ID=F5.HR_EVLOTWLPOSGRPWL_ID AND F5.ORDERNO=5
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F6 ON A.ID=F6.HR_EVLOTWLPOSGRPWL_ID AND F6.ORDERNO=6
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F7 ON A.ID=F7.HR_EVLOTWLPOSGRPWL_ID AND F7.ORDERNO=7
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F8 ON A.ID=F8.HR_EVLOTWLPOSGRPWL_ID AND F8.ORDERNO=8
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F9 ON A.ID=F9.HR_EVLOTWLPOSGRPWL_ID AND F9.ORDERNO=9
	LEFT JOIN HR_EVLOTWLPOSGRPWLFL F10 ON A.ID=F10.HR_EVLOTWLPOSGRPWL_ID AND F10.ORDERNO=10;

-- ----------------------------
-- View structure for VW_HR_EVLOTWLPOSGRPWLFL
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVLOTWLPOSGRPWLFL" AS SELECT A.ID,
	A.HR_EVLOTWLPOSGRPWL_ID,
	A.ORDERNO,
	A.FILENAME,
	A.EXTENSION,
	A.ISREQUIRE_ID,
	A.DESCRIPTION,
