	A.UPDATEBY,
	A.GUID
FROM HR_EVLOTWLPOSGRPWLFL A;

-- ----------------------------
-- View structure for VW_HR_EVPOSITION
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPOSITION" AS SELECT A.ID,
	A.EVPOSITIONCODE,
	A.HR_EVPOSITIONGROUP_ID,
	A.HR_EVPOSITIONLEVEL_ID,
	A.DESCRIPTION,
	A.ISACTIVE_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,

	B.EVPOSITIONGROUPCODE,
	B.EVPOSITIONGROUPNAME,
	B.EVPOSITIONGROUPNAMEENG,
	B.POSITIONTYPE_ID,
	C.EVPOSITIONLEVELCODE,
	C.EVPOSITIONLEVELNAME,
	C.EVPOSITIONLEVELNAMEENG,

	B.EVPOSITIONGROUPNAME || CASE WHEN C.EVPOSITIONLEVELNAME IS NOT NULL THEN '-' || C.EVPOSITIONLEVELNAME END AS EVPOSITIONNAME,
	B.EVPOSITIONGROUPNAMEENG || CASE WHEN C.EVPOSITIONLEVELNAMEENG IS NOT NULL THEN '-' || C.EVPOSITIONLEVELNAMEENG END AS EVPOSITIONNAMEENG
FROM HR_EVPOSITION A
	INNER JOIN HR_EVPOSITIONGROUP B ON A.HR_EVPOSITIONGROUP_ID=B.ID
	LEFT JOIN HR_EVPOSITIONLEVEL C ON A.HR_EVPOSITIONLEVEL_ID=C.ID;

-- ----------------------------
-- View structure for VW_HR_EVPOSITIONGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPOSITIONGROUP" AS SELECT A.ID,
	A.EVPOSITIONGROUPCODE,
	A.EVPOSITIONGROUPNAME,
