FROM HR_EVPOSITIONGROUP A;

-- ----------------------------
-- View structure for VW_HR_EVPOSITIONLEVEL
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPOSITIONLEVEL" AS SELECT A.ID,
