FROM HR_EVPOSITIONLEVEL A;

-- ----------------------------
-- View structure for VW_HR_EVPRJPOSITION
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPRJPOSITION" AS SELECT A.ID,
	A.PRJPOSITIONCODE,
	A.PRJPOSITIONNAME,
	A.PRJPOSITIONNAMEENG,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID
FROM HR_EVPRJPOSITION A;

-- ----------------------------
-- View structure for VW_HR_EVPROJECT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPROJECT" AS SELECT A.ID,
	   A.HR_EVLOTAPP_ID,
	   A.PROJECTNAME,
	   A.DESCRIPTION,
	   A.PERIOD,
	   A.BUDGET,
	   A.PLACE,
	   A.PROJECTSTATUS_ID,
	   A.SCORE,
	   A.WORKTYPE_ID,
	   A.CALCULATETYPE_ID,
	   A.HR_EVLOTPRJRATIO_ID,
	   A.ISSUBMITAPP_ID,
	   A.MT_DEPARTMENT1_ID,
	   A.MT_DEPARTMENT2_ID,
	   A.HR_EVPROJECTTYPE_ID,
	   A.REGISTERDESC,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.GUID,

	   B.BYTEDES AS PROJECTSTATUSNAME,
	   SC.CONFIGVALUE || '?guid=' || A.GUID AS REGISTERURL,
	   L.BUDGETYEAR
FROM   HR_EVPROJECT A
INNER  JOIN HR_EVLOTAPP L ON A.HR_EVLOTAPP_ID = L.ID
INNER  JOIN SS_BYTEDES B ON B.TABLENAME = 'HR_EVPROJECT'
							AND B.COLUMNNAME = 'PROJECTSTATUS_ID'
							AND A.PROJECTSTATUS_ID = B.BYTEID, (SELECT * FROM SS_CONFIG WHERE CONFIGCODE = 'HR_EVPROJECT.REGISTER.URL') SC;

-- ----------------------------
-- View structure for VW_HR_EVPROJECTKEY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPROJECTKEY" AS SELECT A.ID,
	A.HR_EVPROJECT_ID,
	A.LOTCODE,
	A.SECRETKEY,
	A.ISACTIVE_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,

	B.HR_STAFF_ID,
	B.STAFFCODE,
	B.STAFFSTATUSNAME,
	B.SNAME,
	B.SNAMEENG,
	B.SNAMEFULL,
	B.SNAMEFULLENG
FROM HR_EVPROJECTKEY A
	LEFT JOIN VW_HR_EVPROJECTMEMBER B ON A.ID=B.HR_EVPROJECTKEY_ID;

-- ----------------------------
-- View structure for VW_HR_EVPROJECTMEMBER
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPROJECTMEMBER" AS SELECT A.ID,
	A.HR_EVPROJECT_ID,
	A.ORDERNO,
	A.HR_STAFF_ID,
	A.HR_EVPRJPOSITION_ID,
	A.PROPORTION,
	A.HR_EVPROJECTKEY_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,
	A.GUID,

	B.STAFFCODE,
	B.STAFFSTATUSNAME,
	B.SNAME,
	B.SNAMEENG,
	B.SNAMEFULL,
	B.SNAMEFULLENG,
	B.MT_DEPARTMENT_ID,
	C.PRJPOSITIONNAME,
	D.HR_EVLOTAPP_ID,
	D.BUDGETYEAR,
	D.PROJECTNAME,
	D.PROJECTSTATUS_ID,
	D.PROJECTSTATUSNAME,
	D.GUID AS PROJECTGUID,
	D.WORKTYPE_ID,
	D.PLACE,
	D.PERIOD,
	CAST(CASE WHEN D.WORKTYPE_ID=2 THEN D.SCORE ELSE
		CASE WHEN D.CALCULATETYPE_ID=1 THEN D.SCORE*E.RATIO/100 ELSE D.SCORE*A.PROPORTION/100 END END AS NUMBER(15,2)) AS SCORE,
	A.ISACTIVE_ID,
	A.ISSUBMITAPP_ID,
	DP.DEPARTMENTCODE,
	DP.DEPARTMENTNAME,
	DP.DEPARTMENTFULLNAME,
	T.PROJECTTYPECODE,
	T.PROJECTTYPENAME,
	P.POSITIONNAME,
	NVL(A.UPDATEDATETIME, A.CREATEDATETIME) AS MEMBERDATETIME
FROM HR_EVPROJECTMEMBER A
	INNER JOIN VW_HR_STAFF_NAME B ON A.HR_STAFF_ID=B.ID
	LEFT JOIN HR_EVPRJPOSITION C ON A.HR_EVPRJPOSITION_ID=C.ID
	INNER JOIN VW_HR_EVPROJECT D ON A.HR_EVPROJECT_ID=D.ID
	LEFT JOIN HR_EVLOTPRJRATIOITEM E ON D.HR_EVLOTPRJRATIO_ID=E.HR_EVLOTPRJRATIO_ID AND A.HR_EVPRJPOSITION_ID=E.HR_EVPRJPOSITION_ID
	LEFT JOIN VW_MT_DEPARTMENT DP ON B.MT_DEPARTMENT_ID=DP.ID
	INNER JOIN HR_EVPROJECTTYPE T ON D.HR_EVPROJECTTYPE_ID=T.ID
	LEFT JOIN VW_HR_POSITION P ON B.HR_POSITION_ID=P.ID;

-- ----------------------------
-- View structure for VW_HR_EVPROJECTTYPE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPROJECTTYPE" AS SELECT A.ID,
	A.PROJECTTYPECODE,
	A.PROJECTTYPENAME,
	A.PROJECTTYPENAMESHOW,
	A.DESCRIPTION,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY
FROM HR_EVPROJECTTYPE A;

-- ----------------------------
-- View structure for VW_HR_EVPROJECT_APP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_EVPROJECT_APP" AS SELECT CAST(MIN(ROWNUM) AS NUMBER(12)) AS ID,
	AP.HR_EVLOTAPP_ID,
	A.HR_EVPROJECT_ID,
	P.PROJECTNAME,
	P.PROJECTSTATUS_ID
FROM HR_EVPROJECTMEMBER A
	INNER JOIN HR_EVPROJECT P ON A.HR_EVPROJECT_ID=P.ID
	INNER JOIN HR_EVAPPWORK AW ON A.ID=AW.HR_EVPROJECTMEMBER_ID
	INNER JOIN HR_EVAPP AP ON AW.HR_EVAPP_ID=AP.ID
GROUP BY AP.HR_EVLOTAPP_ID,
	A.HR_EVPROJECT_ID,
	P.PROJECTNAME,
	P.PROJECTSTATUS_ID;

-- ----------------------------
-- View structure for VW_HR_POSITION
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_POSITION" AS SELECT A.POSITIONID AS ID,
	   A.POSITIONCODE,
	   A.POSITIONNAME,
	   A.POSITIONNAMEENG,
	   A.DEPARTMENTID AS MT_DEPARTMENT_ID,
	   A.CAMPUSID AS MT_CAMPUS_ID,
	   A.WORKPOSITIONID AS HR_POSITIONWORK_ID,
	   CAST(A.STAFFTYPE AS NUMBER(4)) AS STAFFTYPE_ID,
	   CAST(A.STAFFTYPESUB AS NUMBER(4)) AS STAFFTYPESUB_ID,
	   A.POSITIONSTATUS AS POSITIONSTATUS_CODE,
	   A.STAFFID AS HR_STAFF_ID,
	   A.POSITIONLEVELID AS HR_POSITIONLEVEL_ID
FROM PROMIS.POSITION A;

-- ----------------------------
-- View structure for VW_HR_POSITIONEV
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_POSITIONEV" AS SELECT A.ID,
	A.HR_POSITION_ID,
	A.HR_EVPOSITION_ID,
	A.HR_POSITIONEX_ID,
	A.CREATEBY,
	A.CREATEDATETIME,
	A.UPDATEBY,
	A.UPDATEDATETIME,
	A.GUID,

	P.EVPOSITIONCODE,
	P.EVPOSITIONNAME,
	P.EVPOSITIONNAMEENG,

	PE.POSITIONEXCODE,
	PE.POSITIONEXNAME,
	PE.POSITIONEXNAMEENG,
	PE.HR_STAFF_ID,
	PE.STAFFCODE,
	PE.STAFFNAMEFULL,
	PE.DEPARTMENTCODE,
	PE.DEPARTMENTFULLNAME
FROM HR_POSITIONEV A
	LEFT JOIN VW_HR_POSITIONEX PE ON A.HR_POSITIONEX_ID=PE.ID
	LEFT JOIN VW_HR_EVPOSITION P ON A.HR_EVPOSITION_ID=P.ID;

-- ----------------------------
-- View structure for VW_HR_POSITIONEX
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_POSITIONEX" AS SELECT A.EXPOSITIONID AS ID,
	A.EXPOSITIONCODE AS POSITIONEXCODE,
	A.POSITIONNAME AS POSITIONEXNAME,
	A.POSITIONNAMEENG AS POSITIONEXNAMEENG,
	A.STAFFID AS HR_STAFF_ID,
	B.STAFFCODE,
	B.SNAMEFULL AS STAFFNAMEFULL,
   CASE
        WHEN A.STAFFID IS NOT NULL THEN
         B.STAFFCODE || ': ' || B.SNAMEFULL
    END AS DISPLAY_STAFFNAMEFULL,
	A.DEPARTMENTID AS MT_DEPARTMENT_ID,
	C.DEPARTMENTCODE,
	C.DEPARTMENTFULLNAME,
	CAST(A.EXPOSITIONSTATUS AS NUMBER(2)) AS POSITIONEXSTATUS_ID,
	PS.BYTECODE AS POSITIONEXSTATUSCODE,
	PS.BYTEDES AS POSITIONEXSTATUSNAME
FROM PROMIS.EXPOSITION A
	LEFT JOIN VW_HR_STAFF_NAME B ON A.STAFFID=B.ID
	INNER JOIN VW_MT_DEPARTMENT C ON A.DEPARTMENTID=C.ID
	LEFT JOIN VW_MIS_BYTEDES PS ON PS.TABLENAME='EXPOSITION' AND PS.COLUMNNAME='EXPOSITIONSTATUS' AND A.EXPOSITIONSTATUS=PS.BYTECODE;

-- ----------------------------
-- View structure for VW_HR_POSITIONEXEV
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_POSITIONEXEV" AS SELECT A.ID,
	A.HR_POSITIONEX_ID,
	A.MASTER_ID,
	A.CREATEBY,
	A.CREATEDATETIME,
	A.UPDATEBY,
	A.UPDATEDATETIME,
	A.GUID,

	P.EXPOSITIONCODE AS MASTER_POSITIONEXCODE,
	P.POSITIONNAME AS MASTER_POSITIONEXNAME,
	P.POSITIONNAMEENG AS MASTER_POSITIONEXNAMEENG,
	B.ID AS HR_STAFF_ID,
	B.STAFFCODE AS MASTER_STAFFCODE,
	B.SNAMEFULL AS MASTER_STAFFNAMEFULL,
	C.DEPARTMENTCODE AS MASTER_DEPARTMENTCODE,
	C.DEPARTMENTFULLNAME AS MASTER_DEPARTMENTFULLNAME
FROM HR_POSITIONEXEV A
	INNER JOIN PROMIS.EXPOSITION P ON A.MASTER_ID=P.EXPOSITIONID
	LEFT JOIN VW_HR_STAFF_NAME B ON P.STAFFID=B.ID
	INNER JOIN VW_MT_DEPARTMENT C ON P.DEPARTMENTID=C.ID;

-- ----------------------------
-- View structure for VW_HR_POSITIONEX_INFO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_POSITIONEX_INFO" AS SELECT A.ID,
	A.POSITIONEXCODE,
	A.POSITIONEXNAME,
	A.POSITIONEXNAMEENG,
	A.HR_STAFF_ID,
	A.STAFFCODE,
	A.STAFFNAMEFULL,
	A.DISPLAY_STAFFNAMEFULL,
	A.MT_DEPARTMENT_ID,
	A.DEPARTMENTCODE,
	A.DEPARTMENTFULLNAME,
	A.POSITIONEXSTATUS_ID,
	A.POSITIONEXSTATUSCODE,
	A.POSITIONEXSTATUSNAME,

	E.MASTER_ID,
	E.MASTER_POSITIONEXCODE,
	E.MASTER_POSITIONEXNAME,
	E.MASTER_POSITIONEXNAMEENG,
	E.MASTER_STAFFCODE,
	E.MASTER_STAFFNAMEFULL,
	E.MASTER_DEPARTMENTCODE,
	E.MASTER_DEPARTMENTFULLNAME
FROM VW_HR_POSITIONEX A
	LEFT JOIN VW_HR_POSITIONEXEV E ON A.ID=E.HR_POSITIONEX_ID;

-- ----------------------------
-- View structure for VW_HR_POSITIONWORK
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_POSITIONWORK" AS SELECT A.WORKPOSITIONID AS ID,
  A.WORKPOSITIONCODE AS POSITIONWORKCODE,
    A.WORKPOSITIONNAME AS POSITIONWORKNAME,
    A.WORKPOSITIONNAMEENG AS POSITIONWORKNAMEENG,
  A.STAFFGROUP AS STAFFGROUP_ID,
  B.BYTEORDER || '-' || A.WORKPOSITIONCODE AS POSITIONWORKORDER
FROM PROMIS.WORKPOSITION A
  INNER JOIN (SELECT * FROM VW_MIS_BYTEDES WHERE TABLENAME='STAFFTYPE' AND COLUMNNAME='STAFFGROUP') B ON TO_CHAR(A.STAFFGROUP)=B.BYTECODE;

-- ----------------------------
-- View structure for VW_HR_POSITION_INFO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_POSITION_INFO" AS SELECT P.ID,
	   P.POSITIONCODE,
	   P.POSITIONNAME,
	   P.POSITIONNAMEENG,
	   P.MT_DEPARTMENT_ID,
	   P.MT_CAMPUS_ID,
	   P.HR_POSITIONWORK_ID,
	   V.POSITIONWORKCODE,
	   V.POSITIONWORKNAME,
	   P.POSITIONSTATUS_CODE,
	   PS.BYTECODE AS POSITIONSTATUSCODE,
	   PS.BYTEDES AS POSITIONSTATUSNAME,
	   P.HR_STAFF_ID,
	   S.STAFFCODE,
	   S.SNAMEFULL AS STAFFNAMEFULL,
	   CASE
		   WHEN S.ID IS NOT NULL THEN
			S.STAFFCODE || ': ' || S.SNAMEFULL || ' • ' || S.STAFFSTATUSNAME
	   END AS DISPLAY_STAFFNAMEFULL,
	   D.DEPARTMENTCODE,
	   D.DEPARTMENTNAME,
	   P.STAFFTYPE_ID,
	   ST.BYTECODE AS STAFFTYPECODE,
	   ST.BYTEDES AS STAFFTYPENAME,
	   P.STAFFTYPESUB_ID,
	   STS.STAFFTYPESUBCODE,
	   STS.STAFFTYPESUBNAME,
	   EP.HR_EVPOSITION_ID,
	   EP.HR_POSITIONEX_ID,
	   EP.EVPOSITIONCODE,
	   EP.EVPOSITIONNAME,
	   EP.EVPOSITIONNAMEENG,

	   EP.POSITIONEXCODE,
	   EP.POSITIONEXNAME,
	   EP.POSITIONEXNAMEENG,
	   EP.STAFFCODE AS POSITIONEX_STAFFCODE,
	   EP.STAFFNAMEFULL AS POSITIONEX_STAFFNAMEFULL,
	   EP.DEPARTMENTCODE AS POSITIONEX_DEPARTMENTCODE,
	   EP.DEPARTMENTFULLNAME AS POSITIONEX_DEPARTMENTFULLNAME,
	   S.STAFFSTATUS_ID,
	   S.STAFFSTATUSCODE,
	   S.STAFFSTATUSNAME
FROM   VW_HR_POSITION P
INNER  JOIN VW_HR_DEPARTMENT D ON P.MT_DEPARTMENT_ID = D.ID
INNER  JOIN VW_HR_POSITIONWORK V ON P.HR_POSITIONWORK_ID = V.ID
INNER  JOIN VW_MIS_BYTEDES ST ON ST.TABLENAME = 'STAFF'
								 AND ST.COLUMNNAME = 'STAFFTYPE'
								 AND ST.BYTECODE = TO_CHAR(P.STAFFTYPE_ID)
INNER  JOIN VW_HR_STAFFTYPESUB STS ON P.STAFFTYPESUB_ID=STS.ID
INNER  JOIN VW_MIS_BYTEDES PS ON PS.TABLENAME = 'POSITION'
								 AND PS.COLUMNNAME = 'POSITIONSTATUS'
								 AND PS.BYTECODE = TO_CHAR(P.POSITIONSTATUS_CODE)
LEFT   JOIN VW_HR_POSITIONEV EP ON EP.ID = P.ID
LEFT   JOIN VW_HR_STAFF_NAME S ON P.HR_STAFF_ID = S.ID;

-- ----------------------------
-- View structure for VW_HR_STAFF
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_STAFF" AS SELECT A.STAFFID AS ID,
	TO_CHAR(A.STAFFID) AS GUID,
    A.PREFIXID AS MT_PREFIX_ID,
    A.STAFFSEX AS SEX_CODE,
    --A.PREFIXGENDERID,
    A.STAFFCODE,
    A.STAFFNAME,
     NULL AS STAFFMIDNAME,
    A.STAFFSURNAME,
    A.STAFFNAMEENG,
    A.STAFFSURNAMEENG,
    A.POSITIONNAME,
	A.ADMITDATE,
	A.LEAVEDATE,
	A.RETIREYEAR,
    A.RETIREYEAREXTEND,
    A.DEPARTMENTID AS MT_DEPARTMENT_ID,
	A.MASTERDEPARTMENTID AS MT_DEPARTMENTMASTER_ID,
    A.WORKDEPARTMENTID AS MT_DEPARTMENTWORK_ID,
    A.POSITIONID AS HR_POSITION_ID,
    A.ACADPOSITIONID AS HR_POSITIONWORK_ID,
    A.WORKPOSITIONID AS HR_POSITIONACAD_ID,
	A.EXPOSITIONID AS HR_POSITIONEX_ID,
    A.STAFFTYPE AS HR_STAFFTYPE_ID,
    A.STAFFTYPESUB AS HR_STAFFTYPESUB_ID,
    TO_NUMBER(A.STAFFSTATUS) AS STAFFSTATUS_ID,
    CASE WHEN A.STAFFSTATUS < 70 THEN 1 ELSE 0 END AS ISACTIVE_ID,
    TO_NUMBER(NVL(A.STAFFGROUP,0)) AS STAFFGROUP_ID,
    A.TRANSFERDATE,
    --A.IMAGEFOLDER,
    --A.IMAGEFILENAME,
	B.CITIZENID AS CITIZENNO,
	B.EMAIL,
    B.BIRTHDATE,
	SS.BYTECODE AS STAFFSTATUSCODE,
	SS.BYTEDES AS STAFFSTATUSNAME,
	'D:\MISAPPS\IMAGE\STAFFIMG\' || CASE WHEN A.IMAGEFOLDER IS NOT NULL THEN A.IMAGEFOLDER || '\' END AS IMAGEFOLDER,
	NVL(A.IMAGEFILENAME,A.STAFFCODE || '.JPG') AS IMAGEFILENAME
FROM PROMIS.STAFF A
	LEFT JOIN PROMIS.STAFFBIO B ON A.STAFFID=B.STAFFID
    INNER JOIN (SELECT BYTECODE, BYTEDES
                FROM VW_MIS_BYTEDES
                WHERE TABLENAME = 'STAFFSTATUS'
                      AND COLUMNNAME = 'STAFFSTATUS') SS ON to_char(A.STAFFSTATUS) =
                                                              SS.BYTECODE;

-- ----------------------------
-- View structure for VW_HR_STAFFBIO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_STAFFBIO" AS SELECT A.STAFFID AS ID,
	A.STAFFID AS HR_STAFF_ID,
	A.CITIZENID AS CITIZENNO,
    A.BIRTHDATE,
    A.BIRTHYEAR,
	A.NATIONID AS HR_NATION_ID
FROM PROMIS.STAFFBIO A;

-- ----------------------------
-- View structure for VW_HR_STAFFEV
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_STAFFEV" AS SELECT S.ID,
	   S.STAFFCODE,
	   FN_HR_STAFF_GETNAME(1, P.PREFIXABB, S.STAFFNAME, S.STAFFMIDNAME, S.STAFFSURNAME) AS SNAMEFULL,
	   S.STAFFGROUP_ID,
	   S.STAFFSTATUS_ID,
	   S.ADMITDATE,
	   S.LEAVEDATE,
	   S.RETIREYEAR,
	   S.HR_POSITIONWORK_ID,
	   S.MT_DEPARTMENT_ID,
	   S.MT_DEPARTMENTMASTER_ID,
	   S.HR_STAFFTYPE_ID,
	   S.HR_STAFFTYPESUB_ID,
	   S.HR_POSITIONACAD_ID,
	   S.HR_POSITION_ID,
	   S.HR_POSITIONEX_ID,
	   M.MASTER_ID,

	   PS.POSITIONCODE,
	   PS.POSITIONNAME,

	   PSE.POSITIONEXCODE,
	   PSE.POSITIONEXNAME,

	   PSW.POSITIONWORKCODE,
	   PSW.POSITIONWORKNAME,

	   ST.STAFFTYPECODE,
	   ST.STAFFTYPENAME,

	   S.STAFFSTATUSCODE,
	   S.STAFFSTATUSNAME,

	   STU.BYTECODE AS STAFFTYPESUBCODE,
	   STU.BYTEDES AS STAFFTYPESUBNAME,

	   SG.BYTECODE AS STAFFGROUPCODE,
	   SG.BYTEDES AS STAFFGROUPNAME,

	   D.DEPARTMENTCODE,
	   D.DEPARTMENTNAME,
	   D.DEPARTMENTFULLNAME,
	   D.DEPARTMENTINDEX,

	   PV.HR_EVPOSITION_ID,
	   PV.EVPOSITIONCODE,
	   PV.EVPOSITIONNAME,

	   DECODE(S.HR_POSITIONEX_ID,NULL,PV.HR_STAFF_ID,EV.HR_STAFF_ID) AS MASTERDEFAULT_ID,
	   DECODE(S.HR_POSITIONEX_ID,NULL, PV.STAFFNAMEFULL,EV.MASTER_STAFFNAMEFULL) AS MASTERDEFAULT_STAFFNAMEFULL,
	   DECODE(S.HR_POSITIONEX_ID,NULL, PV.POSITIONEXNAME,EV.MASTER_POSITIONEXNAME) AS MASTERDEFAULT_POSITIONEXNAME,
	   DECODE(S.HR_POSITIONEX_ID,NULL, PV.STAFFNAMEFULL,EV.MASTER_STAFFNAMEFULL) || CHR(13) ||
	   DECODE(S.HR_POSITIONEX_ID,NULL, PV.POSITIONEXNAME,EV.MASTER_POSITIONEXNAME) AS DISPLAY_MASTERDEFAULT
FROM VW_HR_STAFF S
    INNER JOIN VW_HR_STAFFTYPE ST ON S.HR_STAFFTYPE_ID = ST.ID
    INNER JOIN (SELECT BYTECODE, BYTEDES
                FROM VW_MIS_BYTEDES
                WHERE TABLENAME = 'STAFF'
                      AND COLUMNNAME = 'STAFFTYPESUB') STU ON S.HR_STAFFTYPESUB_ID =
                                                              STU.BYTECODE
    INNER JOIN (SELECT BYTECODE, BYTEDES, TABLENAME
                FROM VW_MIS_BYTEDES
                WHERE TABLENAME='STAFFTYPE' AND COLUMNNAME = 'STAFFGROUP') SG ON S.STAFFGROUP_ID =
                                                              SG.BYTECODE
    INNER JOIN VW_MT_DEPARTMENT D ON S.MT_DEPARTMENT_ID = D.ID
    INNER JOIN VW_MT_PREFIX P ON S.MT_PREFIX_ID = P.ID
    LEFT JOIN VW_HR_POSITION PS ON S.HR_POSITION_ID = PS.ID
    LEFT JOIN VW_HR_POSITIONWORK PSW ON S.HR_POSITIONWORK_ID = PSW.ID
    LEFT JOIN VW_HR_POSITIONEV PV ON PS.ID = PV.HR_POSITION_ID
    LEFT JOIN VW_HR_POSITIONEX PSE ON S.HR_POSITIONEX_ID = PSE.ID
    LEFT JOIN VW_HR_POSITIONEXEV EV ON PSE.ID = EV.HR_POSITIONEX_ID
    LEFT JOIN HR_STAFFEV M ON S.ID = M.ID;

-- ----------------------------
-- View structure for VW_HR_STAFFTYPE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_STAFFTYPE" AS SELECT A.STAFFTYPE AS ID,
	A.STAFFTYPECODE,
    A.STAFFTYPENAME,
    A.STAFFTYPEFULLNAME,
    DECODE(A.SHOWFLAG,'Y',1,0) AS ISACTIVE_ID
FROM PROMIS.STAFFTYPE A;

-- ----------------------------
-- View structure for VW_HR_STAFFTYPESUB
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_STAFFTYPESUB" AS SELECT A.STAFFTYPESUB AS ID,
	A.STAFFTYPESUBCODE,
	A.STAFFTYPESUBNAME,
	A.STAFFTYPE AS HR_STAFFTYPE_ID,
	DECODE(A.SHOWFLAG,'Y',1,0) AS ISACTIVE_ID
FROM PROMIS.STAFFTYPESUB A;

-- ----------------------------
-- View structure for VW_HR_STAFF_DISPLAY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_STAFF_DISPLAY" AS SELECT S.ID,
	   S.STAFFCODE,
	   S.SEX_CODE,
	   B.HR_NATION_ID,
	   DECODE(S.SEX_CODE, 'M', 'M:ชาย', 'F', 'F:หญิง', '') AS SEXNAME,
	   CASE
		   WHEN B.HR_NATION_ID =
				FN_SS_CONFIG_GET('HR.DEFAULT.NATION.THAI_ID') OR
				B.HR_NATION_ID = 1 OR B.HR_NATION_ID IS NULL THEN
			FN_HR_STAFF_GETNAME(1,
								PF.PREFIXNAME,
								S.STAFFNAME,
								S.STAFFMIDNAME,
								S.STAFFSURNAME)/* || CASE
				WHEN PFR.ISHR_ID = 1 AND PFR.PREFIXCODE BETWEEN 011 AND 020 THEN
				 ', ' || PFR.PREFIXABB
			END*/
		   ELSE
			FN_HR_STAFF_GETNAME(0,
								nvl(PF.PREFIXNAMEENG,PF.PREFIXNAME),
								nvl(S.STAFFNAMEENG, s.staffname),
								NULL,--nvl(S.STAFFMIDNAMEENG, S.STAFFMIDNAME),
								nvl(S.STAFFSURNAMEENG,S.STAFFSURNAME)) /*|| CASE
				WHEN PFR.ISHR_ID = 1 AND PFR.PREFIXCODE BETWEEN 011 AND 020 THEN
				 ', ' || PFR.PREFIXABBENG
			END*/
	   END AS SNAME,
	   STS.BYTECODE || ': ' || STS.BYTEDES STAFFSTATUS,
	   CASE
		   WHEN S.HR_STAFFTYPE_ID IS NOT NULL THEN
			ST.STAFFTYPECODE || ': ' || ST.STAFFTYPENAME
		   ELSE
			ST.STAFFTYPECODE || ST.STAFFTYPENAME
	   END AS STAFFTYPE,
	   CASE
		   WHEN S.HR_POSITION_ID IS NOT NULL THEN
			PS.POSITIONCODE || ': ' || PS.POSITIONNAME
		   ELSE
			PS.POSITIONCODE || PS.POSITIONNAME
	   END AS POSITION,
	   CASE
		   WHEN S.MT_DEPARTMENT_ID IS NOT NULL THEN
		   /*D.DEPARTMENTCODE || ': ' ||*/
			D.DEPARTMENTFULLNAME
		   ELSE
		   /*D.DEPARTMENTCODE ||*/
			D.DEPARTMENTFULLNAME
	   END AS DEPARTMENT,
	   /*FN_HR_POSITIONEXECTEXTLIST(S.ID)*/ NULL AS POSITIONEXECTEXTLIST, -- ตำแหน่งทางบริหาร
	   /*FN_HR_GETPOSITIONEXECID(S.ID)*/ NULL AS HR_POSITIONEXEC_ID,
	   CASE
		   WHEN S.STAFFSTATUS_ID > 70 AND S.LEAVEDATE IS NOT NULL THEN
			TO_NUMBER(TO_CHAR(S.LEAVEDATE, 'YYYY')) + 543
		   ELSE
			S.RETIREYEAR + S.RETIREYEAREXTEND
	   END AS RETIREYEAR,
	   TO_CHAR(TO_NUMBER(TO_CHAR(S.ADMITDATE,
								 'dd',
								 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))) || ' ' ||
	   TO_CHAR(S.ADMITDATE,
			   'mon YYYY',
			   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') ADMITDATE,
	   TO_CHAR(TO_NUMBER(TO_CHAR(S.TRANSFERDATE,
								 'dd',
								 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))) || ' ' ||
	   TO_CHAR(S.TRANSFERDATE,
			   'mon YYYY',
			   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') TRANSFERDATE,
	   TRIM(TO_CHAR(TO_NUMBER(TO_CHAR(S.LEAVEDATE,
									  'dd',
									  'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))) || ' ' ||
			TO_CHAR(S.LEAVEDATE,
					'mon YYYY',
					'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')) LEAVEDATE,
	   TO_CHAR(TO_NUMBER(TO_CHAR(B.BIRTHDATE,
								 'dd',
								 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))) || ' ' ||
	   TO_CHAR(B.BIRTHDATE,
			   'mon YYYY',
			   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') BIRTHDATE,NULL AS CONTRACTDURATION,
	   CASE
		   WHEN B.BIRTHDATE IS NOT NULL THEN
			GET_HRM_STIMEDIFF(B.BIRTHDATE, SYSDATE, 1, 'YEAR', 0)
		   WHEN B.BIRTHYEAR IS NOT NULL AND
				LENGTH(TO_CHAR(B.BIRTHYEAR)) = 4 THEN
			GET_HRM_STIMEDIFF(TO_DATE(B.BIRTHYEAR - 543 || '0101',
									  'YYYYMMDD'),
							  SYSDATE,
							  1,
							  'YEAR',
							  0)
		   ELSE
			NULL
	   END AS BIRTHAGEYEAR,
	   CASE
		   WHEN B.BIRTHDATE IS NOT NULL THEN
			FN_HR_STIMEDIFF(B.BIRTHDATE, TRUNC(SYSDATE), 0, 'YEAR', NULL)
	   END AS BIRTHAGE,
	   CASE
		   WHEN S.LEAVEDATE IS NOT NULL THEN
			FN_HR_STIMEDIFF(S.ADMITDATE, S.LEAVEDATE, 0, 'YEAR', NULL)
		   ELSE
			FN_HR_STIMEDIFF(S.ADMITDATE, TRUNC(SYSDATE), 0, 'YEAR', NULL)
	   END AS WORKAGE,
	   --FN_HR_STAFFRENAME(S.ID, 1) KEYWORDSEARCH, -- ประวัติการเปลี่ยนชื่อ
	   --S.FL_STORAGE_ID,
	   S.GUID
FROM   VW_HR_STAFF S,
	   VW_HR_STAFFBIO B,
	   VW_MT_PREFIX PF,
	   --VW_MT_PREFIX PFR,
	   --VW_HR_CONTRACT C,
	   VW_HR_STAFFTYPE ST,
	   VW_MT_DEPARTMENT D,
	   VW_HR_POSITION PS,
	   (SELECT *
		FROM   VW_MIS_BYTEDES
		WHERE  TABLENAME = 'STAFFSTATUS' AND
			   COLUMNNAME = 'STAFFSTATUS') STS
WHERE  S.ID = B.HR_STAFF_ID AND
	   --S.HR_CONTRACT_ID = C.ID(+) AND
	   S.MT_PREFIX_ID = PF.ID(+) AND
	   --S.MT_PREFIXRANK_ID = PFR.ID(+) AND
	   S.HR_STAFFTYPE_ID = ST.ID AND
	   S.MT_DEPARTMENT_ID = D.ID AND
	   S.HR_POSITION_ID = PS.ID(+) AND
	   S.STAFFSTATUS_ID = STS.BYTECODE(+);

-- ----------------------------
-- View structure for VW_HR_STAFF_INFO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_STAFF_INFO" AS SELECT S.ID, --VW:  V_HRM_STAFFINFO
	   S.GUID,
	   S.STAFFCODE,
	   --S.MT_PREFIX_ID,
	   P.PREFIXNAME,
	   P.PREFIXABB,
	   --S.MT_PREFIXRANK_ID,
	   S.STAFFNAME,
	   S.STAFFSURNAME,
	   S.STAFFNAMEENG,
	   S.STAFFSURNAMEENG,
	   FN_HR_STAFF_GETNAME(1, P.PREFIXNAME, S.STAFFNAME, S.STAFFMIDNAME, S.STAFFSURNAME) AS SNAMEFULL,
	   FN_HR_STAFF_GETNAME(0,
						   P.PREFIXNAMEENG,
						   S.STAFFNAMEENG,
						   NULL,
						   S.STAFFSURNAMEENG) AS SNAMEFULLENG,
	   FN_HR_STAFF_GETNAME(1, P.PREFIXABB, S.STAFFNAME, S.STAFFMIDNAME, S.STAFFSURNAME) AS SNAMEABB,
	   FN_HR_STAFF_GETNAME(0,
						   P.PREFIXABBENG,
						   S.STAFFNAMEENG,
						   NULL,
						   S.STAFFSURNAMEENG) AS SNAMEABBENG,
	   --BIRTHDATE,
	   --MT_PROVINCEBIRTH_ID,
	  /* CASE
		   WHEN B.BIRTHDATE IS NOT NULL THEN
			GET_HRM_STIMEDIFF(B.BIRTHDATE, SYSDATE, 1, 'YEAR', 0)
		   WHEN B.BIRTHYEAR IS NOT NULL AND LENGTH(TO_CHAR(B.BIRTHYEAR)) = 4 THEN
			GET_HRM_STIMEDIFF(TO_DATE(B.BIRTHYEAR - 543 || '0101', 'YYYYMMDD'),
							  SYSDATE,
							  1,
							  'YEAR',
							  0)
		   ELSE
			NULL
	   END AS BIRTHAGEYEAR,*/
	   --S.SEX_CODE,
	   --DECODE(S.SEX_CODE, 'M', 'ชาย', 'F', 'หญิง', '') AS SEXNAME,
	   --HR_RELIGION_ID,
	   --HR_NATION_ID,
	   --HR_RACE_ID,
	   --BLOOD,
	   --S.HR_STAFFTYPE_ID,
	   /*CASE
		   WHEN S.HR_STAFFTYPE_ID IS NOT NULL THEN
			ST.STAFFTYPECODE || ': ' || ST.STAFFTYPENAME
		   ELSE
			ST.STAFFTYPECODE || ST.STAFFTYPENAME
	   END AS STAFFTYPE,*/
	   --S.STAFFSTATUS_ID,
	   --STS.BYTEID || ': ' || STS.BYTEDES STAFFSTATUS,
	   --GETSTAFFSTATUSBYDATE(ADMITDATE, LEAVEDATE, STAFFSTATUS_ID) STAFFSTATUSBYDATE,
	   --NVL(S.STARTDATE, S.ADMITDATE) STARTDATE,
	   --S.ADMITDATE,
	   --LEAVEDATE,
	   --NVL(B.EMAIL, R.EMAIL) EMAIL,
	   --HOMEPAGE,
	   --B.CITIZENNO,
	   --HIGH,
	   --WEIGHT,
	   /*B.PRESENTPOBOX || ' ' || B.PRESENTPOBOXEXTEND || ' ' ||
	   DECODE(B.PRESENTMOO, '', '', ' หมู่ ' || B.PRESENTMOO) || ' ' ||
	   DECODE(B.PRESENTSTREET, '', '', ' ถนน' || B.PRESENTSTREET) PRESENTADDRESS1,*/
	   /*DECODE((SELECT DISTRICTNAME FROM MT_DISTRICT WHERE ID = B.MT_DISTRICTPRESENT_ID),
			  '',
			  '',
			  ' ตำบล ' ||
			  (SELECT DISTRICTNAME FROM MT_DISTRICT WHERE ID = B.MT_DISTRICTPRESENT_ID)) || ' ' ||
	   DECODE((SELECT CITYNAME FROM MT_CITY WHERE ID = B.MT_CITYPRESENT_ID),
			  '',
			  '',
			  ' อำเภอ ' || (SELECT CITYNAME FROM MT_CITY WHERE ID = B.MT_CITYPRESENT_ID)) PRESENTADDRESS2,*/
	   --PRESENTZIPCODE,
	   --MT_PROVINCEPRESENT_ID,
	   --PERMANENTZIPCODE,
	   --MT_PROVINCEPERMANENT_ID,
	   --B.MOBILENO,
	   --PROFAFFILIATIONS,
	   --ACADPUBSERVICE,
	   --ACTIVITIES,
	   --SPORT,
	   --HOBBIES,
	   --PHONENOEXT,
	   --PERMANENTPHONENO,
	   --PRESENTPHONENO,
	   --POSITIONSTEP,
	   /*CASE
		   WHEN S.STAFFSTATUS_ID > 70 AND S.LEAVEDATE IS NOT NULL THEN
			TO_NUMBER(TO_CHAR(S.LEAVEDATE, 'YYYY')) + 543
		   ELSE
			S.RETIREYEAR + S.RETIREYEAREXTEND
	   END AS RETIREYEAR,*/
	   --S.MT_DEPARTMENT_ID,
	   D.DEPARTMENTCODE,
	   D.DEPARTMENTNAME,
	   D.DEPARTMENTFULLNAME,
	   CASE
		   WHEN S.MT_DEPARTMENT_ID IS NOT NULL THEN
			D.DEPARTMENTCODE || ': ' || D.DEPARTMENTFULLNAME
		   ELSE
			D.DEPARTMENTCODE || D.DEPARTMENTFULLNAME
	   END AS DEPARTMENT,
	   --MT_DEPARTMENTWORK_ID,
	   WD.DEPARTMENTCODE AS WORKDEPARTMENTCODE,
	   WD.DEPARTMENTNAME AS WORKDEPARTMENTNAME,
	   WD.DEPARTMENTFULLNAME AS WORKDEPARTMENTFULLNAME,
	   --WMD.ID AS MASTERWORKDEPARTMENTID,
	   --WMD.DEPARTMENTCODEHR AS MASTERWORKDEPARTMENTCODE,
	   --WMD.DEPARTMENTNAME AS MASTERWORKDEPARTMENTNAME,
	   --S.HR_POSITION_ID,
	   PS.POSITIONCODE,
	   CASE
		   WHEN S.HR_POSITION_ID IS NOT NULL THEN
			PS.POSITIONCODE || ': ' || PS.POSITIONNAME
		   ELSE
			PS.POSITIONCODE || PS.POSITIONNAME
	   END AS POSITION,
	   --S.MT_DEPARTMENTMASTER_ID,
	   MD.DEPARTMENTNAME AS MASTERDEPARTMENTNAME,
	   --S.HR_POSITIONWORK_ID,
	   WP.POSITIONWORKCODE,
	   WP.POSITIONWORKNAME,
	   /*CASE
		   WHEN S.HR_POSITIONACAD_ID BETWEEN 1 AND 4 THEN
			AP.POSITIONACADNAME
		   ELSE
			PS.POSITIONNAME
	   END AS POSITIONNAME,*/
       PS.POSITIONNAME--,
	   --NVL(AP.POSITIONACADNAME, WP.POSITIONWORKNAME) STAFFPOSITIONNAME, -- ตำแหน่งวิชาการ กรณีที่เป็นอาจารย์

	   /*CASE
		   WHEN S.HR_STAFFTYPE_ID = 1 AND S.HR_POSITIONLEVEL_ID IS NOT NULL THEN
			S.POSITIONNAME || ' ระดับ ' || PL.POSITIONLEVELNAME
		   ELSE
			S.POSITIONNAME
	   END AS POSITIONFULLNAME,*/
	   --AP.POSITIONACADTYPENAME,

	   /*CASE
		   WHEN S.HR_POSITIONLEVEL_ID > 0 THEN
			PL.POSITIONLEVELNAME
		   ELSE
			NULL
	   END AS POSITIONLEVELNAME,*/

	   --SC.BANKACCOUNTNO,
	   --SC.MT_BANK_ID,
	   --PAYMETHOD_ID,
	   --TAXCALTYPE_ID,
	   --SC.TAXNO,
	   --SC.CHILD_NOTSTUDY,
	   --SC.CHILD_STUDY,
	   --SC.DONATE1_AMOUNT DONATE1,
	   --SSODATEFROM,
	   --SSODATETO,
	   --SC.BANKACCOUNTNAME,
	   --S.HR_POSITIONLEVEL_ID,
	   --SC.MT_DEPARTMENTPAY_ID,
	   --PD.DEPARTMENTNAME      PAYDEPARTMENTNAME,
	   --S.HR_POSITIONACAD_ID,
	   --AP.POSITIONACADTYPE_ID,
	   --AP.POSITIONACADNAME,
	   --AP.POSITIONACADNAMEENG,
	   --D.DEPARTMENTINDEX,
	   --S.HR_STAFFTYPESUB_ID,
	   --WP.STAFFGROUP_ID,
	   --S.RG_OFFICER_ID,
	   --R.ID MT_REFER_ID,
	   -- เพิ่มเพื่อใช้ออก SLIP 530708
	   /*     S.STAFFNAME || ' ' || S.STAFFSURNAME PARSLIPNAME,
       VCST.STAFFTYPENAME PARSLIPSTAFFTYPE,
       D.DEPARTMENTNAME PARSLIPDEPARTMENT,
       PS.POSITIONNAME PARSLIPPOSITIONNAME,*/
	   --C.UNAME,
	   --C.UADDRESS,
	   --C.TAXNO UTAX,
	   --S.HR_STAFFPAYTYPE_ID,
	   --C.UWEB,
	   --S.POSITIONDATE,
	   --FN_HR_STAFFRENAME(S.ID, NULL) NAMECHANGE, -- ประวัติการเปลี่ยนชื่อ
	   /*CASE
		   WHEN B.BIRTHDATE IS NOT NULL THEN
			FN_HR_STIMEDIFF(B.BIRTHDATE, TRUNC(SYSDATE), 0, 'YEAR', NULL)
	   END AS BIRTHAGE,*/
	   /*CASE
		   WHEN S.LEAVEDATE IS NOT NULL THEN
			FN_HR_STIMEDIFF(S.ADMITDATE, S.LEAVEDATE, 0, 'YEAR', NULL)
		   ELSE
			FN_HR_STIMEDIFF(S.ADMITDATE, TRUNC(SYSDATE), 0, 'YEAR', NULL)
	   END AS WORKAGE,*/
	   --HC.DATEFROM CONTRACTDATEFROM,
	   --HC.DATETO CONTRACTDATETO,
	   --S.FL_STORAGE_ID
FROM   VW_HR_STAFF         S,
	   --PROMIS.STAFFBIO      B,
	   --HR_CONTRACT      HC,
	   VW_MT_DEPARTMENT    D,
	   VW_MT_DEPARTMENT    WD,
	   --PROMIS.DEPARTMENT    PD,
	   VW_MT_DEPARTMENT    MD,
	   VW_MT_PREFIX        P,
	   --PROMIS.PREFIX        PG,
	   VW_HR_POSITION      PS,
	   --PROMIS.POSITIONLEVEL PL,
	   VW_HR_POSITIONWORK  WP--,
	   --PROMIS.STAFFCAL      SC,
	   --VW_HR_POSITIONACAD AP,
	   --HR_STAFFTYPE       ST,
	   --MT_REFER R,
	   --MT_DEPARTMENT WMD,
	   --VL_HR_STAFFTYPE VCST,
	   --MT_CAMPUS C,
	   /*(SELECT *
		FROM   SS_BYTEDES
		WHERE  TABLENAME = 'HR_STAFF' AND COLUMNNAME = 'STAFFSTATUS_ID') STS*/
WHERE  S.MT_PREFIX_ID = P.ID(+)
	--AND S.MT_PREFIXRANK_ID = PG.ID(+)
    --AND S.ID = B.HR_STAFF_ID(+)
    --AND S.HR_STAFFTYPE_ID = ST.ID(+)
    --AND S.HR_CONTRACT_ID = HC.ID(+)
    AND S.MT_DEPARTMENT_ID = D.ID(+)
    AND S.MT_DEPARTMENTWORK_ID = WD.ID(+)
    --AND SC.MT_DEPARTMENTPAY_ID = PD.ID(+)
    AND D.MASTER_ID = MD.ID(+)
    AND S.HR_POSITION_ID = PS.ID(+)
    AND S.HR_POSITIONWORK_ID = WP.ID(+)
    --AND S.ID = SC.HR_STAFF_ID(+)
    --AND S.HR_POSITIONACAD_ID = AP.HR_POSITIONACAD_ID(+)
    --AND S.ID = R.HR_STAFF_ID(+)
    --AND S.HR_POSITIONLEVEL_ID = PL.ID(+)
    /*AND
	   CASE
		   WHEN WD.DEPTGROUPTYPE_ID = 2 THEN
			WD.DEPARTMENTCODE2
		   ELSE
			WD.DEPARTMENTCODE1
	   END = WMD.DEPARTMENTCODE(+)*/
	--AND S.HR_STAFFTYPE_ID = VCST.ID(+)
    --AND D.MT_CAMPUS_ID = C.ID(+)
    --AND S.STAFFSTATUS_ID = STS.BYTEID(+);

-- ----------------------------
-- View structure for VW_HR_STAFF_NAME
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_HR_STAFF_NAME" AS SELECT ST.ID,
	ST.GUID,
	ST.STAFFCODE,
	SN.PREFIXNAME,
	SN.STAFFNAME, --ชื่อ
	SN.STAFFNAMEENG, --ชื่อ (Eng)
	ST.STAFFSURNAME,
	ST.STAFFSURNAMEENG,
	SN.SNAME, --ชื่อ-สกุล
	SN.SNAMEENG, --ชื่อ-สกุล (Eng)
    SN.STAFFFULLNAME AS SNAMEFULL, --คำนำหน้า(เต็ม) ชื่อ-สกุล
	SN.STAFFFULLNAMEENG AS SNAMEFULLENG, --คำนำหน้า(เต็ม) ชื่อ-สกุล (Eng)
    --FN_HR_STAFF_GETNAME(1, PF.PREFIXNAME, ST.STAFFNAME, ST.STAFFMIDNAME, ST.STAFFSURNAME) AS SNAMERANK, --คำนำหน้า(เต็ม) ชื่อ-สกุล
	--FN_HR_STAFF_GETNAME(0, PF.PREFIXNAMEENG, ST.STAFFNAMEENG, '', ST.STAFFSURNAMEENG) AS SNAMERANKENG, --คำนำหน้า(เต็ม) ชื่อ-สกุล (Eng)
	--FN_HR_STAFF_GETNAME(1, PF.PREFIXABB, ST.STAFFNAME, ST.STAFFMIDNAME, ST.STAFFSURNAME) AS SNAMEABBRANK, --คำนำหน้า(ย่อ) ชื่อ-สกุล
	--FN_HR_STAFF_GETNAME(0, PF.PREFIXABBENG, ST.STAFFNAMEENG, '', ST.STAFFSURNAMEENG) AS SNAMEABBRANKENG, --คำนำหน้า(ย่อ) ชื่อ-สกุล (Eng)
  	ST.CITIZENNO || ';' || ST.STAFFCODE || ';' || SN.SNAME || ';' || SN.SNAMEENG AS KEYWORDSEARCH,
	ST.MT_DEPARTMENT_ID,
	ST.HR_STAFFTYPE_ID,
	ST.HR_POSITION_ID,
	ST.STAFFSTATUS_ID,
	ST.ADMITDATE,
	ST.LEAVEDATE,
	ST.RETIREYEAR,
    ST.RETIREYEAREXTEND,
	ST.HR_POSITIONWORK_ID,
	ST.MT_DEPARTMENTWORK_ID,
	ST.CITIZENNO,
    ST.BIRTHDATE,
    ST.TRANSFERDATE,
    ST.ISACTIVE_ID,

    ST.STAFFSTATUSCODE,
    ST.STAFFSTATUSNAME,
	ST.EMAIL
FROM   VW_HR_STAFF ST,
	PROMIS.HR_STAFFNAME SN
WHERE  ST.ID=SN.ID;

-- ----------------------------
-- View structure for VW_MIS_BYTEDES
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_MIS_BYTEDES" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	TABLENAME,
	COLUMNNAME,
	BYTECODE,
	BYTEDES,
	BYTEDESENG,
	BYTEORDER
FROM PROMIS.SYSBYTEDES;

-- ----------------------------
-- View structure for VW_MIS_CONFIG
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_MIS_CONFIG" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	A.CONFIG AS CONFIGCODE,
	A.CONFIGVALUE,
	A.DESCRIPTION
FROM PROMIS.SYSCONFIG A;

-- ----------------------------
-- View structure for VW_MT_DEPARTMENT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_MT_DEPARTMENT" AS SELECT A.DEPARTMENTID AS ID,
  A.DEPARTMENTCODE,
  A.DEPARTMENTCODE1,
  A.DEPARTMENTCODE2,
  A.DEPARTMENTCODE3,
    A.DEPARTMENTCODE AS DEPARTMENTCODEHR,
    A.DEPARTMENTABBNAME AS DEPARTMENTABB,
    NULL AS DEPARTMENTABBENG,
    A.DEPARTMENTNAME,
    A.DEPARTMENTNAMEENG,
    A.DEPARTMENTFULLNAME,
    NULL AS DEPARTMENTFULLNAMEENG,
    A.MASTERID AS MASTER_ID,
    A.DEPARTMENTINDEX,
    A.CAMPUSID AS MT_CAMPUS_ID,
    A.DEPARTMENTGROUP AS DEPARTMENTGROUPCODE,
    A.DEPARTMENTSTATUS AS DEPARTMENTSTATUS_ID,
    A.DEPARTMENTTYPE AS DEPARTMENTTYPE_ID
FROM PROMIS.DEPARTMENT A;

-- ----------------------------
-- View structure for VW_MT_PREFIX
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_MT_PREFIX" AS SELECT A.PREFIXID AS ID,
	A.PREFIXNAME,
    A.PREFIXNAMEENG,
    A.PREFIXABB,
    A.PREFIXABBENG
FROM PROMIS.PREFIX A;

-- ----------------------------
-- View structure for VW_MT_REFER
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_MT_REFER" AS SELECT A.REFERID AS ID,
	   TO_CHAR(A.REFERID) AS GUID,
	   A.REFERCODE,
	   A.REFERNAME,
	   A.REFERNAMEENG,
	   A.RNAME,
	   A.RNAMEENG,
	   A.REFERTYPE AS REFERTYPE_ID,
	   A.STUDENTID AS RG_STUDENT_ID,
	   A.OFFICERID AS RG_OFFICER_ID,
	   A.STAFFID AS HR_STAFF_ID,
	   A.REFERSTATUS AS REFERSTATUS_ID,
	   A.INDIVIDUALTYPE AS INDIVIDUALTYPE_ID,
	   A.TAXID AS TAXNO,
	   A.CITIZENID AS CITIZENNO,
	   A.EMAIL,
	   A.CONTACTPERSON,
	   A.CREATEUSERID AS CREATEBY,
	   A.CREATEDATETIME,
	   A.LASTUPDATEUSERID AS UPDATEBY,
	   A.LASTUPDATEDATETIME AS UPDATEDATETIME
FROM PROMIS.REFER A;

-- ----------------------------
-- View structure for VW_MT_REFER_INFO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_MT_REFER_INFO" AS SELECT R.ID,
	   R.REFERCODE,
	   --R.MT_PREFIX_ID,
	   R.REFERNAME,
	   R.REFERNAMEENG,
	   R.RNAME,
	   R.RNAMEENG,
	   R.REFERTYPE_ID,
	   R.RG_STUDENT_ID,
	   R.RG_OFFICER_ID,
	   R.HR_STAFF_ID,
       HR.MT_PREFIX_ID AS MT_PREFIXSTAFF_ID,
       HR.STAFFCODE,
       HR.STAFFNAME,
       HR.STAFFSURNAME,
       HR.POSITIONNAME,
       MD.ID AS MT_DEPARTMENT_ID,-- HR.MT_DEPARTMENT_ID,
	   --R.GF_REFER_ID,
	   --R.GFMISNO,
	   R.REFERSTATUS_ID,
	   CAST(CASE WHEN R.REFERTYPE_ID = 1 THEN HR.ISACTIVE_ID ELSE 1 END AS NUMBER(1)) AS ISACTIVED_ID,
	   R.INDIVIDUALTYPE_ID,
	   R.TAXNO,
	   R.CITIZENNO,
	   R.CONTACTPERSON,
	   --R.RATE_ID,
	   --R.ADDRESS1,
	   --R.ADDRESS2,
	   --R.ADDRESS3,
	   --R.POBOX,
	   --R.POBOXEXTEND,
	   --R.ROOMNO,
	   --R.BUILDING,
	   --R.FLOORNO,
	   --R.VILLAGE,
	   --R.MOO,
	   --R.LANE,
	   --R.STREET,
	   --R.MT_DISTRICT_ID,
	   --R.MT_CITY_ID,
	   --R.ZIPCODE,
	   --R.MT_PROVINCE_ID,
	   --R.PHONENO,
	   --R.FAX,
	   --R.MOBILE,
	   --R.PAGER,
	   --R.EMAIL,
	   --R.HO_ADDRESS1,
	   --R.HO_ADDRESS2,
	   --R.HO_ADDRESS3,
	   --R.HO_REGISTBY1,
	   --R.HO_REGISTBY2,
	   --R.HO_REGISTNO,
	   --R.HO_REGISTDATE,
	   --R.HO_TAXNO,
	   --R.HO_PHONENO,
	   --R.HO_REGISTATTENTION,
	  -- R.CREDITDAYS,
	   --R.MT_BANK_ID,
	   --R.BANKACCOUNTNO,
	   --R.BANKACCOUNTNAME,
	   --R.MT_BANKBRANCH_ID,
	   --R.ISLOCKPURCHASE_ID,
	   --R.CHEQUEREMARK,
	   --R.FINREFERTYPE_ID,
	   --R.SHOWADDRESSTYPE_ID,
	   R.CREATEBY,
	   R.CREATEDATETIME,
	   R.UPDATEBY,
	   R.UPDATEDATETIME,
	   R.GUID,
	   --R.ISMANUALADDRESS_ID,
	   --R.TAXBRANCHNAME,
	   --R.TAXBRANCHNO,
	   T.BYTECODE           AS REFERTYPECODE,
	   T.BYTEDES            AS REFERTYPENAME,
	   T.BYTEDESENG         AS REFERTYPENAMEENG,
	   --R.INSTITUTION,
	   --R.FIELDEXPERT,
       ST.STAFFTYPENAME,
       CASE WHEN R.REFERTYPE_ID = 1 THEN PSTA.STAFFSTATUSCODE ELSE NULL END STAFFSTATUSCODE,
       CASE WHEN R.REFERTYPE_ID = 1 THEN PSTA.STAFFSTATUSNAME ELSE NULL END STAFFSTATUSNAME,
       CASE WHEN R.REFERTYPE_ID = 1 THEN PSTA.STAFFSTATUSNAMEENG ELSE NULL END STAFFSTATUSNAMEENG,
       CASE WHEN R.REFERTYPE_ID = 1 THEN PSTA.STAFFSTATUSCODE || ': ' || PSTA.STAFFSTATUSNAME ELSE NULL END STAFFSTATUSFULLNAME,
       CASE WHEN R.REFERTYPE_ID = 1 THEN PSTA.STAFFSTATUSCODE || ': ' || PSTA.STAFFSTATUSNAMEENG ELSE NULL END STAFFSTATUSFULLNAMEENG,
       CASE WHEN R.REFERTYPE_ID = 1 THEN HR.ISACTIVE_ID ELSE NULL END  ISHRACTIVE_ID
FROM   VW_MT_REFER R
INNER  JOIN (SELECT * FROM VW_MIS_BYTEDES WHERE TABLENAME='REFER' AND COLUMNNAME='REFERTYPE') T ON R.REFERTYPE_ID=T.BYTECODE
LEFT JOIN VW_HR_STAFF HR ON R.HR_STAFF_ID = HR.ID
LEFT JOIN VW_HR_STAFFTYPE ST ON HR.HR_STAFFTYPE_ID = ST.ID
LEFT JOIN VW_MT_DEPARTMENT MD ON HR.MT_DEPARTMENT_ID = MD.ID
--LEFT JOIN MT_DEPARTMENT D ON MD.DEPARTMENTCODE = D.DEPARTMENTCODE
LEFT  JOIN (SELECT T.BYTECODE     STAFFSTATUSID,
                            T.BYTECODE   STAFFSTATUSCODE,
                            T.BYTEDES    STAFFSTATUSNAME,
                            T.BYTEDESENG STAFFSTATUSNAMEENG,
                            T.BYTEORDER    STAFFSTATUSORDERNO
                     FROM   VW_MIS_BYTEDES T
                     WHERE  T.TABLENAME = 'STAFFSTATUS' AND T.COLUMNNAME LIKE 'STAFFSTATUS') PSTA ON HR.STAFFSTATUS_ID = PSTA.STAFFSTATUSID
--LEFT JOIN HR_STAFF HR ON R.HR_STAFF_ID = HR.ID;

-- ----------------------------
-- View structure for VW_RG_FACULTY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_RG_FACULTY" AS SELECT A.FACULTYID AS ID,
	TO_CHAR(A.FACULTYID) AS FACULTYCODE,
	A.FACULTYNAME,
    A.FACULTYNAMEENG,
    A.FACULTYABB,
    A.FACULTYABBENG
FROM AVSREG.FACULTY@REGLINK A;

-- ----------------------------
-- View structure for VW_RG_PROGRAM
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_RG_PROGRAM" AS SELECT A.PROGRAMID AS ID,
     A.PROGRAMCODE,
     A.PROGRAMNAME,
     A.PROGRAMNAMEENG,
     A.PROGRAMABB,
     A.PROGRAMABBENG,
     A.PROGRAMYEAR,
     A.FACULTYID,
     A.DEGREEID,
     B.DEGREENAME,
     A.PROGRAM,
     C.LEVELNAME,
     A.PROGRAMNAME || CASE
       WHEN A.PROGRAMYEAR IS NOT NULL THEN
      ' (' || A.PROGRAMYEAR || ')'
     END || ' - หลักสูตร' || B.DEGREENAME || ' (' || C.LEVELNAME || ')' AS PROGRAMNAME_DISPLAY,
     A.PROGRAMNAMEENG || CASE
       WHEN A.PROGRAMYEAR IS NOT NULL THEN
      ' (' || A.PROGRAMYEAR || ')'
     END || ' - ' || B.DEGREENAMEENG || ' (' || C.LEVELNAMEENG || ')' AS PROGRAMNAMEENG_DISPLAY
FROM   AVSREG.PROGRAM@REGLINK A
INNER  JOIN AVSREG.DEGREE@REGLINK B
ON     A.DEGREEID = B.DEGREEID
INNER JOIN AVSREG.LEVELID@REGLINK C ON A.LEVELID=C.LEVELID
ORDER  BY A.FACULTYID, A.DEGREEID, A.PROGRAMYEAR;

-- ----------------------------
-- View structure for VW_RG_PROGRAMCODE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_RG_PROGRAMCODE" AS SELECT CAST(PROGRAMCODE AS NUMBER(12)) AS ID,
       PROGRAMCODE,
       PROGRAMCODENAME,
       PROGRAMCODENAMEENG,
  DECODE(PROGRAMCODESTATUS,'C',0,1) AS ISACTIVE_ID
FROM AVSREG.PROGRAMCODE@REGLINK A;

-- ----------------------------
-- View structure for VW_SK_LOCATION
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SK_LOCATION" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
  A.SLCODE AS LOCATIONCODE,
  A.SLNAME AS LOCATIONNAME,
  A.SORTBY AS ORDERNO,
  A.MASTERDEPID AS MT_DEPARTMENTMASTER_ID,
  A.CAMPUSID AS MT_CAMPUS_ID
FROM PROMIS.STOCKLOCATION A;

-- ----------------------------
-- View structure for VW_SS_APPLICATION
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_APPLICATION" AS SELECT
	A.ID,
	A.GUID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,

	A.ORDERNO,
	A.APPLICATIONNAME,
	A.APPLICATIONNAMEENG,
	A.ACTIVE_ID
FROM SS_APPLICATION A;

-- ----------------------------
-- View structure for VW_SS_APPLICATIONCONFEDIT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_APPLICATIONCONFEDIT" AS SELECT A.ID,
	A.SS_APPLICATION_ID,
  A.GROUP_ID,

  B.BYTECODE AS GROUPCODE,
  B.BYTEDES AS GROUPNAME,
  B.BYTEDESENG AS GROUPNAMEENG,
  B.ORDERNO AS GROUPORDER
FROM SS_APPLICATIONCONFEDIT A
	INNER JOIN SS_BYTEDES B ON A.GROUP_ID=B.BYTEID AND B.TABLENAME='SS_APPLICATIONCONFEDIT' AND B.COLUMNNAME='GROUP_ID';

-- ----------------------------
-- View structure for VW_SS_APPLICATIONCONFVIEW
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_APPLICATIONCONFVIEW" AS SELECT A.ID,
	A.SS_APPLICATION_ID,
  A.GROUP_ID,

  B.BYTECODE AS GROUPCODE,
  B.BYTEDES AS GROUPNAME,
  B.BYTEDESENG AS GROUPNAMEENG,
  B.ORDERNO AS GROUPORDER
FROM SS_APPLICATIONCONFVIEW A
	INNER JOIN SS_BYTEDES B ON A.GROUP_ID=B.BYTEID AND B.TABLENAME='SS_APPLICATIONCONFVIEW' AND B.COLUMNNAME='GROUP_ID';

-- ----------------------------
-- View structure for VW_SS_BASICSENDMAIL
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_BASICSENDMAIL" AS SELECT M.ID,
	   M.GUID,
	   MAILSTATUS_ID,
	   MAILSTARTDATETIME,
	   MAILDISPLAYFROM,
	   MAILADDRESSTO,
	   MAILADDRESSCC,
	   MAILADDRESSBCC,
	   MAILPRIORITY_ID,
	   MAILSUBJECT,
	   MAILBODY,
	   MAILBODYISHTML_ID,
	   SENTLOCKCODE,
	   SENTLOCKUNTILDATETIME,
	   SENTERRORDATETIME,
	   SENTERRORMESSAGE,
	   SENTSUCCESSDATETIME,
	   SENTMAILMESSAGEID,
	   SENDRETRYCOUNT,
	   ATTACHMENTSUBFOLDER,
	   ATTACHMENTFILES,
	   SS_APPLICATION_ID,
	   SUBJECT_CODE,
	   EMAILFROMID,
	   EMAILFROMCODE,
	   M.MT_REFER_ID,
	   R.REFERNAME
FROM   SS_BASICSENDMAIL M
LEFT   JOIN VW_MT_REFER R ON M.MT_REFER_ID = R.ID WITH READ ONLY CONSTRAINTS "SYS_C00298342";

-- ----------------------------
-- View structure for VW_SS_BYTEDES
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_BYTEDES" AS SELECT A.ID,
	   A.TABLENAME,
	   A.COLUMNNAME,
	   A.BYTEID,
	   A.BYTECODE,
	   A.BYTEDES,
	   A.BYTEDESENG,
	   A.BYTECODE || ': ' || A.BYTEDES BYTECODEDESTHA,
	   A.BYTECODE || ': ' || (CASE
			WHEN A.BYTEDESENG IS NULL THEN
			 A.BYTEDES
			ELSE
			 A.BYTEDESENG
		END) BYTECODEDESENG,
	   A.BYTEKEYWORD,
	   A.ORDERNO,
	   A.SS_APPLICATION_ID,
	   A.DEFAULT_ID,
	   B.APPLICATIONNAME,
	   B.APPLICATIONNAMEENG,
	   A.ACTIVE_ID,
	   A.CREATEDATETIME,
	   A.CREATEBY,
	   A.UPDATEDATETIME,
	   A.UPDATEBY,
	   A.BYTEDESABB,
	   A.BYTEDESABBENG,
	   A.DESCRIPTION
FROM SS_BYTEDES A
INNER JOIN SS_APPLICATION B ON A.SS_APPLICATION_ID = B.ID WITH READ ONLY CONSTRAINTS "SYS_C00169536";

-- ----------------------------
-- View structure for VW_SS_CLIENTIDENTIFIER
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_CLIENTIDENTIFIER" AS SELECT T.ID,
	   T.CREATEDATETIME,
	   T.CREATEBY,
	   T.UPDATEDATETIME,
	   T.UPDATEBY,
	   T.TERMINALIP,
	   T.SERVERIP,
	   T.SS_USER_ID,
	   NVL2(T.HR_STAFF_ID, S.STAFFNAME || ' ' || S.STAFFSURNAME, R.REFERNAME) USERFULLNAME,
	   T.MT_REFER_ID,
	   T.HR_STAFF_ID,
	   T.HTTPUSERAGENT,
	   T.LOGOUTDATETIME,
	   T.LOGOUTTYPE_ID,
	   T.HOSTNAME,
	   T.IMPERSONATEBY_ID,
	   T.ACCESSEDDATETIME,
	   T.GUID
FROM   SS_CLIENTIDENTIFIER T
LEFT   JOIN PROMIS.REFER R ON T.MT_REFER_ID = R.REFERID
LEFT   JOIN PROMIS.STAFF S ON T.HR_STAFF_ID = S.STAFFID;

-- ----------------------------
-- View structure for VW_SS_COINLOCKER_UNEXPIRED
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_COINLOCKER_UNEXPIRED" AS SELECT
	L.ID,L.GUID,L.CREATEDATETIME,L.CREATEBY,L.UPDATEDATETIME,L.UPDATEBY,L.CREATEBYCLIENT_ID,L.UPDATEBYCLIENT_ID,L.EXPIREEXTENDMINUTES,L.EXPIREDATETIME,L.CONTENTTYPE,L.CONTENTTEXT,L.CONTENTOWNER
FROM
	SS_COINLOCKER L
WHERE
	L.EXPIREDATETIME > SYSDATE;

-- ----------------------------
-- View structure for VW_SS_CONFIG
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_CONFIG" AS SELECT A.ID,
	A.CONFIGCODE,
	A.CONFIGVALUE,
	A.DESCRIPTION,
	A.ISSECRET_ID,
	A.SS_APPLICATION_ID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY
FROM SS_CONFIG A;

-- ----------------------------
-- View structure for VW_SS_CONFIG_REWARDSALARY
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_CONFIG_REWARDSALARY" AS SELECT A.ID,
  A.CONFIGCODE,
  A.CONFIGVALUE,
  A.DESCRIPTION,
  A.ISSECRET_ID,
  A.SS_APPLICATION_ID,
  A.CREATEDATETIME,
  A.CREATEBY,
  A.UPDATEDATETIME,
  A.UPDATEBY
