-- ----------------------------
-- View structure for VW_SS_GRANTUSERMENU
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_GRANTUSERMENU" AS SELECT
	ROWNUM AS ID,
  CASE WHEN B.CALLING IS NULL Then 0 Else 1 END ISMULTIPLECALLING,
	A."MENUGROUPTYPE",A."GUID",A."SS_USER_ID",A."SS_MENU_ID",A."ISFAVOURITES",A."SS_APPLICATION_ID",A."APPLICATIONORDERNO",A."APPLICATIONNAME",A."APPLICATIONNAMEENG",A."SS_MENUGROUP_ID",A."MENUGROUPORDERNO",A."MENUGROUPNAME",A."MENUGROUPNAMEENG",A."MENUORDERNO",A."MENUNAME",A."MENUNAMEENG",A."DESCRIPTION",A."WEBAPPLICATIONNAME",A."CALLING",A."CALLINGURL",A."MENUTYPE_ID",A."REPFORM",A."DOCUMENTCODE",A."RECENTDATETIME",A."FILEGUID",A."FILENAME",A."SS_MENUFAVOURITES_ID",A."SS_MENUFAVOURITESGROUP_ID",A."MENUFAVOURITESORDERNO"
FROM (
	SELECT
		2 AS MENUGROUPTYPE, /* FAVOURITES */
    M.GUID,
		F.SS_USER_ID,
		M.ID SS_MENU_ID,
		1 AS ISFAVOURITES,
    CASE
      WHEN F.SS_MENU_ID IS NULL THEN 100
      ELSE M.SS_APPLICATION_ID
    END SS_APPLICATION_ID,
		M.APPLICATIONORDERNO,
		M.APPLICATIONNAME,
		M.APPLICATIONNAMEENG,
		M.SS_MENUGROUP_ID,
		M.MENUGROUPORDERNO,
		M.MENUGROUPNAME,
		M.MENUGROUPNAMEENG,
		M.MENUORDERNO,
    CASE
      WHEN F.SS_MENU_ID IS NULL THEN F.TITLE
      ELSE M.MENUNAME
    END MENUNAME,
    CASE
      WHEN F.SS_MENU_ID IS NULL THEN F.TITLE
      ELSE M.MENUNAMEENG
    END MENUNAMEENG,
		M.DESCRIPTION,
    M.WEBAPPLICATIONNAME,
		M.CALLING,
		M.CALLINGURL,
		CASE
      WHEN F.SS_MENU_ID IS NULL THEN 1
      ELSE M.MENUTYPE_ID
    END MENUTYPE_ID,
		M.REPFORM,
		M.DOCUMENTCODE,
		M.CREATEDATETIME AS RECENTDATETIME,
		M.FILEGUID,
		M.FILENAME,
    F.ID AS SS_MENUFAVOURITES_ID,
		F.SS_MENUFAVOURITESGROUP_ID,
		F.ORDERNO AS MENUFAVOURITESORDERNO
	FROM SS_MENUFAVOURITES F
	LEFT JOIN (
		SELECT
			MG.SS_MENU_ID,
			RG.SS_USER_ID
		FROM SS_GRANTMENU MG
		JOIN SS_GRANTUSERROLE RG ON MG.SS_ROLE_ID=RG.SS_ROLE_ID
		GROUP BY
			MG.SS_MENU_ID,
			RG.SS_USER_ID
	) V ON V.SS_MENU_ID = F.SS_MENU_ID AND F.SS_USER_ID = V.SS_USER_ID
  LEFT JOIN VW_SS_MENU_INFO M ON M.ID = F.SS_MENU_ID
	WHERE
    (M.MENUACTIVE_ID=1 or  M.MENUACTIVE_ID is null) AND
    (M.MENUGROUPACTIVE_ID=1 or  M.MENUGROUPACTIVE_ID is null) AND
    (M.APPLICATIONACTIVE_ID=1 or  M.APPLICATIONACTIVE_ID is null)
	UNION
	SELECT
		1 AS MENUGROUPTYPE, /* NORMAL */
    M.GUID,
		V.SS_USER_ID,
		M.ID SS_MENU_ID,
		DECODE(F.ID, NULL, 0, 1) ISFAVOURITES,
		M.SS_APPLICATION_ID,
		M.APPLICATIONORDERNO,
		M.APPLICATIONNAME,
		M.APPLICATIONNAMEENG,
		M.SS_MENUGROUP_ID,
		M.MENUGROUPORDERNO,
		M.MENUGROUPNAME,
		M.MENUGROUPNAMEENG,
		M.MENUORDERNO,
		M.MENUNAME,
		M.MENUNAMEENG,
		M.DESCRIPTION,
    M.WEBAPPLICATIONNAME,
		M.CALLING,
		M.CALLINGURL,
		M.MENUTYPE_ID,
		M.REPFORM,
		M.DOCUMENTCODE,
		M.CREATEDATETIME AS RECENTDATETIME,
		M.FILEGUID,
		M.FILENAME,
    NULL AS SS_MENUFAVOURITES_ID,
		NULL AS SS_MENUFAVOURITESGROUP_ID,
		NULL AS MENUFAVOURITESORDERNO
	FROM VW_SS_MENU_INFO M
	JOIN (
		SELECT
			MG.SS_MENU_ID,
			RG.SS_USER_ID
		FROM SS_GRANTMENU MG
		JOIN SS_GRANTUSERROLE RG ON MG.SS_ROLE_ID=RG.SS_ROLE_ID
		GROUP BY
			MG.SS_MENU_ID,
			RG.SS_USER_ID
	) V ON M.ID = V.SS_MENU_ID
	LEFT JOIN SS_MENUFAVOURITES F ON M.ID = F.SS_MENU_ID AND V.SS_USER_ID = F.SS_USER_ID
	WHERE
		M.MENUACTIVE_ID=1 AND
		M.MENUGROUPACTIVE_ID=1 AND
		M.APPLICATIONACTIVE_ID=1
	UNION
	SELECT
		3 AS MENUGROUPTYPE, /* RECENT */
    M.GUID,
		V.SS_USER_ID,
		M.ID AS SS_MENU_ID,
		DECODE(F.ID, NULL, 0, 1) ISFAVOURITES,
		M.SS_APPLICATION_ID,
		M.APPLICATIONORDERNO,
		M.APPLICATIONNAME,
		M.APPLICATIONNAMEENG,
		M.SS_MENUGROUP_ID,
		M.MENUGROUPORDERNO,
		M.MENUGROUPNAME,
		M.MENUGROUPNAMEENG,
		M.MENUORDERNO,
		M.MENUNAME,
		M.MENUNAMEENG,
		M.DESCRIPTION,
    M.WEBAPPLICATIONNAME,
		M.CALLING,
		M.CALLINGURL,
		M.MENUTYPE_ID,
		M.REPFORM,
		M.DOCUMENTCODE,
		S.RECENTDATETIME,
		M.FILEGUID,
		M.FILENAME,
    NULL AS SS_MENUFAVOURITES_ID,
		NULL AS SS_MENUFAVOURITESGROUP_ID,
		NULL AS MENUFAVOURITESORDERNO
	FROM VW_SS_MENU_INFO M
	JOIN (
		SELECT
			MG.SS_MENU_ID,
			RG.SS_USER_ID
		FROM SS_GRANTMENU MG
		JOIN SS_GRANTUSERROLE RG ON MG.SS_ROLE_ID=RG.SS_ROLE_ID
		GROUP BY
			MG.SS_MENU_ID,
			RG.SS_USER_ID
	) V ON M.ID = V.SS_MENU_ID
	JOIN SS_MENURECENT S ON M.ID = S.SS_MENU_ID AND S.SS_USER_ID = V.SS_USER_ID
	LEFT JOIN SS_MENUFAVOURITES F ON M.ID = F.SS_MENU_ID AND V.SS_USER_ID = F.SS_USER_ID
	WHERE
		M.MENUACTIVE_ID=1 AND
		M.MENUGROUPACTIVE_ID=1 AND
		M.APPLICATIONACTIVE_ID=1
	UNION
	SELECT
		0 AS MENUGROUPTYPE, /* ANONYMOUS */
    M.GUID,
		NULL AS SS_USER_ID,
		M.ID AS SS_MENU_ID,
		0 AS ISFAVOURITES,
		M.SS_APPLICATION_ID,
		M.APPLICATIONORDERNO,
		M.APPLICATIONNAME,
		M.APPLICATIONNAMEENG,
		M.SS_MENUGROUP_ID,
		M.MENUGROUPORDERNO,
		M.MENUGROUPNAME,
		M.MENUGROUPNAMEENG,
		M.MENUORDERNO,
		M.MENUNAME,
		M.MENUNAMEENG,
		M.DESCRIPTION,
    M.WEBAPPLICATIONNAME,
		M.CALLING,
		M.CALLINGURL,
		M.MENUTYPE_ID,
		M.REPFORM,
		M.DOCUMENTCODE,
		M.CREATEDATETIME AS RECENTDATETIME,
		M.FILEGUID,
		M.FILENAME,
    NULL AS SS_MENUFAVOURITES_ID,
		NULL AS SS_MENUFAVOURITESGROUP_ID,
		NULL AS MENUFAVOURITESORDERNO
	FROM VW_SS_MENU_INFO M
	WHERE
		M.MENUACTIVE_ID=1 AND
		M.MENUGROUPACTIVE_ID=1 AND
		M.APPLICATIONACTIVE_ID=1 AND
		M.ANONYMOUS_ID=1
) A
LEFT JOIN (
  SELECT UPPER(T.CALLING) CALLING
  FROM SS_MENU T
  HAVING COUNT(*) > 1
  GROUP BY UPPER(T.CALLING)
) B ON B.CALLING = UPPER(A.CALLING);

-- ----------------------------
-- View structure for VW_SS_GRANTUSERROLE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_GRANTUSERROLE" AS SELECT
	A.ID,
	A.SS_ROLE_ID,
	A.SS_USER_ID,
    R.ROLENAME,
    R.ROLENAME AS ROLENAMEENG,
    G.BYTEID AS ROLEGROUP_ID,
    G.BYTECODE AS ROLEGROUPCODE,
	G.BYTEDES AS ROLEGROUPNAME,
	G.BYTEDESENG AS ROLEGROUPNAMEENG,
	F.REFERNAME AS FULLNAME,
	F.REFERNAMEENG AS FULLNAMEENG,
	R.SS_APPLICATION_ID
FROM SS_GRANTUSERROLE A
	INNER JOIN SS_ROLE R ON A.SS_ROLE_ID=R.ID
	INNER JOIN (SELECT * FROM SS_BYTEDES WHERE TABLENAME='SS_ROLE' AND COLUMNNAME='ROLEGROUP_ID') G ON R.ROLEGROUP_ID=G.BYTEID
	INNER JOIN SS_USER U ON U.ID = A.SS_USER_ID
	LEFT JOIN VW_MT_REFER F ON F.ID = U.MT_REFER_ID;

-- ----------------------------
-- View structure for VW_SS_MENU
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_MENU" AS SELECT M.ID,
	   M.GUID,
	   M.CREATEDATETIME,
	   M.ORDERNO,
	   M.MENUNAME,
	   M.MENUNAMEENG,
	   M.ACTIVE_ID,
	   M.DESCRIPTION,
	   M.CALLING,
	   M.MENUTYPE_ID,
	   M.REPFORM,
	   M.DOCUMENTCODE,
	   M.SS_MENUGROUP_ID,
	   M.ANONYMOUS_ID,
	   M.CALLINGURL,
	   M.EDITTYPE_ID,
	   M.CODE,
	   M.FL_STORAGE_ID,
	   M.ISSECRET_ID,
	   FL.GUID AS FILEGUID,
	   FL.FILENAME,
	   MG.ORDERNO AS MENUGROUPORDERNO,
	   MG.MENUGROUPNAME
FROM   SS_MENU M
INNER JOIN SS_MENUGROUP MG ON M.SS_MENUGROUP_ID = MG.ID
LEFT   JOIN FL_STORAGE FL ON M.FL_STORAGE_ID = FL.ID;

-- ----------------------------
-- View structure for VW_SS_MENUGROUP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_MENUGROUP" AS SELECT
	A.ID,
	A.GUID,
	A.CREATEDATETIME,
	A.CREATEBY,
	A.UPDATEDATETIME,
	A.UPDATEBY,

	A.ORDERNO,
	A.MENUGROUPNAME,
	A.SS_APPLICATION_ID,
	A.MENUGROUPNAMEENG,
	A.ACTIVE_ID
FROM SS_MENUGROUP A;

-- ----------------------------
-- View structure for VW_SS_MENU_INFO
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_MENU_INFO" AS SELECT
	M.ID,
	M.GUID,
  M.CREATEDATETIME,
	M.ORDERNO AS MENUORDERNO,
	M.MENUNAME,
	M.MENUNAMEENG,
	M.ACTIVE_ID AS MENUACTIVE_ID,
	M.DESCRIPTION,
	M.CALLING,
	M.MENUTYPE_ID,
	M.REPFORM,
	M.DOCUMENTCODE,
	M.SS_MENUGROUP_ID,
	M.ANONYMOUS_ID,
	M.CALLINGURL,
	M.EDITTYPE_ID,
	M.CODE,
	M.FL_STORAGE_ID,

	MG.MENUGROUPNAME,
	MG.MENUGROUPNAMEENG,
	MG.ORDERNO AS MENUGROUPORDERNO,
	MG.ACTIVE_ID AS MENUGROUPACTIVE_ID,
	MG.SS_APPLICATION_ID,
	AP.APPLICATIONNAME,
	AP.APPLICATIONNAMEENG,
	AP.ORDERNO AS APPLICATIONORDERNO,
	AP.ACTIVE_ID AS APPLICATIONACTIVE_ID,
	AP.WEBAPPLICATIONNAME,

	M.FILEGUID,
	M.FILENAME
FROM VW_SS_MENU M
	JOIN SS_MENUGROUP MG ON M.SS_MENUGROUP_ID=MG.ID
	JOIN SS_APPLICATION AP ON MG.SS_APPLICATION_ID=AP.ID;

-- ----------------------------
-- View structure for VW_SS_NOTIFICATION
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_NOTIFICATION" AS SELECT CAST(ROWNUM AS NUMBER(12)) AS ID,
	CAST(0 AS NUMBER(4))  AS ORDERNO,
	CAST(0 AS NUMBER(12)) AS SS_USER_ID,
	CAST(0 AS NUMBER(12)) AS HR_STAFF_ID,
	NULL AS MESSAGE,
	NULL AS HREF,
	CAST(0 AS NUMBER(1)) AS SHOWONLINE_ID,
	CAST(0 AS NUMBER(1)) AS SHOWBACKEND_ID
FROM DUAL
/*	(
        SELECT 1 AS ORDERNO,
			NULL AS SS_USER_ID,
			C.HR_STAFF_ID,
			'สัญญาจ้างของคุณ ' || CASE WHEN C.CONTRACTNO IS NOT NULL THEN 'เลขที่ ' || TO_CHAR(C.CONTRACTNO) || ' ' END || 'สิ้นสุดสัญญาในวันที่ ' || TRIM(TO_CHAR(TO_NUMBER(TO_CHAR(C.DATETO,'DD')))) || ' ' || TRIM(TO_CHAR(C.DATETO,'MONTH', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')) || ' ' ||
				TO_CHAR(C.DATETO,'YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') || ' กรุณาติดต่องานบริหารงานบุคคล' AS MESSAGE,
			N'' AS HREF,
			1 AS SHOWONLINE_ID,
			1 AS SHOWBACKEND_ID
        FROM VW_HR_CONTRACT_NOTI C
		UNION
		SELECT 2 AS ORDERNO,
			GR.SS_USER_ID,
			C.HR_STAFF_ID,
			'มีบุคลากรรอพิจารณาใบลา/ใบยกเลิกการลา จำนวน ' || TRIM(TO_CHAR(C.CNT,'999,999,999,999,999')) || ' คน' AS MESSAGE,
			'Applications/' || M.CALLING AS HREF,
			1 AS SHOWONLINE_ID,
			0 AS SHOWBACKEND_ID
		FROM SS_GRANTUSERROLE GR
			INNER JOIN SS_GRANTMENU GM ON GR.SS_ROLE_ID=GM.SS_ROLE_ID
			INNER JOIN SS_MENU M ON GM.SS_MENU_ID=M.ID AND M.CODE='VN.OL.HR_ATTREQUEST.HEAD'
			INNER JOIN (
				SELECT B.HR_STAFF_ID, COUNT(A.ID) AS CNT
				FROM VW_HR_ATTREQUESTATITEM_HEAD A
					INNER JOIN VW_SS_USER B ON B.ID=FN_SS_PARAMETER_GETUSERID AND (A.HR_STAFFDEF_ID=B.HR_STAFF_ID OR A.HR_STAFFACT_ID=B.HR_STAFF_ID OR A.HR_STAFFAT_ID=B.HR_STAFF_ID)
				WHERE A.ATITEMSTATUS_ID=10
				GROUP BY B.HR_STAFF_ID
			) C ON C.CNT>0
		WHERE GR.SS_USER_ID=FN_SS_PARAMETER_GETUSERID
		GROUP BY GR.SS_USER_ID, C.HR_STAFF_ID, C.CNT, M.CALLING
		UNION
		SELECT 3 ORDERNO,
			GR.SS_USER_ID,
			NULL AS HR_STAFF_ID,
			'มีบุคลากรที่จะสิ้นสุดสัญญาจ้างภายใน ' || C.PERIODDAY || ' วัน หรือสิ้นสุดสัญญาจ้างมากกว่า ' || C.PERIODDAY || ' วัน จำนวน ' || TRIM(TO_CHAR(C.CNT,'999,999,999,999,999')) || ' คน' AS MESSAGE,
			'Applications/' || M.CALLING AS HREF,
			0 AS SHOWONLINE_ID,
			1 AS SHOWBACKEND_ID
		FROM SS_GRANTUSERROLE GR
			INNER JOIN SS_GRANTMENU GM ON GR.SS_ROLE_ID=GM.SS_ROLE_ID
			INNER JOIN SS_MENU M ON GM.SS_MENU_ID=M.ID AND M.CODE='VN.MIS.HR.CONTRACT.NOTIFICATION'
			INNER JOIN (SELECT PERIODDAY, COUNT(ID) CNT FROM VW_HR_CONTRACT_NOTI GROUP BY PERIODDAY) C ON C.CNT>0
		WHERE GR.SS_USER_ID=FN_SS_PARAMETER_GETUSERID
		GROUP BY GR.SS_USER_ID, C.PERIODDAY, C.CNT, M.CALLING
	) RA*/;

-- ----------------------------
-- View structure for VW_SS_PASSPORT_ENTITY
