-- ----------------------------
-- View structure for VW_SS_ROLE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_ROLE" AS SELECT ID, ROLENAME, ROLEGROUP_ID, SS_ROLEINHERITFROM_ID, SS_APPLICATION_ID, CREATEDATETIME, CREATEBY, UPDATEDATETIME, UPDATEBY
FROM   SS_ROLE;

-- ----------------------------
-- View structure for VW_SS_ROLEGRANT
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_ROLEGRANT" AS SELECT SS_ROLEGRANT.ID,
	SS_ROLEGRANT.GUID,
    SS_ROLEGRANT.SS_ROLE_ID,
    SS_ROLEGRANT.SS_USER_ID,
    SS_ROLE.ROLENAME,
    SS_USER.USERNAME,
    SS_ROLE.ROLEGROUP_ID,
    G.BYTECODE AS ROLEGROUPCODE,
    G.BYTEDES AS ROLEGROUPNAME,
    G.BYTEDESENG AS ROLEGROUPNAMEENG
FROM   SS_ROLEGRANT
	INNER  JOIN SS_ROLE ON SS_ROLEGRANT.SS_ROLE_ID = SS_ROLE.ID
	INNER  JOIN SS_USER ON SS_ROLEGRANT.SS_USER_ID = SS_USER.ID
    INNER JOIN (SELECT * FROM SS_BYTEDES WHERE TABLENAME='SS_ROLE' AND COLUMNNAME='ROLEGROUP_ID') G ON SS_ROLE.ROLEGROUP_ID=G.BYTEID WITH READ ONLY CONSTRAINTS "SYS_C00169541";

-- ----------------------------
-- View structure for VW_SS_TABLECOLUMN
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_TABLECOLUMN" AS SELECT ROWNUM AS ID,
	C.TABLE_NAME,
	   C.COLUMN_NAME,
	   C.DATA_TYPE,
	   C.DATA_LENGTH,
	   C.DATA_PRECISION,
	   C.DATA_SCALE,
	   C.NULLABLE,
	   C.COLUMN_ID,
	   C.DEFAULT_LENGTH,
	   FN_SS_LONGTYPE_GET('DATA_DEFAULT', C.TABLE_NAME, C.COLUMN_NAME) DATA_DEFAULT,
	   --C.DATA_DEFAULT,
	   C.NUM_DISTINCT,
	   --C.LOW_VALUE,
	   --C.HIGH_VALUE,
	   C.DENSITY,
	   C.NUM_NULLS,
	   C.NUM_BUCKETS,
	   C.LAST_ANALYZED,
	   C.SAMPLE_SIZE,
	   TC.COMMENTS TABLE_COMMENTS,
	   CC.COMMENTS COLUMN_COMMENTS
FROM   SYS.USER_TAB_COLUMNS  C,
	   SYS.USER_COL_COMMENTS CC,
	   SYS.USER_TAB_COMMENTS TC
WHERE  C.TABLE_NAME NOT IN (SELECT VIEW_NAME FROM USER_VIEWS) AND
	   C.TABLE_NAME = TC.TABLE_NAME AND
	   C.TABLE_NAME = CC.TABLE_NAME AND
	   C.COLUMN_NAME = CC.COLUMN_NAME;

-- ----------------------------
-- View structure for VW_SS_TABLEDEFAULTVALUE
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_TABLEDEFAULTVALUE" AS select
rownum ID, t.TABLE_NAME, t.COLUMN_NAME, t.DATA_DEFAULT
from DBA_TAB_COLUMNS t
where t.OWNER='VNMIS'

/*
Require SELECT with grant right on DBA_TAB_COLUMNS.

How to:
1. Login as SYSTEM or SYS account.
2. Run commend:
GRANT SELECT ON DBA_TAB_COLUMNS TO VNMIS WITH GRANT OPTION;
*/ WITH READ ONLY CONSTRAINTS "SYS_C00169535";

-- ----------------------------
-- View structure for VW_SS_USER
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_USER" AS SELECT U.ID,
    LOWER(NVL(PE.LOGIN,U.USERNAME)) AS USERNAME,
    NVL(PE.PASSWORD,U.PASSWORD) AS PASSWORD,
    U.MT_REFER_ID,
    U.SS_USERPROFILEPASSWORD_ID,
    U.SS_USERPROFILETIME_ID,
    U.LASTLOGINDATETIME,
    U.LOGINTOTAL,
    U.LASTCHANGEPASSWORDDATETIME,
    U.LASTLOGOFFDATETIME,
    U.LASTACCESSDATETIME,
    U.INVALIDLOGONTOTAL,
    U.ACCOUNTLOCKOUTSINCE,
    U.ACCOUNTLOCKOUTTOTAL,
    U.ACCOUNTLOCKOUTSUMMARY,
    U.ENCRYPTKEYVERSION,
    U.ENCRYPTKEYCONTENT,
    U.CONNECTEDIP,
    U.TERMINALIP,
    U.UNILOGINSERVERID,
    U.UNILOGINENTRYCODE,
    U.UNILOGINENTRYEXPIRE,
    U.VALIDDATEFROM,
    U.VALIDDATETO,
    U.THEME_ID,
    U.THEMESIZE,
    U.ACTIVE_ID,
    U.ALLOW_ID,
    U.ALLOW_USERIMPERSONATE_ID,
    U.ALLOWSETUPONCALLER_ID,
    U.CREATEDATETIME,U.
    CREATEBY,
    U.UPDATEDATETIME,
    U.UPDATEBY,
    U.GUID,
    U.DATABASEREDONLYENABLED,
    U.DATABASEREDONLYEXCLUDETABLES,
    U.SIGNONMETHOD_ID,
	T.BYTECODE AS THEMECODE,
	R.REFERNAME FULLNAME,
	R.REFERNAMEENG FULLNAMEENG,
	HR.ID AS HR_STAFF_ID,
    --D.ID MT_DEPARTMENT_ID,-- HR.MT_DEPARTMENT_ID,
	HR.MT_DEPARTMENT_ID,
    R.REFERCODE,
    R.REFERNAME,
    R.REFERNAMEENG,
    --RT.BYTECODE AS REFERTYPECODE,
    --RT.BYTEDES AS REFERTYPENAME,
    --RT.BYTEDES AS REFERTYPENAMEENG,
    CASE WHEN R.ID IS NOT NULL THEN R.REFERCODE || ': ' || R.REFERNAME  END AS DISPLAYNAME,
	CAST(PE.ID AS NUMBER(12)) AS PP_ENTITY_ID,
	CASE WHEN PE.INVALIDLOGONCOUNT <> 0 OR PE.ACCOUNTLOCKOUTSINCE IS NOT NULL OR PE.ACCOUNTLOCKOUTCOUNT <> 0 THEN 1 ELSE 0 END AS ISLOCK_ID,
	NVL(HR.CITIZENNO,R.CITIZENNO) AS CITIZENNO,
	U.RECEIVEMAILEVHEAD_ID,
	NVL(HR.EMAIL,R.EMAIL) AS EMAIL,
	NULL AS WF_ENTITY_ID
FROM SS_USER U
	INNER JOIN (SELECT * FROM SS_BYTEDES WHERE TABLENAME = 'SS_USER' AND COLUMNNAME = 'THEME_ID') T ON T.BYTEID = U.THEME_ID
	LEFT JOIN VW_MT_REFER R ON U.MT_REFER_ID = R.ID
    --LEFT JOIN (SELECT * FROM SS_BYTEDES WHERE TABLENAME='MT_REFER' AND COLUMNNAME='REFERTYPE_ID') RT ON R.REFERTYPE_ID=RT.BYTEID
	--LEFT JOIN HR_STAFF S ON S.ID = R.HR_STAFF_ID
	LEFT JOIN VW_HR_STAFF HR ON R.HR_STAFF_ID = HR.ID
	LEFT JOIN VW_MT_DEPARTMENT MD ON HR.MT_DEPARTMENT_ID = MD.ID
	--LEFT JOIN MT_DEPARTMENT D ON MD.DEPARTMENTCODE = D.DEPARTMENTCODE
	LEFT JOIN VW_SS_PASSPORT_ENTITY PE ON U.PP_ENTITY_ID=PE.ID AND U.SIGNONMETHOD_ID<>200;

-- ----------------------------
-- View structure for VW_SS_USERMIS_MAP
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_USERMIS_MAP" AS SELECT T.ID SS_USER_ID, T.PP_ENTITY_ID, SM.SYSMISUSERID, SU.SYSUSERID, T.USERNAME, UPPER(PS.LOGIN) LOGINNAME, T.MT_REFER_ID, SM.STAFFID, HR.DEPARTMENTID MT_DEPARTMENT_ID
FROM   SS_USER T
INNER  JOIN (SELECT * FROM PROMIS.PASSPORT_SYSTEMACCOUNT WHERE SYSTEMID = 1) PS ON T.PP_ENTITY_ID = PS.ENTITYID
INNER  JOIN PROMIS.SYSMISUSER SM ON UPPER(PS.LOGIN) = UPPER(SM.LOGINNAME)
INNER  JOIN PROMIS.SYSUSER SU ON UPPER(PS.LOGIN) = UPPER(SU.DBLOGIN)
LEFT   JOIN PROMIS.STAFF HR ON SM.STAFFID = HR.STAFFID;

-- ----------------------------
-- View structure for VW_SS_WEBBOARD
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_WEBBOARD" AS SELECT A.ID,
  A.TOPICNAME,
  A.TOPICNAMEENG,
  A.DETAIL,
  A.DETAILENG,
  A.WRITERNAME,
  A.WRITERNAMEENG,
  A.DATEBEGIN,
  A.DATEEND,
  A.LEVEL_ID,
  A.GROUP_ID,
  A.STATUS_ID,
  A.WEBBOARDTYPE_ID,
  A.IMAGEPOSITION_CODE,
  NVL(A.IMAGEPOSITION_CODE, IP.BYTECODE) AS IMAGEPOSITION_VALUE,
  A.FL_STORAGEIMAGE_ID,
  A.FL_STORAGEDOC_ID,
  A.FL_STORAGEDOC2_ID,
  A.FL_STORAGEDOC3_ID,
  A.FL_STORAGEDOC4_ID,
  A.IMAGELINKURL,
  A.IMAGELINKTARGET_CODE,
  A.CREATEBY,
  A.CREATEDATETIME,
  A.UPDATEBY,
  A.UPDATEDATETIME,
  A.GUID,

  FI.FILENAME AS IMAGENAME,
  FI.GUID AS IMAGEGUID,
  FD.FILENAME AS DOCNAME,
  FD.GUID AS DOCGUID,
  FD2.FILENAME AS DOCNAME2,
  FD2.GUID AS DOCGUID2,
  FD3.FILENAME AS DOCNAME3,
  FD3.GUID AS DOCGUID3,
  FD4.FILENAME AS DOCNAME4,
  FD4.GUID AS DOCGUID4,
  CASE WHEN L.BYTEID>4 THEN NULL ELSE L.BYTECODE END AS LEVELCODE,
  CASE WHEN L.BYTEID>4 THEN NULL ELSE L.BYTEDES END AS LEVELNAME,
  CASE WHEN L.BYTEID>4 THEN NULL ELSE L.BYTEDESENG END AS LEVELNAMEENG
FROM SS_WEBBOARD A
  LEFT JOIN FL_STORAGE FI ON A.FL_STORAGEIMAGE_ID=FI.ID
  LEFT JOIN FL_STORAGE FD ON A.FL_STORAGEDOC_ID=FD.ID
  LEFT JOIN FL_STORAGE FD2 ON A.FL_STORAGEDOC2_ID=FD2.ID
  LEFT JOIN FL_STORAGE FD3 ON A.FL_STORAGEDOC3_ID=FD3.ID
  LEFT JOIN FL_STORAGE FD4 ON A.FL_STORAGEDOC4_ID=FD4.ID
  INNER JOIN (SELECT * FROM SS_BYTEDES WHERE TABLENAME='SS_WEBBOARD' AND COLUMNNAME='LEVEL_ID') L ON A.LEVEL_ID=L.BYTEID,
  (SELECT * FROM SS_BYTEDES WHERE TABLENAME='SS_WEBBOARD' AND COLUMNNAME='IMAGEPOSITION_CODE' AND DEFAULT_ID=1) IP;

