-- ----------------------------
-- View structure for VW_SS_WEBBOARD_PUBLIC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_WEBBOARD_PUBLIC" AS SELECT A.ID,
  A.TOPICNAME,
  A.TOPICNAMEENG,
  A.DETAIL,
  A.DETAILENG,
  A.WRITERNAME,
  A.WRITERNAMEENG,
  A.DATEBEGIN,
  A.DATEEND,
  A.LEVEL_ID,
  A.GROUP_ID,
  A.STATUS_ID,
  A.WEBBOARDTYPE_ID,
  A.IMAGEPOSITION_CODE,
  A.IMAGEPOSITION_VALUE,
  A.FL_STORAGEIMAGE_ID,
  A.FL_STORAGEDOC_ID,
  A.FL_STORAGEDOC2_ID,
  A.FL_STORAGEDOC3_ID,
  A.FL_STORAGEDOC4_ID,
  A.IMAGELINKURL,
  NVL(A.IMAGELINKTARGET_CODE,'_BLANK') AS IMAGELINKTARGET_CODE,
  A.CREATEBY,
  A.CREATEDATETIME,
  A.UPDATEBY,
  A.UPDATEDATETIME,
  A.GUID,

  A.IMAGENAME,
  A. IMAGEGUID,
  A.DOCNAME,
  A.DOCGUID,
  A.DOCNAME2,
  A.DOCGUID2,
  A.DOCNAME3,
  A.DOCGUID3,
  A.DOCNAME4,
  A.DOCGUID4,
  A.LEVELCODE,
  A.LEVELNAME,
  A.LEVELNAMEENG
FROM VW_SS_WEBBOARD A
WHERE A.GROUP_ID=1 AND A.STATUS_ID=60
  AND A.DATEBEGIN <= TRUNC(SYSDATE) AND TRUNC(SYSDATE) <= NVL(A.DATEEND,TRUNC(SYSDATE));

-- ----------------------------
-- View structure for VW_SS_WEBBOARD_SPECIFIC
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_SS_WEBBOARD_SPECIFIC" AS SELECT A.ID,
	   A.TOPICNAME,
	   A.TOPICNAMEENG,
	   A.DETAIL,
	   A.DETAILENG,
	   A.WRITERNAME,
	   A.WRITERNAMEENG,
	   A.DATEBEGIN,
	   A.DATEEND,
	   A.LEVEL_ID,
	   A.GROUP_ID,
	   A.STATUS_ID,
	   A.WEBBOARDTYPE_ID,
	   A.IMAGEPOSITION_CODE,
	   A.IMAGEPOSITION_VALUE,
	   A.FL_STORAGEIMAGE_ID,
	   A.FL_STORAGEDOC_ID,
	   A.FL_STORAGEDOC2_ID,
	   A.FL_STORAGEDOC3_ID,
	   A.FL_STORAGEDOC4_ID,
	   A.IMAGELINKURL,
	   NVL(A.IMAGELINKTARGET_CODE, '_BLANK') AS IMAGELINKTARGET_CODE,
	   A.CREATEBY,
	   A.CREATEDATETIME,
	   A.UPDATEBY,
	   A.UPDATEDATETIME,
	   A.GUID,

	   A.IMAGENAME,
	   A. IMAGEGUID,
	   A.DOCNAME,
	   A.DOCGUID,
	   A.DOCNAME2,
	   A.DOCGUID2,
	   A.DOCNAME3,
	   A.DOCGUID3,
	   A.DOCNAME4,
	   A.DOCGUID4,
	   A.LEVELCODE,
	   A.LEVELNAME,
	   A.LEVELNAMEENG,

	   AI.HR_STAFF_ID
FROM VW_SS_WEBBOARD A
INNER JOIN (SELECT D.SS_WEBBOARD_ID,
				   S.ID AS HR_STAFF_ID
			FROM VW_HR_STAFF S
			INNER JOIN SS_WEBBOARDDEPT_CH D ON S.MT_DEPARTMENT_ID = D.MT_DEPARTMENT_ID
											   OR S.MT_DEPARTMENTWORK_ID = D.MT_DEPARTMENT_ID
			UNION
			SELECT SS_WEBBOARD_ID,
				   HR_STAFF_ID
			FROM SS_WEBBOARDSTAFF
			WHERE ISEXCLUDE_ID = 0) AI ON A.ID = AI.SS_WEBBOARD_ID
LEFT JOIN SS_WEBBOARDSTAFF AP ON AI.SS_WEBBOARD_ID = AP.SS_WEBBOARD_ID
								 AND AI.HR_STAFF_ID = AP.HR_STAFF_ID
								 AND ISEXCLUDE_ID = 1
WHERE A.GROUP_ID = 2
	  AND AP.ID IS NULL
	  AND A.STATUS_ID = 60
	  AND A.DATEBEGIN <= TRUNC(SYSDATE)
	  AND TRUNC(SYSDATE) <= NVL(A.DATEEND, TRUNC(SYSDATE));

-- ----------------------------
-- View structure for VW_WF_ENTITYRIGHTVALID
-- ----------------------------
CREATE OR REPLACE VIEW "VNMIS"."VW_WF_ENTITYRIGHTVALID" AS SELECT
	R.ID,R.GUID,R.CREATEDATETIME,R.CREATEBY,R.UPDATEDATETIME,R.UPDATEBY,R.WF_ENTITY_ID,R.MT_REFER_ID,R.VALIDDATEFROM,R.VALIDDATETHRU,R.NOTE,R.ISOWNER_ID,R.FULLRIGHT_ID,R.ADMINRIGHT_ID,R.GRANTRIGHT_ID,R.STARTRIGHT_ID,R.VIEWRIGHT_ID,R.APPROVERIGHT_ID,R.DELEGATERIGHT_ID,R.REDIRECTRIGHT_ID
FROM WF_ENTITYRIGHT R
WHERE
	(R.VALIDDATEFROM IS NULL OR R.VALIDDATEFROM <= SYSDATE)
	AND (R.VALIDDATETHRU IS NULL OR R.VALIDDATETHRU >= SYSDATE);

-- ----------------------------
-- Function structure for FN_HR_EVLOTWLPOSGRPWL_SCORE
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_HR_EVLOTWLPOSGRPWL_SCORE" AS
BEGIN
	V_SCORE := 0;
	IF P_SCORETYPE_ID IN (1, 5) AND NVL(P_TOTALWORK, 0) >= P_MINTOTAL THEN
		V_SCORE := P_EACHSCORE * NVL(P_TOTALWORK, 0);
	
	ELSIF P_SCORETYPE_ID = 2 AND NVL(P_TOTALWORK, 0) >= P_MINTOTAL THEN
		V_SCORE := P_MAINEACHSCORE * NVL(P_TOTALWORK, 0);
	
	ELSIF P_SCORETYPE_ID IN (3, 6, 7, 8) THEN
		V_SCORE := NVL(P_SCORE, 0);
	
	ELSIF P_SCORETYPE_ID = 4 AND NVL(P_TOTALWORK, 0) >= P_MINTOTAL THEN
		V_SCORE := P_MAXSCORE;
	
	END IF;

	IF V_SCORE > P_MAXSCORE AND P_MAXSCORE > 0 THEN
		V_SCORE := P_MAXSCORE;
	END IF;

	RETURN V_SCORE;
END;
/

-- ----------------------------
-- Function structure for FN_HR_EVLOTWLPOSGRP_SCORE
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_HR_EVLOTWLPOSGRP_SCORE" AS
BEGIN
	IF P_MAXSCORE > 0 AND P_SCORE > P_MAXSCORE THEN
		V_SCORE := P_MAXSCORE;
	ELSE
		V_SCORE := P_SCORE;
	END IF;

	RETURN V_SCORE;
END;
/

-- ----------------------------
-- Function structure for FN_HR_STAFF_GETNAME
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_HR_STAFF_GETNAME" AS
BEGIN
	RETURN TRIM(P_PREFIXNAME || CASE WHEN
				P_ISTHAI <> 1 AND INSTR(NVL(P_PREFIXNAME, '-'), '.') = 0 THEN ' '
				END || P_STAFFNAME || ' ' || CASE WHEN
				P_STAFFMIDNAME IS NOT NULL THEN P_STAFFMIDNAME || ' '
				END || P_STAFFSURNAME);
END;
/

-- ----------------------------
-- Function structure for FN_HR_STIMEDIFF
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_HR_STIMEDIFF" AS
BEGIN

	STIMEDIFF := NULL;

	IF (DATEA IS NOT NULL) AND (DATEB IS NOT NULL) THEN

		IF ((DATEB - DATEA) < 0) OR (DATEA IS NULL) OR (DATEB IS NULL) THEN
			STIMEDIFF := NULL;
			RETURN STIMEDIFF;
		ELSE

			IYEARA  := TO_NUMBER(TO_CHAR(DATEA, 'YYYY'));
			IYEARB  := TO_NUMBER(TO_CHAR(DATEB, 'YYYY'));
			IMONTHA := TO_NUMBER(TO_CHAR(DATEA, 'MM'));
			IMONTHB := TO_NUMBER(TO_CHAR(DATEB, 'MM'));
			IDATEA  := TO_NUMBER(TO_CHAR(DATEA, 'DD'));
			IDATEB  := TO_NUMBER(TO_CHAR(DATEB, 'DD'));

			IYEARDIFF := IYEARB - IYEARA;

			IF IMONTHB < IMONTHA THEN

				IF IYEARB = IYEARA + 1 AND IDATEA = 1 AND (IMONTHA = (IMONTHB + 1)) AND
				   IDATEB = FN_SS_GETDAYSOFMONTH(DATEB) THEN
					IYEARDIFF := 1;
				ELSE
					IDATEB := IDATEB + 1;

					IYEARDIFF  := IYEARDIFF - 1;
					IMONTHDIFF := (IMONTHB - IMONTHA) + 12;

					IF IDATEA < IDATEB THEN
						IDAYDIFF := IDATEB - IDATEA;
					ELSIF IDATEA > IDATEB THEN
						IMONTHDIFF := IMONTHDIFF - 1;
						IDAYDIFF   := (FN_SS_GETDAYSOFMONTH(ADD_MONTHS(DATEB, -1)) - IDATEA) + IDATEB;
					END IF;
				END IF;

			ELSIF IMONTHB > IMONTHA THEN

				IF IYEARB = IYEARA AND IDATEA = 1 AND IMONTHA = 1 AND IDATEB = 31 AND IMONTHB = 12 THEN
					IYEARDIFF := 1;
					IGAPDAY   := 1;
				ELSE
					IDATEB     := IDATEB + 1;
					IMONTHDIFF := IMONTHB - IMONTHA;

					IF IDATEA < IDATEB THEN
						IDAYDIFF := IDATEB - IDATEA;
					ELSIF IDATEA > IDATEB THEN
						IMONTHDIFF := IMONTHDIFF - 1;
						IF IMONTHA + 1 = IMONTHB THEN
							IDAYDIFF := (FN_SS_GETDAYSOFMONTH(ADD_MONTHS(DATEB, -1)) - IDATEA) + IDATEB;
							IGAPDAY  := 1;
						ELSE
							-- IDAYDIFF := (fn_ss_GETDAYSOFMONTH(ADD_MONTHS(DATEB, -1)) - IDATEA) + IDATEB - 1;
							IDAYDIFF := (FN_SS_GETDAYSOFMONTH(ADD_MONTHS(DATEB, -1)) - IDATEA) + IDATEB;
							IGAPDAY  := -1;
						END IF;
					ELSE
						IF IMONTHA + 1 = IMONTHB THEN
							IGAPDAY := 1;
						ELSE
							IGAPDAY := -1;
						END IF;
					END IF;
				END IF;

			ELSE
				IMONTHDIFF := 0;

				IF IDATEA < IDATEB THEN
					IF IDATEA = 1 AND IDATEB = FN_SS_GETDAYSOFMONTH(DATEA) THEN
						IMONTHDIFF := 1;
						IGAPDAY    := 1;
					ELSE
						IDAYDIFF := IDATEB - IDATEA;
						IF IYEARA <> IYEARB THEN
							IF NOT ISLEAPYEAR(IYEARA) AND ISLEAPYEAR(IYEARB) THEN
								IF IDATEA = 28 AND IDATEB = 29 AND IMONTHA = 2 AND IMONTHB = 2 THEN
									IMONTHDIFF := 0;
									IDAYDIFF   := 0;
								ELSE
									IDAYDIFF := IDATEB - IDATEA + 1;
								END IF;
							END IF;
						ELSE
							IGAPDAY  := 1;
							IDAYDIFF := IDAYDIFF + IGAPDAY;
						END IF;
					END IF;

				ELSIF IDATEA > IDATEB THEN

					IF ISLEAPYEAR(IYEARA) AND NOT ISLEAPYEAR(IYEARB) THEN
						IF IDATEA = 29 AND IDATEB = 28 AND IMONTHA = 2 AND IMONTHB = 2 THEN
							IMONTHDIFF := 0;
							IDAYDIFF   := 0;
						ELSE
							IF IDATEA = (IDATEB + 1) THEN
								IMONTHDIFF := 0;
								IDAYDIFF   := 0;
							ELSE
								IYEARDIFF  := IYEARDIFF - 1;
								IMONTHDIFF := 11;
								IDAYDIFF   := IDATEB - IDATEA + FN_SS_GETDAYSOFMONTH(DATEB);
							END IF;
						END IF;

					ELSE
						IF IDATEA = (IDATEB + 1) THEN
							IMONTHDIFF := 0;
							IDAYDIFF   := 0;
						ELSE
							IYEARDIFF  := IYEARDIFF - 1;
							IMONTHDIFF := 11;
							IDAYDIFF   := (FN_SS_GETDAYSOFMONTH(DATEB - 1) - IDATEA) + IDATEB + 1;
						END IF;
					END IF;
				ELSE
					IDAYDIFF := 1;
					IGAPDAY  := 1;
				END IF;
			END IF;

			IF IDAYDIFF >= FN_SS_GETDAYSOFMONTH(DATEB) THEN
				IMONTHDIFF := IMONTHDIFF + 1;
				IDAYDIFF   := IDAYDIFF - FN_SS_GETDAYSOFMONTH(DATEB);
			END IF;

			IF IMONTHDIFF >= 12 THEN
				IYEARDIFF  := IYEARDIFF + 1;
				IMONTHDIFF := IMONTHDIFF - 12;
			END IF;

			--return section
			IF IYEARDIFF > 0 THEN
				IRETURNYEAR := IYEARDIFF;
			END IF;

			IF IMONTHDIFF > 0 THEN
				IRETURNMONTH := IMONTHDIFF;
			END IF;

			IF IDAYDIFF > 0 THEN
				IRETURNDAY := IDAYDIFF;
			END IF;

			IRETURNDAYS := (DATEB - DATEA) + IGAPDAY;

		END IF;

		-- ส่วนค่าที่ Return
		IF ILANG = 1 THEN
			IF IYEARDIFF > 0 THEN
				STIMEDIFF := IYEARDIFF || ' years ';
			END IF;

			IF IMONTHDIFF > 0 THEN
				STIMEDIFF := STIMEDIFF || IMONTHDIFF || ' months ';
			END IF;

			IF IDAYDIFF > 0 THEN
				STIMEDIFF := STIMEDIFF || IDAYDIFF || ' days';
			END IF;
		ELSE
			IF IYEARDIFF > 0 THEN
				STIMEDIFF := IYEARDIFF || ' ปี ';
			END IF;

			IF IMONTHDIFF > 0 THEN
				STIMEDIFF := STIMEDIFF || IMONTHDIFF || ' เดือน ';
			END IF;

			IF IDAYDIFF > 0 THEN
				STIMEDIFF := STIMEDIFF || IDAYDIFF || ' วัน';
			END IF;
		END IF;
	END IF;

	IF VTYPE = 1 THEN
		IF VRTYPE = 'YEAR' THEN
			RETURN IYEARDIFF;
		ELSIF VRTYPE = 'MONTH' THEN
			RETURN IMONTHDIFF;
		ELSIF VRTYPE = 'DAY' THEN
			RETURN IDAYDIFF;
		ELSE
			RETURN NULL;
		END IF;
	ELSE
		RETURN STIMEDIFF;
	END IF;

END;
/

