FUNCTION "VNMIS"."FN_SS_DELETEBY_GET" AS
BEGIN
	BEGIN
		SELECT CREATEBY
		INTO   V_DELETEBY
		FROM   SS_PARAMETER_CH T
		WHERE  T.SESSIONID = USERENV('SESSIONID')
			   AND PARAMETERNAME = 'SYSTEM.SS_DELETE.DELETEBY';
