-- ----------------------------
-- Function structure for FN_SS_ENDLOOP
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_SS_ENDLOOP" AS
BEGIN

	IF VINITIAL = VINHERIT THEN
		TEMP := -1; -- ERROR
	ELSE
		BEGIN
			SELECT SS_ROLEINHERITFROM_ID
			INTO   TEMP
			FROM   SS_ROLE
			WHERE  ID = VINHERIT;
		EXCEPTION
			WHEN OTHERS THEN
				TEMP := -2; -- END
		END;
		IF TEMP <> -2 THEN
			TEMP := FN_SS_ENDLOOP(VINITIAL, TEMP);
		END IF;
	END IF;

	RETURN(TEMP);

END;
/

-- ----------------------------
-- Function structure for FN_SS_GETDAYSOFMONTH
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_SS_GETDAYSOFMONTH" AS
BEGIN
	IF VDATE IS NOT NULL THEN
		VDATEFROM := TO_DATE('01/' || TO_CHAR(VDATE, 'MM') || '/' || TO_CHAR(VDATE, 'YYYY'), 'DD/MM/YYYY');
		VDATETO   := LAST_DAY(VDATE);
		TEMP      := (VDATETO - VDATEFROM) + 1;
	END IF;

	RETURN(TEMP);

END;
/

-- ----------------------------
-- Function structure for FN_SS_LONGTYPE_GET
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_SS_LONGTYPE_GET" AS
BEGIN
    CASE VCODE
        WHEN 'DATA_DEFAULT' THEN
            SELECT DATA_DEFAULT
            INTO STR
            FROM SYS.USER_TAB_COLUMNS
            WHERE TABLE_NAME = VTABLE
                  AND COLUMN_NAME = VCOLUMN;
        WHEN 'TRIGGER_BODY' THEN
            SELECT TRIGGER_BODY
            INTO STR
            FROM USER_TRIGGERS
            WHERE TRIGGER_NAME = VTABLE;
        WHEN 'VIEW_TEXT' THEN
            SELECT TEXT INTO STR FROM USER_VIEWS WHERE VIEW_NAME = VTABLE;

        ELSE
            STR := NULL;
    END CASE;

    RETURN STR;

END FN_SS_LONGTYPE_GET;
/

-- ----------------------------
-- Function structure for FN_SS_PARAMETER_GETDATE
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_SS_PARAMETER_GETDATE" AS
BEGIN
  BEGIN
    SELECT T.VALUEDATE
    INTO   VRESULT
    FROM   SS_PARAMETER_CH T
    WHERE  T.PARAMETERNAME = VNAME AND
         (T.SESSIONID = USERENV('SESSIONID') OR
         (T.SESSIONID = 0 AND NVL(T.HOSTNAME, '-') = USERENV('TERMINAL')));
    RETURN VRESULT;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF VNULLABLE = 'N' THEN
        PD_SS_RAISEERROR(-20001,
                 ODBCERR('ไม่พบ Parameter ชื่อ ' || VNAME));
      ELSE
        RETURN NULL;
      END IF;
    WHEN TOO_MANY_ROWS THEN
      /*PD_SS_RAISEERROR(-20001,
            ODBCERR('Parameter ชื่อ ' || VNAME || ' มีหลายค่า'));*/
      SELECT T.VALUEDATE
      INTO   VRESULT
      FROM   SS_PARAMETER_CH T
      WHERE  T.PARAMETERNAME = VNAME AND T.SESSIONID = USERENV('SESSIONID');
      RETURN VRESULT;
  END;
END;
/

