-- ----------------------------
-- Function structure for FN_SS_RANDOMSTR_GET
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_SS_RANDOMSTR_GET" AS
BEGIN
	FOR I IN 1 .. P_LENGTH
	LOOP
		/*MY_STR := MY_STR || DBMS_RANDOM.STRING(CASE
            WHEN DBMS_RANDOM.VALUE(0, 1) < 0.5 THEN
             'l'
            ELSE
             'X'
        END,
        1);*/
		MY_STR := MY_STR || CASE
					  WHEN DBMS_RANDOM.VALUE(0, 1) < 0.5 THEN
					   TO_CHAR(CEIL(DBMS_RANDOM.VALUE(1, 9)))
					  ELSE
					   DBMS_RANDOM.STRING('U', 1)
				  END;
	END LOOP;
	RETURN MY_STR;
END;
/

-- ----------------------------
-- Function structure for FN_SS_SCHEMAOBJECTNAME_CONVERT
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."FN_SS_SCHEMAOBJECTNAME_CONVERT" AS
BEGIN
	IF P_NAME IS NULL THEN
		RETURN NULL;
	END IF;
	V_OLDNAME := REPLACE(REPLACE(UPPER(P_NAME), '-', '_'), ' ', '_');
	FOR V_IDX IN 1 .. LENGTH(V_OLDNAME)
	LOOP
		V_CHARAT := SUBSTR(V_OLDNAME, V_IDX, 1);
		V_INVALIDCHAR := LENGTH(TRIM(TRANSLATE(V_CHARAT,
											   'ABCDEFGHIJKLMNOPQRSTUVWXYZ_0123456789',
											   ' ')));
		IF V_INVALIDCHAR IS NULL THEN
			V_NEWNAME := V_NEWNAME || V_CHARAT;
		END IF;
	END LOOP;
	RETURN V_NEWNAME;
END;
/

