-- ----------------------------
-- Function structure for GET_HRM_STIMEDIFF
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."GET_HRM_STIMEDIFF" AS
BEGIN

	STIMEDIFF := NULL;

	IF (DATEA IS NOT NULL) AND (DATEB IS NOT NULL) THEN

		IF ((DATEB - DATEA) < 0) OR (DATEA IS NULL) OR (DATEB IS NULL) THEN
			STIMEDIFF := NULL;
			RETURN STIMEDIFF;
		ELSE

			IYEARA  := TO_NUMBER(TO_CHAR(DATEA, 'YYYY'));
			IYEARB  := TO_NUMBER(TO_CHAR(DATEB, 'YYYY'));
			IMONTHA := TO_NUMBER(TO_CHAR(DATEA, 'MM'));
			IMONTHB := TO_NUMBER(TO_CHAR(DATEB, 'MM'));
			IDATEA  := TO_NUMBER(TO_CHAR(DATEA, 'DD'));
			IDATEB  := TO_NUMBER(TO_CHAR(DATEB, 'DD'));

			IYEARDIFF := IYEARB - IYEARA;

			IF IMONTHB < IMONTHA THEN

				IF IYEARB = IYEARA + 1 AND IDATEA = 1 AND (IMONTHA = (IMONTHB + 1)) AND
				   IDATEB = fn_ss_GETDAYSOFMONTH(DATEB) THEN
					IYEARDIFF := 1;
				ELSE
					IDATEB := IDATEB + 1;

					IYEARDIFF  := IYEARDIFF - 1;
					IMONTHDIFF := (IMONTHB - IMONTHA) + 12;

					IF IDATEA < IDATEB THEN
						IDAYDIFF := IDATEB - IDATEA;
					ELSIF IDATEA > IDATEB THEN
						IMONTHDIFF := IMONTHDIFF - 1;
						IDAYDIFF   := (fn_ss_GETDAYSOFMONTH(ADD_MONTHS(DATEB, -1)) - IDATEA) + IDATEB;
					END IF;
				END IF;

			ELSIF IMONTHB > IMONTHA THEN

				IF IYEARB = IYEARA AND IDATEA = 1 AND IMONTHA = 1 AND IDATEB = 31 AND IMONTHB = 12 THEN
					IYEARDIFF := 1;
					IGAPDAY   := 1;
				ELSE
					IDATEB     := IDATEB + 1;
					IMONTHDIFF := IMONTHB - IMONTHA;

					IF IDATEA < IDATEB THEN
						IDAYDIFF := IDATEB - IDATEA;
					ELSIF IDATEA > IDATEB THEN
						IMONTHDIFF := IMONTHDIFF - 1;
						IF IMONTHA + 1 = IMONTHB THEN
							IDAYDIFF := (fn_ss_GETDAYSOFMONTH(ADD_MONTHS(DATEB, -1)) - IDATEA) + IDATEB;
							IGAPDAY  := 1;
						ELSE
							-- IDAYDIFF := (fn_ss_GETDAYSOFMONTH(ADD_MONTHS(DATEB, -1)) - IDATEA) + IDATEB - 1;
              IDAYDIFF := (fn_ss_GETDAYSOFMONTH(ADD_MONTHS(DATEB, -1)) - IDATEA) + IDATEB;
							IGAPDAY  := -1;
						END IF;
					ELSE
						IF IMONTHA + 1 = IMONTHB THEN
							IGAPDAY := 1;
						ELSE
							IGAPDAY := -1;
						END IF;
					END IF;
				END IF;

			ELSE
				IMONTHDIFF := 0;

				IF IDATEA < IDATEB THEN
					IF IDATEA = 1 AND IDATEB = fn_ss_GETDAYSOFMONTH(DATEA) THEN
						IMONTHDIFF := 1;
						IGAPDAY    := 1;
					ELSE
						IDAYDIFF := IDATEB - IDATEA;
						IF IYEARA <> IYEARB THEN
							IF NOT ISLEAPYEAR(IYEARA) AND ISLEAPYEAR(IYEARB) THEN
								IF IDATEA = 28 AND IDATEB = 29 AND IMONTHA = 2 AND IMONTHB = 2 THEN
									IMONTHDIFF := 0;
									IDAYDIFF   := 0;
								ELSE
									IDAYDIFF := IDATEB - IDATEA + 1;
								END IF;
							END IF;
						ELSE
							IGAPDAY  := 1;
							IDAYDIFF := IDAYDIFF + IGAPDAY;
						END IF;
					END IF;

				ELSIF IDATEA > IDATEB THEN

					IF ISLEAPYEAR(IYEARA) AND NOT ISLEAPYEAR(IYEARB) THEN
						IF IDATEA = 29 AND IDATEB = 28 AND IMONTHA = 2 AND IMONTHB = 2 THEN
							IMONTHDIFF := 0;
							IDAYDIFF   := 0;
						ELSE
							IF IDATEA = (IDATEB + 1) THEN
								IMONTHDIFF := 0;
								IDAYDIFF   := 0;
							ELSE
								IYEARDIFF  := IYEARDIFF - 1;
								IMONTHDIFF := 11;
								IDAYDIFF   := IDATEB - IDATEA + fn_ss_GETDAYSOFMONTH(DATEB);
							END IF;
						END IF;

					ELSE
						IF IDATEA = (IDATEB + 1) THEN
							IMONTHDIFF := 0;
							IDAYDIFF   := 0;
						ELSE
							IYEARDIFF  := IYEARDIFF - 1;
							IMONTHDIFF := 11;
							IDAYDIFF   := (fn_ss_GETDAYSOFMONTH(DATEB - 1) - IDATEA) + IDATEB + 1;
						END IF;
					END IF;
				ELSE
					IDAYDIFF := 1;
					IGAPDAY  := 1;
				END IF;
			END IF;

			IF IDAYDIFF >= fn_ss_GETDAYSOFMONTH(DATEB) THEN
				IMONTHDIFF := IMONTHDIFF + 1;
				IDAYDIFF   := IDAYDIFF - fn_ss_GETDAYSOFMONTH(DATEB);
			END IF;

			IF IMONTHDIFF >= 12 THEN
				IYEARDIFF  := IYEARDIFF + 1;
				IMONTHDIFF := IMONTHDIFF - 12;
			END IF;

			--return section
			IF IYEARDIFF > 0 THEN
				IRETURNYEAR := IYEARDIFF;
			END IF;

			IF IMONTHDIFF > 0 THEN
				IRETURNMONTH := IMONTHDIFF;
			END IF;

			IF IDAYDIFF > 0 THEN
				IRETURNDAY := IDAYDIFF;
			END IF;

			IRETURNDAYS := (DATEB - DATEA) + IGAPDAY;

		END IF;

		-- ส่วนค่าที่ Return
		IF ILANG = 1 THEN
			IF IYEARDIFF > 0 THEN
				STIMEDIFF := IYEARDIFF || ' years ';
			END IF;

			IF IMONTHDIFF > 0 THEN
				STIMEDIFF := STIMEDIFF || IMONTHDIFF || ' months ';
			END IF;

			IF IDAYDIFF > 0 THEN
				STIMEDIFF := STIMEDIFF || IDAYDIFF || ' days';
			END IF;
		ELSE
			IF IYEARDIFF > 0 THEN
				STIMEDIFF := IYEARDIFF || ' ปี ';
			END IF;

			IF IMONTHDIFF > 0 THEN
				STIMEDIFF := STIMEDIFF || IMONTHDIFF || ' เดือน ';
			END IF;

			IF IDAYDIFF > 0 THEN
				STIMEDIFF := STIMEDIFF || IDAYDIFF || ' วัน';
			END IF;
		END IF;
	END IF;

	IF VTYPE = 1 THEN
		IF VRTYPE = 'YEAR' THEN
			RETURN IYEARDIFF;
		ELSIF VRTYPE = 'MONTH' THEN
			RETURN IMONTHDIFF;
		ELSIF VRTYPE = 'DAY' THEN
			RETURN IDAYDIFF;
		ELSE
			RETURN NULL;
		END IF;
	ELSE
		RETURN STIMEDIFF;
	END IF;

END;
/

-- ----------------------------
-- Function structure for ISLEAPYEAR
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."ISLEAPYEAR" AS
BEGIN
	IF ((VYEAR MOD 400) = 0) OR ((VYEAR MOD 100) <> 0) AND ((VYEAR MOD 4) = 0) THEN
		RETURN TRUE;
	ELSE
		RETURN FALSE;
	END IF;
END;
/

-- ----------------------------
-- Function structure for ODBCERR
-- ----------------------------
CREATE OR REPLACE
FUNCTION "VNMIS"."ODBCERR" AS
BEGIN
	CRLF := CHR(13) || CHR(10);
	RETURN CRLF || '______________________________________________________________' || CRLF || CRLF || 'ไ ม่ ส า ม า ร ถ ทำ ร า ย ก า ร ไ ด้ ' || CRLF || CRLF || ERRIN || CRLF || '______________________________________________________________' || CRLF || CRLF;
END;
/

-- ----------------------------
-- Function structure for PD_BP_PERIODAPPACTBUDQTR_CAL
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_BP_PERIODAPPACTBUDQTR_CAL" AS
BEGIN
	SELECT NVL(SUM(MONTH01), 0),
		   NVL(SUM(MONTH02), 0),
		   NVL(SUM(MONTH03), 0),
		   NVL(SUM(MONTH04), 0),
		   NVL(SUM(MONTH05), 0),
		   NVL(SUM(MONTH06), 0),
		   NVL(SUM(MONTH07), 0),
		   NVL(SUM(MONTH08), 0),
		   NVL(SUM(MONTH09), 0),
		   NVL(SUM(MONTH10), 0),
		   NVL(SUM(MONTH11), 0),
		   NVL(SUM(MONTH12), 0)
	INTO   V_MONTH01,
		   V_MONTH02,
		   V_MONTH03,
		   V_MONTH04,
		   V_MONTH05,
		   V_MONTH06,
		   V_MONTH07,
		   V_MONTH08,
		   V_MONTH09,
		   V_MONTH10,
		   V_MONTH11,
		   V_MONTH12
	FROM   BP_PERIODAPPACTEXP
	WHERE  BP_PERIODAPPACT_ID = P_BP_PERIODAPPACT_ID;

	UPDATE BP_PERIODAPPACTBUDQTR
	SET    QUATER1 = V_MONTH01 + V_MONTH02 + V_MONTH03,
		   QUATER2 = V_MONTH04 + V_MONTH05 + V_MONTH06,
		   QUATER3 = V_MONTH07 + V_MONTH08 + V_MONTH09,
		   QUATER4 = V_MONTH10 + V_MONTH11 + V_MONTH12,
		   MONTH01 = V_MONTH01,
		   MONTH02 = V_MONTH02,
		   MONTH03 = V_MONTH03,
		   MONTH04 = V_MONTH04,
		   MONTH05 = V_MONTH05,
		   MONTH06 = V_MONTH06,
		   MONTH07 = V_MONTH07,
		   MONTH08 = V_MONTH08,
		   MONTH09 = V_MONTH09,
		   MONTH10 = V_MONTH10,
		   MONTH11 = V_MONTH11,
		   MONTH12 = V_MONTH12,
		   TOTAL = V_MONTH01 + V_MONTH02 + V_MONTH03 + V_MONTH04 + V_MONTH05 +
				   V_MONTH06 + V_MONTH07 + V_MONTH08 + V_MONTH09 + V_MONTH10 +
				   V_MONTH11 + V_MONTH12,
		   UPDATEBY = P_UPDATEBY,
		   UPDATEDATETIME = SYSDATE
	WHERE  BP_PERIODAPPACT_ID = P_BP_PERIODAPPACT_ID;
END;
/

-- ----------------------------
-- Function structure for PD_BP_PERIODAPPACTEXP_CAL
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_BP_PERIODAPPACTEXP_CAL" AS
BEGIN
	FOR ITEM IN (SELECT ID FROM BP_PERIODAPPACTEXP A WHERE A.BP_PERIODAPPACT_ID = P_BP_PERIODAPPACT_ID)
	LOOP
		SELECT NVL(SUM(MONTH01), 0),
			   NVL(SUM(MONTH02), 0),
			   NVL(SUM(MONTH03), 0),
			   NVL(SUM(MONTH04), 0),
			   NVL(SUM(MONTH05), 0),
			   NVL(SUM(MONTH06), 0),
			   NVL(SUM(MONTH07), 0),
			   NVL(SUM(MONTH08), 0),
			   NVL(SUM(MONTH09), 0),
			   NVL(SUM(MONTH10), 0),
			   NVL(SUM(MONTH11), 0),
			   NVL(SUM(MONTH12), 0),
			   NVL(SUM(TOTAL), 0)
		INTO V_MONTH01,
			 V_MONTH02,
			 V_MONTH03,
			 V_MONTH04,
			 V_MONTH05,
			 V_MONTH06,
			 V_MONTH07,
			 V_MONTH08,
			 V_MONTH09,
			 V_MONTH10,
			 V_MONTH11,
			 V_MONTH12,
			 V_TOTAL
		FROM BP_PERIODAPPACTEXPITEM
		WHERE BP_PERIODAPPACTEXP_ID = ITEM.ID;
	
		UPDATE BP_PERIODAPPACTEXP
		SET MONTH01 = V_MONTH01,
			MONTH02 = V_MONTH02,
			MONTH03 = V_MONTH03,
			MONTH04 = V_MONTH04,
			MONTH05 = V_MONTH05,
			MONTH06 = V_MONTH06,
			MONTH07 = V_MONTH07,
			MONTH08 = V_MONTH08,
			MONTH09 = V_MONTH09,
			MONTH10 = V_MONTH10,
			MONTH11 = V_MONTH11,
			MONTH12 = V_MONTH12,
			TOTAL = V_TOTAL
		WHERE ID = ITEM.ID;
	END LOOP;

	SELECT BP_PERIODAPP_ID INTO V_BP_PERIODAPP_ID FROM BP_PERIODAPPACT WHERE ID = P_BP_PERIODAPPACT_ID;

	PD_BP_PERIODAPPACTBUDQTR_CAL(P_BP_PERIODAPPACT_ID, P_UPDATEBY);
	PD_BP_PERIODAPP_CAL(V_BP_PERIODAPP_ID, P_UPDATEBY);
END;
/

