		(BP_PERIODAPP_ID,
		 ORDERNO,
		 BG_PLANPRDPRJACT_ID,
		 CREATEBY)
		SELECT P_BP_PERIODAPP_ID,
			   ROWNUM,
			   BG_PLANPRDPRJACT_ID,
			   P_CREATEBY
		FROM (SELECT A.ID AS BG_PLANPRDPRJACT_ID FROM VW_BG_PLANPRDPRJACT A WHERE A.BG_PLANPRDPRJ_ID = (SELECT BG_PLANPRDPRJ_ID FROM BP_PERIODAPP WHERE ID = P_BP_PERIODAPP_ID) ORDER BY A.ACTIVITYCODE) AA;
