-- ----------------------------
-- Function structure for PD_BP_PERIODAPPACT_IMP
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_BP_PERIODAPPACT_IMP" AS
BEGIN
	FOR ITEM IN (SELECT A.ID,
						C.ID AS BP_PERIODAPPACT_ID
				 FROM VW_BG_PLANPRDPRJACT A,
					  (SELECT * FROM BP_PERIODAPPACT WHERE BP_PERIODAPP_ID = P_BP_PERIODAPP_ID) C
				 WHERE A.BG_PLANPRDPRJ_ID = P_BG_STRUCPLANPRDPRJ_ID
					   AND A.ID = C.BG_PLANPRDPRJACT_ID(+)
				 ORDER BY A.ACTIVITYCODE)
	LOOP
		V_ORDERNO := V_ORDERNO + 1;
		IF ITEM.BP_PERIODAPPACT_ID IS NULL THEN
			INSERT INTO BP_PERIODAPPACT
				(BP_PERIODAPP_ID,
				 ORDERNO,
				 BG_PLANPRDPRJACT_ID,
				 CREATEBY)
			VALUES
				(P_BP_PERIODAPP_ID,
				 V_ORDERNO,
				 ITEM.ID,
				 P_CREATEBY);
		
			UPDATE BP_PERIODAPPDATAGROUP
			SET COMPLETE_ID = 0,
				UPDATEBY = P_CREATEBY
			WHERE BP_MTAPPDATAGROUP_ID > 1
				  AND BP_PERIODAPP_ID = P_BP_PERIODAPP_ID;
		ELSE
			UPDATE BP_PERIODAPPACT
			SET ORDERNO = V_ORDERNO,
				UPDATEBY = P_CREATEBY
			WHERE ID = ITEM.BP_PERIODAPPACT_ID;
		END IF;
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_BP_PERIODAPP_CAL
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_BP_PERIODAPP_CAL" AS
BEGIN
	SELECT NVL(SUM(A.TOTAL), 0)
	INTO   V_BUDGETTOTAL
	FROM   BP_PERIODAPPACTEXP A,
		   BP_PERIODAPPACT B
	WHERE  A.BP_PERIODAPPACT_ID = B.ID
		   AND B.BP_PERIODAPP_ID = P_ID;

	UPDATE BP_PERIODAPP
	SET    BUDGETTOTAL = V_BUDGETTOTAL,
		   UPDATEBY = P_UPDATEBY,
		   UPDATEDATETIME = SYSDATE
	WHERE  ID = P_ID;
END;
/

