-- ----------------------------
-- Function structure for PD_BP_PERIODAPP_DEL_BODY
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_BP_PERIODAPP_DEL_BODY" AS
BEGIN
	--clear reference
	UPDATE BP_PERIODAPPACTEXP
	SET BG_BUDGET_ID = NULL,
		REFCODE = NULL
	WHERE BP_PERIODAPPACT_ID IN (SELECT ID FROM BP_PERIODAPPACT WHERE BP_PERIODAPP_ID = P_BP_PERIODAPP_ID);

	--clear budget
	FOR ITEM IN (SELECT ID
				 FROM VW_BG_BUDGET
				 WHERE BP_PERIODAPPACTEXP_ID IN (SELECT A.ID FROM BP_PERIODAPPACTEXP A INNER JOIN BP_PERIODAPPACT B ON A.BP_PERIODAPPACT_ID = B.ID WHERE B.BP_PERIODAPP_ID = P_BP_PERIODAPP_ID))
	LOOP
		UPDATE PROMIS.BUDGET SET BP_PERIODAPPACTEXP_ID = NULL WHERE BUDGETID = ITEM.ID;
	
		DELETE PROMIS.BUDGET WHERE BUDGETID = ITEM.ID;
	END LOOP;

	--clear budgetstruc...
	SELECT * INTO V_BP_PERIODAPP FROM BP_PERIODAPP WHERE ID = P_BP_PERIODAPP_ID;

	DELETE FROM PROMIS.BUDGETSTRUCDEPARTMENT
	WHERE (BUDGETPERIODID, BUDGETGROUPID, DEPARTMENTID) IN (SELECT A.BUDGETPERIODID,
																   A.BUDGETGROUPID,
																   A.DEPARTMENTID
															FROM PROMIS.BUDGETSTRUCDEPARTMENT A
															LEFT JOIN PROMIS.BUDGET B ON A.BUDGETPERIODID = B.BUDGETPERIODID
																						 AND A.BUDGETGROUPID = B.BUDGETGROUPID
																						 AND A.DEPARTMENTID = B.DEPARTMENTID
															WHERE B.BUDGETID IS NULL);

	DELETE FROM PROMIS.BUDGETSTRUCPROJECTACTIVITY
	WHERE BUDGETSTRUCPROJECTACTIVITYID IN (SELECT D.BUDGETSTRUCPROJECTACTIVITYID
										   FROM PROMIS.BUDGETSTRUCPLAN A
										   INNER JOIN PROMIS.BUDGETSTRUCPRODUCT B ON A.BUDGETSTRUCPLANID = B.BUDGETSTRUCPLANID
										   INNER JOIN PROMIS.BUDGETSTRUCPROJECT C ON B.BUDGETSTRUCPLANID = C.BUDGETSTRUCPLANID
																					 AND B.PRODUCTID = C.PRODUCTID
										   INNER JOIN PROMIS.BUDGETSTRUCPROJECTACTIVITY D ON C.BUDGETSTRUCPROJECTID = D.BUDGETSTRUCPROJECTID
										   LEFT JOIN PROMIS.BUDGET E ON A.BUDGETPERIODID = E.BUDGETPERIODID
																		AND A.BUDGETGROUPID = E.BUDGETGROUPID
																		AND C.PROJECTID = E.PROJECTID
																		AND D.ACTIVITYID = E.ACTIVITYID
																		AND A.BUDGETSTUCTYPE = E.BUDGETSTUCTYPE
										   WHERE A.BUDGETSTUCTYPE = V_BP_PERIODAPP.STRUCTYPE_CODE
												 AND A.BUDGETPERIODID = V_BP_PERIODAPP.BUDGETYEAR
												 AND A.BUDGETGROUPID = V_BP_PERIODAPP.BG_BUDGETGROUP_ID
												 AND E.BUDGETID IS NULL);

	DELETE FROM PROMIS.BUDGETSTRUCPROJECT
	WHERE BUDGETSTRUCPROJECTID IN (SELECT C.BUDGETSTRUCPROJECTID
								   FROM PROMIS.BUDGETSTRUCPLAN A
								   INNER JOIN PROMIS.BUDGETSTRUCPRODUCT B ON A.BUDGETSTRUCPLANID = B.BUDGETSTRUCPLANID
								   INNER JOIN PROMIS.BUDGETSTRUCPROJECT C ON B.BUDGETSTRUCPLANID = C.BUDGETSTRUCPLANID
																			 AND B.PRODUCTID = C.PRODUCTID
								   LEFT JOIN PROMIS.BUDGETSTRUCPROJECTACTIVITY D ON C.BUDGETSTRUCPROJECTID = D.BUDGETSTRUCPROJECTID
								   WHERE A.BUDGETSTUCTYPE = V_BP_PERIODAPP.STRUCTYPE_CODE
										 AND A.BUDGETPERIODID = V_BP_PERIODAPP.BUDGETYEAR
										 AND A.BUDGETGROUPID = V_BP_PERIODAPP.BG_BUDGETGROUP_ID
										 AND D.BUDGETSTRUCPROJECTACTIVITYID IS NULL);

	DELETE FROM PROMIS.BUDGETSTRUCPRODUCT
	WHERE BUDGETSTRUCPRODUCTID IN (SELECT B.BUDGETSTRUCPRODUCTID
								   FROM PROMIS.BUDGETSTRUCPLAN A
								   INNER JOIN PROMIS.BUDGETSTRUCPRODUCT B ON A.BUDGETSTRUCPLANID = B.BUDGETSTRUCPLANID
								   LEFT JOIN PROMIS.BUDGETSTRUCPROJECT C ON B.BUDGETSTRUCPLANID = C.BUDGETSTRUCPLANID
																			AND B.PRODUCTID = C.PRODUCTID
								   WHERE A.BUDGETSTUCTYPE = V_BP_PERIODAPP.STRUCTYPE_CODE
										 AND A.BUDGETPERIODID = V_BP_PERIODAPP.BUDGETYEAR
										 AND A.BUDGETGROUPID = V_BP_PERIODAPP.BG_BUDGETGROUP_ID
										 AND C.BUDGETSTRUCPROJECTID IS NULL);

	DELETE FROM PROMIS.BUDGETSTRUCPLAN
	WHERE BUDGETSTRUCPLANID IN (SELECT A.BUDGETSTRUCPLANID
								FROM PROMIS.BUDGETSTRUCPLAN A
								LEFT JOIN PROMIS.BUDGETSTRUCPRODUCT B ON A.BUDGETSTRUCPLANID = B.BUDGETSTRUCPLANID
								WHERE A.BUDGETSTUCTYPE = V_BP_PERIODAPP.STRUCTYPE_CODE
									  AND A.BUDGETPERIODID = V_BP_PERIODAPP.BUDGETYEAR
									  AND A.BUDGETGROUPID = V_BP_PERIODAPP.BG_BUDGETGROUP_ID
									  AND B.BUDGETSTRUCPRODUCTID IS NULL);

END;
/

-- ----------------------------
-- Function structure for PD_BP_PERIODAPP_EXP
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_BP_PERIODAPP_EXP" AS
BEGIN
	--IMPORTPAYMENTONGL

	FOR ITEM IN (SELECT A.STRUCTYPE_CODE,
						A.BUDGETYEAR,
						A.BG_BUDGETGROUP_ID,
						A.BG_PLAN_ID,
						A.BG_PLANPRD_ID,
						A.BG_PLANPRDPRJ_ID,
						A.MT_DEPARTMENT_ID,
						B.BUDGETSTRUCPLANID,
						C.BUDGETSTRUCPRODUCTID,
						D.BUDGETSTRUCPROJECTID,
						E.BUDGETPERIODID AS HAS_BUDGETSTRUCDEPARTMENT_ID,
						F.BUDGETPERIODID AS HAS_BUDGETPERIOD_ID
				 FROM BP_PERIODAPP A
				 LEFT JOIN PROMIS.BUDGETSTRUCPLAN B ON A.STRUCTYPE_CODE = B.BUDGETSTUCTYPE
													   AND A.BUDGETYEAR = B.BUDGETPERIODID
													   AND A.BG_BUDGETGROUP_ID = B.BUDGETGROUPID
													   AND A.BG_PLAN_ID = B.PLANID
				 LEFT JOIN PROMIS.BUDGETSTRUCPRODUCT C ON B.BUDGETSTRUCPLANID = C.BUDGETSTRUCPLANID
														  AND C.PRODUCTID = A.BG_PLANPRD_ID
				 LEFT JOIN PROMIS.BUDGETSTRUCPROJECT D ON D.BUDGETSTRUCPLANID = C.BUDGETSTRUCPLANID
														  AND D.PRODUCTID = C.PRODUCTID
														  AND D.PROJECTID = A.BG_PLANPRDPRJ_ID
				 LEFT JOIN PROMIS.BUDGETSTRUCDEPARTMENT E ON E.BUDGETPERIODID = A.BUDGETYEAR
															 AND E.BUDGETGROUPID = A.BG_BUDGETGROUP_ID
															 AND E.DEPARTMENTID = A.MT_DEPARTMENT_ID
				 LEFT JOIN PROMIS.BUDGETPERIOD F ON F.BUDGETPERIODID = A.BUDGETYEAR
													AND F.BUDGETGROUPID = A.BG_BUDGETGROUP_ID
				 WHERE A.ID = P_BP_PERIOADAPP_ID)
	LOOP
		IF ITEM.HAS_BUDGETPERIOD_ID IS NULL THEN
			INSERT INTO PROMIS.BUDGETPERIOD
				(BUDGETPERIODID,
				 BUDGETGROUPID,
				 BUDGETPERIODSTATUS)
			VALUES
				(ITEM.BUDGETYEAR,
				 ITEM.BG_BUDGETGROUP_ID,
				 1);
		END IF;
	
		IF ITEM.HAS_BUDGETSTRUCDEPARTMENT_ID IS NULL THEN
			INSERT INTO PROMIS.BUDGETSTRUCDEPARTMENT
				(BUDGETPERIODID,
				 BUDGETGROUPID,
				 DEPARTMENTID)
			VALUES
				(ITEM.BUDGETYEAR,
				 ITEM.BG_BUDGETGROUP_ID,
				 ITEM.MT_DEPARTMENT_ID);
		END IF;
	
		BEGIN
			SELECT MIN(STRATEGYID)
			INTO V_STRATEGYID
			FROM PROMIS.BUDGETSTRATEGY
			WHERE BUDGETPERIODID = ITEM.BUDGETYEAR
				  AND STRATEGYDESCRIPTION = 'ไม่ระบุ';
		EXCEPTION
			WHEN OTHERS THEN
				V_STRATEGYID := NULL;
		END;
	
		IF V_STRATEGYID IS NULL THEN
			INSERT INTO PROMIS.BUDGETSTRATEGY
				(STRATEGYDESCRIPTION,
				 BUDGETPERIODID)
			VALUES
				('ไม่ระบุ',
				 ITEM.BUDGETYEAR)
			RETURNING STRATEGYID INTO V_STRATEGYID;
		END IF;
	
		IF ITEM.BUDGETSTRUCPLANID IS NULL THEN
			INSERT INTO PROMIS.BUDGETSTRUCPLAN
				(BUDGETSTUCTYPE,
				 BUDGETPERIODID,
				 BUDGETGROUPID,
				 PLANID,
				 STRATEGYID)
			VALUES
				(ITEM.STRUCTYPE_CODE,
				 ITEM.BUDGETYEAR,
				 ITEM.BG_BUDGETGROUP_ID,
				 ITEM.BG_PLAN_ID,
				 V_STRATEGYID)
			RETURNING BUDGETSTRUCPLANID INTO V_BUDGETSTRUCPLANID;
		ELSE
			V_BUDGETSTRUCPLANID := ITEM.BUDGETSTRUCPLANID;
		END IF;
	
		IF ITEM.BUDGETSTRUCPRODUCTID IS NULL THEN
			INSERT INTO PROMIS.BUDGETSTRUCPRODUCT
				(BUDGETSTRUCPLANID,
				 PRODUCTID)
			VALUES
				(V_BUDGETSTRUCPLANID,
				 ITEM.BG_PLANPRD_ID);
		END IF;
	
		IF ITEM.BUDGETSTRUCPROJECTID IS NULL THEN
			INSERT INTO PROMIS.BUDGETSTRUCPROJECT
				(BUDGETSTRUCPLANID,
				 PRODUCTID,
				 PROJECTID)
			VALUES
				(V_BUDGETSTRUCPLANID,
				 ITEM.BG_PLANPRD_ID,
				 ITEM.BG_PLANPRDPRJ_ID)
			RETURNING BUDGETSTRUCPROJECTID INTO V_BUDGETSTRUCPROJECTID;
		ELSE
			V_BUDGETSTRUCPROJECTID := ITEM.BUDGETSTRUCPROJECTID;
		END IF;
	
		INSERT INTO PROMIS.BUDGETSTRUCPROJECTACTIVITY
			(BUDGETSTRUCPROJECTID,
			 ACTIVITYID)
			SELECT V_BUDGETSTRUCPROJECTID,
				   A.ACTIVITYID
			FROM PROMIS.PROJECTACTIVITY A
			WHERE A.PROJECTID = ITEM.BG_PLANPRDPRJ_ID
				  AND A.ACTIVITYID NOT IN (SELECT ACTIVITYID FROM PROMIS.BUDGETSTRUCPROJECTACTIVITY WHERE BUDGETSTRUCPROJECTID = V_BUDGETSTRUCPROJECTID);
	
	END LOOP;

	OPEN CPOST;
	LOOP
	
		FETCH CPOST
			INTO RPOST;
		EXIT WHEN CPOST%NOTFOUND;
	
		INSERT INTO PROMIS.BUDGET
			(BUDGETPERIODID,
			 BUDGETGROUPID,
			 PROJECTID,
			 ACTIVITYID,
			 DEPARTMENTID,
			 FUNDGROUPID,
			 ACCOUNTTYPEID,
			 BUDGETNAME,
			 REQUESTBUDGET,
			 TOTALBUDGET,
			 CURRENTBUDGET,
			 RM01,
			 RM02,
			 RM03,
			 RM04,
			 RM05,
			 RM06,
			 RM07,
			 RM08,
			 RM09,
			 RM10,
			 RM11,
			 RM12,
			 TM01,
			 TM02,
			 TM03,
			 TM04,
			 TM05,
			 TM06,
			 TM07,
			 TM08,
			 TM09,
			 TM10,
			 TM11,
			 TM12,
			 APPROVEUSERID,
			 BP_PERIODAPPACTEXP_ID,
			 BUDGETSTUCTYPE)
		VALUES
			(RPOST.BUDGETYEAR,
			 RPOST.BG_BUDGETGROUP_ID,
			 RPOST.BG_PLANPRDPRJ_ID,
			 RPOST.BG_ACTIVITY_ID,
			 RPOST.MT_DEPARTMENT_ID,
			 1,
			 RPOST.BG_ACCOUNTTYPE_ID,
			 RPOST.EXPENSE,
			 RPOST.TOTAL,
			 RPOST.TOTAL,
			 RPOST.TOTAL,
			 RPOST.MONTH01,
			 RPOST.MONTH02,
			 RPOST.MONTH03,
			 RPOST.MONTH04,
			 RPOST.MONTH05,
			 RPOST.MONTH06,
			 RPOST.MONTH07,
			 RPOST.MONTH08,
			 RPOST.MONTH09,
			 RPOST.MONTH10,
			 RPOST.MONTH11,
			 RPOST.MONTH12,
			 RPOST.MONTH01,
			 RPOST.MONTH02,
			 RPOST.MONTH03,
			 RPOST.MONTH04,
			 RPOST.MONTH05,
			 RPOST.MONTH06,
			 RPOST.MONTH07,
			 RPOST.MONTH08,
			 RPOST.MONTH09,
			 RPOST.MONTH10,
			 RPOST.MONTH11,
			 RPOST.MONTH12,
			 P_CREATEBY,
			 RPOST.ID,
			 RPOST.STRUCTYPE_CODE);
	
		SELECT ID,
			   BUDGETCODE
		INTO VBUDGETID,
			 VBUDGETCODE
		FROM VW_BG_BUDGET
		WHERE BP_PERIODAPPACTEXP_ID = RPOST.ID;
	
		UPDATE BP_PERIODAPPACTEXP BPE
		SET BPE.BG_BUDGET_ID = VBUDGETID,
			BPE.REFCODE = VBUDGETCODE
		WHERE BPE.ID = RPOST.ID;
	
	END LOOP;
	CLOSE CPOST;

	UPDATE BP_PERIODAPP BP SET BP.STATUS_ID = 60 WHERE BP.ID = P_BP_PERIOADAPP_ID;

END;
/

