-- ----------------------------
-- Function structure for PD_BP_PERIODUOBJECTIVE_COPY
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_BP_PERIODUOBJECTIVE_COPY" AS
BEGIN
	FOR ITEM IN (SELECT ID,
						A.BP_UOBJECTIVE_ID
				 FROM VW_BP_PERIODUOBJECTIVE A
				 WHERE BUDGETYEAR = P_BUDGETYEARFROM
				 ORDER BY A.UOBJECTIVECODE)
	LOOP
		INSERT INTO BP_PERIODUOBJECTIVE
			(BUDGETYEAR,
			 BP_UOBJECTIVE_ID,
			 CREATEBY)
		VALUES
			(P_BUDGETYEARTO,
			 ITEM.BP_UOBJECTIVE_ID,
			 P_CREATEBY)
		RETURNING ID INTO V_ID;
	
		PD_BP_PERIODUKPI_COPY(ITEM.ID, V_ID, P_CREATEBY);
	END LOOP;
END;
/

