-- ----------------------------
-- Function structure for PD_HR_EVAPPBOARD_ROLE
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPPBOARD_ROLE" AS
BEGIN
	PD_SS_DELETE_INSERTSESSION(P_CREATEBY, 'SS_GRANTUSERROLE');

	DELETE FROM SS_GRANTUSERROLE
	WHERE  SS_ROLE_ID = 16030
		   AND SS_USER_ID NOT IN (SELECT DISTINCT U.ID
								  FROM   HR_EVAPP A
								  INNER  JOIN VW_SS_USER U ON NVL(A.HR_STAFFBOARD1_ID, 0) = U.HR_STAFF_ID
															  OR NVL(A.HR_STAFFBOARD2_ID, 0) = U.HR_STAFF_ID
															  OR NVL(A.HR_STAFFBOARD3_ID, 0) = U.HR_STAFF_ID
															  OR NVL(A.HR_STAFFBOARD4_ID, 0) = U.HR_STAFF_ID
															  OR NVL(A.HR_STAFFBOARD5_ID, 0) = U.HR_STAFF_ID
								  WHERE  U.HR_STAFF_ID IS NOT NULL);

	INSERT INTO SS_GRANTUSERROLE
		(SS_ROLE_ID,
		 SS_USER_ID,
		 CREATEBY)
		SELECT DISTINCT 16030,
						U.ID,
						P_CREATEBY
		FROM   HR_EVAPP A
		INNER  JOIN VW_SS_USER U ON NVL(A.HR_STAFFBOARD1_ID, 0) = U.HR_STAFF_ID
									OR NVL(A.HR_STAFFBOARD2_ID, 0) = U.HR_STAFF_ID
									OR NVL(A.HR_STAFFBOARD3_ID, 0) = U.HR_STAFF_ID
									OR NVL(A.HR_STAFFBOARD4_ID, 0) = U.HR_STAFF_ID
									OR NVL(A.HR_STAFFBOARD5_ID, 0) = U.HR_STAFF_ID
		WHERE  U.HR_STAFF_ID IS NOT NULL
			   AND U.ID NOT IN (SELECT SS_USER_ID FROM SS_GRANTUSERROLE WHERE SS_ROLE_ID = 16030);
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPPBOARD_UBY
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPPBOARD_UBY" AS
BEGIN
	IF P_STAFF_ID IS NULL THEN
		PD_SS_DELETE_INSERTSESSION(P_EXECUTEBY, 'HR_EVAPPBOARD');

		DELETE FROM HR_EVAPPBOARD
		WHERE  HR_EVAPP_ID = P_APP_ID
			   AND ORDERNO = P_ORDERNO;

	ELSE
		BEGIN
			SELECT ID
			INTO   V_APPBOARD_ID
			FROM   HR_EVAPPBOARD
			WHERE  HR_EVAPP_ID = P_APP_ID
				   AND ORDERNO = P_ORDERNO;
		EXCEPTION
			WHEN OTHERS THEN
				V_APPBOARD_ID := NULL;
		END;

		IF V_APPBOARD_ID IS NULL THEN
			INSERT INTO HR_EVAPPBOARD
				(HR_EVAPP_ID,
				 ORDERNO,
				 HR_STAFF_ID,
				 BOARDSTATUS_ID,
				 CREATEBY)
			VALUES
				(P_APP_ID,
				 P_ORDERNO,
				 P_STAFF_ID,
				 P_STATUS_ID,
				 P_EXECUTEBY);
		ELSE
			UPDATE HR_EVAPPBOARD
			SET    HR_STAFF_ID = P_STAFF_ID,
				   BOARDSTATUS_ID = P_STATUS_ID,
				   UPDATEBY = P_EXECUTEBY
			WHERE  ID = V_APPBOARD_ID;
		END IF;
	END IF;

END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPPWORK_IMPCMD
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPPWORK_IMPCMD" AS
BEGIN
	SELECT ID INTO V_LOCK_ID FROM HR_EVAPP WHERE ID = P_EVAPP_ID FOR UPDATE;

	SELECT B.HR_EVLOTAPP_ID,
		   A.HR_EVLOTWL_ID,
		   B.HR_EVPOSITION_ID,
		   B.HR_STAFF_ID,
		   B.HEADERSTATUS_ID
	INTO   V_EVLOTAPP_ID,
		   V_EVLOTWL_ID,
		   V_EVPOSITION_ID,
		   V_STAFF_ID,
		   V_HEADERSTATUS_ID
	FROM   HR_EVLOTAPP A
	INNER  JOIN HR_EVAPP B ON A.ID = B.HR_EVLOTAPP_ID
	WHERE  B.ID = P_EVAPP_ID;

	IF V_HEADERSTATUS_ID > 11 THEN
		RETURN;
	END IF;

	FOR GRPWL IN (SELECT C.ID,
						 DECODE(C.SCORETYPE_ID, 6, 1, 7, 2, 8, 3) AS TYPE_ID
				  FROM   HR_EVLOTWLPOS A
				  INNER  JOIN HR_EVLOTWLPOSGRP B ON A.ID = B.HR_EVLOTWLPOS_ID
				  INNER  JOIN HR_EVLOTWLPOSGRPWL C ON B.ID = C.HR_EVLOTWLPOSGRP_ID
				  WHERE  A.HR_EVLOTWL_ID = V_EVLOTWL_ID
						 AND A.HR_EVPOSITION_ID = V_EVPOSITION_ID
						 AND C.SCORETYPE_ID IN (6, 7, 8))
	LOOP
		BEGIN
			SELECT MIN(ID) INTO V_EVLOTWLPOSGRPWLFL_ID FROM HR_EVLOTWLPOSGRPWLFL WHERE HR_EVLOTWLPOSGRPWL_ID = GRPWL.ID;
		EXCEPTION
			WHEN NO_DATA_FOUND THEN
				V_EVLOTWLPOSGRPWLFL_ID := NULL;
		END;
	
		FOR ITEM IN (SELECT A.ID,
							A.HR_EVCOMMAND_ID,
							A.COMMANDNAME,
							A.FL_STORAGE_ID,
							A.SCORE,
							F.DIRECTORY,
							F.FILENAME,
							F.EXTENSION,
							F.FILESIZE,
							F.FULLNAME,
							F.FL_CONFIG_ID
					 FROM   VW_HR_EVCOMMANDMEMBER A
					 INNER  JOIN FL_STORAGE F ON A.FL_STORAGE_ID = F.ID
					 WHERE  A.TYPE_ID = GRPWL.TYPE_ID
							AND A.HR_EVLOTAPP_ID = V_EVLOTAPP_ID
							AND A.ISACTIVE_ID = 1
							AND A.HR_STAFF_ID = V_STAFF_ID
					 ORDER  BY A.ORDERNO)
		LOOP
			V_CNT := 1;
			IF GRPWL.TYPE_ID = 1 THEN
				SELECT COUNT(WL.ID)
				INTO   V_CNT
				FROM   HR_EVCOMMANDGRPWL WL
				INNER  JOIN HR_EVLOTWLPOS P ON WL.HR_EVLOTWLPOS_ID = P.ID
				WHERE  WL.HR_EVCOMMAND_ID = ITEM.HR_EVCOMMAND_ID
					   AND P.HR_EVPOSITION_ID = V_EVPOSITION_ID
					   AND P.HR_EVLOTWL_ID = V_EVLOTWL_ID
					   AND WL.HR_EVLOTWLPOSGRPWL_ID = GRPWL.ID;
			END IF;
		
			IF V_CNT > 0 THEN
				IF V_EVLOTWLPOSGRPWLFL_ID IS NOT NULL THEN
					INSERT INTO FL_STORAGE
						(DIRECTORY,
						 FILENAME,
						 EXTENSION,
						 FILESIZE,
						 FULLNAME,
						 FL_CONFIG_ID,
						 CREATEBY)
					VALUES
						(ITEM.DIRECTORY,
						 ITEM.FILENAME,
						 ITEM.EXTENSION,
						 ITEM.FILESIZE,
						 ITEM.FULLNAME,
						 ITEM.FL_CONFIG_ID,
						 P_CREATEBY)
					RETURNING ID INTO V_STORAGE_ID;
				END IF;
			
				BEGIN
					SELECT ID
					INTO   V_EVAPPWORK_ID
					FROM   HR_EVAPPWORK
					WHERE  HR_EVAPP_ID = P_EVAPP_ID
						   AND HR_EVCOMMANDMEMBER_ID = ITEM.ID;
				EXCEPTION
					WHEN NO_DATA_FOUND THEN
						V_EVAPPWORK_ID := NULL;
				END;
			
				IF V_EVAPPWORK_ID IS NULL THEN
					BEGIN
						SELECT NVL(MAX(ORDERNO), 0)
						INTO   V_ORDERNO
						FROM   HR_EVAPPWORK
						WHERE  HR_EVAPP_ID = P_EVAPP_ID
							   AND HR_EVLOTWLPOSGRPWL_ID = GRPWL.ID;
					EXCEPTION
						WHEN NO_DATA_FOUND THEN
							V_ORDERNO := 0;
					END;
				
					V_ORDERNO := V_ORDERNO + 1;
					INSERT INTO HR_EVAPPWORK
						(HR_EVAPP_ID,
						 HR_EVLOTWLPOSGRPWL_ID,
						 HR_EVCOMMANDMEMBER_ID,
						 ORDERNO,
						 DESCRIPTION,
						 TOTALWORK,
						 SCORE,
						 HEADERSTATUS_ID,
						 CREATEBY)
					VALUES
						(P_EVAPP_ID,
						 GRPWL.ID,
						 ITEM.ID,
						 V_ORDERNO,
						 ITEM.COMMANDNAME,
						 1,
						 ITEM.SCORE,
						 10,
						 P_CREATEBY)
					RETURNING ID INTO V_EVAPPWORK_ID;
				
					IF V_STORAGE_ID IS NOT NULL THEN
						INSERT INTO HR_EVAPPWORKITEM
							(HR_EVAPPWORK_ID,
							 ORDERNO,
							 FL_STORAGE_ID,
							 HR_EVLOTWLPOSGRPWLFL_ID,
							 HR_EVCOMMAND_ID,
							 CREATEBY)
						VALUES
							(V_EVAPPWORK_ID,
							 1,
							 V_STORAGE_ID,
							 V_EVLOTWLPOSGRPWLFL_ID,
							 ITEM.HR_EVCOMMAND_ID,
							 P_CREATEBY);
					END IF;
				ELSE
					--DBMS_OUTPUT.PUT_LINE(V_EVAPPWORK_ID);
					UPDATE HR_EVAPPWORK
					SET    HR_EVLOTWLPOSGRPWL_ID = GRPWL.ID,
						   DESCRIPTION = ITEM.COMMANDNAME,
						   SCORE = ITEM.SCORE,
						   UPDATEBY = P_CREATEBY
					WHERE  ID = V_EVAPPWORK_ID;
				
					IF V_STORAGE_ID IS NOT NULL THEN
						UPDATE HR_EVAPPWORKITEM
						SET    FL_STORAGE_ID = V_STORAGE_ID,
							   UPDATEBY = P_CREATEBY
						WHERE  HR_EVAPPWORK_ID = V_EVAPPWORK_ID;
					END IF;
				END IF;
			END IF;
		
		END LOOP;
	
	END LOOP;
	--COMMIT;

	--PD_HR_EVAPP_SCORE_CON(P_EVAPP_ID, 0, P_CREATEBY);
	--COMMIT;

END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPPWORK_IMPPRJ
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPPWORK_IMPPRJ" AS
BEGIN
	SELECT ID INTO V_LOCK_ID FROM HR_EVAPP WHERE ID = P_EVAPP_ID FOR UPDATE;

	SELECT B.HR_EVLOTAPP_ID,
		   A.HR_EVLOTWL_ID,
		   B.HR_EVPOSITION_ID,
		   B.HR_STAFF_ID,
		   B.HEADERSTATUS_ID
	INTO   V_EVLOTAPP_ID,
		   V_EVLOTWL_ID,
		   V_EVPOSITION_ID,
		   V_STAFF_ID,
		   V_HEADERSTATUS_ID
	FROM   HR_EVLOTAPP A
	INNER  JOIN HR_EVAPP B ON A.ID = B.HR_EVLOTAPP_ID
	WHERE  B.ID = P_EVAPP_ID;

	IF V_HEADERSTATUS_ID > 11 THEN
		RETURN;
	END IF;

	BEGIN
		SELECT MIN(C.ID)
		INTO   V_EVLOTWLPOSGRPWL_ID
		FROM   HR_EVLOTWLPOS A
		INNER  JOIN HR_EVLOTWLPOSGRP B ON A.ID = B.HR_EVLOTWLPOS_ID
		INNER  JOIN HR_EVLOTWLPOSGRPWL C ON B.ID = C.HR_EVLOTWLPOSGRP_ID
		WHERE  A.HR_EVLOTWL_ID = V_EVLOTWL_ID
			   AND A.HR_EVPOSITION_ID = V_EVPOSITION_ID
			   AND C.ISINCLUDEPROJECT_ID = 1;
	EXCEPTION
		WHEN NO_DATA_FOUND THEN
			V_EVLOTWLPOSGRPWL_ID := NULL;
	END;

	IF V_EVLOTWLPOSGRPWL_ID IS NOT NULL THEN
	
		FOR ITEM IN (SELECT *
					 FROM   VW_HR_EVPROJECTMEMBER
					 WHERE  HR_EVLOTAPP_ID = V_EVLOTAPP_ID
							AND ISACTIVE_ID = 1
							AND HR_STAFF_ID = V_STAFF_ID
					 ORDER  BY ID)
		LOOP
		
			BEGIN
				SELECT ID
				INTO   V_EVAPPWORK_ID
				FROM   HR_EVAPPWORK
				WHERE  HR_EVAPP_ID = P_EVAPP_ID
					   AND HR_EVPROJECTMEMBER_ID = ITEM.ID
				FOR    UPDATE;
			EXCEPTION
				WHEN NO_DATA_FOUND THEN
					V_EVAPPWORK_ID := NULL;
			END;
		
			IF V_EVAPPWORK_ID IS NULL THEN
				BEGIN
					SELECT NVL(MAX(ORDERNO), 0)
					INTO   V_ORDERNO
					FROM   HR_EVAPPWORK
					WHERE  HR_EVAPP_ID = P_EVAPP_ID
						   AND HR_EVLOTWLPOSGRPWL_ID = V_EVLOTWLPOSGRPWL_ID;
				EXCEPTION
					WHEN NO_DATA_FOUND THEN
						V_ORDERNO := 0;
				END;
			
				V_ORDERNO := V_ORDERNO + 1;
				INSERT INTO HR_EVAPPWORK
					(HR_EVAPP_ID,
					 HR_EVLOTWLPOSGRPWL_ID,
					 HR_EVPROJECTMEMBER_ID,
					 ORDERNO,
					 DESCRIPTION,
					 TOTALWORK,
					 SCORE,
					 HEADERSTATUS_ID,
					 CREATEBY)
				VALUES
					(P_EVAPP_ID,
					 V_EVLOTWLPOSGRPWL_ID,
					 ITEM.ID,
					 V_ORDERNO,
					 ITEM.PROJECTNAME || CASE WHEN ITEM.PRJPOSITIONNAME IS NOT NULL THEN ' [' || ITEM.PRJPOSITIONNAME || ']' END,
					 1,
					 ITEM.SCORE,
					 10,
					 P_CREATEBY);
			ELSE
				UPDATE HR_EVAPPWORK
				SET    HR_EVLOTWLPOSGRPWL_ID = V_EVLOTWLPOSGRPWL_ID,
					   DESCRIPTION = ITEM.PROJECTNAME || CASE
										 WHEN ITEM.PRJPOSITIONNAME IS NOT NULL THEN
										  ' [' || ITEM.PRJPOSITIONNAME || ']'
									 END,
					   SCORE = ITEM.SCORE,
					   UPDATEBY = P_CREATEBY
				WHERE  ID = V_EVAPPWORK_ID;
			END IF;
		
		END LOOP;
	
	END IF;

	--PD_HR_EVAPP_SCORE_CON(P_EVAPP_ID, 0, P_CREATEBY);
	--COMMIT;

END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPPWORK_IMPPRJ_BK
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPPWORK_IMPPRJ_BK" AS
BEGIN
	SELECT B.HR_EVLOTAPP_ID,
		   A.HR_EVLOTWL_ID,
		   B.HR_EVPOSITION_ID,
		   B.HR_STAFF_ID,
		   B.HEADERSTATUS_ID
	INTO   V_EVLOTAPP_ID,
		   V_EVLOTWL_ID,
		   V_EVPOSITION_ID,
		   V_STAFF_ID,
		   V_HEADERSTATUS_ID
	FROM   HR_EVLOTAPP A
	INNER  JOIN HR_EVAPP B ON A.ID = B.HR_EVLOTAPP_ID
	WHERE  B.ID = P_EVAPP_ID;

	IF V_HEADERSTATUS_ID > 11 THEN
		RETURN;
	END IF;

	BEGIN
		SELECT MIN(C.ID)
		INTO   V_EVLOTWLPOSGRPWL_ID
		FROM   HR_EVLOTWLPOS A
		INNER  JOIN HR_EVLOTWLPOSGRP B ON A.ID = B.HR_EVLOTWLPOS_ID
		INNER  JOIN HR_EVLOTWLPOSGRPWL C ON B.ID = C.HR_EVLOTWLPOSGRP_ID
		WHERE  A.HR_EVLOTWL_ID = V_EVLOTWL_ID
			   AND A.HR_EVPOSITION_ID = V_EVPOSITION_ID
			   AND C.ISINCLUDEPROJECT_ID = 1;
	EXCEPTION
		WHEN NO_DATA_FOUND THEN
			V_EVLOTWLPOSGRPWL_ID := NULL;
	END;

	IF V_EVLOTWLPOSGRPWL_ID IS NOT NULL THEN
		/*
            BEGIN
                SELECT NVL(MAX(ORDERNO), 0)
                INTO   V_ORDERNO
                FROM   HR_EVAPPWORK
                WHERE  HR_EVAPP_ID = P_EVAPP_ID
                       AND HR_EVLOTWLPOSGRPWL_ID = V_EVLOTWLPOSGRPWL_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_ORDERNO := 0;
            END;
        */
		FOR ITEM IN (SELECT *
					 FROM   VW_HR_EVPROJECTMEMBER
					 WHERE  HR_EVLOTAPP_ID = V_EVLOTAPP_ID
							AND ISACTIVE_ID = 1
							AND HR_STAFF_ID = V_STAFF_ID
					 ORDER  BY ID)
		LOOP
			--V_ORDERNO := V_ORDERNO + 1;
		
			MERGE INTO HR_EVAPPWORK T
			USING (SELECT P_EVAPP_ID AS HR_EVAPP_ID,
						  ITEM.ID AS HR_EVPROJECTMEMBER_ID
				   FROM   DUAL) S
			ON (T.HR_EVAPP_ID = S.HR_EVAPP_ID AND T.HR_EVPROJECTMEMBER_ID = S.HR_EVPROJECTMEMBER_ID)
			
			WHEN MATCHED THEN
				UPDATE
				SET    T.HR_EVLOTWLPOSGRPWL_ID = V_EVLOTWLPOSGRPWL_ID,
					   T.DESCRIPTION = ITEM.PROJECTNAME || CASE
										   WHEN ITEM.PRJPOSITIONNAME IS NOT NULL THEN
											' [' || ITEM.PRJPOSITIONNAME || ']'
									   END,
					   T.SCORE = ITEM.SCORE,
					   T.UPDATEBY = P_CREATEBY
				
				
				
				
			
			WHEN NOT MATCHED THEN
				INSERT
					(HR_EVAPP_ID,
					 HR_EVLOTWLPOSGRPWL_ID,
					 HR_EVPROJECTMEMBER_ID,
					 ORDERNO,
					 DESCRIPTION,
					 TOTALWORK,
					 SCORE,
					 HEADERSTATUS_ID,
					 CREATEBY)
				VALUES
					(P_EVAPP_ID,
					 V_EVLOTWLPOSGRPWL_ID,
					 ITEM.ID,
					 (SELECT NVL(MAX(W.ORDERNO), 0) + 1
					  FROM   HR_EVAPPWORK W
					  WHERE  W.HR_EVAPP_ID = P_EVAPP_ID
							 AND W.HR_EVLOTWLPOSGRPWL_ID = V_EVLOTWLPOSGRPWL_ID),
					 
					 ITEM.PROJECTNAME || CASE
						 WHEN ITEM.PRJPOSITIONNAME IS NOT NULL THEN
						  ' [' || ITEM.PRJPOSITIONNAME || ']'
					 END,
					 
					 1,
					 ITEM.SCORE,
					 10,
					 P_CREATEBY);
		
		/*
                                                                                                        BEGIN
                                                                                                            SELECT ID
                                                                                                            INTO   V_EVAPPWORK_ID
                                                                                                            FROM   HR_EVAPPWORK
                                                                                                            WHERE  HR_EVAPP_ID = P_EVAPP_ID
                                                                                                                   AND HR_EVPROJECTMEMBER_ID = ITEM.ID;
                                                                                                        EXCEPTION
                                                                                                            WHEN NO_DATA_FOUND THEN
                                                                                                                V_EVAPPWORK_ID := NULL;
                                                                                                        END;
                                                                                                    
                                                                                                        IF V_EVAPPWORK_ID IS NULL THEN
                                                                                                            V_ORDERNO := V_ORDERNO + 1;
                                                                                                            INSERT INTO HR_EVAPPWORK
                                                                                                                (HR_EVAPP_ID,
                                                                                                                 HR_EVLOTWLPOSGRPWL_ID,
                                                                                                                 HR_EVPROJECTMEMBER_ID,
                                                                                                                 ORDERNO,
                                                                                                                 DESCRIPTION,
                                                                                                                 TOTALWORK,
                                                                                                                 SCORE,
                                                                                                                 HEADERSTATUS_ID,
                                                                                                                 CREATEBY)
                                                                                                            VALUES
                                                                                                                (P_EVAPP_ID,
                                                                                                                 V_EVLOTWLPOSGRPWL_ID,
                                                                                                                 ITEM.ID,
                                                                                                                 V_ORDERNO,
                                                                                                                 ITEM.PROJECTNAME || CASE WHEN ITEM.PRJPOSITIONNAME IS NOT NULL THEN ' [' || ITEM.PRJPOSITIONNAME || ']' END,
                                                                                                                 1,
                                                                                                                 ITEM.SCORE,
                                                                                                                 10,
                                                                                                                 P_CREATEBY);
                                                                                                        ELSE
                                                                                                            UPDATE HR_EVAPPWORK
                                                                                                            SET    HR_EVLOTWLPOSGRPWL_ID = V_EVLOTWLPOSGRPWL_ID,
                                                                                                                   DESCRIPTION = ITEM.PROJECTNAME || CASE
                                                                                                                                     WHEN ITEM.PRJPOSITIONNAME IS NOT NULL THEN
                                                                                                                                      ' [' || ITEM.PRJPOSITIONNAME || ']'
                                                                                                                                 END,
                                                                                                                   SCORE = ITEM.SCORE,
                                                                                                                   UPDATEBY = P_CREATEBY
                                                                                                            WHERE  ID = V_EVAPPWORK_ID;
                                                                                                        END IF;
                                                                                                    */
		END LOOP;
	
	END IF;
	--COMMIT;

	--PD_HR_EVAPP_SCORE_CON(P_EVAPP_ID, 0, P_CREATEBY);
	--COMMIT;

END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPPWORK_IMPTOTALCOURSE
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPPWORK_IMPTOTALCOURSE" AS
BEGIN
	SELECT A.HR_EVLOTWL_ID,
		   B.HR_EVPOSITION_ID,
		   B.HEADERSTATUS_ID,
		   B.TOTALCOURSE
	INTO   V_EVLOTWL_ID,
		   V_EVPOSITION_ID,
		   V_HEADERSTATUS_ID,
		   V_TOTALCOURSE
	FROM   HR_EVLOTAPP A
	INNER  JOIN HR_EVAPP B ON A.ID = B.HR_EVLOTAPP_ID
	WHERE  B.ID = P_EVAPP_ID;

	IF V_HEADERSTATUS_ID <= 11 THEN
		BEGIN
			SELECT MIN(C.ID)
			INTO   V_EVLOTWLPOSGRPWL_ID
			FROM   HR_EVLOTWLPOS A
			INNER  JOIN HR_EVLOTWLPOSGRP B ON A.ID = B.HR_EVLOTWLPOS_ID
			INNER  JOIN HR_EVLOTWLPOSGRPWL C ON B.ID = C.HR_EVLOTWLPOSGRP_ID
			LEFT   JOIN VW_HR_EVLOTWLPOSGRPMAIN M ON C.HR_EVLOTWLPOSGRPMAIN_ID = M.ID
			WHERE  A.HR_EVLOTWL_ID = V_EVLOTWL_ID
				   AND A.HR_EVPOSITION_ID = V_EVPOSITION_ID
				   AND C.SCORETYPE_ID = 5;
		EXCEPTION
			WHEN OTHERS THEN
				V_EVLOTWLPOSGRPWL_ID := NULL;
		END;
		IF V_EVLOTWLPOSGRPWL_ID IS NOT NULL THEN
		
			SELECT A.EACHSCORE INTO V_EACHSCORE FROM HR_EVLOTWLPOSGRPWL A WHERE A.ID = V_EVLOTWLPOSGRPWL_ID;
		
			BEGIN
				SELECT ID
				INTO   V_EVAPPWORK_ID
				FROM   HR_EVAPPWORK
				WHERE  HR_EVAPP_ID = P_EVAPP_ID
					   AND HR_EVLOTWLPOSGRPWL_ID = V_EVLOTWLPOSGRPWL_ID;
			EXCEPTION
				WHEN OTHERS THEN
					V_EVAPPWORK_ID := NULL;
			END;
		
			IF V_EVAPPWORK_ID IS NULL THEN
				V_ORDERNO := V_ORDERNO + 1;
				INSERT INTO HR_EVAPPWORK
					(HR_EVAPP_ID,
					 HR_EVLOTWLPOSGRPWL_ID,
					 ORDERNO,
					 DESCRIPTION,
					 TOTALWORK,
					 SCORE,
					 HEADERSTATUS_ID,
					 CREATEBY)
				VALUES
					(P_EVAPP_ID,
					 V_EVLOTWLPOSGRPWL_ID,
					 V_ORDERNO,
					 '-',
					 V_TOTALCOURSE,
					 V_TOTALCOURSE * V_EACHSCORE,
					 10,
					 P_CREATEBY);
			ELSE
				UPDATE HR_EVAPPWORK
				SET    HR_EVLOTWLPOSGRPWL_ID = V_EVLOTWLPOSGRPWL_ID,
					   DESCRIPTION = '-',
					   TOTALWORK = V_TOTALCOURSE,
					   SCORE = V_TOTALCOURSE * V_EACHSCORE,
					   UPDATEBY = P_CREATEBY
				WHERE  ID = V_EVAPPWORK_ID;
			END IF;
		
		
		END IF;
	
		COMMIT;
		PD_HR_EVAPP_SCORE(P_EVAPP_ID, P_CREATEBY);
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_CLEAR
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_CLEAR" AS
BEGIN
	INSERT INTO SS_PARAMETER_CH
		(PARAMETERNAME,
		 VALUENUMBER)
	VALUES
		('SS_CLEARDATA',
		 1);
	UPDATE HR_EVAPP SET APPSTATUS_ID = 10;
	DELETE FROM HR_EVAPP;
	UPDATE HR_EVPROJECTMEMBER SET ISSUBMITAPP_ID = 0 WHERE ISSUBMITAPP_ID = 1;
	UPDATE HR_EVCOMMANDMEMBER SET ISSUBMITAPP_ID = 0 WHERE ISSUBMITAPP_ID = 1;
	DELETE FROM SS_PARAMETER_CH WHERE PARAMETERNAME = 'SS_CLEARDATA';
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_DEL
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_DEL" AS
BEGIN
	DELETE FROM HR_EVAPP A
	WHERE HR_EVLOTAPP_ID = P_EVLOTAPP_ID
		  AND HR_EVPOSITION_ID = P_EVPOSITION_ID
		  AND MT_DEPARTMENT_ID IN (SELECT ID
								   FROM VW_MT_DEPARTMENT
								   WHERE DEPARTMENTCODE >= P_DEPARTMENTFROM_CODE
										 AND DEPARTMENTCODE <= P_DEPARTMENTTO_CODE)
		  AND HR_STAFF_ID IN (SELECT ID
							  FROM VW_HR_STAFF
							  WHERE STAFFSTATUS_ID >= P_STAFFSTATUSFROM_ID
									AND STAFFSTATUS_ID <= P_STAFFSTATUSTO_ID);
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_DELPOS
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_DELPOS" AS
BEGIN
	FOR ITEM IN (SELECT A.ID
				 FROM HR_EVPOSITION A
				 WHERE A.EVPOSITIONCODE >= P_EVPOSITIONFROM_CODE
					   AND A.EVPOSITIONCODE <= P_EVPOSITIONTO_CODE)
	LOOP
		PD_HR_EVAPP_DEL(P_EVLOTAPP_ID, ITEM.ID, P_DEPARTMENTFROM_CODE, P_DEPARTMENTTO_CODE, P_STAFFSTATUSFROM_ID, P_STAFFSTATUSTO_ID);
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_HEADERSTATUS
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_HEADERSTATUS" AS
BEGIN
	IF P_HEADERSTATUS_ID = 11 THEN
		UPDATE HR_EVAPP
		SET    APPSTATUS_ID = 10,
			   HEADERSTATUS_ID = P_HEADERSTATUS_ID,
			   UPDATEBY = P_UPDATEBY,
			   UPDATEDATETIME = SYSDATE
		WHERE  ID = P_EVAPP_ID;

	ELSIF P_HEADERSTATUS_ID = 30 THEN
		UPDATE HR_EVAPP
		SET    HEADERSTATUS_ID = P_HEADERSTATUS_ID,
			   UPDATEBY = P_UPDATEBY,
			   UPDATEDATETIME = SYSDATE
		WHERE  ID = P_EVAPP_ID;

	ELSIF P_HEADERSTATUS_ID = 50 THEN
		--V_SCOREAPPROVE := 0;
		/*      FOR ITEM IN (SELECT * FROM VW_HR_EVAPPWORK_SUMGROUP WHERE HR_EVAPP_ID=P_EVAPP_ID)
                LOOP
                    V_SCOREAPPROVE := V_SCOREAPPROVE + ITEM.SUM_WORKGROUPSCOREVERIFY;
                END LOOP;
        */
		UPDATE HR_EVAPP
		SET    HEADERSTATUS_ID = P_HEADERSTATUS_ID,
			   HEADERFINISHDATE = SYSDATE,
			   --SCOREAPPROVE=V_SCOREAPPROVE,
			   UPDATEBY = P_UPDATEBY,
			   UPDATEDATETIME = SYSDATE
		WHERE  ID = P_EVAPP_ID;

		PD_HR_EVAPP_SCORE(P_EVAPP_ID, P_UPDATEBY);

		SELECT D.ID,
			   A.HR_EVLOTAPP_ID,
			   B.POSITIONTYPE_ID,
			   A.HR_STAFFTYPE_ID
		INTO   V_DEPARTMENT_ID,
			   V_EVLOTAPP_ID,
			   V_POSITIONTYPE_ID,
			   V_STAFFTYPE_ID
		FROM   HR_EVAPP A
		INNER  JOIN VW_HR_EVPOSITION B ON A.HR_EVPOSITION_ID = B.ID
		INNER  JOIN VW_MT_DEPARTMENT C ON A.MT_DEPARTMENT_ID = C.ID
		INNER  JOIN VW_MT_DEPARTMENT D ON C.DEPARTMENTCODE1 = D.DEPARTMENTCODE
		WHERE  A.ID = P_EVAPP_ID;

		UPDATE HR_EVAPP
		SET    ORDERSCORE = NULL
		WHERE  ID IN (SELECT A.ID
					  FROM   HR_EVAPP A
					  INNER  JOIN VW_HR_EVPOSITION B ON A.HR_EVPOSITION_ID = B.ID
					  INNER  JOIN VW_MT_DEPARTMENT C ON A.MT_DEPARTMENT_ID = C.ID
					  INNER  JOIN VW_MT_DEPARTMENT D ON C.DEPARTMENTCODE1 = D.DEPARTMENTCODE
					  WHERE  D.ID = V_DEPARTMENT_ID
							 AND A.HR_EVLOTAPP_ID = V_EVLOTAPP_ID
							 AND A.HR_STAFFTYPE_ID = V_STAFFTYPE_ID
							 AND D.ID = V_POSITIONTYPE_ID);

		V_ORDERSCORE := 1;
		FOR ITEM IN (SELECT A.SCOREAPPROVE
					 FROM   HR_EVAPP A
					 INNER  JOIN VW_HR_EVPOSITION B ON A.HR_EVPOSITION_ID = B.ID
					 INNER  JOIN VW_MT_DEPARTMENT C ON A.MT_DEPARTMENT_ID = C.ID
					 INNER  JOIN VW_MT_DEPARTMENT D ON C.DEPARTMENTCODE1 = D.DEPARTMENTCODE
					 WHERE  D.ID = V_DEPARTMENT_ID
							AND A.HR_EVLOTAPP_ID = V_EVLOTAPP_ID
							AND A.HR_STAFFTYPE_ID = V_STAFFTYPE_ID
							AND B.POSITIONTYPE_ID = V_POSITIONTYPE_ID
							AND A.APPSTATUS_ID = 50
					 GROUP  BY SCOREAPPROVE
					 ORDER  BY SCOREAPPROVE DESC)
		LOOP
			UPDATE HR_EVAPP
			SET    ORDERSCORE = V_ORDERSCORE
			WHERE  ID IN (SELECT A.ID
						  FROM   HR_EVAPP A
						  INNER  JOIN VW_HR_EVPOSITION B ON A.HR_EVPOSITION_ID = B.ID
						  INNER  JOIN VW_MT_DEPARTMENT C ON A.MT_DEPARTMENT_ID = C.ID
						  INNER  JOIN VW_MT_DEPARTMENT D ON C.DEPARTMENTCODE1 = D.DEPARTMENTCODE
						  WHERE  D.ID = V_DEPARTMENT_ID
								 AND A.HR_EVLOTAPP_ID = V_EVLOTAPP_ID
								 AND A.HR_STAFFTYPE_ID = V_STAFFTYPE_ID
								 AND B.POSITIONTYPE_ID = V_POSITIONTYPE_ID
								 AND A.APPSTATUS_ID = 50
								 AND A.SCOREAPPROVE = ITEM.SCOREAPPROVE);
			V_ORDERSCORE := V_ORDERSCORE + 1;
		END LOOP;

	ELSIF P_HEADERSTATUS_ID = 60 THEN
		UPDATE HR_EVAPP
		SET    HEADERSTATUS_ID = P_HEADERSTATUS_ID,
			   SELFFINISHDATE = SYSDATE,
			   UPDATEBY = P_UPDATEBY,
			   UPDATEDATETIME = SYSDATE
		WHERE  ID = P_EVAPP_ID;

	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_IMP
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_IMP" AS
BEGIN
	FOR ITEM IN (SELECT P_EVLOTAPP_ID,
						A.ID,
						A.MT_DEPARTMENT_ID,
						A.HR_POSITION_ID,
						A.HR_POSITIONEX_ID,
						A.HR_EVPOSITION_ID,
						10,
						NVL(A.MASTER_ID, A.MASTERDEFAULT_ID) AS HR_STAFFHEADER_ID,
						P_CREATEBY,
						SYSDATE
				 FROM VW_HR_STAFFEV A
				 WHERE A.STAFFSTATUS_ID >= P_STAFFSTATUSFROM_ID
					   AND A.STAFFSTATUS_ID <= P_STAFFSTATUSTO_ID
					   AND A.HR_EVPOSITION_ID = P_EVPOSITION_ID
					   AND A.DEPARTMENTCODE >= P_DEPARTMENTFROM_CODE
					   AND A.DEPARTMENTCODE <= P_DEPARTMENTTO_CODE)
	LOOP
		BEGIN
			SELECT ID,
				   APPSTATUS_ID
			INTO V_EVAPP_ID,
				 V_APPSTATUS_ID
			FROM HR_EVAPP
			WHERE HR_STAFF_ID = ITEM.ID
				  AND HR_EVLOTAPP_ID = P_EVLOTAPP_ID;
		EXCEPTION
			WHEN OTHERS THEN
				V_EVAPP_ID := NULL;
		END;
	
		IF V_EVAPP_ID IS NULL THEN
			INSERT INTO HR_EVAPP
				(HR_EVLOTAPP_ID,
				 HR_STAFF_ID,
				 MT_DEPARTMENT_ID,
				 HR_POSITION_ID,
				 HR_POSITIONEX_ID,
				 HR_EVPOSITION_ID,
				 APPSTATUS_ID,
				 HR_STAFFHEADER_ID,
				 CREATEBY,
				 CREATEDATETIME)
			VALUES
				(P_EVLOTAPP_ID,
				 ITEM.ID,
				 ITEM.MT_DEPARTMENT_ID,
				 ITEM.HR_POSITION_ID,
				 ITEM.HR_POSITIONEX_ID,
				 ITEM.HR_EVPOSITION_ID,
				 10,
				 ITEM.HR_STAFFHEADER_ID,
				 P_CREATEBY,
				 SYSDATE);
		ELSIF V_APPSTATUS_ID = 10 THEN
			UPDATE HR_EVAPP
			SET MT_DEPARTMENT_ID = ITEM.MT_DEPARTMENT_ID,
				HR_POSITION_ID = ITEM.HR_POSITION_ID,
				HR_POSITIONEX_ID = ITEM.HR_POSITIONEX_ID,
				HR_EVPOSITION_ID = ITEM.HR_EVPOSITION_ID,
				HR_STAFFHEADER_ID = ITEM.HR_STAFFHEADER_ID
			WHERE ID = V_EVAPP_ID;
		END IF;
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_IMPPOS
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_IMPPOS" AS
BEGIN
	FOR ITEM IN (SELECT A.ID
				 FROM   HR_EVPOSITION A
				 WHERE  A.ISACTIVE_ID = 1
						AND A.EVPOSITIONCODE >= P_EVPOSITIONFROM_CODE
						AND A.EVPOSITIONCODE <= P_EVPOSITIONTO_CODE)
	LOOP
		PD_HR_EVAPP_IMP(P_EVLOTAPP_ID, ITEM.ID, P_DEPARTMENTFROM_CODE, P_DEPARTMENTTO_CODE, P_STAFFSTATUSFROM_ID, P_STAFFSTATUSTO_ID, P_CREATEBY);
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_SCORE
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_SCORE" AS
BEGIN
	SELECT A.APPSTATUS_ID,
		   A.HR_EVLOTAPP_ID,
		   A.HR_STAFF_ID,
		   A.HR_EVPOSITION_ID,
		   A.RATIOBEHAVIOR
	INTO   V_APPSTATUS_ID,
		   V_EVLOTAPP_ID,
		   V_STAFF_ID,
		   V_EVPOSITION_ID,
		   V_RATIOBEHAVIOR
	FROM   HR_EVAPP A
	WHERE  A.ID = P_EVAPP_ID;

	PD_HR_EVAPP_SCORE_CON(P_EVAPP_ID, 1, V_APPSTATUS_ID, V_EVLOTAPP_ID, V_STAFF_ID, V_EVPOSITION_ID, V_RATIOBEHAVIOR, P_EXECUTEBY);
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_SCORE_BAK
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_SCORE_BAK" AS
BEGIN
	SELECT ID INTO V_DUMMY_ID FROM HR_EVAPP WHERE ID = P_EVAPP_ID FOR UPDATE;

	SELECT A.APPSTATUS_ID,
		   A.HR_EVLOTAPP_ID,
		   A.HR_STAFF_ID,
		   A.HR_EVPOSITION_ID,
		   A.RATIOBEHAVIOR
	INTO   V_APPSTATUS_ID,
		   V_EVLOTAPP_ID,
		   V_STAFF_ID,
		   V_EVPOSITION_ID,
		   V_RATIOBEHAVIOR
	FROM   HR_EVAPP A
	WHERE  A.ID = P_EVAPP_ID;

	SELECT * INTO R_HR_EVLOTAPP FROM HR_EVLOTAPP WHERE ID = V_EVLOTAPP_ID;

	SELECT CONFIGVALUE INTO V_SCOREMODE FROM SS_CONFIG WHERE CONFIGCODE = 'HR_EV.MAXSCORE.MODE';

	IF V_APPSTATUS_ID IN (10, 11, 30, 50) THEN
		UPDATE HR_EVAPPWORK W
		SET    W.SCORETEMP = W.SCORE,
			   W.SCORE = CASE
							 WHEN W.HR_EVPROJECTMEMBER_ID IS NOT NULL AND NOT EXISTS (SELECT 1
								   FROM   HR_EVPROJECTMEMBER A
								   JOIN   HR_EVPROJECT B ON B.ID = A.HR_EVPROJECT_ID
								   WHERE  A.ID = W.HR_EVPROJECTMEMBER_ID
										  AND A.ISACTIVE_ID = 1
										  AND B.PROJECTSTATUS_ID = 60) THEN
							  0
						 
							 WHEN W.HR_EVCOMMANDMEMBER_ID IS NOT NULL AND NOT EXISTS (SELECT 1
								   FROM   HR_EVCOMMANDMEMBER A
								   JOIN   HR_EVCOMMAND B ON B.ID = A.HR_EVCOMMAND_ID
								   WHERE  A.ID = W.HR_EVCOMMANDMEMBER_ID
										  AND A.ISACTIVE_ID = 1
										  AND B.COMMANDSTATUS_ID = 60) THEN
							  0
						 
							 ELSE
							  W.SCORE
						 END
		WHERE  W.HR_EVAPP_ID = P_EVAPP_ID
			   AND (W.HR_EVPROJECTMEMBER_ID IS NOT NULL OR W.HR_EVCOMMANDMEMBER_ID IS NOT NULL);
		/*      
                UPDATE HR_EVAPPWORK
                SET    SCORETEMP = SCORE
                WHERE  (HR_EVPROJECTMEMBER_ID IS NOT NULL OR HR_EVCOMMANDMEMBER_ID IS NOT NULL)
                       AND HR_EVAPP_ID = P_EVAPP_ID;
            
                UPDATE HR_EVAPPWORK
                SET    SCORE = 0
                WHERE  HR_EVPROJECTMEMBER_ID IS NOT NULL
                       AND HR_EVAPP_ID = P_EVAPP_ID
                       AND HR_EVPROJECTMEMBER_ID NOT IN (SELECT A.ID
                                                         FROM   HR_EVPROJECTMEMBER A
                                                         INNER  JOIN HR_EVPROJECT B ON A.HR_EVPROJECT_ID = B.ID
                                                         WHERE  A.ISACTIVE_ID = 1
                                                                AND B.PROJECTSTATUS_ID = 60);
            
                UPDATE HR_EVAPPWORK
                SET    SCORE = 0
                WHERE  HR_EVCOMMANDMEMBER_ID IS NOT NULL
                       AND HR_EVAPP_ID = P_EVAPP_ID
                       AND HR_EVCOMMANDMEMBER_ID NOT IN (SELECT A.ID
                                                         FROM   HR_EVCOMMANDMEMBER A
                                                         INNER  JOIN HR_EVCOMMAND B ON A.HR_EVCOMMAND_ID = B.ID
                                                         WHERE  A.ISACTIVE_ID = 1
                                                                AND B.COMMANDSTATUS_ID = 60);
        */
	
		/*      SELECT NVL(SUM(SUM_TOTALSCORE), 0),
               NVL(SUM(SUM_SCOREINPUT), 0)
        INTO   V_SCOREINPUT,
               V_SCOREGROUP
        FROM   VW_HR_EVAPPWORK_SUMGROUP
        WHERE  HR_EVAPP_ID = P_EVAPP_ID;*/
	
		-- คำนวณคะแนนที่บันทึกและคะแนนที่ได้ตามกลุ่ม
		BEGIN
			SELECT WG.SCORE_MAIN + WG.SCORE_WORK + WG.SCORE_PROJECT,
				   CASE
					   WHEN NVL(LG.MAXSCORE_MAIN, 0) < WG.SCORE_MAIN THEN
						NVL(LG.MAXSCORE_MAIN, 0)
					   ELSE
						WG.SCORE_MAIN
				   END + CASE
					   WHEN NVL(LG.MAXSCORE_WORK, 0) < WG.SCORE_WORK THEN
						NVL(LG.MAXSCORE_WORK, 0)
					   ELSE
						WG.SCORE_WORK
				   END + CASE
					   WHEN NVL(LG.MAXSCORE_PROJECT, 0) < WG.SCORE_PROJECT THEN
						NVL(LG.MAXSCORE_PROJECT, 0)
					   ELSE
						WG.SCORE_PROJECT
				   END
			INTO   V_SCOREINPUT,
				   V_SCOREGROUP
			FROM   VW_HR_EVLOTAPPGROUP_SCORE LG,
				   VW_HR_EVAPPGROUP_SCORE WG
			WHERE  LG.HR_EVLOTAPP_ID = V_EVLOTAPP_ID
				   AND WG.HR_EVAPP_ID = P_EVAPP_ID;
		EXCEPTION
			WHEN NO_DATA_FOUND THEN
				V_SCOREINPUT := 0;
				V_SCOREGROUP := 0;
		END;
	
		SELECT NVL(SUM(SCOREAPPROVE), 0),
			   COUNT(ID)
		INTO   V_CHILDSCORE,
			   V_CHILDCOUNT
		FROM   HR_EVAPP_MU A
		WHERE  A.HR_STAFFHEADER_ID IS NOT NULL
			   AND HR_EVLOTAPP_ID = V_EVLOTAPP_ID
			   AND A.HR_STAFFHEADER_ID = V_STAFF_ID;
	
		IF V_CHILDCOUNT > 0 THEN
			V_SCOREUNDER := ROUND((V_CHILDSCORE / V_CHILDCOUNT) * R_HR_EVLOTAPP.RATIOFORHEADER / 100, 2);
		END IF;
	
		SELECT A.SUM_MAXSCORE,
			   A.NOLIMIT_ID
		INTO   V_MAXSCORE,
			   V_NOLIMIT_ID
		FROM   VW_HR_EVLOTWLPOS A
		WHERE  A.HR_EVLOTWL_ID = R_HR_EVLOTAPP.HR_EVLOTWL_ID
			   AND A.HR_EVPOSITION_ID = V_EVPOSITION_ID;
	
		--V_SCOREMODE 1: จากคะแนนเต็มของภาระงาน, 2: จากรอบการประเมิน
		IF V_SCOREMODE = '2' THEN
			V_MAXSCORE := R_HR_EVLOTAPP.TOTALSCORE;
			/*IF V_NOLIMIT_ID = 1 OR V_MAXSCORE = 0 THEN
                -- ไม่มีการกำหนดเพดานคะแนน
                V_MAXSCORE := R_HR_EVLOTAPP.TOTALSCORE;
            
                IF V_SCOREAPPROVE > V_MAXSCORE THEN
                    V_SCOREAPPROVE := V_MAXSCORE;
                END IF;
            ELSE
                V_SCOREAPPROVE := R_HR_EVLOTAPP.TOTALSCORE * V_SCOREAPPROVE / V_MAXSCORE;
                V_MAXSCORE := R_HR_EVLOTAPP.TOTALSCORE;
            END IF;*/
		END IF;
	
		V_SCOREAPPROVE := V_SCOREGROUP + V_SCOREUNDER;
	
		IF V_SCOREAPPROVE > V_MAXSCORE THEN
			V_SCOREAPPROVE := V_MAXSCORE;
		END IF;
	
		--DBMS_OUTPUT.PUT_LINE(V_SCOREAPPROVE);
		V_RATIOACHIEVEMENT := ROUND(V_SCOREAPPROVE * R_HR_EVLOTAPP.RATIOACHIEVEMENT / V_MAXSCORE, 2);
		V_RATIOSCORE := V_RATIOACHIEVEMENT + V_RATIOBEHAVIOR;
		BEGIN
			SELECT MIN(ID)
			INTO   V_EVLOTSCOREITEM_ID
			FROM   HR_EVLOTSCOREITEM
			WHERE  HR_EVLOTSCORE_ID = R_HR_EVLOTAPP.HR_EVLOTSCORE_ID
				   AND MINSCORE <= V_RATIOSCORE
				   AND V_RATIOSCORE <= MAXSCORE;
		EXCEPTION
			WHEN NO_DATA_FOUND THEN
				V_EVLOTSCOREITEM_ID := NULL;
		END;
		UPDATE HR_EVAPP
		SET    TOTALACHIEVEMENT = ROUND(100 * V_SCOREAPPROVE / V_MAXSCORE, 2),
			   TOTALBEHAVIOR = ROUND(V_RATIOBEHAVIOR * 100 / R_HR_EVLOTAPP.RATIOBEHAVIOR, 2),
			   SCOREAPPROVE = V_SCOREAPPROVE,
			   RATIOACHIEVEMENT = V_RATIOACHIEVEMENT,
			   RATIOSCORE = V_RATIOSCORE,
			   HR_EVLOTSCOREITEM_ID = V_EVLOTSCOREITEM_ID,
			   SCOREINPUT = V_SCOREINPUT,
			   SCOREGROUP = V_SCOREGROUP,
			   SCOREUNDER = V_SCOREUNDER,
			   UPDATEBY = V_EXECUTEBY
		WHERE  ID = P_EVAPP_ID;
	
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_SCORE_CON
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_SCORE_CON" AS
BEGIN

	--SELECT * INTO R_HR_EVLOTAPP FROM HR_EVLOTAPP WHERE ID = P_EVLOTAPP_ID;
	SELECT RATIOFORHEADER,
		   HR_EVLOTWL_ID,
		   TOTALSCORE,
		   RATIOACHIEVEMENT,
		   HR_EVLOTSCORE_ID,
		   RATIOBEHAVIOR
	INTO   V_LOTRATIOFORHEADER,
		   V_EVLOTWL_ID,
		   V_LOTTOTALSCORE,
		   V_LOTRATIOACHIEVEMENT,
		   V_EVLOTSCORE_ID,
		   V_LOTRATIOBEHAVIOR
	FROM   HR_EVLOTAPP
	WHERE  ID = P_EVLOTAPP_ID;

	SELECT CONFIGVALUE INTO V_SCOREMODE FROM SS_CONFIG WHERE CONFIGCODE = 'HR_EV.MAXSCORE.MODE';

	IF P_APPSTATUS_ID IN (10, 11, 20, 30, 50) THEN
		IF P_UPDATEWORK_ID = 1 THEN
			UPDATE HR_EVAPPWORK W
			SET    W.SCORETEMP = W.SCORE,
				   W.SCORE = CASE
								 WHEN W.HR_EVPROJECTMEMBER_ID IS NOT NULL AND NOT EXISTS (SELECT 1
									   FROM   HR_EVPROJECTMEMBER A
									   JOIN   HR_EVPROJECT B ON B.ID = A.HR_EVPROJECT_ID
									   WHERE  A.ID = W.HR_EVPROJECTMEMBER_ID
											  AND A.ISACTIVE_ID = 1
											  AND B.PROJECTSTATUS_ID = 60) THEN
								  0
							 
								 WHEN W.HR_EVCOMMANDMEMBER_ID IS NOT NULL AND NOT EXISTS (SELECT 1
									   FROM   HR_EVCOMMANDMEMBER A
									   JOIN   HR_EVCOMMAND B ON B.ID = A.HR_EVCOMMAND_ID
									   WHERE  A.ID = W.HR_EVCOMMANDMEMBER_ID
											  AND A.ISACTIVE_ID = 1
											  AND B.COMMANDSTATUS_ID = 60) THEN
								  0
							 
								 ELSE
								  W.SCORE
							 END
			WHERE  W.HR_EVAPP_ID = P_EVAPP_ID
				   AND (W.HR_EVPROJECTMEMBER_ID IS NOT NULL OR W.HR_EVCOMMANDMEMBER_ID IS NOT NULL);
		END IF;
		/*      
                UPDATE HR_EVAPPWORK
                SET    SCORETEMP = SCORE
                WHERE  (HR_EVPROJECTMEMBER_ID IS NOT NULL OR HR_EVCOMMANDMEMBER_ID IS NOT NULL)
                       AND HR_EVAPP_ID = P_EVAPP_ID;
            
                UPDATE HR_EVAPPWORK
                SET    SCORE = 0
                WHERE  HR_EVPROJECTMEMBER_ID IS NOT NULL
                       AND HR_EVAPP_ID = P_EVAPP_ID
                       AND HR_EVPROJECTMEMBER_ID NOT IN (SELECT A.ID
                                                         FROM   HR_EVPROJECTMEMBER A
                                                         INNER  JOIN HR_EVPROJECT B ON A.HR_EVPROJECT_ID = B.ID
                                                         WHERE  A.ISACTIVE_ID = 1
                                                                AND B.PROJECTSTATUS_ID = 60);
            
                UPDATE HR_EVAPPWORK
                SET    SCORE = 0
                WHERE  HR_EVCOMMANDMEMBER_ID IS NOT NULL
                       AND HR_EVAPP_ID = P_EVAPP_ID
                       AND HR_EVCOMMANDMEMBER_ID NOT IN (SELECT A.ID
                                                         FROM   HR_EVCOMMANDMEMBER A
                                                         INNER  JOIN HR_EVCOMMAND B ON A.HR_EVCOMMAND_ID = B.ID
                                                         WHERE  A.ISACTIVE_ID = 1
                                                                AND B.COMMANDSTATUS_ID = 60);
        */
	
		/*      SELECT NVL(SUM(SUM_TOTALSCORE), 0),
               NVL(SUM(SUM_SCOREINPUT), 0)
        INTO   V_SCOREINPUT,
               V_SCOREGROUP
        FROM   VW_HR_EVAPPWORK_SUMGROUP
        WHERE  HR_EVAPP_ID = P_EVAPP_ID;*/
	
		-- คำนวณคะแนนที่บันทึกและคะแนนที่ได้ตามกลุ่ม
		BEGIN
			SELECT WG.SCORE_MAIN + WG.SCORE_WORK + WG.SCORE_PROJECT,
				   CASE
					   WHEN NVL(LG.MAXSCORE_MAIN, 0) < WG.SCORE_MAIN THEN
						NVL(LG.MAXSCORE_MAIN, 0)
					   ELSE
						WG.SCORE_MAIN
				   END + CASE
					   WHEN NVL(LG.MAXSCORE_WORK, 0) < WG.SCORE_WORK THEN
						NVL(LG.MAXSCORE_WORK, 0)
					   ELSE
						WG.SCORE_WORK
				   END + CASE
					   WHEN NVL(LG.MAXSCORE_PROJECT, 0) < WG.SCORE_PROJECT THEN
						NVL(LG.MAXSCORE_PROJECT, 0)
					   ELSE
						WG.SCORE_PROJECT
				   END
			INTO   V_SCOREINPUT,
				   V_SCOREGROUP
			FROM   VW_HR_EVLOTAPPGROUP_SCORE LG,
				   VW_HR_EVAPPGROUP_SCORE WG
			WHERE  LG.HR_EVLOTAPP_ID = P_EVLOTAPP_ID
				   AND WG.HR_EVAPP_ID = P_EVAPP_ID;
		EXCEPTION
			WHEN NO_DATA_FOUND THEN
				V_SCOREINPUT := 0;
				V_SCOREGROUP := 0;
		END;
	
		SELECT NVL(SUM(SCOREAPPROVE), 0),
			   COUNT(ID)
		INTO   V_CHILDSCORE,
			   V_CHILDCOUNT
		FROM   HR_EVAPP A
		WHERE  A.HR_STAFFHEADER_ID IS NOT NULL
			   AND HR_EVLOTAPP_ID = P_EVLOTAPP_ID
			   AND A.HR_STAFFHEADER_ID = P_STAFF_ID
			   AND A.ID <> P_EVAPP_ID;
	
		IF V_CHILDCOUNT > 0 THEN
			V_SCOREUNDER := ROUND((V_CHILDSCORE / V_CHILDCOUNT) * V_LOTRATIOFORHEADER / 100, 2);
		END IF;
	
		SELECT A.SUM_MAXSCORE,
			   A.NOLIMIT_ID
		INTO   V_MAXSCORE,
			   V_NOLIMIT_ID
		FROM   VW_HR_EVLOTWLPOS A
		WHERE  A.HR_EVLOTWL_ID = V_EVLOTWL_ID
			   AND A.HR_EVPOSITION_ID = P_EVPOSITION_ID;
	
		--V_SCOREMODE 1: จากคะแนนเต็มของภาระงาน, 2: จากรอบการประเมิน
		IF V_SCOREMODE = '2' THEN
			V_MAXSCORE := V_LOTTOTALSCORE;
			/*IF V_NOLIMIT_ID = 1 OR V_MAXSCORE = 0 THEN
                -- ไม่มีการกำหนดเพดานคะแนน
                V_MAXSCORE := R_HR_EVLOTAPP.TOTALSCORE;
            
                IF V_SCOREAPPROVE > V_MAXSCORE THEN
                    V_SCOREAPPROVE := V_MAXSCORE;
                END IF;
            ELSE
                V_SCOREAPPROVE := R_HR_EVLOTAPP.TOTALSCORE * V_SCOREAPPROVE / V_MAXSCORE;
                V_MAXSCORE := R_HR_EVLOTAPP.TOTALSCORE;
            END IF;*/
		END IF;
	
		V_SCOREAPPROVE := V_SCOREGROUP + V_SCOREUNDER;
	
		IF V_SCOREAPPROVE > V_MAXSCORE THEN
			V_SCOREAPPROVE := V_MAXSCORE;
		END IF;
	
		--DBMS_OUTPUT.PUT_LINE(V_SCOREAPPROVE);
		V_RATIOACHIEVEMENT := ROUND(V_SCOREAPPROVE * V_LOTRATIOACHIEVEMENT / V_MAXSCORE, 2);
		V_RATIOSCORE := V_RATIOACHIEVEMENT + P_RATIOBEHAVIOR;
		BEGIN
			SELECT MIN(ID)
			INTO   V_EVLOTSCOREITEM_ID
			FROM   HR_EVLOTSCOREITEM
			WHERE  HR_EVLOTSCORE_ID = V_EVLOTSCORE_ID
				   AND MINSCORE <= V_RATIOSCORE
				   AND V_RATIOSCORE <= MAXSCORE;
		EXCEPTION
			WHEN NO_DATA_FOUND THEN
				V_EVLOTSCOREITEM_ID := NULL;
		END;
	
		UPDATE HR_EVAPP
		SET    TOTALACHIEVEMENT = ROUND(100 * V_SCOREAPPROVE / V_MAXSCORE, 2),
			   TOTALBEHAVIOR = ROUND(P_RATIOBEHAVIOR * 100 / V_LOTRATIOBEHAVIOR, 2),
			   SCOREAPPROVE = V_SCOREAPPROVE,
			   RATIOACHIEVEMENT = V_RATIOACHIEVEMENT,
			   RATIOSCORE = V_RATIOSCORE,
			   HR_EVLOTSCOREITEM_ID = V_EVLOTSCOREITEM_ID,
			   SCOREINPUT = V_SCOREINPUT,
			   SCOREGROUP = V_SCOREGROUP,
			   SCOREUNDER = V_SCOREUNDER,
			   UPDATEBY = V_EXECUTEBY
		WHERE  ID = P_EVAPP_ID;
	
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVAPP_SCORE_CON_T
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVAPP_SCORE_CON_T" AS
BEGIN

	--SELECT * INTO R_HR_EVLOTAPP FROM HR_EVLOTAPP WHERE ID = P_EVLOTAPP_ID;
	SELECT RATIOFORHEADER,
		   HR_EVLOTWL_ID,
		   TOTALSCORE,
		   RATIOACHIEVEMENT,
		   HR_EVLOTSCORE_ID,
		   RATIOBEHAVIOR
	INTO   V_LOTRATIOFORHEADER,
		   V_EVLOTWL_ID,
		   V_LOTTOTALSCORE,
		   V_LOTRATIOACHIEVEMENT,
		   V_EVLOTSCORE_ID,
		   V_LOTRATIOBEHAVIOR
	FROM   HR_EVLOTAPP
	WHERE  ID = P_EVLOTAPP_ID;

	SELECT CONFIGVALUE INTO V_SCOREMODE FROM SS_CONFIG WHERE CONFIGCODE = 'HR_EV.MAXSCORE.MODE';

	IF P_APPSTATUS_ID IN (10, 11, 20, 30, 50) THEN
		-- คำนวณคะแนนที่บันทึกและคะแนนที่ได้ตามกลุ่ม
		BEGIN
			SELECT WG.SCORE_MAIN,
				   WG.SCORE_WORK,
				   WG.SCORE_PROJECT
			INTO   V_SCORE_MAIN,
				   V_SCORE_WORK,
				   V_SCORE_PROJECT
			FROM   VW_HR_EVAPPGROUP_SCORE WG
			WHERE  WG.HR_EVAPP_ID = P_EVAPP_ID;
		
		EXCEPTION
			WHEN OTHERS THEN
				V_SCORE_MAIN := 0;
				V_SCORE_WORK := 0;
				V_SCORE_PROJECT := 0;
		END;
		V_SCOREINPUT := V_SCORE_MAIN + V_SCORE_WORK + V_SCORE_PROJECT;
	
		BEGIN
			SELECT CASE
					   WHEN NVL(LG.MAXSCORE_MAIN, 0) < V_SCORE_MAIN THEN
						NVL(LG.MAXSCORE_MAIN, 0)
					   ELSE
						V_SCORE_MAIN
				   END + CASE
					   WHEN NVL(LG.MAXSCORE_WORK, 0) < V_SCORE_WORK THEN
						NVL(LG.MAXSCORE_WORK, 0)
					   ELSE
						V_SCORE_WORK
				   END + CASE
					   WHEN NVL(LG.MAXSCORE_PROJECT, 0) < V_SCORE_PROJECT THEN
						NVL(LG.MAXSCORE_PROJECT, 0)
					   ELSE
						V_SCORE_PROJECT
				   END
			INTO   V_SCOREGROUP
			FROM   VW_HR_EVLOTAPPGROUP_SCORE LG
			WHERE  LG.HR_EVLOTAPP_ID = P_EVLOTAPP_ID;
		EXCEPTION
			WHEN OTHERS THEN
				V_SCOREGROUP := 0;
		END;
		/*
            BEGIN
                SELECT WG.SCORE_MAIN + WG.SCORE_WORK + WG.SCORE_PROJECT,
                       CASE
                           WHEN NVL(LG.MAXSCORE_MAIN, 0) < WG.SCORE_MAIN THEN
                            NVL(LG.MAXSCORE_MAIN, 0)
                           ELSE
                            WG.SCORE_MAIN
                       END + CASE
                           WHEN NVL(LG.MAXSCORE_WORK, 0) < WG.SCORE_WORK THEN
                            NVL(LG.MAXSCORE_WORK, 0)
                           ELSE
                            WG.SCORE_WORK
                       END + CASE
                           WHEN NVL(LG.MAXSCORE_PROJECT, 0) < WG.SCORE_PROJECT THEN
                            NVL(LG.MAXSCORE_PROJECT, 0)
                           ELSE
                            WG.SCORE_PROJECT
                       END
                INTO   V_SCOREINPUT,
                       V_SCOREGROUP
                FROM   VW_HR_EVLOTAPPGROUP_SCORE LG,
                       VW_HR_EVAPPGROUP_SCORE WG
                WHERE  LG.HR_EVLOTAPP_ID = P_EVLOTAPP_ID
                       AND WG.HR_EVAPP_ID = P_EVAPP_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_SCOREINPUT := 0;
                    V_SCOREGROUP := 0;
            END;
        */
		SELECT NVL(SUM(SCOREAPPROVE), 0),
			   COUNT(ID)
		INTO   V_CHILDSCORE,
			   V_CHILDCOUNT
		FROM   HR_EVAPP A
		WHERE  A.HR_STAFFHEADER_ID IS NOT NULL
			   AND HR_EVLOTAPP_ID = P_EVLOTAPP_ID
			   AND A.HR_STAFFHEADER_ID = P_STAFF_ID
			   AND A.ID <> P_EVAPP_ID;
	
		IF V_CHILDCOUNT > 0 THEN
			V_SCOREUNDER := ROUND((V_CHILDSCORE / V_CHILDCOUNT) * V_LOTRATIOFORHEADER / 100, 2);
		END IF;
	
		SELECT A.SUM_MAXSCORE,
			   A.NOLIMIT_ID
		INTO   V_MAXSCORE,
			   V_NOLIMIT_ID
		FROM   VW_HR_EVLOTWLPOS A
		WHERE  A.HR_EVLOTWL_ID = V_EVLOTWL_ID
			   AND A.HR_EVPOSITION_ID = P_EVPOSITION_ID;
	
		--V_SCOREMODE 1: จากคะแนนเต็มของภาระงาน, 2: จากรอบการประเมิน
		IF V_SCOREMODE = '2' THEN
			V_MAXSCORE := V_LOTTOTALSCORE;
			/*IF V_NOLIMIT_ID = 1 OR V_MAXSCORE = 0 THEN
                -- ไม่มีการกำหนดเพดานคะแนน
                V_MAXSCORE := R_HR_EVLOTAPP.TOTALSCORE;
            
                IF V_SCOREAPPROVE > V_MAXSCORE THEN
                    V_SCOREAPPROVE := V_MAXSCORE;
                END IF;
            ELSE
                V_SCOREAPPROVE := R_HR_EVLOTAPP.TOTALSCORE * V_SCOREAPPROVE / V_MAXSCORE;
                V_MAXSCORE := R_HR_EVLOTAPP.TOTALSCORE;
            END IF;*/
		END IF;
	
		V_SCOREAPPROVE := V_SCOREGROUP + V_SCOREUNDER;
	
		IF V_SCOREAPPROVE > V_MAXSCORE THEN
			V_SCOREAPPROVE := V_MAXSCORE;
		END IF;
	
		--DBMS_OUTPUT.PUT_LINE(V_SCOREAPPROVE);
		V_RATIOACHIEVEMENT := ROUND(V_SCOREAPPROVE * V_LOTRATIOACHIEVEMENT / V_MAXSCORE, 2);
		V_RATIOSCORE := V_RATIOACHIEVEMENT + P_RATIOBEHAVIOR;
		BEGIN
			SELECT MIN(ID)
			INTO   V_EVLOTSCOREITEM_ID
			FROM   HR_EVLOTSCOREITEM
			WHERE  HR_EVLOTSCORE_ID = V_EVLOTSCORE_ID
				   AND MINSCORE <= V_RATIOSCORE
				   AND V_RATIOSCORE <= MAXSCORE;
		EXCEPTION
			WHEN NO_DATA_FOUND THEN
				V_EVLOTSCOREITEM_ID := NULL;
		END;
		V_SCOREAPPROVE := NVL(V_SCOREAPPROVE, 0);
		V_RATIOSCORE := NVL(V_RATIOSCORE, 0);
		V_RATIOACHIEVEMENT := NVL(V_RATIOACHIEVEMENT, 0);
		V_SCOREINPUT := NVL(V_SCOREINPUT, 0);
		V_LOTRATIOBEHAVIOR := NVL(V_LOTRATIOBEHAVIOR, 0);
		V_SCOREGROUP := NVL(V_SCOREGROUP, 0);
		UPDATE HR_EVAPP
		SET    TOTALACHIEVEMENT = ROUND(100 * V_SCOREAPPROVE / V_MAXSCORE, 2),
			   TOTALBEHAVIOR = ROUND(P_RATIOBEHAVIOR * 100 / V_LOTRATIOBEHAVIOR, 2),
			   SCOREAPPROVE = V_SCOREAPPROVE,
			   RATIOACHIEVEMENT = V_RATIOACHIEVEMENT,
			   RATIOSCORE = V_RATIOSCORE,
			   HR_EVLOTSCOREITEM_ID = V_EVLOTSCOREITEM_ID,
			   SCOREINPUT = V_SCOREINPUT,
			   SCOREGROUP = V_SCOREGROUP,
			   SCOREUNDER = V_SCOREUNDER,
			   UPDATEBY = V_EXECUTEBY
		WHERE  ID = P_EVAPP_ID;
	
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVCOMMANDKEY_GEN
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVCOMMANDKEY_GEN" AS
BEGIN
	SELECT TO_CHAR(SYSDATE, 'YYYYMMDD-HH24MISS') INTO V_LOTCODE FROM DUAL;
	WHILE (V_START < P_TOTAL)
	LOOP
		V_HASERROR := 0;
		BEGIN
			INSERT INTO HR_EVCOMMANDKEY
				(HR_EVCOMMAND_ID,
				 LOTCODE,
				 SECRETKEY,
				 CREATEBY)
			VALUES
				(P_EVCOMMAND_ID,
				 V_LOTCODE,
				 FN_SS_RANDOMSTR_GET(6),
				 P_CREATEBY);
		EXCEPTION
			WHEN OTHERS THEN
				V_HASERROR := 1;
		END;

		IF V_HASERROR = 0 THEN
			V_START := V_START + 1;
		END IF;
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVLOTWLPOSGRPWL_COPY
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVLOTWLPOSGRPWL_COPY" AS
BEGIN
	FOR GRPWL IN (SELECT *
				  FROM   HR_EVLOTWLPOSGRPWL
				  WHERE  HR_EVLOTWLPOSGRP_ID = P_SOURCEGRP_ID
						 AND NVL(HR_EVLOTWLPOSGRPMAIN_ID, 0) = NVL(P_SOURCEGRPMAIN_ID, 0)
				  ORDER  BY ORDERNO)
	LOOP
		INSERT INTO HR_EVLOTWLPOSGRPWL
			(HR_EVLOTWLPOSGRP_ID,
			 HR_EVLOTWLPOSGRPMAIN_ID,
			 ORDERNO,
			 WORKNAME,
			 UNITNAME,
			 TOTALBASE,
			 EACHSCORE,
			 MAXSCORE,
			 ISREQUIREFILE_ID,
			 CANHEADERADD_ID,
			 FILENAME,
			 INPUTDESCRIPTION,
			 MINTOTAL,
			 ISINCLUDEPROJECT_ID,
			 SCORETYPE_ID,
			 INPUTTYPE_ID,
			 CREATEBY)
		VALUES
			(P_EVLOTWLPOSGRP_ID,
			 P_EVLOTWLPOSGRPMAIN_ID,
			 GRPWL.ORDERNO,
			 GRPWL.WORKNAME,
			 GRPWL.UNITNAME,
			 GRPWL.TOTALBASE,
			 GRPWL.EACHSCORE,
			 GRPWL.MAXSCORE,
			 GRPWL.ISREQUIREFILE_ID,
			 GRPWL.CANHEADERADD_ID,
			 GRPWL.FILENAME,
			 GRPWL.INPUTDESCRIPTION,
			 GRPWL.MINTOTAL,
			 GRPWL.ISINCLUDEPROJECT_ID,
			 GRPWL.SCORETYPE_ID,
			 GRPWL.INPUTTYPE_ID,
			 P_USER)
		RETURNING ID INTO V_EVLOTWLPOSGRPWL_ID;

		INSERT INTO HR_EVLOTWLPOSGRPWLFL
			(HR_EVLOTWLPOSGRPWL_ID,
			 ORDERNO,
			 FILENAME,
			 EXTENSION,
			 ISREQUIRE_ID,
			 DESCRIPTION,
			 CREATEBY)
			SELECT V_EVLOTWLPOSGRPWL_ID,
				   ORDERNO,
				   FILENAME,
				   EXTENSION,
				   ISREQUIRE_ID,
				   DESCRIPTION,
				   P_USER
			FROM   HR_EVLOTWLPOSGRPWLFL
			WHERE  HR_EVLOTWLPOSGRPWL_ID = GRPWL.ID
			ORDER  BY ORDERNO;
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVLOTWLPOSGRPWL_FL
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVLOTWLPOSGRPWL_FL" AS
BEGIN
	FOR ITEM IN (SELECT ID,FILENAME FROM HR_EVLOTWLPOSGRPWLFL WHERE HR_EVLOTWLPOSGRPWL_ID=P_EVLOTWLPOSGRPWL_ID ORDER BY ORDERNO)
	LOOP
		V_ORDERNO := V_ORDERNO +1;

		UPDATE HR_EVLOTWLPOSGRPWLFL
		SET ORDERNO = V_ORDERNO
		WHERE ID=ITEM.ID;

		IF V_FILENAME IS NULL THEN
			V_FILENAME := ITEM.FILENAME;
		ELSE
			IF V_ORDERNO=2 THEN
				V_FILENAME := '1. ' || V_FILENAME || CHR(10) || TO_CHAR(V_ORDERNO) || '. ' || ITEM.FILENAME;
			ELSE
				V_FILENAME := V_FILENAME || CHR(10) || TO_CHAR(V_ORDERNO) || '. ' || ITEM.FILENAME;
			END IF;
		END IF;
	END LOOP;

	UPDATE HR_EVLOTWLPOSGRPWL
	SET FILENAME=V_FILENAME,
		UPDATEDATETIME=SYSDATE,
		UPDATEBY=P_UPDATEBY
	WHERE ID=P_EVLOTWLPOSGRPWL_ID;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVLOTWLPOSGRPWL_PRJ
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVLOTWLPOSGRPWL_PRJ" AS
BEGIN
	SELECT A.HR_EVLOTWLPOS_ID, B.ISINCLUDEPROJECT_ID
	INTO V_EVLOTWLPOS_ID, V_ISINCLUDEPROJECT_ID
	FROM HR_EVLOTWLPOSGRP A
	INNER JOIN HR_EVLOTWLPOSGRPWL B ON A.ID = B.HR_EVLOTWLPOSGRP_ID
	WHERE B.ID = P_EVLOTWLPOSGRPWL_ID;

	IF V_ISINCLUDEPROJECT_ID = 1 THEN
		UPDATE HR_EVLOTWLPOSGRPWL
		SET ISINCLUDEPROJECT_ID = 0,
			UPDATEBY = P_UPDATEBY,
			UPDATEDATETIME = SYSDATE
		WHERE ID <> P_EVLOTWLPOSGRPWL_ID
			  AND ISINCLUDEPROJECT_ID = 1
			  AND HR_EVLOTWLPOSGRP_ID IN
			  (SELECT B.ID
				   FROM HR_EVLOTWLPOSGRP A
				   INNER JOIN HR_EVLOTWLPOSGRPWL B ON A.ID =
													  B.HR_EVLOTWLPOSGRP_ID
				   WHERE A.HR_EVLOTWLPOS_ID = V_EVLOTWLPOS_ID);
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVLOTWLPOS_COPY
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVLOTWLPOS_COPY" AS
BEGIN
	SELECT COUNT(ID) INTO V_CNT FROM HR_EVLOTWLPOSGRP WHERE HR_EVLOTWLPOS_ID = P_EVLOTWLPOS_ID;

	IF V_CNT = 0 THEN
		FOR GRP IN (SELECT A.* FROM HR_EVLOTWLPOSGRP A WHERE A.HR_EVLOTWLPOS_ID = P_SOURCEWLPOS_ID ORDER BY A.ORDERNO)
		LOOP
			INSERT INTO HR_EVLOTWLPOSGRP
				(HR_EVLOTWLPOS_ID,
				 ORDERNO,
				 WORKGROUPNAME,
				 HR_EVGROUP_ID,
				 DESCRIPTION,
				 MAXSCORE,
				 CREATEBY)
			VALUES
				(P_EVLOTWLPOS_ID,
				 GRP.ORDERNO,
				 GRP.WORKGROUPNAME,
				 GRP.HR_EVGROUP_ID,
				 GRP.DESCRIPTION,
				 GRP.MAXSCORE,
				 P_USER)
			RETURNING ID INTO V_EVLOTWLPOSGRP_ID;

			FOR GRPMAIN IN (SELECT * FROM HR_EVLOTWLPOSGRPMAIN WHERE HR_EVLOTWLPOSGRP_ID = GRP.ID ORDER BY ORDERNO)
			LOOP
				INSERT INTO HR_EVLOTWLPOSGRPMAIN
					(HR_EVLOTWLPOSGRP_ID,
					 ORDERNO,
					 MAINNAME,
					 EACHSCORE,
					 MAXSCORE,
					 CREATEBY)
				VALUES
					(V_EVLOTWLPOSGRP_ID,
					 GRPMAIN.ORDERNO,
					 GRPMAIN.MAINNAME,
					 GRPMAIN.EACHSCORE,
					 GRPMAIN.MAXSCORE,
					 P_USER)
				RETURNING ID INTO V_EVLOTWLPOSGRPMAIN_ID;

				PD_HR_EVLOTWLPOSGRPWL_COPY(GRP.ID, GRPMAIN.ID, V_EVLOTWLPOSGRP_ID, V_EVLOTWLPOSGRPMAIN_ID, P_USER);
			END LOOP;

			PD_HR_EVLOTWLPOSGRPWL_COPY(GRP.ID, NULL, V_EVLOTWLPOSGRP_ID, NULL, P_USER);
		END LOOP;
	ELSE
		NULL;
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVLOTWLPOS_DEL
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVLOTWLPOS_DEL" AS
BEGIN

	DELETE FROM HR_EVLOTWLPOSGRPWLFL
	WHERE HR_EVLOTWLPOSGRPWL_ID IN (SELECT B.ID FROM HR_EVLOTWLPOSGRP A INNER JOIN HR_EVLOTWLPOSGRPWL B ON A.ID = B.HR_EVLOTWLPOSGRP_ID WHERE A.HR_EVLOTWLPOS_ID = P_EVLOTWLPOS_ID);

	DELETE FROM HR_EVLOTWLPOSGRPWL WHERE HR_EVLOTWLPOSGRP_ID IN (SELECT ID FROM HR_EVLOTWLPOSGRP WHERE HR_EVLOTWLPOS_ID = P_EVLOTWLPOS_ID);

	DELETE FROM HR_EVLOTWLPOSGRPMAIN WHERE HR_EVLOTWLPOSGRP_ID IN (SELECT ID FROM HR_EVLOTWLPOSGRP WHERE HR_EVLOTWLPOS_ID = P_EVLOTWLPOS_ID);

	DELETE FROM HR_EVLOTWLPOSGRP WHERE HR_EVLOTWLPOS_ID = P_EVLOTWLPOS_ID;

END;
/

-- ----------------------------
-- Function structure for PD_HR_EVLOTWLPOS_GEN
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVLOTWLPOS_GEN" AS
BEGIN
	IF NVL(P_EVLOTWL_ID, 0) > 0 THEN
		INSERT INTO HR_EVLOTWLPOS
			(HR_EVLOTWL_ID,
			 HR_EVPOSITION_ID,
			 CREATEDATETIME,
			 CREATEBY)
			SELECT P_EVLOTWL_ID,
				   ID,
				   SYSDATE,
				   P_CREATEBY
			FROM   HR_EVPOSITION
			WHERE  ISACTIVE_ID = 1
				   AND ID NOT IN (SELECT HR_EVPOSITION_ID FROM HR_EVLOTWLPOS WHERE HR_EVLOTWL_ID = P_EVLOTWL_ID);
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_HR_EVPROJECTKEY_GEN
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_HR_EVPROJECTKEY_GEN" AS
BEGIN
	SELECT TO_CHAR(SYSDATE, 'YYYYMMDD-HH24MISS') INTO V_LOTCODE FROM DUAL;
	WHILE (V_START < P_TOTAL)
	LOOP
		V_HASERROR := 0;
		BEGIN
			INSERT INTO HR_EVPROJECTKEY
				(HR_EVPROJECT_ID,
				 LOTCODE,
				 SECRETKEY,
				 CREATEBY)
			VALUES
				(P_EVPROJECT_ID,
				 V_LOTCODE,
				 FN_SS_RANDOMSTR_GET(6),
				 P_CREATEBY);
		EXCEPTION
			WHEN OTHERS THEN
				V_HASERROR := 1;
		END;
	
		IF V_HASERROR = 0 THEN
			V_START := V_START + 1;
		END IF;
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_SS_CLIENTIDENTIFIER_ACCDATE
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_CLIENTIDENTIFIER_ACCDATE" AS
BEGIN
	UPDATE SS_CLIENTIDENTIFIER C
	SET
		C.ACCESSEDDATETIME=SYSDATE
	WHERE
		C.ID=V_ID;
END;
/

-- ----------------------------
-- Function structure for PD_SS_CLIENTIDENTIFIER_LOGOUT
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_CLIENTIDENTIFIER_LOGOUT" AS
BEGIN
	UPDATE SS_CLIENTIDENTIFIER C
	SET
		C.LOGOUTDATETIME=SYSDATE,
		C.LOGOUTTYPE_ID=V_LOGOUTTYPE_ID
	WHERE
		C.ID=V_ID AND
		C.LOGOUTDATETIME IS NULL;
END;
/

-- ----------------------------
-- Function structure for PD_SS_COINLOCKER_CLEAN
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_COINLOCKER_CLEAN" AS
BEGIN
	DELETE FROM SS_COINLOCKER
	WHERE  EXPIREDATETIME < SYSDATE
		   OR UPDATEDATETIME < SYSDATE - 3;
END;
/

-- ----------------------------
-- Function structure for PD_SS_COINLOCKER_EXPIREEXTEND
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_COINLOCKER_EXPIREEXTEND" AS
BEGIN
	UPDATE SS_COINLOCKER
	SET    EXPIREDATETIME = SYSDATE + EXPIREEXTENDMINUTES / 1440
	WHERE  ID = COINLOCKER_ID;
	IF FLOOR(DBMS_RANDOM.VALUE(1, 33)) = 1 THEN
		PD_SS_COINLOCKER_CLEAN();
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_SS_DBMESSAGE_GEN
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_DBMESSAGE_GEN" AS
BEGIN
	FOR CNAME IN (SELECT A.CONSTRAINT_NAME
				  FROM   USER_CONSTRAINTS A
				  WHERE  A.CONSTRAINT_TYPE = 'U' AND A.CONSTRAINT_NAME NOT LIKE '%GUID' AND
						 A.CONSTRAINT_NAME NOT IN (SELECT DBMESSAGECODE FROM SS_DBMESSAGE))
	LOOP
		V_RET := '';
		FOR COL IN (SELECT A.COLUMN_NAME, B.COMMENTS
					FROM   USER_CONS_COLUMNS A, USER_COL_COMMENTS B
					WHERE  A.CONSTRAINT_NAME = CNAME.CONSTRAINT_NAME AND B.COLUMN_NAME <> 'GUID' AND A.TABLE_NAME = B.TABLE_NAME AND
						   A.COLUMN_NAME = B.COLUMN_NAME
					ORDER  BY A.COLUMN_NAME)
		LOOP
			COLNO := INSTR(COL.COMMENTS, '<map', 1);
			IF COLNO = 0 THEN
				COLTEXT := COL.COMMENTS;
			ELSE
				COLTEXT := SUBSTR(COL.COMMENTS, 1, COLNO - 1);
			END IF;
			IF V_RET IS NULL THEN
				V_RET := COLTEXT;
			ELSE
				V_RET := V_RET || ', ' || COLTEXT;
			END IF;
		END LOOP;

		IF V_RET IS NOT NULL THEN
			/*DBMS_OUTPUT.PUT_LINE('INSERT INTO SS_DBMESSAGE (DBMESSAGECODE, DBMESSAGE) VALUES (' || CNAME.CONSTRAINT_NAME || ', ' || V_RET ||
            ' || '' ซ้ำ'');');*/
			INSERT INTO SS_DBMESSAGE (DBMESSAGECODE, DBMESSAGE) VALUES (CNAME.CONSTRAINT_NAME, V_RET || ' ซ้ำ');
		END IF;
	END LOOP;
END PD_SS_DBMESSAGE_GEN;
/

