PROCEDURE "VNMIS"."PD_SS_EDITBUDGETGROUP_CH" AS
BEGIN

  DELETE FROM SS_EDITBUDGETGROUP_CH;

  OPEN CBGROUP;
  LOOP
    FETCH CBGROUP
      INTO VBGROUP;
    EXIT WHEN CBGROUP%NOTFOUND;

    OPEN CINSERT(VBGROUP.CODEFROM, VBGROUP.CODETO);
    LOOP
      FETCH CINSERT
        INTO VID;
      EXIT WHEN CINSERT%NOTFOUND;

      BEGIN
        INSERT INTO SS_EDITBUDGETGROUP_CH
          (SS_ROLE_ID, SS_MENU_ID, BG_BUDGETGROUP_ID)
        VALUES
          (VBGROUP.SS_ROLE_ID, VBGROUP.SS_MENU_ID, VID);
      EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
          NULL;
      END;

    END LOOP;
    CLOSE CINSERT;

  END LOOP;
  CLOSE CBGROUP;

END;
/

-- ----------------------------
-- Function structure for PD_SS_EDITDEPARTMENT_CH
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_EDITDEPARTMENT_CH" AS
BEGIN

	DELETE FROM SS_EDITDEPARTMENT_CH;

	-- สำหรับระบบงานบุคลากร และระบบเงินเดือน
	OPEN CDEPT_HRM;
	LOOP
		FETCH CDEPT_HRM
			INTO VDEPT_HRM;
		EXIT WHEN CDEPT_HRM%NOTFOUND;
	
		OPEN CINSERT_HRM(VDEPT_HRM.DEPTFROM, VDEPT_HRM.DEPTTO);
		LOOP
			FETCH CINSERT_HRM
				INTO VDEPARTMENTID;
			EXIT WHEN CINSERT_HRM%NOTFOUND;
		
			BEGIN
				INSERT INTO SS_EDITDEPARTMENT_CH
					(SS_ROLE_ID,
					 SS_MENU_ID,
					 MT_DEPARTMENT_ID)
				VALUES
					(VDEPT_HRM.SS_ROLE_ID,
					 VDEPT_HRM.SS_MENU_ID,
					 VDEPARTMENTID);
			EXCEPTION
				WHEN DUP_VAL_ON_INDEX THEN
					NULL;
			END;
		
		END LOOP;
		CLOSE CINSERT_HRM;
	
	END LOOP;
	CLOSE CDEPT_HRM;

	-- สำหรับระบบงานอื่น
	OPEN CDEPT;
	LOOP
		FETCH CDEPT
			INTO VDEPT;
		EXIT WHEN CDEPT%NOTFOUND;
	
		OPEN CINSERT(VDEPT.DEPTFROM, VDEPT.DEPTTO);
		LOOP
			FETCH CINSERT
				INTO VDEPARTMENTID;
			EXIT WHEN CINSERT%NOTFOUND;
		
			BEGIN
				INSERT INTO SS_EDITDEPARTMENT_CH
					(SS_ROLE_ID,
					 SS_MENU_ID,
					 MT_DEPARTMENT_ID)
				VALUES
					(VDEPT.SS_ROLE_ID,
					 VDEPT.SS_MENU_ID,
					 VDEPARTMENTID);
			EXCEPTION
				WHEN DUP_VAL_ON_INDEX THEN
					NULL;
			END;
		
		END LOOP;
		CLOSE CINSERT;
	
	END LOOP;
	CLOSE CDEPT;

END;
/

