-- ----------------------------
-- Function structure for PD_SS_GRANTDEPARTMENT_CH
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_GRANTDEPARTMENT_CH" AS
BEGIN

	DELETE FROM SS_GRANTDEPARTMENT_CH WHERE SS_APPLICATION_ID = VAPPID;

	IF VAPPID IN (160, 170) THEN
		-- สำหรับระบบงานบุคลากร และระบบเงินเดือน
		OPEN CDEPT_HRM;
		LOOP
			FETCH CDEPT_HRM
				INTO VDEPT_HRM;
			EXIT WHEN CDEPT_HRM%NOTFOUND;
		
			OPEN CINSERT_HRM(VDEPT_HRM.DEPTFROM, VDEPT_HRM.DEPTTO);
			LOOP
				FETCH CINSERT_HRM
					INTO VDEPARTMENTID;
				EXIT WHEN CINSERT_HRM%NOTFOUND;
			
				BEGIN
					INSERT INTO SS_GRANTDEPARTMENT_CH
						(SS_ROLE_ID,
						 SS_APPLICATION_ID,
						 MT_DEPARTMENT_ID)
					VALUES
						(VDEPT_HRM.SS_ROLE_ID,
						 VAPPID,
						 VDEPARTMENTID);
				EXCEPTION
					WHEN DUP_VAL_ON_INDEX THEN
						NULL;
				END;
			
			END LOOP;
			CLOSE CINSERT_HRM;
		
		END LOOP;
		CLOSE CDEPT_HRM;
	ELSE
		-- สำหรับระบบงานอื่น
		OPEN CDEPT;
		LOOP
			FETCH CDEPT
				INTO VDEPT;
			EXIT WHEN CDEPT%NOTFOUND;
		
			OPEN CINSERT(VDEPT.DEPTFROM, VDEPT.DEPTTO);
			LOOP
				FETCH CINSERT
					INTO VDEPARTMENTID;
				EXIT WHEN CINSERT%NOTFOUND;
			
				BEGIN
					INSERT INTO SS_GRANTDEPARTMENT_CH
						(SS_ROLE_ID,
						 SS_APPLICATION_ID,
						 MT_DEPARTMENT_ID)
					VALUES
						(VDEPT.SS_ROLE_ID,
						 VAPPID,
						 VDEPARTMENTID);
				EXCEPTION
					WHEN DUP_VAL_ON_INDEX THEN
						NULL;
				END;
			
			END LOOP;
			CLOSE CINSERT;
		
		END LOOP;
		CLOSE CDEPT;
	END IF;

END;
/

