-- ----------------------------
-- Function structure for PD_SS_GRANT_COPY
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_GRANT_COPY" AS
BEGIN
	INSERT INTO SS_GRANTUSERROLE
		(SS_ROLE_ID,
		 SS_USER_ID,
		 CREATEDATETIME,
		 CREATEBY)
		SELECT SS_ROLE_ID,
			   P_USERTO_ID,
			   SYSDATE,
			   P_CREATEBY
		FROM   SS_GRANTUSERROLE A
		INNER  JOIN SS_ROLE B
		ON     A.SS_ROLE_ID = B.ID
		WHERE  (B.SS_APPLICATION_ID = P_APPLICATION_ID OR
			   P_APPLICATION_ID = 0)
			   AND A.SS_USER_ID = P_USERFROM_ID
			   AND SS_ROLE_ID NOT IN
			   (SELECT SS_ROLE_ID
					FROM   SS_GRANTUSERROLE
					WHERE  SS_USER_ID = P_USERTO_ID);

	PD_SS_GRANT_REFRESH(2, NULL);
	PD_SS_GRANT_REFRESH(3, NULL);
	PD_SS_GRANT_REFRESH(4, NULL);
END;
/

-- ----------------------------
-- Function structure for PD_SS_GRANT_REFRESH
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_GRANT_REFRESH" AS
BEGIN
	--XX1 M   เมนู
	--2   B   หน่วยงาน(งบประมาณ)
	--3   V   แสดงผล
	--4   E   แก้ไข
	--XX5 T   แก้ไขข้อมูลพื้นฐาน
  --6   WFHR หน่วยงานสวัสดิการ
	PD_SS_ROLE_REFRESH(VROLEGROUPID);
	COMMIT;

	OPEN CAPP;
	LOOP

		FETCH CAPP
			INTO VAPP;
		EXIT WHEN CAPP%NOTFOUND;

		IF VROLEGROUPID = 2 THEN
			--PD_SS_GRANTBGGROUP_CH(VAPP);
			--COMMIT;
			--PD_SS_GRANTBGDEPT_CH(VAPP);
			--COMMIT;
NULL;
		ELSIF VROLEGROUPID = 3 THEN
			PD_SS_GRANTBUDGETGROUP_CH(VAPP);
			COMMIT;
			PD_SS_GRANTDEPARTMENT_CH(VAPP);
			COMMIT;
		ELSIF VROLEGROUPID = 4 THEN
			NULL;
		END IF;

	END LOOP;

	--100   Master
	--110   Budget
	--120   Purchase
	--130   Finance
	--140   Stock
	--150   Account
	--160   Human Resource
	--170   Payroll
	--180   Cost
	--190   Building
	--200   Text
	--210   Quaility
	--220   Performance
	--230   Research
	--700   Task
	--800   Online
	--900   Administrator

	IF VROLEGROUPID = 2 THEN
		NULL;
	ELSIF VROLEGROUPID = 3 THEN

		IF VAPPID = 150 OR VAPPID IS NULL THEN
			PD_SS_GRANTBOOK_CH;
			COMMIT;
		END IF;

		IF VAPPID IN (120, 140) OR VAPPID IS NULL THEN
			PD_SS_GRANTLOCATION_CH;
			COMMIT;
		END IF;

		IF VAPPID = 130 OR VAPPID IS NULL THEN
			--PD_SS_GRANTPREPAYTYPE_CH;
			--COMMIT;
			--PD_SS_GRANTPAYMENTTYPE_CH;
			--COMMIT;
NULL;
		END IF;

		IF VAPPID IN (160, 170) OR VAPPID IS NULL THEN
			--PD_SS_GRANTPAYGROUP_CH;
			--COMMIT;
			--PD_SS_GRANTSTAFFPAYTYPE_CH;
			--COMMIT;
			--PD_SS_GRANTSTAFFTYPE_CH;
			--COMMIT;
NULL;
		END IF;

	ELSIF VROLEGROUPID = 4 THEN

		PD_SS_EDITDEPARTMENT_CH;
		COMMIT;

		IF VAPPID = 150 OR VAPPID IS NULL THEN
			--PD_SS_EDITBOOK_CH;
			--COMMIT;
NULL;
		END IF;

		IF VAPPID = 110 OR VAPPID IS NULL THEN
			PD_SS_EDITBUDGETGROUP_CH;
			COMMIT;
		END IF;

		IF VAPPID IN (120, 140) OR VAPPID IS NULL THEN
			--PD_SS_EDITLOCATION_CH;
			--COMMIT;
NULL;
		END IF;

		IF VAPPID IN (160, 170) OR VAPPID IS NULL THEN
			--PD_SS_EDITPAYGROUP_CH;
			--COMMIT;
			--PD_SS_EDITSTAFFPAYTYPE_CH;
			--COMMIT;
			--PD_SS_EDITSTAFFTYPE_CH;
			--COMMIT;
NULL;
		END IF;

		IF VAPPID IN (160) OR VAPPID IS NULL THEN
			--PD_SS_EDITCOMMANDTYPE_CH;
			--COMMIT;
NULL;
		END IF;

	 ELSIF VROLEGROUPID = 6 THEN
    PD_SS_GRANTDEPARTMENT_CH(160);
    COMMIT;
	END IF;

END;
/

