END;
/

-- ----------------------------
-- Function structure for PD_SS_MENUFAVOURITESGRP_SWPODR
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_MENUFAVOURITESGRP_SWPODR" AS
BEGIN
	T_RESULT := 0;
	IF A_ID IS NULL OR A_INSERTAFTERID IS NULL OR A_ID = A_INSERTAFTERID THEN
		-- Verify inputs
		Return;
	ElsIF A_INSERTAFTERID > 0 THEN
		-- Check: Are thay same group? Then read group ID.
		SELECT MAX(I1.SS_USER_ID), MAX(I1.ORDERNO)
		INTO V_USERID, V_ORDERNO
		FROM SS_MENUFAVOURITESGROUP I1
		JOIN SS_MENUFAVOURITESGROUP I2 ON I1.SS_USER_ID = I2.SS_USER_ID
		WHERE I1.ID=A_ID AND I2.ID=A_INSERTAFTERID;
	ELSE
		-- Check: Is ID exist? Then read group ID.
		SELECT MAX(I1.SS_USER_ID), MAX(I1.ORDERNO)
		INTO V_USERID, V_ORDERNO
		FROM SS_MENUFAVOURITESGROUP I1
		WHERE I1.ID=A_ID;
	END IF;
	IF V_USERID IS NULL THEN
		Return;
	END IF;

	IF A_INSERTAFTERID >= 0 THEN
		IF A_INSERTAFTERID = 0 THEN
			-- Move to the top.
			V_INSERTAFTERORDERNO := 1;
		ELSE
			SELECT MAX(I1.ORDERNO)
			INTO V_INSERTAFTERORDERNO
			FROM SS_MENUFAVOURITESGROUP I1
			WHERE I1.ID=A_INSERTAFTERID;
		END IF;

		UPDATE SS_MENUFAVOURITESGROUP
		SET ORDERNO = ORDERNO + 1
		WHERE SS_USER_ID = V_USERID AND ORDERNO >= V_INSERTAFTERORDERNO;

		UPDATE SS_MENUFAVOURITESGROUP
		SET ORDERNO = V_INSERTAFTERORDERNO
		WHERE ID=A_ID;
		T_RESULT := 1;
	ELSIF A_INSERTAFTERID = -1 THEN
		-- Move to the end.
		DECLARE
			V_MAXORDERNO SS_MENUFAVOURITESGROUP.SS_USER_ID%TYPE;
		BEGIN
			SELECT MAX(I1.ORDERNO)
			INTO V_MAXORDERNO
			FROM SS_MENUFAVOURITESGROUP I1
			WHERE I1.SS_USER_ID=V_USERID;

			IF V_MAXORDERNO <> V_ORDERNO THEN
				UPDATE SS_MENUFAVOURITESGROUP
				SET ORDERNO = V_MAXORDERNO + 1
				WHERE ID=A_ID;
			END If;
		END;
		T_RESULT := 1;
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_SS_MENUFAVOURITES_SWPODR
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_MENUFAVOURITES_SWPODR" AS
BEGIN
	T_RESULT := 0;
	IF A_ID IS NULL OR A_INSERTAFTERID IS NULL OR A_ID = A_INSERTAFTERID THEN
		-- Verify inputs
		Return;
	ElsIF A_INSERTAFTERID > 0 THEN
		-- Check: Are thay same group? Then read group ID.
		SELECT MAX(I1.SS_MENUFAVOURITESGROUP_ID), MAX(I1.ORDERNO)
		INTO V_GROUP, V_ORDERNO
		FROM SS_MENUFAVOURITES I1
		JOIN SS_MENUFAVOURITES I2 ON I1.SS_MENUFAVOURITESGROUP_ID = I2.SS_MENUFAVOURITESGROUP_ID
		WHERE I1.ID=A_ID AND I2.ID=A_INSERTAFTERID;
	ELSE
		-- Check: Is ID exist? Then read group ID.
		SELECT MAX(I1.SS_MENUFAVOURITESGROUP_ID), MAX(I1.ORDERNO)
		INTO V_GROUP, V_ORDERNO
		FROM SS_MENUFAVOURITES I1
		WHERE I1.ID=A_ID;
	END IF;
	IF V_GROUP IS NULL THEN
		Return;
	END IF;

	IF A_INSERTAFTERID >= 0 THEN
		IF A_INSERTAFTERID = 0 THEN
			-- Move to the top.
			V_INSERTAFTERORDERNO := 1;
		ELSE
			SELECT MAX(I1.ORDERNO)
			INTO V_INSERTAFTERORDERNO
			FROM SS_MENUFAVOURITES I1
			WHERE I1.ID=A_INSERTAFTERID;
		END IF;

		UPDATE SS_MENUFAVOURITES
		SET ORDERNO = ORDERNO + 1
		WHERE SS_MENUFAVOURITESGROUP_ID = V_GROUP AND ORDERNO >= V_INSERTAFTERORDERNO;

		UPDATE SS_MENUFAVOURITES
		SET ORDERNO = V_INSERTAFTERORDERNO
		WHERE ID=A_ID;
		T_RESULT := 1;
	ELSIF A_INSERTAFTERID = -1 THEN
		-- Move to the end.
		DECLARE
			V_MAXORDERNO SS_MENUFAVOURITES.SS_MENUFAVOURITESGROUP_ID%TYPE;
		BEGIN
			SELECT MAX(I1.ORDERNO)
			INTO V_MAXORDERNO
			FROM SS_MENUFAVOURITES I1
			WHERE I1.SS_MENUFAVOURITESGROUP_ID=V_GROUP;

			IF V_MAXORDERNO <> V_ORDERNO THEN
				UPDATE SS_MENUFAVOURITES
				SET ORDERNO = V_MAXORDERNO + 1
				WHERE ID=A_ID;
			END If;
		END;
		T_RESULT := 1;
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_SS_PARAMETER_CH_CLEARPARAM
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_PARAMETER_CH_CLEARPARAM" AS
BEGIN
	DELETE FROM SS_PARAMETER_CH WHERE SESSIONID = USERENV('SESSIONID');
END;
/

-- ----------------------------
-- Function structure for PD_SS_PARAMETER_CH_DELPARAM
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_PARAMETER_CH_DELPARAM" AS
BEGIN
	IF INSTR(P_PARAMETERFILTER, '%') > 0 THEN
		DELETE FROM SS_PARAMETER_CH
		WHERE SESSIONID = USERENV('SESSIONID') AND PARAMETERNAME LIKE UPPER(P_PARAMETERFILTER);
	ELSE
		DELETE FROM SS_PARAMETER_CH
		WHERE SESSIONID = USERENV('SESSIONID') AND PARAMETERNAME = UPPER(P_PARAMETERFILTER);
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_SS_PARAMETER_CH_SETPARAM
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_PARAMETER_CH_SETPARAM" AS
BEGIN
  If trunc(dbms_random.value(1, 20)) = 1 Then
    DELETE FROM SS_PARAMETER_CH
    WHERE
      CREATEDATETIME <= SYSDATE - 1 OR
      (SESSIONID = USERENV('SESSIONID') AND PARAMETERNAME = UPPER(P_PARAMETERNAME));
  Else
    DELETE FROM SS_PARAMETER_CH
    WHERE SESSIONID = USERENV('SESSIONID') AND PARAMETERNAME = UPPER(P_PARAMETERNAME);
  End If;
  --If P_USERNAME IS NULL THEN
    INSERT INTO SS_PARAMETER_CH (PARAMETERNAME, VALUEDATE, VALUENUMBER, VALUETEXT)
    VALUES (UPPER(P_PARAMETERNAME), P_VALUEDATE, P_VALUENUMBER, P_VALUETEXT);
  --ELSE
  --  INSERT INTO SS_PARAMETER_CH (CREATEBY, UPDATEBY, PARAMETERNAME, VALUEDATE, VALUENUMBER, VALUETEXT)
  --  VALUES (P_USERNAME, P_USERNAME, UPPER(P_PARAMETERNAME), P_VALUEDATE, P_VALUENUMBER, P_VALUETEXT);
  --END IF;
END;
/

-- ----------------------------
-- Function structure for PD_SS_PARAMETER_CH_SETPARAMUSR
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_PARAMETER_CH_SETPARAMUSR" AS
BEGIN
	If trunc(dbms_random.value(1, 20)) = 1 Then
		DELETE FROM SS_PARAMETER_CH
		WHERE
			CREATEDATETIME <= SYSDATE - 1 OR
			(SESSIONID = USERENV('SESSIONID') AND PARAMETERNAME = UPPER(P_PARAMETERNAME));
	Else
		DELETE FROM SS_PARAMETER_CH
		WHERE SESSIONID = USERENV('SESSIONID') AND PARAMETERNAME = UPPER(P_PARAMETERNAME);
	End If;
	If P_USERNAME IS NULL THEN
		INSERT INTO SS_PARAMETER_CH (PARAMETERNAME, VALUEDATE, VALUENUMBER, VALUETEXT)
		VALUES (UPPER(P_PARAMETERNAME), P_VALUEDATE, P_VALUENUMBER, P_VALUETEXT);
	ELSE
		INSERT INTO SS_PARAMETER_CH (CREATEBY, UPDATEBY, PARAMETERNAME, VALUEDATE, VALUENUMBER, VALUETEXT)
		VALUES (P_USERNAME, P_USERNAME, UPPER(P_PARAMETERNAME), P_VALUEDATE, P_VALUENUMBER, P_VALUETEXT);
	END IF;
END;
/

