-- ----------------------------
-- Function structure for PD_SS_ROLE_REFRESH
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_ROLE_REFRESH" AS
BEGIN
	IF VROLEGROUPID IS NULL THEN
	
		OPEN CROLE;
		LOOP
			FETCH CROLE
				INTO VROLE;
			EXIT WHEN CROLE%NOTFOUND;
		
			IF FN_SS_ENDLOOP(VROLE.SS_ROLE_ID, VROLE.SS_ROLEINHERITFROM_ID) = -1 THEN
				PD_SS_RAISEERROR(-20001,
								 ODBCERR('CIRCULAR LOOP ( ' ||
										 VROLE.SS_ROLE_ID || ' : ' ||
										 VROLE.SS_ROLEINHERITFROM_ID || ' )'));
			END IF;
		
		END LOOP;
		CLOSE CROLE;
	
		DELETE FROM SS_ROLE_CH;
	
		OPEN CROLEALL;
		LOOP
			FETCH CROLEALL
				INTO VROLE;
			EXIT WHEN CROLEALL%NOTFOUND;
		
			SYS_INS_ROLE_TMP_LOOP(VROLE.SS_ROLE_ID,
								  VROLE.SS_ROLEINHERITFROM_ID);
		
		END LOOP;
		CLOSE CROLEALL;
	
	ELSE
	
		OPEN GROLE;
		LOOP
			FETCH GROLE
				INTO VROLE;
			EXIT WHEN GROLE%NOTFOUND;
		
			IF FN_SS_ENDLOOP(VROLE.SS_ROLE_ID, VROLE.SS_ROLEINHERITFROM_ID) = -1 THEN
				PD_SS_RAISEERROR(-20001,
								 ODBCERR('CIRCULAR LOOP ( ' ||
										 VROLE.SS_ROLE_ID || ' : ' ||
										 VROLE.SS_ROLEINHERITFROM_ID || ' )'));
			END IF;
		
		END LOOP;
		CLOSE GROLE;
	
		DELETE FROM SS_ROLE_CH
		WHERE  SS_ROLE_ID IN
			   (SELECT ID FROM SS_ROLE WHERE ROLEGROUP_ID = VROLEGROUPID);
	
		OPEN GROLEALL;
		LOOP
			FETCH GROLEALL
				INTO VROLE;
			EXIT WHEN GROLEALL%NOTFOUND;
		
			SYS_INS_ROLE_TMP_LOOP(VROLE.SS_ROLE_ID,
								  VROLE.SS_ROLEINHERITFROM_ID);
		
		END LOOP;
		CLOSE GROLEALL;
	
	END IF;

END;
/

-- ----------------------------
-- Function structure for PD_SS_USER_SETPASSWORD
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_USER_SETPASSWORD" AS
BEGIN
	SELECT * INTO V_SS_USER FROM SS_USER WHERE GUID = P_GUID;

	IF P_TYPECODE = '0' THEN
		-- CLEAR
		UPDATE PROMIS.PASSPORT_ENTITY
		SET    PASSWORD = NULL
		WHERE  ENTITYID = V_SS_USER.PP_ENTITY_ID;
	ELSIF P_TYPECODE = '1' THEN
		--SET
		UPDATE PROMIS.PASSPORT_ENTITY
		SET    PASSWORD = LOWER(V_SS_USER.USERNAME)
		WHERE  ENTITYID = V_SS_USER.PP_ENTITY_ID;
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_SS_USER_SYNC
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_USER_SYNC" AS
BEGIN
	FOR ENTITY IN (SELECT * FROM PROMIS.PASSPORT_ENTITY)
	LOOP
		UPDATE SS_USER
		SET    PP_ENTITY_ID = ENTITY.ENTITYID
		WHERE  UPPER(USERNAME) = UPPER(ENTITY.LOGIN);
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_SS_USER_UNLOCK
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_USER_UNLOCK" AS
BEGIN
	SELECT PP_ENTITY_ID
	INTO   V_PP_ENTITY_ID
	FROM   SS_USER
	WHERE  GUID = P_GUID;

	IF V_PP_ENTITY_ID IS NOT NULL THEN
		UPDATE PROMIS.PASSPORT_ENTITY
		SET    INVALIDLOGONCOUNT = 0,
			   ACCOUNTLOCKOUTSINCE = NULL,
			   ACCOUNTLOCKOUTCOUNT = 0
		WHERE  ENTITYID = V_PP_ENTITY_ID;
	END IF;
END;
/

-- ----------------------------
-- Function structure for PD_SS_WEBBOARDDEPT_CH
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_WEBBOARDDEPT_CH" AS
BEGIN
	DELETE FROM SS_WEBBOARDDEPT_CH WHERE SS_WEBBOARD_ID = P_SS_WEBBOARD_ID;

	FOR ITEM IN (SELECT DF.DEPARTMENTCODE AS CODEFROM,
						DT.DEPARTMENTCODE AS CODETO
				 FROM   SS_WEBBOARDDEPT WD
				 INNER  JOIN VW_MT_DEPARTMENT DF
				 ON     WD.MT_DEPARTMENTFROM_ID = DF.ID
				 INNER  JOIN VW_MT_DEPARTMENT DT
				 ON     WD.MT_DEPARTMENTTO_ID = DT.ID
				 WHERE  WD.SS_WEBBOARD_ID = P_SS_WEBBOARD_ID)
	LOOP
		INSERT INTO SS_WEBBOARDDEPT_CH
			(SS_WEBBOARD_ID,
			 MT_DEPARTMENT_ID,
			 CREATEBY)
			SELECT P_SS_WEBBOARD_ID,
				   D.ID,
				   P_CREATEBY
			FROM   VW_MT_DEPARTMENT D
			WHERE  D.DEPARTMENTCODE >= ITEM.CODEFROM
				   AND D.DEPARTMENTCODE <= ITEM.CODETO
				   AND D.ID NOT IN
				   (SELECT MT_DEPARTMENT_ID
						FROM   SS_WEBBOARDDEPT_CH
						WHERE  SS_WEBBOARD_ID = P_SS_WEBBOARD_ID);
	END LOOP;
END;
/

-- ----------------------------
-- Function structure for PD_SS_WEBMESSAGE_GEN
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."PD_SS_WEBMESSAGE_GEN" AS
BEGIN
	INSERT INTO SS_WEBMESSAGE
		(WEBMESSAGECODE,
		 WEBMESSAGE,
		 WEBMESSAGEENG)
		SELECT /*DISTINCT*/
		 'LABEL.' || A.TABLE_NAME,
		 A.TABLE_COMMENTS,
		 ''
		FROM   VW_SS_TABLECOLUMN A
		WHERE  TABLE_NAME = UPPER(VTABLENAME)
			   AND 'LABEL.' || A.TABLE_NAME NOT IN
			   (SELECT WEBMESSAGECODE FROM SS_WEBMESSAGE)
		GROUP  BY A.TABLE_NAME,
				  A.TABLE_COMMENTS;

	INSERT INTO SS_WEBMESSAGE
		(WEBMESSAGECODE,
		 WEBMESSAGE,
		 WEBMESSAGEENG)
		SELECT 'LABEL.' || A.TABLE_NAME || '.' || A.COLUMN_NAME,
			   A.COLUMN_COMMENTS,
			   ''
		FROM   VW_SS_TABLECOLUMN A
		WHERE  TABLE_NAME = UPPER(VTABLENAME)
			   AND
			   COLUMN_NAME NOT IN ('ID',
								   'CREATEDATETIME',
								   'CREATEBY',
								   'UPDATEDATETIME',
								   'UPDATEBY',
								   'ORDERNO',
								   'GUID',
								   'ACTIVE_ID',
								   'DEFAULT_ID',
								   'CREATEBYCLIENT_ID',
								   'UPDATEBYCLIENT_ID')
			   AND 'LABEL.' || A.TABLE_NAME || '.' || A.COLUMN_NAME NOT IN
			   (SELECT WEBMESSAGECODE FROM SS_WEBMESSAGE);
END;
/

-- ----------------------------
-- Function structure for SYS_INS_ROLE_TMP_LOOP
-- ----------------------------
CREATE OR REPLACE
PROCEDURE "VNMIS"."SYS_INS_ROLE_TMP_LOOP" AS
BEGIN
	IF VINHERIT IS NULL THEN
		INSERT INTO SS_ROLE_CH
			(SS_ROLE_ID,
			 SS_ROLE_CH.SS_ROLEGRANT_ID)
		VALUES
			(VINITIAL,
			 VINITIAL);
	ELSE
		INSERT INTO SS_ROLE_CH
			(SS_ROLE_ID,
			 SS_ROLEGRANT_ID)
		VALUES
			(VINITIAL,
			 VINHERIT);
	
		SELECT SS_ROLEINHERITFROM_ID
		INTO   TEMP
		FROM   SS_ROLE
		WHERE  ID = VINHERIT;
	
		SYS_INS_ROLE_TMP_LOOP(VINITIAL, TEMP);
	END IF;
END;
/

