-- ----------------------------
-- Triggers structure for table BP_BUDGETGROUP
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_BP_BUDGETGROUP_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."BP_BUDGETGROUP" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		:NEW.ID := :NEW.BG_BUDGETGROUP_ID;
		/*      IF :NEW.ID IS NULL THEN
            SELECT SQ_BG_BUDGETGROUP_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
        END IF;*/
	
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
/

