-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_BP_KPIACTIVITY_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."BP_KPIACTIVITY" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		SELECT SQ_BP_KPIACTIVITY_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
    BEGIN
      :new.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
