-- ----------------------------
-- Triggers structure for table BP_PERIODAPP
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_BP_PERIODAPP_IUA" AFTER INSERT OR UPDATE ON "VNMIS"."BP_PERIODAPP" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		INSERT INTO BP_PERIODAPPDATAGROUP
			(BP_PERIODAPP_ID,
			 BP_MTAPPDATAGROUP_ID,
			 COMPLETE_ID,
			 CREATEBY)
			SELECT :NEW.ID,
				   ID,
				   0,
				   :NEW.CREATEBY
			FROM BP_MTAPPDATAGROUP
			ORDER BY MTAPPDATAGROUPCODE;
	END IF;

	IF NVL(:NEW.BG_PLANPRDPRJ_ID, -1) <> NVL(:OLD.BG_PLANPRDPRJ_ID, -1) THEN
		PD_BP_PERIODAPPACT_IMP(:NEW.ID, :NEW.BG_PLANPRDPRJ_ID, :NEW.CREATEBY);
	END IF;
END;
/
CREATE TRIGGER "VNMIS"."TG_BP_PERIODAPP_UBY" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."BP_PERIODAPP" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_CNT NUMBER;
	V_SUM NUMBER;
BEGIN
	IF INSERTING THEN
		SELECT SQ_BP_PERIODAPP_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
	
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	
		IF NVL(:NEW.STATUS_ID, -1) <> NVL(:OLD.STATUS_ID, -1) THEN
		
			IF NVL(:NEW.STATUS_ID, -1) = 10 THEN
				--กรณีส่งแก้ไข
				SELECT COUNT(ID)
				INTO V_CNT
				FROM BP_PERIODAPPREMARK
				WHERE BP_PERIODAPP_ID = :NEW.ID
					  AND EDIT_ID = 0;
			
				IF V_CNT = 0 THEN
					PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากไม่ได้ระบุรายการที่ต้องแก้ไข');
				END IF;
			
				UPDATE BP_PERIODAPPACTEXP
				SET BG_BUDGET_ID = NULL,
					REFCODE = NULL,
					UPDATEDATETIME = SYSDATE,
					UPDATEBY = :NEW.UPDATEBY
				WHERE BP_PERIODAPPACT_ID IN (SELECT ID FROM BP_PERIODAPPACT WHERE BP_PERIODAPP_ID = :NEW.ID);
			
			ELSIF NVL(:NEW.STATUS_ID, -1) = 30 THEN
				:NEW.SUBMITDATE := SYSDATE;
				SELECT COUNT(ID)
				INTO V_CNT
				FROM BP_PERIODAPPREMARK
				WHERE (DESCRIPTION IS NULL)
					  AND EDIT_ID = 0
					  AND BP_PERIODAPP_ID = :NEW.ID;
			
				IF V_CNT > 0 THEN
					PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากยังไม่ระบุรายการที่แก้ไข');
				END IF;
			
				UPDATE BP_PERIODAPPREMARK
				SET EDIT_ID = 1
				WHERE EDIT_ID = 0
					  AND BP_PERIODAPP_ID = :NEW.ID;
			
				SELECT COUNT(ADG.ID)
				INTO V_CNT
				FROM BP_PERIODAPPDATAGROUP ADG,
					 BP_MTAPPDATAGROUP PDG
				WHERE ADG.BP_MTAPPDATAGROUP_ID = PDG.ID
					  AND ADG.BP_PERIODAPP_ID = :NEW.ID
					  AND ADG.COMPLETE_ID = 0;
			
				IF V_CNT > 0 THEN
					PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากข้อมูลไม่ครบถ้วน');
				END IF;
			
				SELECT SUM(A.TOTAL)
				INTO V_SUM
				FROM BP_PERIODAPPACTEXPITEM A,
					 BP_PERIODAPPACTEXP B,
					 BP_PERIODAPPACT C
				WHERE A.BP_PERIODAPPACTEXP_ID = B.ID
					  AND B.BP_PERIODAPPACT_ID = C.ID
					  AND BP_PERIODAPP_ID = :NEW.ID;
				IF V_SUM <> :NEW.BUDGETTOTAL THEN
					PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากงบประมาณรวมไม่เท่ากับผลรวมค่าใช้จ่าย');
				END IF;
			
			ELSE
				SELECT COUNT(ID)
				INTO V_CNT
				FROM BP_PERIODAPPREMARK
				WHERE EDIT_ID = 0
					  AND BP_PERIODAPP_ID = :NEW.ID;
			
				IF V_CNT > 0 THEN
					PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากยังไม่ระบุรายการที่แก้ไข');
				END IF;
			END IF;
		
		END IF;
	
		IF NVL(:NEW.MT_DEPARTMENT_ID, -1) <> NVL(:OLD.MT_DEPARTMENT_ID, -1) THEN
			DELETE FROM BP_PERIODAPPACTKPI WHERE BP_PERIODAPPACT_ID IN (SELECT ID FROM BP_PERIODAPPACT WHERE BP_PERIODAPP_ID = :NEW.ID);
		END IF;
	
		IF NVL(:NEW.BG_PLANPRDPRJ_ID, -1) <> NVL(:OLD.BG_PLANPRDPRJ_ID, -1) THEN
			DELETE FROM BP_PERIODAPPACT WHERE BP_PERIODAPP_ID = :OLD.ID;
			:NEW.BUDGETTOTAL := 0;
		END IF;
	
	ELSIF DELETING THEN
		/*      DELETE FROM BP_PERIODAPPRISK WHERE BP_PERIODAPP_ID = :OLD.ID;
        DELETE FROM BP_PERIODAPPBENEFIT WHERE BP_PERIODAPP_ID = :OLD.ID;*/
		DELETE FROM BP_PERIODAPPDATAGROUP WHERE BP_PERIODAPP_ID = :OLD.ID;
		DELETE FROM BP_PERIODAPPACT WHERE BP_PERIODAPP_ID = :OLD.ID;
		DELETE FROM BP_PERIODAPPMONITOR WHERE BP_PERIODAPP_ID = :OLD.ID;
		/*DELETE FROM BP_PERIODAPPPERSON WHERE BP_PERIODAPP_ID = :OLD.ID;*/
		DELETE FROM BP_PERIODAPPREMARK WHERE BP_PERIODAPP_ID = :OLD.ID;
	
	END IF;
END;
/

