  :NEW.TOTAL := :NEW.MONTH01 + :NEW.MONTH02 + :NEW.MONTH03 + :NEW.MONTH04 +
                :NEW.MONTH05 + :NEW.MONTH06 + :NEW.MONTH07 + :NEW.MONTH08 +
                :NEW.MONTH09 + :NEW.MONTH10 + :NEW.MONTH11 + :NEW.MONTH12;
END;
/

