CREATE TRIGGER "VNMIS"."TG_FL_STORAGE_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."FL_STORAGE" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		SELECT SQ_FL_STORAGE_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV',
												  'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
