            VALUES (TMPNUM, 'FL_STORAGE', LTYPE, 'FULLNAME', :NEW.FULLNAME, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'FL_STORAGE', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'DIRECTORY' AND NVL(:OLD.DIRECTORY, '@-VNMISLOG-@') <> NVL(:NEW.DIRECTORY, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'FL_STORAGE', LTYPE, 'DIRECTORY', :NEW.DIRECTORY, :NEW.CREATEBY);
