                IF NVL(:OLD.FILESIZE, 999999999999) <> NVL(:NEW.FILESIZE, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'FL_STORAGE', LTYPE, 'FILESIZE', :OLD.FILESIZE, :NEW.FILESIZE, :NEW.UPDATEBY);
