CREATE TRIGGER "VNMIS"."TG_HR_EVAPP_BRD" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."HR_EVAPP" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING OR UPDATING THEN
		IF NVL(:NEW.HR_STAFFBOARD1_ID, 0) <> NVL(:OLD.HR_STAFFBOARD1_ID, 0) OR NVL(:NEW.BOARDSTATUS1_ID, 0) <> NVL(:OLD.BOARDSTATUS1_ID, 0) THEN
			PD_HR_EVAPPBOARD_UBY(:NEW.ID, 1, :NEW.HR_STAFFBOARD1_ID, :NEW.BOARDSTATUS1_ID, NVL(:NEW.UPDATEBY, :NEW.CREATEBY));
		END IF;
		IF NVL(:NEW.HR_STAFFBOARD2_ID, 0) <> NVL(:OLD.HR_STAFFBOARD2_ID, 0) OR NVL(:NEW.BOARDSTATUS2_ID, 0) <> NVL(:OLD.BOARDSTATUS2_ID, 0) THEN
			PD_HR_EVAPPBOARD_UBY(:NEW.ID, 2, :NEW.HR_STAFFBOARD2_ID, :NEW.BOARDSTATUS2_ID, NVL(:NEW.UPDATEBY, :NEW.CREATEBY));
		END IF;
		IF NVL(:NEW.HR_STAFFBOARD3_ID, 0) <> NVL(:OLD.HR_STAFFBOARD3_ID, 0) OR NVL(:NEW.BOARDSTATUS3_ID, 0) <> NVL(:OLD.BOARDSTATUS3_ID, 0) THEN
			PD_HR_EVAPPBOARD_UBY(:NEW.ID, 3, :NEW.HR_STAFFBOARD3_ID, :NEW.BOARDSTATUS3_ID, NVL(:NEW.UPDATEBY, :NEW.CREATEBY));
		END IF;
		IF NVL(:NEW.HR_STAFFBOARD4_ID, 0) <> NVL(:OLD.HR_STAFFBOARD4_ID, 0) OR NVL(:NEW.BOARDSTATUS4_ID, 0) <> NVL(:OLD.BOARDSTATUS4_ID, 0) THEN
			PD_HR_EVAPPBOARD_UBY(:NEW.ID, 4, :NEW.HR_STAFFBOARD4_ID, :NEW.BOARDSTATUS4_ID, NVL(:NEW.UPDATEBY, :NEW.CREATEBY));
		END IF;
		IF NVL(:NEW.HR_STAFFBOARD5_ID, 0) <> NVL(:OLD.HR_STAFFBOARD5_ID, 0) OR NVL(:NEW.BOARDSTATUS5_ID, 0) <> NVL(:OLD.BOARDSTATUS5_ID, 0) THEN
			PD_HR_EVAPPBOARD_UBY(:NEW.ID, 5, :NEW.HR_STAFFBOARD5_ID, :NEW.BOARDSTATUS5_ID, NVL(:NEW.UPDATEBY, :NEW.CREATEBY));
		END IF;
	
	ELSIF DELETING THEN
		DELETE FROM HR_EVAPPBOARD WHERE HR_EVAPP_ID = :OLD.ID;
	
	END IF;
END;
/
CREATE TRIGGER "VNMIS"."TG_HR_EVAPP_UBY" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."HR_EVAPP" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	--V_MAXSCORE VW_HR_EVLOTWLPOS.SUM_MAXSCORE%TYPE;
	--V_SCOREAPPROVE HR_EVAPP.SCOREAPPROVE%TYPE;
	--V_RATIOACHIEVEMENT HR_EVAPP.RATIOACHIEVEMENT%TYPE;
	--V_CHILDSCORE HR_EVAPP.SCOREAPPROVE%TYPE;
	V_RATIOBEHAVIOR HR_EVLOTAPP.RATIOBEHAVIOR%TYPE;
	V_CHILDCOUNT NUMBER;
BEGIN
	IF INSERTING OR UPDATING THEN
		-- แก้ไขตำแหน่งผู้ประเมิน ถ้ามีการเปลี่ยนแปลงผู้ประเมินใหม่
		IF NVL(:NEW.HR_STAFFHEADER_ID, -1) <> NVL(:OLD.HR_STAFFHEADER_ID, -1) THEN
			BEGIN
				SELECT NVL(C.POSITIONEXNAME, B.POSITIONNAME)
				INTO   :NEW.HEADERPOSITION
				FROM   VW_HR_STAFF A
				INNER  JOIN VW_HR_POSITION B ON A.HR_POSITION_ID = B.ID
				LEFT   JOIN VW_HR_POSITIONEX C ON A.HR_POSITIONEX_ID = C.ID
				WHERE  A.ID = NVL(:NEW.HR_STAFFHEADER_ID, -1);
			EXCEPTION
				WHEN OTHERS THEN
					:NEW.HEADERPOSITION := NULL;
			END;
		END IF;
	
		IF :NEW.RATIOBEHAVIOR > 0 THEN
			SELECT RATIOBEHAVIOR INTO V_RATIOBEHAVIOR FROM HR_EVLOTAPP WHERE ID = :NEW.HR_EVLOTAPP_ID;
		
			IF V_RATIOBEHAVIOR < :NEW.RATIOBEHAVIOR THEN
				PD_SS_RAISEERROR(-20001, 'ร้อยละคะแนนพฤติกรรมการปฏิบัติราชการ (สมรรถนะ) ต้องไม่เกิน "' || V_RATIOBEHAVIOR || '"');
			END IF;
		END IF;
	
		IF (:NEW.HEADERSTATUS_ID = 30 OR :NEW.APPSTATUS_ID = 30) AND :NEW.HR_STAFFHEADER_ID IS NULL THEN
			PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากไม่ได้ระบุผู้ประเมิน กรุณาติดต่อเจ้าหน้าที่บุคลากร"');
		END IF;
	
		IF :NEW.TOTALCOURSE <> :OLD.TOTALCOURSE AND (:NEW.HEADERSTATUS_ID = 30 OR :NEW.APPSTATUS_ID = 30) THEN
			PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากส่งแบบประเมินแล้ว"');
		END IF;
	
		IF NVL(:NEW.BOARDSTATUS1_ID, 0) <> NVL(:OLD.BOARDSTATUS1_ID, 0) AND NVL(:NEW.BOARDSTATUS2_ID, 0) <> NVL(:OLD.BOARDSTATUS2_ID, 0) AND
		   NVL(:NEW.BOARDSTATUS3_ID, 0) <> NVL(:OLD.BOARDSTATUS3_ID, 0) AND NVL(:NEW.BOARDSTATUS4_ID, 0) <> NVL(:OLD.BOARDSTATUS4_ID, 0) AND
		   NVL(:NEW.BOARDSTATUS5_ID, 0) <> NVL(:OLD.BOARDSTATUS5_ID, 0) AND :NEW.APPSTATUS_ID > 20 THEN
			PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากส่งแบบประเมินแล้ว"');
		END IF;
	
		IF :NEW.APPSTATUS_ID <> :OLD.APPSTATUS_ID THEN
			IF :NEW.APPSTATUS_ID <= 20 THEN
				:NEW.HEADERSTATUS_ID := 11;
			END IF;
		END IF;
	
		IF :NEW.HEADERSTATUS_ID <> :OLD.HEADERSTATUS_ID THEN
			UPDATE HR_EVAPPWORK
			SET    HEADERSTATUS_ID = DECODE(:NEW.HEADERSTATUS_ID, 11, 10, 20, 10, :NEW.HEADERSTATUS_ID)
			WHERE  (HEADERSTATUS_ID = 10 OR HEADERSTATUS_ID = 30)
				   AND HR_EVAPP_ID = :NEW.ID;
		
			IF :NEW.HEADERSTATUS_ID = 50 THEN
				:NEW.HEADERSUBMITDATE := SYSDATE;
			
				IF :OLD.APPSTATUS_ID = 30 THEN
					:NEW.APPSTATUS_ID := 50;
				END IF;
			END IF;
		
			IF :NEW.HEADERSTATUS_ID = 50 THEN
				UPDATE HR_EVPROJECTMEMBER
				SET    ISSUBMITAPP_ID = 1
				WHERE  ID IN (SELECT A.HR_EVPROJECTMEMBER_ID
							  FROM   HR_EVAPPWORK_MU A
							  WHERE  A.HR_EVPROJECTMEMBER_ID IS NOT NULL
									 AND HR_EVAPP_ID = :NEW.ID);
				UPDATE HR_EVCOMMANDMEMBER
				SET    ISSUBMITAPP_ID = 1
				WHERE  ID IN (SELECT A.HR_EVCOMMANDMEMBER_ID
							  FROM   HR_EVAPPWORK_MU A
							  WHERE  A.HR_EVCOMMANDMEMBER_ID IS NOT NULL
									 AND HR_EVAPP_ID = :NEW.ID);
			ELSE
				UPDATE HR_EVPROJECTMEMBER
				SET    UPDATEBY = '1' || UPDATEBY,
					   ISSUBMITAPP_ID = 0
				WHERE  ID IN (SELECT A.HR_EVPROJECTMEMBER_ID
							  FROM   HR_EVAPPWORK_MU A
							  WHERE  A.HR_EVPROJECTMEMBER_ID IS NOT NULL
									 AND HR_EVAPP_ID = :NEW.ID);
			
				UPDATE HR_EVCOMMANDMEMBER
				SET    UPDATEBY = '1' || UPDATEBY,
					   ISSUBMITAPP_ID = 0
				WHERE  ID IN (SELECT A.HR_EVCOMMANDMEMBER_ID
							  FROM   HR_EVAPPWORK_MU A
							  WHERE  A.HR_EVCOMMANDMEMBER_ID IS NOT NULL
									 AND HR_EVAPP_ID = :NEW.ID);
			END IF;
		END IF;
	
		IF :NEW.APPSTATUS_ID <= 11 THEN
			:NEW.BOARDSTATUS1_ID := 10;
			:NEW.BOARDSTATUS2_ID := 10;
			:NEW.BOARDSTATUS3_ID := 10;
			:NEW.BOARDSTATUS4_ID := 10;
			:NEW.BOARDSTATUS5_ID := 10;
		END IF;
	
		IF :NEW.APPSTATUS_ID = 20 AND (NVL(:NEW.BOARDSTATUS1_ID, 0) <> NVL(:OLD.BOARDSTATUS1_ID, 0) OR NVL(:NEW.BOARDSTATUS2_ID, 0) <> NVL(:OLD.BOARDSTATUS2_ID, 0) OR
		   NVL(:NEW.BOARDSTATUS3_ID, 0) <> NVL(:OLD.BOARDSTATUS3_ID, 0) OR NVL(:NEW.BOARDSTATUS4_ID, 0) <> NVL(:OLD.BOARDSTATUS4_ID, 0) OR
		   NVL(:NEW.BOARDSTATUS5_ID, 0) <> NVL(:OLD.BOARDSTATUS5_ID, 0) OR NVL(:NEW.HR_STAFFBOARD1_ID, 0) <> NVL(:OLD.HR_STAFFBOARD1_ID, 0) OR
		   NVL(:NEW.HR_STAFFBOARD2_ID, 0) <> NVL(:OLD.HR_STAFFBOARD2_ID, 0) OR NVL(:NEW.HR_STAFFBOARD3_ID, 0) <> NVL(:OLD.HR_STAFFBOARD3_ID, 0) OR
		   NVL(:NEW.HR_STAFFBOARD4_ID, 0) <> NVL(:OLD.HR_STAFFBOARD4_ID, 0) OR NVL(:NEW.HR_STAFFBOARD5_ID, 0) <> NVL(:OLD.HR_STAFFBOARD5_ID, 0)) THEN
			IF CASE
				   WHEN :NEW.HR_STAFFBOARD1_ID IS NOT NULL THEN
					:NEW.BOARDSTATUS1_ID
				   ELSE
					60
			   END = 60 AND CASE
				   WHEN :NEW.HR_STAFFBOARD2_ID IS NOT NULL THEN
					:NEW.BOARDSTATUS2_ID
				   ELSE
					60
			   END = 60 AND CASE
				   WHEN :NEW.HR_STAFFBOARD3_ID IS NOT NULL THEN
					:NEW.BOARDSTATUS3_ID
				   ELSE
					60
			   END = 60 AND CASE
				   WHEN :NEW.HR_STAFFBOARD4_ID IS NOT NULL THEN
					:NEW.BOARDSTATUS4_ID
				   ELSE
					60
			   END = 60 AND CASE
				   WHEN :NEW.HR_STAFFBOARD5_ID IS NOT NULL THEN
					:NEW.BOARDSTATUS5_ID
				   ELSE
					60
			   END = 60 THEN
				:NEW.APPSTATUS_ID := 30;
			END IF;
		END IF;
	
		IF :NEW.APPSTATUS_ID <> :OLD.APPSTATUS_ID THEN
			IF :NEW.APPSTATUS_ID = 20 THEN
				IF :NEW.HR_STAFFBOARD1_ID IS NULL AND :NEW.HR_STAFFBOARD2_ID IS NULL AND :NEW.HR_STAFFBOARD3_ID IS NULL AND :NEW.HR_STAFFBOARD4_ID IS NULL AND :NEW.HR_STAFFBOARD5_ID IS NULL THEN
					:NEW.APPSTATUS_ID := 30;
				END IF;
			END IF;
			IF :OLD.APPSTATUS_ID = 50 THEN
				UPDATE HR_EVAPPWORK
				SET    SCORETEMP = 0,
					   SCORE = SCORETEMP
				WHERE  (HR_EVPROJECTMEMBER_ID IS NOT NULL OR HR_EVCOMMANDMEMBER_ID IS NOT NULL)
					   AND HR_EVAPP_ID = :NEW.ID;
			END IF;
		
			IF :NEW.APPSTATUS_ID IN (30, 50) THEN
				SELECT COUNT(ID)
				INTO   V_CHILDCOUNT
				FROM   HR_EVAPP_MU A
				WHERE  A.APPSTATUS_ID < 50
					   AND A.HR_STAFFHEADER_ID IS NOT NULL
					   AND A.HR_EVLOTAPP_ID = :NEW.HR_EVLOTAPP_ID
					   AND A.HR_STAFFHEADER_ID = :NEW.HR_STAFF_ID;
				IF V_CHILDCOUNT > 0 THEN
					PD_SS_RAISEERROR(-20001,
									 'ไม่สามารถยืนยันข้อมูลได้ เนื่องจากพบรายการของผู้ถูกประเมินที่ยังไม่ได้ยืนยันภาระงาน');
				END IF;
			END IF;
		
			IF :NEW.APPSTATUS_ID < 50 THEN
				:NEW.RATIOACHIEVEMENT := 0;
				:NEW.RATIOSCORE := 0;
				:NEW.HR_EVLOTSCOREITEM_ID := NULL;
				:NEW.ORDERSCORE := NULL;
			END IF;
		
			IF :NEW.APPSTATUS_ID = 60 THEN
				:NEW.SELFFINISHDATE := SYSDATE;
			END IF;
		
		END IF;
	END IF;

	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_HR_EVAPP_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;
	
		SELECT DEPARTMENTID,
			   POSITIONID,
			   EXPOSITIONID,
			   STAFFTYPE
		INTO   :NEW.MT_DEPARTMENT_ID,
			   :NEW.HR_POSITION_ID,
			   :NEW.HR_POSITIONEX_ID,
			   :NEW.HR_STAFFTYPE_ID
		FROM   PROMIS.STAFF
		WHERE  STAFFID = :NEW.HR_STAFF_ID;
	
		INSERT INTO HR_EVAPP_MU
			(ID,
			 HR_EVLOTAPP_ID,
			 HR_STAFF_ID,
			 APPSTATUS_ID,
			 HR_STAFFHEADER_ID,
			 HEADERSTATUS_ID,
			 SCOREAPPROVE,
			 RATIOACHIEVEMENT,
			 RATIOBEHAVIOR,
			 RATIOSCORE)
		VALUES
			(:NEW.ID,
			 :NEW.HR_EVLOTAPP_ID,
			 :NEW.HR_STAFF_ID,
			 :NEW.APPSTATUS_ID,
			 :NEW.HR_STAFFHEADER_ID,
			 :NEW.HEADERSTATUS_ID,
			 :NEW.SCOREAPPROVE,
			 NVL(:NEW.RATIOACHIEVEMENT, 0),
			 :NEW.RATIOBEHAVIOR,
			 :NEW.RATIOSCORE);
	
	ELSIF UPDATING THEN
		IF NVL(:OLD.APPSTATUS_ID, 10) > 10 AND :NEW.HR_EVPOSITION_ID <> :OLD.HR_EVPOSITION_ID THEN
			PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากตำแหน่งประเมินมีการเปลี่ยนแปลง');
		END IF;
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	
		IF :NEW.HR_EVPOSITION_ID <> :OLD.HR_EVPOSITION_ID THEN
			DELETE FROM HR_EVAPPWLPOSGRPWLREM
			WHERE  HR_EVLOTWLPOSGRPWL_ID NOT IN (SELECT E.ID
												 FROM   HR_EVLOTAPP B
												 INNER  JOIN HR_EVLOTWLPOS C ON B.HR_EVLOTWL_ID = C.HR_EVLOTWL_ID
												 INNER  JOIN HR_EVLOTWLPOSGRP D ON C.ID = D.HR_EVLOTWLPOS_ID
												 INNER  JOIN HR_EVLOTWLPOSGRPWL E ON D.ID = E.HR_EVLOTWLPOSGRP_ID
												 WHERE  B.ID = :NEW.HR_EVLOTAPP_ID
														AND C.HR_EVPOSITION_ID = :NEW.HR_EVPOSITION_ID)
				   AND HR_EVAPP_ID = :NEW.ID
				   AND HR_EVLOTWLPOSGRPWL_ID IS NOT NULL;
		
			DELETE FROM HR_EVAPPWORK
			WHERE  HR_EVLOTWLPOSGRPWL_ID NOT IN (SELECT E.ID
												 FROM   HR_EVLOTAPP B
												 INNER  JOIN HR_EVLOTWLPOS C ON B.HR_EVLOTWL_ID = C.HR_EVLOTWL_ID
												 INNER  JOIN HR_EVLOTWLPOSGRP D ON C.ID = D.HR_EVLOTWLPOS_ID
												 INNER  JOIN HR_EVLOTWLPOSGRPWL E ON D.ID = E.HR_EVLOTWLPOSGRP_ID
												 WHERE  B.ID = :NEW.HR_EVLOTAPP_ID
														AND C.HR_EVPOSITION_ID = :NEW.HR_EVPOSITION_ID)
				   AND HR_EVAPP_ID = :NEW.ID
				   AND HR_EVLOTWLPOSGRPWL_ID IS NOT NULL;
		END IF;
		UPDATE HR_EVAPP_MU
		SET    HR_EVLOTAPP_ID = :NEW.HR_EVLOTAPP_ID,
			   HR_STAFF_ID = :NEW.HR_STAFF_ID,
			   APPSTATUS_ID = :NEW.APPSTATUS_ID,
			   HR_STAFFHEADER_ID = :NEW.HR_STAFFHEADER_ID,
			   HEADERSTATUS_ID = :NEW.HEADERSTATUS_ID,
			   SCOREAPPROVE = :NEW.SCOREAPPROVE,
			   RATIOACHIEVEMENT = NVL(:NEW.RATIOACHIEVEMENT, 0),
			   RATIOBEHAVIOR = :NEW.RATIOBEHAVIOR,
			   RATIOSCORE = :NEW.RATIOSCORE
		WHERE  ID = :NEW.ID;
	
	ELSIF DELETING THEN
		IF NVL(:OLD.APPSTATUS_ID, 10) NOT IN (10, 11) THEN
			PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากสถานะรายการไม่ใช่ 10 หรือ 11');
		END IF;
		DELETE FROM HR_EVAPPWORKITEM WHERE HR_EVAPPWORK_ID IN (SELECT ID FROM HR_EVAPPWORK WHERE HR_EVAPP_ID = :OLD.ID);
		DELETE FROM HR_EVAPPWORK WHERE HR_EVAPP_ID = :OLD.ID;
		DELETE FROM HR_EVAPPREMARK WHERE HR_EVAPP_ID = :OLD.ID;
		DELETE FROM HR_EVAPP_MU WHERE ID = :OLD.ID;
	END IF;

	IF NVL(:NEW.APPSTATUS_ID, 0) <> NVL(:OLD.APPSTATUS_ID, 0) AND NVL(:NEW.APPSTATUS_ID, 0) = 11 THEN
		INSERT INTO SS_BASICSENDMAIL
			(MAILADDRESSTO,
			 MAILSUBJECT,
			 MAILBODY,
			 MAILBODYISHTML_ID,
			 SS_MAILCONFIG_ID,
			 CREATEBY)
			SELECT ST.EVAPPEMAILACCOUNT,
				   'ทบทวนภาระงานใหม่',
				   'เรียน ' || S.SNAMEFULL || '<br><br>ขอให้ทบทวนภาระงานใหม่ตามข้อเสนอแนะ/แก้ไข จากผู้บังคับบัญชา และส่งข้อมูลอีกครั้ง<br><br>ข้อเสนอแนะ/แก้ไข จากผู้บังคับบัญชา&nbsp;:&nbsp;' ||
				   :NEW.HEADERADDITION,
				   1,
				   1,
				   :NEW.UPDATEBY
			FROM   HR_STAFF ST
			INNER  JOIN VW_HR_STAFF_NAME S ON ST.ID = S.ID
			WHERE  ST.ID = :NEW.HR_STAFF_ID
				   AND ST.EVAPPEMAILACCOUNT IS NOT NULL
				   AND ST.EVAPPEMAILRECEIVEHEAD_ID = 1;
	END IF;
END;
/

