-- ----------------------------
-- Triggers structure for table HR_EVAPPWORK
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_HR_EVAPPWORK_UBY" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."HR_EVAPPWORK" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_HR_EVAPPWORK_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;
	
		INSERT INTO HR_EVAPPWORK_MU
			(ID,
			 HR_EVAPP_ID,
			 HR_EVLOTWLPOSGRPWL_ID,
			 HR_EVPROJECTMEMBER_ID,
			 ORDERNO,
			 DESCRIPTION,
			 TOTALWORK,
			 SCORE,
			 HEADERSTATUS_ID,
			 URL,
			 ISHEADERADD_ID,
			 SCORETEMP,
			 HEADERREMARK,
			 HR_EVCOMMANDMEMBER_ID)
		VALUES
			(:NEW.ID,
			 :NEW.HR_EVAPP_ID,
			 :NEW.HR_EVLOTWLPOSGRPWL_ID,
			 :NEW.HR_EVPROJECTMEMBER_ID,
			 :NEW.ORDERNO,
			 :NEW.DESCRIPTION,
			 :NEW.TOTALWORK,
			 :NEW.SCORE,
			 :NEW.HEADERSTATUS_ID,
			 :NEW.URL,
			 :NEW.ISHEADERADD_ID,
			 :NEW.SCORETEMP,
			 :NEW.HEADERREMARK,
			 :NEW.HR_EVCOMMANDMEMBER_ID);
	
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	
		UPDATE HR_EVAPPWORK_MU
		SET    HR_EVAPP_ID = :NEW.HR_EVAPP_ID,
			   HR_EVLOTWLPOSGRPWL_ID = :NEW.HR_EVLOTWLPOSGRPWL_ID,
			   HR_EVPROJECTMEMBER_ID = :NEW.HR_EVPROJECTMEMBER_ID,
			   ORDERNO = :NEW.ORDERNO,
			   DESCRIPTION = :NEW.DESCRIPTION,
			   TOTALWORK = :NEW.TOTALWORK,
			   SCORE = :NEW.SCORE,
			   HEADERSTATUS_ID = :NEW.HEADERSTATUS_ID,
			   URL = :NEW.URL,
			   ISHEADERADD_ID = :NEW.ISHEADERADD_ID,
			   SCORETEMP = :NEW.SCORETEMP,
			   HEADERREMARK = :NEW.HEADERREMARK,
			   HR_EVCOMMANDMEMBER_ID = :NEW.HR_EVCOMMANDMEMBER_ID
		WHERE  ID = :OLD.ID;
	
	ELSIF DELETING THEN
		DELETE FROM HR_EVAPPWORKITEM WHERE HR_EVAPPWORK_ID = :OLD.ID;
		DELETE FROM HR_EVAPPWORK_MU WHERE ID = :OLD.ID;
	END IF;

END;
/

