-- ----------------------------
-- Triggers structure for table HR_EVCOMMAND
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_HR_EVCOMMAND_UBY" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."HR_EVCOMMAND" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_ISCLEARDATA_ID NUMBER;
BEGIN
	SELECT NVL(FN_SS_PARAMETER_GETNUMBER('SS_CLEARDATA'), 0) INTO V_ISCLEARDATA_ID FROM DUAL;

	IF (UPDATING OR DELETING) AND :OLD.ISSUBMITAPP_ID = 1 AND SUBSTR(:NEW.UPDATEBY, 1, 1) <> '1' AND V_ISCLEARDATA_ID = 0 AND NVL(:NEW.COMMANDSTATUS_ID, :OLD.COMMANDSTATUS_ID) <> 60 THEN
		PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากยืนยันการอ้างอิงในภาระงานแล้ว');
	END IF;

	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_HR_EVCOMMAND_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;

	ELSIF UPDATING THEN
		IF SUBSTR(:NEW.UPDATEBY, 1, 1) = '1' THEN
			:NEW.UPDATEBY := SUBSTR(:NEW.UPDATEBY, 2);
		END IF;
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;

	ELSIF DELETING THEN
		DELETE FROM HR_EVCOMMANDMEMBER WHERE HR_EVCOMMAND_ID = :OLD.ID;
		DELETE FROM HR_EVCOMMANDKEY WHERE HR_EVCOMMAND_ID = :OLD.ID;
		DELETE FROM FL_STORAGE WHERE ID = NVL(:OLD.FL_STORAGE_ID, 0);
	END IF;

	IF NOT DELETING AND (:NEW.HR_EVLOTAPP_ID <> :OLD.HR_EVLOTAPP_ID) THEN
		DELETE FROM HR_EVCOMMANDGRPWL
		WHERE  HR_EVLOTWLPOS_ID NOT IN (SELECT LP.ID FROM HR_EVLOTAPP A INNER JOIN HR_EVLOTWLPOS LP ON A.HR_EVLOTWL_ID = LP.HR_EVLOTWL_ID WHERE A.ID = :NEW.HR_EVLOTAPP_ID);
	END IF;
END;
/

