-- ----------------------------
-- Triggers structure for table HR_EVCOMMANDGRPWL
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_HR_EVCOMMANDGRPWL_UBY" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."HR_EVCOMMANDGRPWL" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_EVLOTWLSOURCE_ID HR_EVLOTAPP.HR_EVLOTWL_ID%TYPE;
	V_EVLOTWLCURRENT_ID HR_EVLOTAPP.HR_EVLOTWL_ID%TYPE;
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_HR_EVCOMMANDGRPWL_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;

	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;

	IF (INSERTING OR UPDATING) THEN
		SELECT L.HR_EVLOTWL_ID INTO V_EVLOTWLSOURCE_ID FROM HR_EVCOMMAND C INNER JOIN HR_EVLOTAPP L ON C.HR_EVLOTAPP_ID = L.ID WHERE C.ID = :NEW.HR_EVCOMMAND_ID;

		SELECT HR_EVLOTWL_ID INTO V_EVLOTWLCURRENT_ID FROM HR_EVLOTWLPOS WHERE ID = :NEW.HR_EVLOTWLPOS_ID;

		IF V_EVLOTWLSOURCE_ID <> V_EVLOTWLCURRENT_ID THEN
			PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากชุดภาะงานไม่สัมพันธ์กับคำสั่ง');
		END IF;
	END IF;

END;
/

