-- ----------------------------
-- Triggers structure for table HR_EVCOMMANDMEMBER
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_HR_EVCOMMANDMEMBER_UBY" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."HR_EVCOMMANDMEMBER" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_CNT NUMBER;
	V_ISCLEARDATA_ID NUMBER;
	V_ORDERNO HR_EVCOMMANDMEMBER.ORDERNO%TYPE := 0;
BEGIN
	SELECT NVL(FN_SS_PARAMETER_GETNUMBER('SS_CLEARDATA'), 0) INTO V_ISCLEARDATA_ID FROM DUAL;

	IF (UPDATING OR DELETING) AND :OLD.ISSUBMITAPP_ID = 1 AND SUBSTR(:NEW.UPDATEBY, 1, 1) <> '1' AND V_ISCLEARDATA_ID = 0 THEN
		PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากยืนยันการอ้างอิงในภาระงานแล้ว');
	END IF;

	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_HR_EVCOMMANDMEMBER_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;

		BEGIN
			SELECT NVL(MAX(ORDERNO), 0) INTO V_ORDERNO FROM HR_EVCOMMANDMEMBER_MU A WHERE A.HR_EVCOMMAND_ID = :NEW.HR_EVCOMMAND_ID;
		EXCEPTION
			WHEN OTHERS THEN
				V_ORDERNO := 0;
		END;

		INSERT INTO HR_EVCOMMANDMEMBER_MU
			(ID,
			 HR_EVCOMMAND_ID,
			 ORDERNO,
			 HR_STAFF_ID,
			 ISACTIVE_ID,
			 ISSUBMITAPP_ID,
			 HR_EVCOMMANDKEY_ID)
		VALUES
			(:NEW.ID,
			 :NEW.HR_EVCOMMAND_ID,
			 V_ORDERNO + 1,
			 :NEW.HR_STAFF_ID,
			 :NEW.ISACTIVE_ID,
			 :NEW.ISSUBMITAPP_ID,
			 :NEW.HR_EVCOMMANDKEY_ID);

		IF :NEW.HR_EVCOMMANDKEY_ID IS NOT NULL THEN
			UPDATE HR_EVCOMMANDKEY SET ISACTIVE_ID = 1 WHERE ID = NVL(:NEW.HR_EVCOMMANDKEY_ID, 0);
		END IF;

	ELSIF UPDATING THEN
		IF SUBSTR(:NEW.UPDATEBY, 1, 1) = '1' THEN
			:NEW.UPDATEBY := SUBSTR(:NEW.UPDATEBY, 2);
		END IF;
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;

		IF NVL(:OLD.HR_EVCOMMANDKEY_ID, 0) <> NVL(:NEW.HR_EVCOMMANDKEY_ID, 0) THEN
			IF NVL(:NEW.HR_EVCOMMANDKEY_ID, 0) > 0 THEN
				SELECT COUNT(ID)
				INTO   V_CNT
				FROM   HR_EVCOMMANDMEMBER_MU
				WHERE  HR_EVCOMMANDKEY_ID IS NOT NULL
					   AND HR_EVCOMMANDKEY_ID = NVL(:NEW.HR_EVCOMMANDKEY_ID, 0);

				IF V_CNT > 0 THEN
					PD_SS_RAISEERROR(-20001, 'ไม่สามารถใช้ Serial Key นี้ได้ เนื่องจากได้ลงทะเบียนเรียบร้อยแล้ว');
				END IF;
				UPDATE HR_EVCOMMANDKEY SET ISACTIVE_ID = 1 WHERE ID = NVL(:NEW.HR_EVCOMMANDKEY_ID, 0);
				--ELSE
				--UPDATE HR_EVCOMMANDKEY SET ISACTIVE_ID = 0 WHERE ID = NVL(:OLD.HR_EVCOMMANDKEY_ID, 0);
			END IF;
		END IF;

		UPDATE HR_EVCOMMANDMEMBER_MU
		SET    HR_EVCOMMAND_ID = :NEW.HR_EVCOMMAND_ID,
			   ORDERNO = :NEW.ORDERNO,
			   HR_STAFF_ID = :NEW.HR_STAFF_ID,
			   ISACTIVE_ID = :NEW.ISACTIVE_ID,
			   ISSUBMITAPP_ID = :NEW.ISSUBMITAPP_ID,
			   HR_EVCOMMANDKEY_ID = :NEW.HR_EVCOMMANDKEY_ID
		WHERE  ID = :NEW.ID;

		IF :NEW.ISACTIVE_ID <> :OLD.ISACTIVE_ID AND :NEW.ISACTIVE_ID = 0 THEN
			DELETE FROM HR_EVAPPWORK WHERE HR_EVCOMMANDMEMBER_ID = :NEW.ID;
		END IF;

	ELSIF DELETING THEN
		DELETE FROM HR_EVAPPWORK WHERE HR_EVCOMMANDMEMBER_ID = :OLD.ID;
		DELETE FROM HR_EVCOMMANDMEMBER_MU WHERE ID = :OLD.ID;
		--UPDATE HR_EVCOMMANDKEY SET ISACTIVE_ID = 0 WHERE ID = NVL(:OLD.HR_EVCOMMANDKEY_ID, 0);
	END IF;

	SELECT COUNT(ID) INTO V_CNT FROM HR_EVCOMMANDMEMBER_MU WHERE HR_EVCOMMAND_ID = NVL(:OLD.ID, :NEW.ID);

	UPDATE HR_EVCOMMAND
	SET    ISSUBMITAPP_ID = DECODE(V_CNT, 0, 0, 1),
		   UPDATEBY = '1' || UPDATEBY
	WHERE  ID = NVL(:OLD.ID, :NEW.ID);
END;
/

