-- ----------------------------
-- Triggers structure for table HR_EVLOTSCOREITEM
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_HR_EVLOTSCOREITEM_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."HR_EVLOTSCOREITEM" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_TOTALSCORE HR_EVLOTSCORE.TOTALSCORE%TYPE;
BEGIN
	IF INSERTING OR UPDATING THEN
		SELECT TOTALSCORE INTO V_TOTALSCORE FROM HR_EVLOTSCORE WHERE ID = :NEW.HR_EVLOTSCORE_ID;
	
		IF :NEW.MAXSCORE > V_TOTALSCORE THEN
			PD_SS_RAISEERROR(-20001, 'คะแนนสูงสุดต้องไม่เกิน "' || TO_CHAR(V_TOTALSCORE) || '"');
		END IF;
	
		IF :NEW.MINSCORE >= :NEW.MAXSCORE THEN
			PD_SS_RAISEERROR(-20001, 'คะแนนต่ำสุดต้องน้อยกว่าคะแนนสูงสุด');
		END IF;
	END IF;

	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_HR_EVLOTSCOREITEM_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;
	
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
/

