-- ----------------------------
-- Triggers structure for table HR_EVPOSITION
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_HR_EVPOSITION_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."HR_EVPOSITION" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_EVPOSITIONGROUPCODE HR_EVPOSITIONGROUP.EVPOSITIONGROUPCODE%TYPE;
	V_EVPOSITIONLEVELCODE HR_EVPOSITIONLEVEL.EVPOSITIONLEVELCODE%TYPE;
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_HR_EVPOSITION_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;
	
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;

	IF (INSERTING OR UPDATING) AND (NVL(:NEW.HR_EVPOSITIONGROUP_ID, -1) <> NVL(:OLD.HR_EVPOSITIONGROUP_ID, -1) OR NVL(:NEW.HR_EVPOSITIONLEVEL_ID, -1) <> NVL(:OLD.HR_EVPOSITIONLEVEL_ID, -1)) THEN
		BEGIN
			SELECT EVPOSITIONGROUPCODE INTO V_EVPOSITIONGROUPCODE FROM HR_EVPOSITIONGROUP WHERE ID = :NEW.HR_EVPOSITIONGROUP_ID;
		EXCEPTION
			WHEN OTHERS THEN
				V_EVPOSITIONGROUPCODE := NULL;
		END;
	
		BEGIN
			SELECT EVPOSITIONLEVELCODE INTO V_EVPOSITIONLEVELCODE FROM HR_EVPOSITIONLEVEL WHERE ID = :NEW.HR_EVPOSITIONLEVEL_ID;
		EXCEPTION
			WHEN OTHERS THEN
				V_EVPOSITIONLEVELCODE := '00';
		END;
	
		:NEW.EVPOSITIONCODE := V_EVPOSITIONGROUPCODE || V_EVPOSITIONLEVELCODE;
	END IF;
END;
/

