-- ----------------------------
-- Triggers structure for table HR_EVPROJECTMEMBER
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_HR_EVPROJECTMEMBER_UBY" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."HR_EVPROJECTMEMBER" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_CNT NUMBER;
	V_ISCLEARDATA_ID NUMBER;
	V_ORDERNO HR_EVPROJECTMEMBER.ORDERNO%TYPE := 0;
BEGIN
	SELECT NVL(FN_SS_PARAMETER_GETNUMBER('SS_CLEARDATA'), 0) INTO V_ISCLEARDATA_ID FROM DUAL;

	IF (UPDATING OR DELETING) AND :OLD.ISSUBMITAPP_ID = 1 AND SUBSTR(:NEW.UPDATEBY, 1, 1) <> '1' AND V_ISCLEARDATA_ID = 0 THEN
		PD_SS_RAISEERROR(-20001, 'ไม่สามารถทำรายการได้ เนื่องจากยืนยันการอ้างอิงในภาระงานแล้ว');
	END IF;

	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_HR_EVPROJECTMEMBER_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;
	
		BEGIN
			SELECT NVL(MAX(ORDERNO), 0) INTO V_ORDERNO FROM HR_EVPROJECTMEMBER_MU A WHERE A.HR_EVPROJECT_ID = :NEW.HR_EVPROJECT_ID;
		EXCEPTION
			WHEN OTHERS THEN
				V_ORDERNO := 0;
		END;
	
		:NEW.ORDERNO := V_ORDERNO + 1;
	
		INSERT INTO HR_EVPROJECTMEMBER_MU
			(ID,
			 HR_EVPROJECT_ID,
			 ORDERNO,
			 HR_STAFF_ID,
			 HR_EVPRJPOSITION_ID,
			 PROPORTION,
			 ISACTIVE_ID,
			 ISSUBMITAPP_ID,
			 HR_EVPROJECTKEY_ID)
		VALUES
			(:NEW.ID,
			 :NEW.HR_EVPROJECT_ID,
			 V_ORDERNO + 1,
			 :NEW.HR_STAFF_ID,
			 :NEW.HR_EVPRJPOSITION_ID,
			 :NEW.PROPORTION,
			 :NEW.ISACTIVE_ID,
			 :NEW.ISSUBMITAPP_ID,
			 :NEW.HR_EVPROJECTKEY_ID);
	
		IF :NEW.HR_EVPROJECTKEY_ID IS NOT NULL THEN
			UPDATE HR_EVPROJECTKEY SET ISACTIVE_ID = 1 WHERE ID = NVL(:NEW.HR_EVPROJECTKEY_ID, 0);
		END IF;
	
	ELSIF UPDATING THEN
		IF SUBSTR(:NEW.UPDATEBY, 1, 1) = '1' THEN
			:NEW.UPDATEBY := SUBSTR(:NEW.UPDATEBY, 2);
		END IF;
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	
		IF NVL(:OLD.HR_EVPROJECTKEY_ID, 0) <> NVL(:NEW.HR_EVPROJECTKEY_ID, 0) THEN
			IF NVL(:NEW.HR_EVPROJECTKEY_ID, 0) > 0 THEN
				SELECT COUNT(ID)
				INTO   V_CNT
				FROM   HR_EVPROJECTMEMBER_MU
				WHERE  HR_EVPROJECTKEY_ID IS NOT NULL
					   AND HR_EVPROJECTKEY_ID = NVL(:NEW.HR_EVPROJECTKEY_ID, 0);
			
				IF V_CNT > 0 THEN
					PD_SS_RAISEERROR(-20001, 'ไม่สามารถใช้ Serial Key นี้ได้ เนื่องจากได้ลงทะเบียนเรียบร้อยแล้ว');
				END IF;
				UPDATE HR_EVPROJECTKEY SET ISACTIVE_ID = 1 WHERE ID = NVL(:NEW.HR_EVPROJECTKEY_ID, 0);
				--ELSE
				--UPDATE HR_EVPROJECTKEY SET ISACTIVE_ID = 0 WHERE ID = NVL(:OLD.HR_EVPROJECTKEY_ID, 0);
			END IF;
		END IF;
	
		UPDATE HR_EVPROJECTMEMBER_MU
		SET    HR_EVPROJECT_ID = :NEW.HR_EVPROJECT_ID,
			   ORDERNO = :NEW.ORDERNO,
			   HR_STAFF_ID = :NEW.HR_STAFF_ID,
			   HR_EVPRJPOSITION_ID = :NEW.HR_EVPRJPOSITION_ID,
			   PROPORTION = :NEW.PROPORTION,
			   ISACTIVE_ID = :NEW.ISACTIVE_ID,
			   ISSUBMITAPP_ID = :NEW.ISSUBMITAPP_ID,
			   HR_EVPROJECTKEY_ID = :NEW.HR_EVPROJECTKEY_ID
		WHERE  ID = :NEW.ID;
	
		IF :NEW.ISACTIVE_ID <> :OLD.ISACTIVE_ID AND :NEW.ISACTIVE_ID = 0 THEN
			DELETE FROM HR_EVAPPWORK WHERE HR_EVPROJECTMEMBER_ID = :NEW.ID;
		END IF;
	
	ELSIF DELETING THEN
		DELETE FROM HR_EVAPPWORK WHERE HR_EVPROJECTMEMBER_ID = :OLD.ID;
		DELETE FROM HR_EVPROJECTMEMBER_MU WHERE ID = :OLD.ID;
		IF V_ISCLEARDATA_ID = 0 THEN
			UPDATE HR_EVPROJECTKEY SET ISACTIVE_ID = 0 WHERE ID = NVL(:OLD.HR_EVPROJECTKEY_ID, 0);
		END IF;
	END IF;

	SELECT COUNT(ID) INTO V_CNT FROM HR_EVPROJECTMEMBER_MU WHERE HR_EVPROJECT_ID = NVL(:OLD.ID, :NEW.ID);

	UPDATE HR_EVPROJECT
	SET    ISSUBMITAPP_ID = DECODE(V_CNT, 0, 0, 1),
		   UPDATEBY = '1' || UPDATEBY
	WHERE  ID = NVL(:OLD.ID, :NEW.ID);
END;
/

