CREATE TRIGGER "VNMIS"."TL_SS_APPLICATION" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_APPLICATION" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_APPLICATION'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.ACTIVE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ACTIVE_ID', :OLD.ACTIVE_ID, VBY);
            END IF;

            IF :OLD.APPLICATIONNAME IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'APPLICATIONNAME', :OLD.APPLICATIONNAME, VBY);
            END IF;

            IF :OLD.APPLICATIONNAMEENG IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'APPLICATIONNAMEENG', :OLD.APPLICATIONNAMEENG, VBY);
            END IF;

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.ORDERNO IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ORDERNO', :OLD.ORDERNO, VBY);
            END IF;

            IF :OLD.WEBAPPLICATIONNAME IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'WEBAPPLICATIONNAME', :OLD.WEBAPPLICATIONNAME, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ACTIVE_ID', :NEW.ACTIVE_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'APPLICATIONNAME', :NEW.APPLICATIONNAME, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ORDERNO', :NEW.ORDERNO, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'ACTIVE_ID' AND NVL(:OLD.ACTIVE_ID, '999999999999') <> NVL(:NEW.ACTIVE_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ACTIVE_ID', :NEW.ACTIVE_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'APPLICATIONNAME' AND NVL(:OLD.APPLICATIONNAME, '@-VNMISLOG-@') <> NVL(:NEW.APPLICATIONNAME, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'APPLICATIONNAME', :NEW.APPLICATIONNAME, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'APPLICATIONNAMEENG' AND NVL(:OLD.APPLICATIONNAMEENG, '@-VNMISLOG-@') <> NVL(:NEW.APPLICATIONNAMEENG, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'APPLICATIONNAMEENG', :NEW.APPLICATIONNAMEENG, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'ORDERNO' AND NVL(:OLD.ORDERNO, '999999999999') <> NVL(:NEW.ORDERNO, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ORDERNO', :NEW.ORDERNO, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'WEBAPPLICATIONNAME' AND NVL(:OLD.WEBAPPLICATIONNAME, '@-VNMISLOG-@') <> NVL(:NEW.WEBAPPLICATIONNAME, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'WEBAPPLICATIONNAME', :NEW.WEBAPPLICATIONNAME, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

                IF NVL(:OLD.ACTIVE_ID, 999999999999) <> NVL(:NEW.ACTIVE_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ACTIVE_ID', :OLD.ACTIVE_ID, :NEW.ACTIVE_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.APPLICATIONNAME, '@-VNMISLOG-@') <> NVL(:NEW.APPLICATIONNAME, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'APPLICATIONNAME', :OLD.APPLICATIONNAME, :NEW.APPLICATIONNAME, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.APPLICATIONNAMEENG, '@-VNMISLOG-@') <> NVL(:NEW.APPLICATIONNAMEENG, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'APPLICATIONNAMEENG', :OLD.APPLICATIONNAMEENG, :NEW.APPLICATIONNAMEENG, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;


                IF NVL(:OLD.ORDERNO, 999999999999) <> NVL(:NEW.ORDERNO, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ORDERNO', :OLD.ORDERNO, :NEW.ORDERNO, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.WEBAPPLICATIONNAME, '@-VNMISLOG-@') <> NVL(:NEW.WEBAPPLICATIONNAME, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'WEBAPPLICATIONNAME', :OLD.WEBAPPLICATIONNAME, :NEW.WEBAPPLICATIONNAME, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'ACTIVE_ID' AND NVL(:OLD.ACTIVE_ID, '999999999999') <> NVL(:NEW.ACTIVE_ID, '999999999999') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, COLNAME, :OLD.ACTIVE_ID, :NEW.ACTIVE_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='APPLICATIONNAME'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, COLNAME, :OLD.APPLICATIONNAME, :NEW.APPLICATIONNAME, :NEW.UPDATEBY);

                ELSIF COLNAME ='APPLICATIONNAMEENG'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, COLNAME, :OLD.APPLICATIONNAMEENG, :NEW.APPLICATIONNAMEENG, :NEW.UPDATEBY);

                ELSIF COLNAME ='ORDERNO'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, COLNAME, :OLD.ORDERNO, :NEW.ORDERNO, :NEW.UPDATEBY);

                ELSIF COLNAME ='WEBAPPLICATIONNAME'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, COLNAME, :OLD.WEBAPPLICATIONNAME, :NEW.WEBAPPLICATIONNAME, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_APPLICATION', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

