-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_SS_APPLICATIONCONFEDIT_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."SS_APPLICATIONCONFEDIT" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_SS_APPLICATIONCONFEDIT_ID.NEXTVAL
			INTO   :NEW.ID
			FROM   DUAL;
