			:NEW.MAILADDRESSTO := REPLACE(:NEW.MAILADDRESSTO, ';', ',');
		END IF;
		IF :NEW.MAILADDRESSCC IS NOT NULL AND
		   INSTR(:NEW.MAILADDRESSCC, ';') > 0 THEN
			:NEW.MAILADDRESSCC := REPLACE(:NEW.MAILADDRESSCC, ';', ',');
		END IF;
		IF :NEW.MAILADDRESSBCC IS NOT NULL AND
		   INSTR(:NEW.MAILADDRESSBCC, ';') > 0 THEN
			:NEW.MAILADDRESSBCC := REPLACE(:NEW.MAILADDRESSBCC, ';', ',');
		END IF;
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK() = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV',
												  'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
