	IF :OLD.MAILADDRESSTO <> :NEW.MAILADDRESSTO AND
	   :NEW.MAILADDRESSTO IS NOT NULL AND
	   INSTR(:NEW.MAILADDRESSTO, ';') > 0 THEN
		:NEW.MAILADDRESSTO := REPLACE(:NEW.MAILADDRESSTO, ';', ',');
	END IF;
	IF :OLD.MAILADDRESSCC <> :NEW.MAILADDRESSCC AND
	   :NEW.MAILADDRESSCC IS NOT NULL AND
	   INSTR(:NEW.MAILADDRESSCC, ';') > 0 THEN
		:NEW.MAILADDRESSCC := REPLACE(:NEW.MAILADDRESSCC, ';', ',');
