                ELSIF COLNAME ='DEFAULT_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_BYTEDES', LTYPE, COLNAME, :OLD.DEFAULT_ID, :NEW.DEFAULT_ID, :NEW.UPDATEBY);

                ELSIF COLNAME ='ORDERNO'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
