-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_SS_COINLOCKER_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."SS_COINLOCKER" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		SELECT SQ_SS_COINLOCKER_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		:NEW.EXPIREDATETIME := SYSDATE + :NEW.EXPIREEXTENDMINUTES / 1440;
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV',
												  'CLIENT_IDENTIFIER');
			IF :NEW.UPDATEBYCLIENT_ID IS NULL THEN
				:NEW.UPDATEBYCLIENT_ID := :NEW.CREATEBYCLIENT_ID;
			END IF;
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
/

