CREATE TRIGGER "VNMIS"."TL_SS_CONFIG" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_CONFIG" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_CONFIG'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.CONFIGCODE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'CONFIGCODE', :OLD.CONFIGCODE, VBY);
            END IF;

            IF :OLD.CONFIGVALUE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'CONFIGVALUE', :OLD.CONFIGVALUE, VBY);
            END IF;

            IF :OLD.DESCRIPTION IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'DESCRIPTION', :OLD.DESCRIPTION, VBY);
            END IF;

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.ISSECRET_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'ISSECRET_ID', :OLD.ISSECRET_ID, VBY);
            END IF;

            IF :OLD.SS_APPLICATION_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'SS_APPLICATION_ID', :OLD.SS_APPLICATION_ID, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'CONFIGCODE', :NEW.CONFIGCODE, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'ISSECRET_ID', :NEW.ISSECRET_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'SS_APPLICATION_ID', :NEW.SS_APPLICATION_ID, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'CONFIGCODE' AND NVL(:OLD.CONFIGCODE, '@-VNMISLOG-@') <> NVL(:NEW.CONFIGCODE, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'CONFIGCODE', :NEW.CONFIGCODE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'CONFIGVALUE' AND NVL(:OLD.CONFIGVALUE, '@-VNMISLOG-@') <> NVL(:NEW.CONFIGVALUE, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'CONFIGVALUE', :NEW.CONFIGVALUE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'DESCRIPTION' AND NVL(:OLD.DESCRIPTION, '@-VNMISLOG-@') <> NVL(:NEW.DESCRIPTION, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'DESCRIPTION', :NEW.DESCRIPTION, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'ISSECRET_ID' AND NVL(:OLD.ISSECRET_ID, '999999999999') <> NVL(:NEW.ISSECRET_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'ISSECRET_ID', :NEW.ISSECRET_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SS_APPLICATION_ID' AND NVL(:OLD.SS_APPLICATION_ID, '999999999999') <> NVL(:NEW.SS_APPLICATION_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'SS_APPLICATION_ID', :NEW.SS_APPLICATION_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

                IF NVL(:OLD.CONFIGCODE, '@-VNMISLOG-@') <> NVL(:NEW.CONFIGCODE, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_CONFIG', LTYPE, 'CONFIGCODE', :OLD.CONFIGCODE, :NEW.CONFIGCODE, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.CONFIGVALUE, '@-VNMISLOG-@') <> NVL(:NEW.CONFIGVALUE, '@-VNMISLOG-@') THEN
