CREATE TRIGGER "VNMIS"."TL_SS_EDITDEPARTMENT" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_EDITDEPARTMENT" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_EDITDEPARTMENT'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.MT_DEPARTMENTFROM_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'MT_DEPARTMENTFROM_ID', :OLD.MT_DEPARTMENTFROM_ID, VBY);
            END IF;

            IF :OLD.MT_DEPARTMENTTO_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'MT_DEPARTMENTTO_ID', :OLD.MT_DEPARTMENTTO_ID, VBY);
            END IF;

            IF :OLD.SS_MENU_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'SS_MENU_ID', :OLD.SS_MENU_ID, VBY);
            END IF;

            IF :OLD.SS_ROLE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'SS_ROLE_ID', :OLD.SS_ROLE_ID, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'MT_DEPARTMENTFROM_ID', :NEW.MT_DEPARTMENTFROM_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'MT_DEPARTMENTTO_ID', :NEW.MT_DEPARTMENTTO_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'SS_MENU_ID', :NEW.SS_MENU_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'SS_ROLE_ID', :NEW.SS_ROLE_ID, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'MT_DEPARTMENTFROM_ID' AND NVL(:OLD.MT_DEPARTMENTFROM_ID, '999999999999') <> NVL(:NEW.MT_DEPARTMENTFROM_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'MT_DEPARTMENTFROM_ID', :NEW.MT_DEPARTMENTFROM_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'MT_DEPARTMENTTO_ID' AND NVL(:OLD.MT_DEPARTMENTTO_ID, '999999999999') <> NVL(:NEW.MT_DEPARTMENTTO_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'MT_DEPARTMENTTO_ID', :NEW.MT_DEPARTMENTTO_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SS_MENU_ID' AND NVL(:OLD.SS_MENU_ID, '999999999999') <> NVL(:NEW.SS_MENU_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'SS_MENU_ID', :NEW.SS_MENU_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SS_ROLE_ID' AND NVL(:OLD.SS_ROLE_ID, '999999999999') <> NVL(:NEW.SS_ROLE_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'SS_ROLE_ID', :NEW.SS_ROLE_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN


                IF NVL(:OLD.MT_DEPARTMENTFROM_ID, 999999999999) <> NVL(:NEW.MT_DEPARTMENTFROM_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'MT_DEPARTMENTFROM_ID', :OLD.MT_DEPARTMENTFROM_ID, :NEW.MT_DEPARTMENTFROM_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.MT_DEPARTMENTTO_ID, 999999999999) <> NVL(:NEW.MT_DEPARTMENTTO_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'MT_DEPARTMENTTO_ID', :OLD.MT_DEPARTMENTTO_ID, :NEW.MT_DEPARTMENTTO_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SS_MENU_ID, 999999999999) <> NVL(:NEW.SS_MENU_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'SS_MENU_ID', :OLD.SS_MENU_ID, :NEW.SS_MENU_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SS_ROLE_ID, 999999999999) <> NVL(:NEW.SS_ROLE_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'SS_ROLE_ID', :OLD.SS_ROLE_ID, :NEW.SS_ROLE_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'MT_DEPARTMENTFROM_ID' AND NVL(:OLD.MT_DEPARTMENTFROM_ID, '999999999999') <> NVL(:NEW.MT_DEPARTMENTFROM_ID, '999999999999') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, COLNAME, :OLD.MT_DEPARTMENTFROM_ID, :NEW.MT_DEPARTMENTFROM_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='MT_DEPARTMENTTO_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, COLNAME, :OLD.MT_DEPARTMENTTO_ID, :NEW.MT_DEPARTMENTTO_ID, :NEW.UPDATEBY);

                ELSIF COLNAME ='SS_MENU_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, COLNAME, :OLD.SS_MENU_ID, :NEW.SS_MENU_ID, :NEW.UPDATEBY);

                ELSIF COLNAME ='SS_ROLE_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, COLNAME, :OLD.SS_ROLE_ID, :NEW.SS_ROLE_ID, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_EDITDEPARTMENT', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

