CREATE TRIGGER "VNMIS"."TG_SS_EXPQRY_D" AFTER DELETE ON "VNMIS"."SS_EXPQRY" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
BEGIN
	DELETE FROM SS_MENUFAVOURITES WHERE FAVOURITESTYPE_ID=2 AND REFERENCE1NUMBER=:OLD.ID;
END;
/
CREATE TRIGGER "VNMIS"."TG_SS_EXPQRY_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."SS_EXPQRY" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		SELECT SQ_SS_EXPQRY_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		:NEW.CODE := FN_SS_SCHEMAOBJECTNAME_CONVERT(:NEW.CODE);
	
		IF :NEW.SS_EXPQRYDBCONN_ID IS NULL THEN
			SELECT MIN(ID)
			INTO   :NEW.SS_EXPQRYDBCONN_ID
			FROM   SS_EXPQRYDBCONN
			WHERE  ISENABLED_ID = 1
				   AND ISUSECURRENTDBCONNECTION_ID = 1;
		END IF;
	ELSIF UPDATING THEN
		IF UPDATING('CODE') THEN
			:NEW.CODE := FN_SS_SCHEMAOBJECTNAME_CONVERT(:NEW.CODE);
		END IF;
		:NEW.UPDATEDATETIME := SYSDATE;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV',
												  'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
/

