CREATE TRIGGER "VNMIS"."TL_SS_FILEEXTENSION" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_FILEEXTENSION" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_FILEEXTENSION'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.CONTENTTYPE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'CONTENTTYPE', :OLD.CONTENTTYPE, VBY);
            END IF;

            IF :OLD.FILEEXTENSION IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'FILEEXTENSION', :OLD.FILEEXTENSION, VBY);
            END IF;

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.ISIMAGE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'ISIMAGE', :OLD.ISIMAGE, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'CONTENTTYPE', :NEW.CONTENTTYPE, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'FILEEXTENSION', :NEW.FILEEXTENSION, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'ISIMAGE', :NEW.ISIMAGE, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'CONTENTTYPE' AND NVL(:OLD.CONTENTTYPE, '@-VNMISLOG-@') <> NVL(:NEW.CONTENTTYPE, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'CONTENTTYPE', :NEW.CONTENTTYPE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'FILEEXTENSION' AND NVL(:OLD.FILEEXTENSION, '@-VNMISLOG-@') <> NVL(:NEW.FILEEXTENSION, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'FILEEXTENSION', :NEW.FILEEXTENSION, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'ISIMAGE' AND NVL(:OLD.ISIMAGE, '999999999999') <> NVL(:NEW.ISIMAGE, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'ISIMAGE', :NEW.ISIMAGE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

                IF NVL(:OLD.CONTENTTYPE, '@-VNMISLOG-@') <> NVL(:NEW.CONTENTTYPE, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'CONTENTTYPE', :OLD.CONTENTTYPE, :NEW.CONTENTTYPE, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.FILEEXTENSION, '@-VNMISLOG-@') <> NVL(:NEW.FILEEXTENSION, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'FILEEXTENSION', :OLD.FILEEXTENSION, :NEW.FILEEXTENSION, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;


                IF NVL(:OLD.ISIMAGE, 999999999999) <> NVL(:NEW.ISIMAGE, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'ISIMAGE', :OLD.ISIMAGE, :NEW.ISIMAGE, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'CONTENTTYPE' AND NVL(:OLD.CONTENTTYPE, '@-VNMISLOG-@') <> NVL(:NEW.CONTENTTYPE, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, COLNAME, :OLD.CONTENTTYPE, :NEW.CONTENTTYPE, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='FILEEXTENSION'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, COLNAME, :OLD.FILEEXTENSION, :NEW.FILEEXTENSION, :NEW.UPDATEBY);

                ELSIF COLNAME ='ISIMAGE'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, COLNAME, :OLD.ISIMAGE, :NEW.ISIMAGE, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_FILEEXTENSION', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

