CREATE TRIGGER "VNMIS"."TG_SS_GRANTMENU_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."SS_GRANTMENU" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_MENUAPP_ID SS_MENUGROUP.SS_APPLICATION_ID%TYPE;
	V_ROLEAPP_ID SS_ROLE.SS_APPLICATION_ID%TYPE;
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_SS_GRANTMENU_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;

		SELECT SS_APPLICATION_ID INTO V_ROLEAPP_ID
		FROM SS_ROLE
		WHERE ID=NVL(:NEW.SS_ROLE_ID,0);

		SELECT B.SS_APPLICATION_ID INTO V_MENUAPP_ID
		FROM SS_MENU A
			INNER JOIN SS_MENUGROUP B ON A.SS_MENUGROUP_ID=B.ID
		WHERE A.ID=NVL(:NEW.SS_MENU_ID,0);

		IF V_ROLEAPP_ID<>V_MENUAPP_ID THEN
			PD_SS_RAISEERROR(-20001,
									ODBCERR(' ระบบงานของ role ไม่สัมพันธ์กับระบบงานของเมนู  '));
		END IF;

	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV',
												  'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
/
CREATE TRIGGER "VNMIS"."TL_SS_GRANTMENU" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_GRANTMENU" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_GRANTMENU'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.SS_MENU_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'SS_MENU_ID', :OLD.SS_MENU_ID, VBY);
            END IF;

            IF :OLD.SS_ROLE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'SS_ROLE_ID', :OLD.SS_ROLE_ID, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'SS_MENU_ID', :NEW.SS_MENU_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'SS_ROLE_ID', :NEW.SS_ROLE_ID, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'SS_MENU_ID' AND NVL(:OLD.SS_MENU_ID, '999999999999') <> NVL(:NEW.SS_MENU_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'SS_MENU_ID', :NEW.SS_MENU_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SS_ROLE_ID' AND NVL(:OLD.SS_ROLE_ID, '999999999999') <> NVL(:NEW.SS_ROLE_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'SS_ROLE_ID', :NEW.SS_ROLE_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN


                IF NVL(:OLD.SS_MENU_ID, 999999999999) <> NVL(:NEW.SS_MENU_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'SS_MENU_ID', :OLD.SS_MENU_ID, :NEW.SS_MENU_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SS_ROLE_ID, 999999999999) <> NVL(:NEW.SS_ROLE_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'SS_ROLE_ID', :OLD.SS_ROLE_ID, :NEW.SS_ROLE_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'SS_MENU_ID' AND NVL(:OLD.SS_MENU_ID, '999999999999') <> NVL(:NEW.SS_MENU_ID, '999999999999') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, COLNAME, :OLD.SS_MENU_ID, :NEW.SS_MENU_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='SS_ROLE_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, COLNAME, :OLD.SS_ROLE_ID, :NEW.SS_ROLE_ID, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_GRANTMENU', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

