CREATE TRIGGER "VNMIS"."TL_SS_GRANTUSERROLE" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_GRANTUSERROLE" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_GRANTUSERROLE'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.SS_ROLE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'SS_ROLE_ID', :OLD.SS_ROLE_ID, VBY);
            END IF;

            IF :OLD.SS_USER_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'SS_USER_ID', :OLD.SS_USER_ID, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'SS_ROLE_ID', :NEW.SS_ROLE_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'SS_USER_ID', :NEW.SS_USER_ID, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'SS_ROLE_ID' AND NVL(:OLD.SS_ROLE_ID, '999999999999') <> NVL(:NEW.SS_ROLE_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'SS_ROLE_ID', :NEW.SS_ROLE_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SS_USER_ID' AND NVL(:OLD.SS_USER_ID, '999999999999') <> NVL(:NEW.SS_USER_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'SS_USER_ID', :NEW.SS_USER_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN


                IF NVL(:OLD.SS_ROLE_ID, 999999999999) <> NVL(:NEW.SS_ROLE_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'SS_ROLE_ID', :OLD.SS_ROLE_ID, :NEW.SS_ROLE_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SS_USER_ID, 999999999999) <> NVL(:NEW.SS_USER_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'SS_USER_ID', :OLD.SS_USER_ID, :NEW.SS_USER_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'SS_ROLE_ID' AND NVL(:OLD.SS_ROLE_ID, '999999999999') <> NVL(:NEW.SS_ROLE_ID, '999999999999') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, COLNAME, :OLD.SS_ROLE_ID, :NEW.SS_ROLE_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='SS_USER_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, COLNAME, :OLD.SS_USER_ID, :NEW.SS_USER_ID, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_GRANTUSERROLE', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

