CREATE TRIGGER "VNMIS"."TL_SS_MENU" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_MENU" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_MENU'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.ACTIVE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'ACTIVE_ID', :OLD.ACTIVE_ID, VBY);
            END IF;

            IF :OLD.ANONYMOUS_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'ANONYMOUS_ID', :OLD.ANONYMOUS_ID, VBY);
            END IF;

            IF :OLD.CALLING IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'CALLING', :OLD.CALLING, VBY);
            END IF;

            IF :OLD.CALLINGURL IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'CALLINGURL', :OLD.CALLINGURL, VBY);
            END IF;

            IF :OLD.CODE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'CODE', :OLD.CODE, VBY);
            END IF;

            IF :OLD.DESCRIPTION IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'DESCRIPTION', :OLD.DESCRIPTION, VBY);
            END IF;

            IF :OLD.DOCUMENTCODE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'DOCUMENTCODE', :OLD.DOCUMENTCODE, VBY);
            END IF;

            IF :OLD.EDITTYPE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'EDITTYPE_ID', :OLD.EDITTYPE_ID, VBY);
            END IF;

            IF :OLD.FL_STORAGE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'FL_STORAGE_ID', :OLD.FL_STORAGE_ID, VBY);
            END IF;

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.LOGKEEP_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'LOGKEEP_ID', :OLD.LOGKEEP_ID, VBY);
            END IF;

            IF :OLD.MENUNAME IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_MENU', LTYPE, 'MENUNAME', :OLD.MENUNAME, VBY);
