CREATE TRIGGER "VNMIS"."TG_SS_ORMREFERENCE_COLUMNS" BEFORE INSERT OR UPDATE OF "REFERENCINGCOLUMNS", "SOURCECOLUMNS" ON "VNMIS"."SS_ORMREFERENCE" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	:NEW.SOURCECOLUMNS := REPLACE(:NEW.SOURCECOLUMNS, ' ', '');
	:NEW.REFERENCINGCOLUMNS := REPLACE(:NEW.REFERENCINGCOLUMNS, ' ', '');
END;
/
CREATE TRIGGER "VNMIS"."TG_SS_ORMREFERENCE_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."SS_ORMREFERENCE" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_SS_ORMREFERENCE_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;
	
	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV',
												  'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
/
CREATE TRIGGER "VNMIS"."TL_SS_ORMREFERENCE" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_ORMREFERENCE" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_ORMREFERENCE'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.ENABLED IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'ENABLED', :OLD.ENABLED, VBY);
            END IF;

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.KEYTYPE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'KEYTYPE', :OLD.KEYTYPE, VBY);
            END IF;

            IF :OLD.NAME IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'NAME', :OLD.NAME, VBY);
            END IF;

            IF :OLD.REFERENCINGCOLUMNS IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'REFERENCINGCOLUMNS', :OLD.REFERENCINGCOLUMNS, VBY);
            END IF;

            IF :OLD.REFERENCINGTABLE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'REFERENCINGTABLE', :OLD.REFERENCINGTABLE, VBY);
            END IF;

            IF :OLD.SOURCECOLUMNS IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'SOURCECOLUMNS', :OLD.SOURCECOLUMNS, VBY);
            END IF;

            IF :OLD.SOURCETABLE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'SOURCETABLE', :OLD.SOURCETABLE, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'ENABLED', :NEW.ENABLED, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'KEYTYPE', :NEW.KEYTYPE, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'NAME', :NEW.NAME, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'REFERENCINGCOLUMNS', :NEW.REFERENCINGCOLUMNS, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'REFERENCINGTABLE', :NEW.REFERENCINGTABLE, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'SOURCECOLUMNS', :NEW.SOURCECOLUMNS, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'SOURCETABLE', :NEW.SOURCETABLE, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'ENABLED' AND NVL(:OLD.ENABLED, '999999999999') <> NVL(:NEW.ENABLED, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'ENABLED', :NEW.ENABLED, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'KEYTYPE' AND NVL(:OLD.KEYTYPE, '999999999999') <> NVL(:NEW.KEYTYPE, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'KEYTYPE', :NEW.KEYTYPE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'NAME' AND NVL(:OLD.NAME, '@-VNMISLOG-@') <> NVL(:NEW.NAME, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'NAME', :NEW.NAME, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'REFERENCINGCOLUMNS' AND NVL(:OLD.REFERENCINGCOLUMNS, '@-VNMISLOG-@') <> NVL(:NEW.REFERENCINGCOLUMNS, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'REFERENCINGCOLUMNS', :NEW.REFERENCINGCOLUMNS, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'REFERENCINGTABLE' AND NVL(:OLD.REFERENCINGTABLE, '@-VNMISLOG-@') <> NVL(:NEW.REFERENCINGTABLE, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'REFERENCINGTABLE', :NEW.REFERENCINGTABLE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SOURCECOLUMNS' AND NVL(:OLD.SOURCECOLUMNS, '@-VNMISLOG-@') <> NVL(:NEW.SOURCECOLUMNS, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'SOURCECOLUMNS', :NEW.SOURCECOLUMNS, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SOURCETABLE' AND NVL(:OLD.SOURCETABLE, '@-VNMISLOG-@') <> NVL(:NEW.SOURCETABLE, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'SOURCETABLE', :NEW.SOURCETABLE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

                IF NVL(:OLD.ENABLED, 999999999999) <> NVL(:NEW.ENABLED, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'ENABLED', :OLD.ENABLED, :NEW.ENABLED, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;


                IF NVL(:OLD.KEYTYPE, 999999999999) <> NVL(:NEW.KEYTYPE, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'KEYTYPE', :OLD.KEYTYPE, :NEW.KEYTYPE, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.NAME, '@-VNMISLOG-@') <> NVL(:NEW.NAME, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'NAME', :OLD.NAME, :NEW.NAME, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.REFERENCINGCOLUMNS, '@-VNMISLOG-@') <> NVL(:NEW.REFERENCINGCOLUMNS, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'REFERENCINGCOLUMNS', :OLD.REFERENCINGCOLUMNS, :NEW.REFERENCINGCOLUMNS, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.REFERENCINGTABLE, '@-VNMISLOG-@') <> NVL(:NEW.REFERENCINGTABLE, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'REFERENCINGTABLE', :OLD.REFERENCINGTABLE, :NEW.REFERENCINGTABLE, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SOURCECOLUMNS, '@-VNMISLOG-@') <> NVL(:NEW.SOURCECOLUMNS, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'SOURCECOLUMNS', :OLD.SOURCECOLUMNS, :NEW.SOURCECOLUMNS, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SOURCETABLE, '@-VNMISLOG-@') <> NVL(:NEW.SOURCETABLE, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'SOURCETABLE', :OLD.SOURCETABLE, :NEW.SOURCETABLE, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'ENABLED' AND NVL(:OLD.ENABLED, '999999999999') <> NVL(:NEW.ENABLED, '999999999999') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, COLNAME, :OLD.ENABLED, :NEW.ENABLED, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='KEYTYPE'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, COLNAME, :OLD.KEYTYPE, :NEW.KEYTYPE, :NEW.UPDATEBY);

                ELSIF COLNAME ='NAME'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, COLNAME, :OLD.NAME, :NEW.NAME, :NEW.UPDATEBY);

                ELSIF COLNAME ='REFERENCINGCOLUMNS'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, COLNAME, :OLD.REFERENCINGCOLUMNS, :NEW.REFERENCINGCOLUMNS, :NEW.UPDATEBY);

                ELSIF COLNAME ='REFERENCINGTABLE'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, COLNAME, :OLD.REFERENCINGTABLE, :NEW.REFERENCINGTABLE, :NEW.UPDATEBY);

                ELSIF COLNAME ='SOURCECOLUMNS'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, COLNAME, :OLD.SOURCECOLUMNS, :NEW.SOURCECOLUMNS, :NEW.UPDATEBY);

                ELSIF COLNAME ='SOURCETABLE'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, COLNAME, :OLD.SOURCETABLE, :NEW.SOURCETABLE, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_ORMREFERENCE', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

