CREATE TRIGGER "VNMIS"."TL_SS_PASSPORTLOG" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_PASSPORTLOG" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
