        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_PASSPORTLOG'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.DESCRIPTION IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'DESCRIPTION', :OLD.DESCRIPTION, VBY);
            END IF;

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.IPADDRESS IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'IPADDRESS', :OLD.IPADDRESS, VBY);
            END IF;

            IF :OLD.LOGTYPE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'LOGTYPE_ID', :OLD.LOGTYPE_ID, VBY);
            END IF;

            IF :OLD.SS_PASSPORTENTITY_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'SS_PASSPORTENTITY_ID', :OLD.SS_PASSPORTENTITY_ID, VBY);
            END IF;

            IF :OLD.SS_PASSPORTSERVER_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'SS_PASSPORTSERVER_ID', :OLD.SS_PASSPORTSERVER_ID, VBY);
            END IF;

            IF :OLD.TERMINALIP IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'TERMINALIP', :OLD.TERMINALIP, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'LOGTYPE_ID', :NEW.LOGTYPE_ID, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'DESCRIPTION' AND NVL(:OLD.DESCRIPTION, '@-VNMISLOG-@') <> NVL(:NEW.DESCRIPTION, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'DESCRIPTION', :NEW.DESCRIPTION, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'IPADDRESS' AND NVL(:OLD.IPADDRESS, '@-VNMISLOG-@') <> NVL(:NEW.IPADDRESS, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'IPADDRESS', :NEW.IPADDRESS, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'LOGTYPE_ID' AND NVL(:OLD.LOGTYPE_ID, '999999999999') <> NVL(:NEW.LOGTYPE_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'LOGTYPE_ID', :NEW.LOGTYPE_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SS_PASSPORTENTITY_ID' AND NVL(:OLD.SS_PASSPORTENTITY_ID, '999999999999') <> NVL(:NEW.SS_PASSPORTENTITY_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'SS_PASSPORTENTITY_ID', :NEW.SS_PASSPORTENTITY_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SS_PASSPORTSERVER_ID' AND NVL(:OLD.SS_PASSPORTSERVER_ID, '999999999999') <> NVL(:NEW.SS_PASSPORTSERVER_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'SS_PASSPORTSERVER_ID', :NEW.SS_PASSPORTSERVER_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'TERMINALIP' AND NVL(:OLD.TERMINALIP, '@-VNMISLOG-@') <> NVL(:NEW.TERMINALIP, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'TERMINALIP', :NEW.TERMINALIP, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

                IF NVL(:OLD.DESCRIPTION, '@-VNMISLOG-@') <> NVL(:NEW.DESCRIPTION, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'DESCRIPTION', :OLD.DESCRIPTION, :NEW.DESCRIPTION, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;


                IF NVL(:OLD.IPADDRESS, '@-VNMISLOG-@') <> NVL(:NEW.IPADDRESS, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'IPADDRESS', :OLD.IPADDRESS, :NEW.IPADDRESS, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.LOGTYPE_ID, 999999999999) <> NVL(:NEW.LOGTYPE_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'LOGTYPE_ID', :OLD.LOGTYPE_ID, :NEW.LOGTYPE_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SS_PASSPORTENTITY_ID, 999999999999) <> NVL(:NEW.SS_PASSPORTENTITY_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'SS_PASSPORTENTITY_ID', :OLD.SS_PASSPORTENTITY_ID, :NEW.SS_PASSPORTENTITY_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SS_PASSPORTSERVER_ID, 999999999999) <> NVL(:NEW.SS_PASSPORTSERVER_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'SS_PASSPORTSERVER_ID', :OLD.SS_PASSPORTSERVER_ID, :NEW.SS_PASSPORTSERVER_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.TERMINALIP, '@-VNMISLOG-@') <> NVL(:NEW.TERMINALIP, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'TERMINALIP', :OLD.TERMINALIP, :NEW.TERMINALIP, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'DESCRIPTION' AND NVL(:OLD.DESCRIPTION, '@-VNMISLOG-@') <> NVL(:NEW.DESCRIPTION, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, COLNAME, :OLD.DESCRIPTION, :NEW.DESCRIPTION, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='IPADDRESS'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, COLNAME, :OLD.IPADDRESS, :NEW.IPADDRESS, :NEW.UPDATEBY);

                ELSIF COLNAME ='LOGTYPE_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, COLNAME, :OLD.LOGTYPE_ID, :NEW.LOGTYPE_ID, :NEW.UPDATEBY);

                ELSIF COLNAME ='SS_PASSPORTENTITY_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, COLNAME, :OLD.SS_PASSPORTENTITY_ID, :NEW.SS_PASSPORTENTITY_ID, :NEW.UPDATEBY);

                ELSIF COLNAME ='SS_PASSPORTSERVER_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, COLNAME, :OLD.SS_PASSPORTSERVER_ID, :NEW.SS_PASSPORTSERVER_ID, :NEW.UPDATEBY);

                ELSIF COLNAME ='TERMINALIP'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, COLNAME, :OLD.TERMINALIP, :NEW.TERMINALIP, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_PASSPORTLOG', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

