CREATE TRIGGER "VNMIS"."TG_SS_ROLE_LOCK" BEFORE DELETE OR UPDATE ON "VNMIS"."SS_ROLE" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF :OLD.ID=80001 THEN
		IF UPDATING THEN
                PD_SS_RAISEERROR(-20001,
                                 'ไม่อนุญาตให้แก้ไขรายการนี้');
		ELSIF DELETING THEN
                PD_SS_RAISEERROR(-20001,
                                 'ไม่อนุญาตให้ลบรายการนี้');
		END IF;
	END IF;
END;
/
