CREATE TRIGGER "VNMIS"."TG_SS_ROLEGRANT_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."SS_ROLEGRANT" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
		   SELECT SQ_SS_ROLEGRANT_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;

	ELSIF UPDATING THEN
		:NEW.UPDATEDATETIME := SYSDATE;
		IF FN_SS_UPDATEBY_CHK = 'O' THEN
			:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		END IF;
    BEGIN
        :new.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV','CLIENT_IDENTIFIER');
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
	END IF;
END;
