                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.SS_USER_ID, 999999999999) <> NVL(:NEW.SS_USER_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ROLEGRANT', LTYPE, 'SS_USER_ID', :OLD.SS_USER_ID, :NEW.SS_USER_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'SS_ROLE_ID' AND NVL(:OLD.SS_ROLE_ID, '999999999999') <> NVL(:NEW.SS_ROLE_ID, '999999999999') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ROLEGRANT', LTYPE, COLNAME, :OLD.SS_ROLE_ID, :NEW.SS_ROLE_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='SS_USER_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_ROLEGRANT', LTYPE, COLNAME, :OLD.SS_USER_ID, :NEW.SS_USER_ID, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_ROLEGRANT', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

