CREATE TRIGGER "VNMIS"."TG_SS_USER_SYNC" BEFORE INSERT OR UPDATE OF "MT_REFER_ID", "PASSWORD", "USERNAME" ON "VNMIS"."SS_USER" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_PP_ENTITY_ID SS_USER.PP_ENTITY_ID%TYPE;
	V_REFERNAME PROMIS.REFER.REFERNAME%TYPE;
	V_HR_STAFF_ID PROMIS.REFER.STAFFID%TYPE;
	V_RG_OFFICER_ID PROMIS.REFER.OFFICERID%TYPE;
	V_MT_REFER_ID PROMIS.REFER.REFERID%TYPE;

	V_STAFFID PROMIS.PASSPORT_ENTITY.STAFFID%TYPE;
	V_OFFICERID PROMIS.PASSPORT_ENTITY.OFFICERID%TYPE;
	V_CONFIGVALUE SS_CONFIG.CONFIGVALUE%TYPE;
BEGIN
	BEGIN
		SELECT CONFIGVALUE
		INTO   V_CONFIGVALUE
		FROM   SS_CONFIG
		WHERE  CONFIGCODE = 'SECURITY.SIGNON.METHOD_CODE';
	EXCEPTION
		WHEN OTHERS THEN
			V_CONFIGVALUE := '-';
	END;

	IF (NVL(:NEW.SIGNONMETHOD_ID, -1) IN (0, 1) AND V_CONFIGVALUE = '100') OR
	   NVL(:NEW.SIGNONMETHOD_ID, -1) = 100 THEN
		IF INSERTING THEN
			:NEW.PASSWORD := NULL;
		END IF;
	
		IF :NEW.PP_ENTITY_ID IS NULL THEN
			BEGIN
				SELECT ENTITYID,
					   STAFFID,
					   OFFICERID
				INTO   V_PP_ENTITY_ID,
					   V_STAFFID,
					   V_OFFICERID
				FROM   PROMIS.PASSPORT_ENTITY
				WHERE  UPPER(LOGIN) = UPPER(:NEW.USERNAME);
			EXCEPTION
				WHEN OTHERS THEN
					V_PP_ENTITY_ID := NULL;
			END;
		ELSE
			V_PP_ENTITY_ID := :NEW.PP_ENTITY_ID;
		END IF;
	
		IF V_PP_ENTITY_ID IS NULL THEN
			IF :NEW.MT_REFER_ID IS NULL THEN
				INSERT INTO PROMIS.PASSPORT_ENTITY
					(LOGIN,
					 PASSWORD)
				VALUES
					(LOWER(:NEW.USERNAME),
					 LOWER(:NEW.USERNAME))
				RETURNING ENTITYID INTO V_PP_ENTITY_ID;
			ELSE
				BEGIN
					SELECT REFERNAME,
						   STAFFID,
						   OFFICERID
					INTO   V_REFERNAME,
						   V_HR_STAFF_ID,
						   V_RG_OFFICER_ID
					FROM   PROMIS.REFER
					WHERE  REFERID = :NEW.MT_REFER_ID;
				EXCEPTION
					WHEN OTHERS THEN
						V_REFERNAME := NULL;
						V_HR_STAFF_ID := NULL;
						V_RG_OFFICER_ID := NULL;
				END;
			
				INSERT INTO PROMIS.PASSPORT_ENTITY
					(FULLNAME,
					 LOGIN,
					 PASSWORD,
					 STAFFID,
					 OFFICERID)
				VALUES
					(V_REFERNAME,
					 LOWER(:NEW.USERNAME),
					 LOWER(:NEW.USERNAME),
					 V_HR_STAFF_ID,
					 V_RG_OFFICER_ID)
				RETURNING ENTITYID INTO V_PP_ENTITY_ID;
			END IF;
		
		ELSE
			IF V_MT_REFER_ID IS NULL THEN
				BEGIN
					SELECT ID
					INTO   V_MT_REFER_ID
					FROM   VW_MT_REFER
					WHERE  HR_STAFF_ID = NVL(V_STAFFID, 0);
				EXCEPTION
					WHEN OTHERS THEN
						V_MT_REFER_ID := NULL;
				END;
			END IF;
		
			IF V_MT_REFER_ID IS NULL THEN
				BEGIN
					SELECT ID
					INTO   V_MT_REFER_ID
					FROM   VW_MT_REFER
					WHERE  RG_OFFICER_ID = NVL(V_OFFICERID, 0);
				EXCEPTION
					WHEN OTHERS THEN
						V_MT_REFER_ID := NULL;
				END;
			END IF;
		
			IF V_MT_REFER_ID IS NOT NULL THEN
				:NEW.MT_REFER_ID := V_MT_REFER_ID;
			END IF;
		END IF;
	
		:NEW.PP_ENTITY_ID := V_PP_ENTITY_ID;
	
		--แก้ไขรหัสผ่าน
		IF UPDATING AND NVL(:NEW.PASSWORD, '-') <> NVL(:OLD.PASSWORD, '-') AND
		   :NEW.PP_ENTITY_ID IS NOT NULL THEN
			UPDATE PROMIS.PASSPORT_ENTITY
			SET    PASSWORD = :NEW.PASSWORD
			WHERE  ENTITYID = :NEW.PP_ENTITY_ID;
		END IF;
	END IF;
END;
/
