CREATE TRIGGER "VNMIS"."TL_SS_USERPROFILEPASSWORD" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_USERPROFILEPASSWORD" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	CURSOR LOG IS
		SELECT LOGTYPE_CODE,
			   DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
		FROM   SS_TABLOG
		WHERE  TABLENAME = 'SS_USERPROFILEPASSWORD'
		GROUP  BY LOGTYPE_CODE,
				  DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
		ORDER  BY LOGTYPE_CODE,
				  DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

	LTYPE VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
	COLNAME VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
	TMPNUM NUMBER;
	CTR NUMBER := 0;
	VFLAG VARCHAR2(1) := 'N';
	UNULL NUMBER := 0;
	VBY SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

	OPEN LOG;
	LOOP
		FETCH LOG
			INTO LTYPE,
				 COLNAME;
		EXIT WHEN LOG%NOTFOUND;
	
		IF CTR = 0 THEN
			SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
			CTR := 1;
		END IF;
	
		IF LTYPE = 'D' AND DELETING THEN
		
			VBY := FN_SS_DELETEBY_GET();
		
			IF :OLD.ALLOW_NOT_CHANGE_WHEN_RESET_ID IS NOT NULL THEN
				INSERT INTO VNMISLOG.SS_TABLELOG
					(LOGSEQUENCE,
					 TABLENAME,
					 LOGTYPE_CODE,
					 COLUMNNAME,
					 NUMBEROLD,
					 CREATEBY)
				VALUES
					(TMPNUM,
					 'SS_USERPROFILEPASSWORD',
					 LTYPE,
					 'ALLOW_NOT_CHANGE_WHEN_RESET_ID',
					 :OLD.ALLOW_NOT_CHANGE_WHEN_RESET_ID,
					 VBY);
			END IF;
		
			IF :OLD.ALLOW_PREVIOUS_ID IS NOT NULL THEN
				INSERT INTO VNMISLOG.SS_TABLELOG
					(LOGSEQUENCE,
					 TABLENAME,
					 LOGTYPE_CODE,
					 COLUMNNAME,
					 NUMBEROLD,
					 CREATEBY)
				VALUES
					(TMPNUM,
