					INSERT INTO VNMISLOG.SS_TABLELOG
						(LOGSEQUENCE,
						 TABLENAME,
						 LOGTYPE_CODE,
						 COLUMNNAME,
						 TEXTOLD,
						 TEXTNEW,
						 CREATEBY)
					VALUES
						(TMPNUM,
						 'SS_USERPROFILETIME',
						 LTYPE,
						 COLNAME,
						 :OLD.PROFILENAME,
						 :NEW.PROFILENAME,
						 :NEW.UPDATEBY);
				END IF;

			END IF;

			IF CTR = 1 AND VFLAG = 'Y' THEN

				INSERT INTO VNMISLOG.SS_TABLELOG
					(LOGSEQUENCE,
					 TABLENAME,
					 LOGTYPE_CODE,
					 COLUMNNAME,
					 NUMBEROLD,
					 NUMBERNEW,
					 CREATEBY)
				VALUES
					(TMPNUM,
					 'SS_USERPROFILETIME',
					 LTYPE,
					 'ID',
					 :OLD.ID,
					 :NEW.ID,
					 :NEW.UPDATEBY);
				CTR := 2;

			END IF;
		END IF;
	END LOOP;
	<<END_LOOP_LOG>>
	CLOSE LOG;
END;
