CREATE TRIGGER "VNMIS"."TL_SS_USERPROFILETIMEITEM" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_USERPROFILETIMEITEM" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_USERPROFILETIMEITEM'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
    VFLAG     VARCHAR2(1) := 'N';
    UNULL     NUMBER := 0;
    VBY     SS_PARAMETER_CH.CREATEBY%TYPE;

BEGIN

    OPEN LOG;
    LOOP
        FETCH LOG
            INTO LTYPE, COLNAME;
        EXIT WHEN LOG%NOTFOUND;

        IF CTR = 0 THEN
            SELECT SQ_SS_LOGSEQUENCE.NEXTVAL INTO TMPNUM FROM DUAL;
            CTR := 1;
        END IF;

        IF LTYPE = 'D' AND DELETING THEN

            VBY := FN_SS_DELETEBY_GET();

            IF :OLD.DAYOFWEEK_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'DAYOFWEEK_ID', :OLD.DAYOFWEEK_ID, VBY);
            END IF;

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'ID', :OLD.ID, VBY);
            END IF;

            IF :OLD.SS_USERPROFILETIME_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'SS_USERPROFILETIME_ID', :OLD.SS_USERPROFILETIME_ID, VBY);
            END IF;

            IF :OLD.TIMEFROM IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, DATEOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'TIMEFROM', :OLD.TIMEFROM, VBY);
            END IF;

            IF :OLD.TIMETO IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, DATEOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'TIMETO', :OLD.TIMETO, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'DAYOFWEEK_ID', :NEW.DAYOFWEEK_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'SS_USERPROFILETIME_ID', :NEW.SS_USERPROFILETIME_ID, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'DAYOFWEEK_ID' AND NVL(:OLD.DAYOFWEEK_ID, '999999999999') <> NVL(:NEW.DAYOFWEEK_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'DAYOFWEEK_ID', :NEW.DAYOFWEEK_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'SS_USERPROFILETIME_ID' AND NVL(:OLD.SS_USERPROFILETIME_ID, '999999999999') <> NVL(:NEW.SS_USERPROFILETIME_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'SS_USERPROFILETIME_ID', :NEW.SS_USERPROFILETIME_ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;


                IF COLNAME = 'TIMEFROM' AND NVL(TO_CHAR(:OLD.TIMEFROM, 'DD-MM-YYYY'), '@') <> NVL(TO_CHAR(:NEW.TIMEFROM, 'DD-MM-YYYY'), '@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, DATENEW, CREATEBY)
            VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'TIMEFROM', :NEW.TIMEFROM, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;


                IF COLNAME = 'TIMETO' AND NVL(TO_CHAR(:OLD.TIMETO, 'DD-MM-YYYY'), '@') <> NVL(TO_CHAR(:NEW.TIMETO, 'DD-MM-YYYY'), '@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, DATENEW, CREATEBY)
            VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'TIMETO', :NEW.TIMETO, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

                IF NVL(:OLD.DAYOFWEEK_ID, 999999999999) <> NVL(:NEW.DAYOFWEEK_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'DAYOFWEEK_ID', :OLD.DAYOFWEEK_ID, :NEW.DAYOFWEEK_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;


                IF NVL(:OLD.SS_USERPROFILETIME_ID, 999999999999) <> NVL(:NEW.SS_USERPROFILETIME_ID, 999999999999) THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'SS_USERPROFILETIME_ID', :OLD.SS_USERPROFILETIME_ID, :NEW.SS_USERPROFILETIME_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(TO_CHAR(:OLD.TIMEFROM, 'DD-MM-YYYY'), '@') <> NVL(TO_CHAR(:NEW.TIMEFROM, 'DD-MM-YYYY'), '@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, DATEOLD, DATENEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'TIMEFROM', :OLD.TIMEFROM, :NEW.TIMEFROM, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(TO_CHAR(:OLD.TIMETO, 'DD-MM-YYYY'), '@') <> NVL(TO_CHAR(:NEW.TIMETO, 'DD-MM-YYYY'), '@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, DATEOLD, DATENEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'TIMETO', :OLD.TIMETO, :NEW.TIMETO, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;


                IF COLNAME = 'DAYOFWEEK_ID' AND NVL(:OLD.DAYOFWEEK_ID, '999999999999') <> NVL(:NEW.DAYOFWEEK_ID, '999999999999') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, COLNAME, :OLD.DAYOFWEEK_ID, :NEW.DAYOFWEEK_ID, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='SS_USERPROFILETIME_ID'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, COLNAME, :OLD.SS_USERPROFILETIME_ID, :NEW.SS_USERPROFILETIME_ID, :NEW.UPDATEBY);

                ELSIF COLNAME ='TIMEFROM'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, DATEOLD, DATENEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, COLNAME, :OLD.TIMEFROM, :NEW.TIMEFROM, :NEW.UPDATEBY);

                ELSIF COLNAME ='TIMETO'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, DATEOLD, DATENEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, COLNAME, :OLD.TIMETO, :NEW.TIMETO, :NEW.UPDATEBY);
                END IF;

            END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN

                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, NUMBERNEW, CREATEBY)
                VALUES (TMPNUM, 'SS_USERPROFILETIMEITEM', LTYPE, 'ID',:OLD.ID, :NEW.ID, :NEW.UPDATEBY);
                CTR := 2;

            END IF;
        END IF;
    END LOOP;
    <<END_LOOP_LOG>>
    CLOSE LOG;
END;
/

