	:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
END;
/
CREATE TRIGGER "VNMIS"."TG_SS_WEBBOARD_UBY" BEFORE DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_WEBBOARD" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_CNTDEPT NUMBER := 0;
	V_CNTSTAFF NUMBER := 0;
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_SS_WEBBOARD_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;
	
	ELSIF UPDATING THEN
		:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		:NEW.UPDATEDATETIME := SYSDATE;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV', 'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	
		IF :NEW.STATUS_ID <> :OLD.STATUS_ID AND :NEW.STATUS_ID = 60 THEN
			IF :NEW.GROUP_ID = 2 THEN
				SELECT COUNT(ID) INTO V_CNTDEPT FROM SS_WEBBOARDDEPT WHERE SS_WEBBOARD_ID = :NEW.ID;
			
				SELECT COUNT(ID) INTO V_CNTSTAFF FROM SS_WEBBOARDSTAFF WHERE SS_WEBBOARD_ID = :NEW.ID;
			
				IF V_CNTDEPT + V_CNTSTAFF = 0 THEN
					PD_SS_RAISEERROR(-20001, ODBCERR('ระบุหน่วยงาน/บุคลากร'));
				END IF;
			END IF;
		
			PD_SS_WEBBOARDDEPT_CH(:NEW.ID, :NEW.CREATEBY);
		END IF;
	ELSE
		DELETE FROM SS_WEBBOARDSTAFF WHERE SS_WEBBOARD_ID = :OLD.ID;
		DELETE FROM SS_WEBBOARDDEPT WHERE SS_WEBBOARD_ID = :OLD.ID;
		DELETE FROM SS_WEBBOARDDEPT_CH WHERE SS_WEBBOARD_ID = :OLD.ID;
		DELETE FROM FL_STORAGE WHERE ID = :OLD.FL_STORAGEIMAGE_ID;
		DELETE FROM FL_STORAGE WHERE ID = :OLD.FL_STORAGEDOC_ID;
		DELETE FROM FL_STORAGE WHERE ID = :OLD.FL_STORAGEDOC2_ID;
		DELETE FROM FL_STORAGE WHERE ID = :OLD.FL_STORAGEDOC3_ID;
		DELETE FROM FL_STORAGE WHERE ID = :OLD.FL_STORAGEDOC4_ID;
	END IF;
END;
/
CREATE TRIGGER "VNMIS"."TL_SS_WEBBOARD" AFTER DELETE OR INSERT OR UPDATE ON "VNMIS"."SS_WEBBOARD" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_WEBBOARD'
        GROUP  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        ORDER  BY LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME) DESC;

    LTYPE     VNMISLOG.SS_TABLELOG.LOGTYPE_CODE%TYPE;
    COLNAME   VNMISLOG.SS_TABLELOG.COLUMNNAME%TYPE;
    TMPNUM    NUMBER;
    CTR       NUMBER := 0;
