            END IF;

            IF :OLD.FL_STORAGEDOC_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'FL_STORAGEDOC_ID', :OLD.FL_STORAGEDOC_ID, VBY);
            END IF;

            IF :OLD.FL_STORAGEIMAGE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'FL_STORAGEIMAGE_ID', :OLD.FL_STORAGEIMAGE_ID, VBY);
            END IF;

            IF :OLD.GROUP_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'GROUP_ID', :OLD.GROUP_ID, VBY);
            END IF;

            IF :OLD.ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'ID', :OLD.ID, VBY);
