            IF :OLD.IMAGEPOSITION_CODE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'IMAGEPOSITION_CODE', :OLD.IMAGEPOSITION_CODE, VBY);
            END IF;

            IF :OLD.LEVEL_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'LEVEL_ID', :OLD.LEVEL_ID, VBY);
            END IF;

            IF :OLD.STATUS_ID IS NOT NULL THEN
