                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'STATUS_ID', :OLD.STATUS_ID, VBY);
            END IF;

            IF :OLD.TOPICNAME IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'TOPICNAME', :OLD.TOPICNAME, VBY);
