            IF :OLD.WEBBOARDTYPE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'WEBBOARDTYPE_ID', :OLD.WEBBOARDTYPE_ID, VBY);
