            IF :OLD.WF_PROCESSINSTANCE_ID IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBEROLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBBOARD', LTYPE, 'WF_PROCESSINSTANCE_ID', :OLD.WF_PROCESSINSTANCE_ID, VBY);
