CREATE TRIGGER "VNMIS"."TG_SS_WEBBOARDDEPT_UBY" BEFORE INSERT OR UPDATE ON "VNMIS"."SS_WEBBOARDDEPT" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF INSERTING THEN
		IF :NEW.ID IS NULL THEN
			SELECT SQ_SS_WEBBOARDDEPT_ID.NEXTVAL INTO :NEW.ID FROM DUAL;
		END IF;
	ELSE
		:NEW.UPDATEBY := SUBSTR(USER, 1, 16);
		:NEW.UPDATEDATETIME := SYSDATE;
		BEGIN
			:NEW.UPDATEBYCLIENT_ID := SYS_CONTEXT('USERENV',
												  'CLIENT_IDENTIFIER');
		EXCEPTION
			WHEN OTHERS THEN
				NULL;
		END;
	END IF;
END;
