    CURSOR LOG IS
        SELECT LOGTYPE_CODE, DECODE(LOGTYPE_CODE, 'D', NULL, COLUMNNAME)
        FROM   SS_TABLOG
        WHERE  TABLENAME = 'SS_WEBBOARDDEPT'
