            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBBOARDDEPT', LTYPE, 'MT_DEPARTMENTTO_ID', :NEW.MT_DEPARTMENTTO_ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBBOARDDEPT', LTYPE, 'SS_WEBBOARD_ID', :NEW.SS_WEBBOARD_ID, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'MT_DEPARTMENTFROM_ID' AND NVL(:OLD.MT_DEPARTMENTFROM_ID, '999999999999') <> NVL(:NEW.MT_DEPARTMENTFROM_ID, '999999999999') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBBOARDDEPT', LTYPE, 'MT_DEPARTMENTFROM_ID', :NEW.MT_DEPARTMENTFROM_ID, :NEW.CREATEBY);
