                VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGE', :OLD.WEBMESSAGE, VBY);
            END IF;

            IF :OLD.WEBMESSAGECODE IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGECODE', :OLD.WEBMESSAGECODE, VBY);
            END IF;

            IF :OLD.WEBMESSAGEENG IS NOT NULL THEN
                INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, CREATEBY)
                VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGEENG', :OLD.WEBMESSAGEENG, VBY);
            END IF;

        ELSIF LTYPE = 'I' AND INSERTING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN

            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGECODE', :NEW.WEBMESSAGECODE, :NEW.CREATEBY);
                UNULL := 1;

            ELSE

                IF UNULL = 1 THEN
                    GOTO END_LOOP_LOG;
                END IF;

                IF COLNAME = 'WEBMESSAGE' AND NVL(:OLD.WEBMESSAGE, '@-VNMISLOG-@') <> NVL(:NEW.WEBMESSAGE, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGE', :NEW.WEBMESSAGE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'WEBMESSAGECODE' AND NVL(:OLD.WEBMESSAGECODE, '@-VNMISLOG-@') <> NVL(:NEW.WEBMESSAGECODE, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGECODE', :NEW.WEBMESSAGECODE, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                IF COLNAME = 'WEBMESSAGEENG' AND NVL(:OLD.WEBMESSAGEENG, '@-VNMISLOG-@') <> NVL(:NEW.WEBMESSAGEENG, '@-VNMISLOG-@') THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGEENG', :NEW.WEBMESSAGEENG, :NEW.CREATEBY);
                    VFLAG := 'Y';
                END IF;

                END IF;

            IF CTR = 1 AND VFLAG = 'Y' THEN
            INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, NUMBERNEW, CREATEBY)
            VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'ID', :NEW.ID, :NEW.CREATEBY);
                    VFLAG := 'Y';
                CTR := 2;

            END IF;

        ELSIF LTYPE = 'U' AND UPDATING THEN

            IF NVL(COLNAME, 'NULL') = 'NULL' THEN


                IF NVL(:OLD.WEBMESSAGE, '@-VNMISLOG-@') <> NVL(:NEW.WEBMESSAGE, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGE', :OLD.WEBMESSAGE, :NEW.WEBMESSAGE, :NEW.UPDATEBY);
                    VFLAG := 'Y';
                END IF;

                IF NVL(:OLD.WEBMESSAGECODE, '@-VNMISLOG-@') <> NVL(:NEW.WEBMESSAGECODE, '@-VNMISLOG-@') THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG(LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, 'WEBMESSAGECODE', :OLD.WEBMESSAGECODE, :NEW.WEBMESSAGECODE, :NEW.UPDATEBY);
