                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, COLNAME, :OLD.WEBMESSAGE, :NEW.WEBMESSAGE, :NEW.UPDATEBY);
                    VFLAG := 'Y';

                ELSIF COLNAME ='WEBMESSAGECODE'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
                    VALUES (TMPNUM, 'SS_WEBMESSAGE', LTYPE, COLNAME, :OLD.WEBMESSAGECODE, :NEW.WEBMESSAGECODE, :NEW.UPDATEBY);

                ELSIF COLNAME ='WEBMESSAGEENG'THEN
                    INSERT INTO VNMISLOG.SS_TABLELOG (LOGSEQUENCE, TABLENAME, LOGTYPE_CODE, COLUMNNAME, TEXTOLD, TEXTNEW, CREATEBY)
