-- ----------------------------
-- Triggers structure for table WF_ENTITY
-- ----------------------------
CREATE TRIGGER "VNMIS"."TG_WF_ENTITY_IA_OWNERRIGHT" AFTER INSERT ON "VNMIS"."WF_ENTITY" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
BEGIN
	IF :NEW.MT_REFERACTUAL_ID IS NOT NULL THEN
		INSERT INTO WF_ENTITYRIGHT
			(WF_ENTITY_ID,
			 MT_REFER_ID,
			 ISOWNER_ID)
		VALUES
			(:NEW.ID,
			 :NEW.MT_REFERACTUAL_ID,
			 1);
	END IF;
END;
/
CREATE TRIGGER "VNMIS"."TG_WF_ENTITY_UA_OWNERRIGHT" AFTER UPDATE OF "MT_REFERACTUAL_ID" ON "VNMIS"."WF_ENTITY" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	VCNT NUMBER;
BEGIN
	DELETE FROM WF_ENTITYRIGHT
	WHERE  MT_REFER_ID = :OLD.ID
		   AND ISOWNER_ID = 1;

	IF :NEW.MT_REFERACTUAL_ID IS NOT NULL THEN
		SELECT COUNT(*)
		INTO   VCNT
		FROM   WF_ENTITYRIGHT
		WHERE  WF_ENTITY_ID = :NEW.ID
			   AND MT_REFER_ID = :NEW.MT_REFERACTUAL_ID;

		IF NVL(VCNT, 0) = 0 THEN

			INSERT INTO WF_ENTITYRIGHT
				(WF_ENTITY_ID,
				 MT_REFER_ID,
				 ISOWNER_ID)
			VALUES
				(:NEW.ID,
				 :NEW.MT_REFERACTUAL_ID,
				 1);
		END IF;
	END IF;
END;
/
