CREATE TRIGGER "VNMIS"."TG_WF_SEQFLOW_U_CURRENTROUND" BEFORE UPDATE OF "CURRENTROUNDNUMBER" ON "VNMIS"."WF_SEQFLOW" REFERENCING OLD AS "OLD" NEW AS "NEW" FOR EACH ROW 
DECLARE
	V_SEQFLOWROUND_ID NUMBER;
BEGIN
	UPDATE WF_SEQFLOWROUND
	SET    ENABLED_ID = 0
	WHERE  WF_SEQFLOW_ID = :NEW.ID
		   AND ENABLED_ID = 1;
	UPDATE WF_SEQFLOWITEM
	SET    ENABLED_ID = 0
	WHERE  WF_SEQFLOW_ID = :NEW.ID
		   AND ENABLED_ID = 1;

	SELECT MAX(ID)
	INTO   V_SEQFLOWROUND_ID
	FROM   WF_SEQFLOWROUND
	WHERE  WF_SEQFLOW_ID = :NEW.ID
		   AND ROUNDNUMBER = :NEW.CURRENTROUNDNUMBER;

	IF V_SEQFLOWROUND_ID IS NULL THEN
		INSERT INTO WF_SEQFLOWROUND
			(CREATEBY,
			 UPDATEBY,
			 WF_SEQFLOW_ID,
			 WF_SEQFLOWTEMPLATE_ID,
			 ROUNDNUMBER)
		VALUES
			(:NEW.UPDATEBY,
			 :NEW.UPDATEBY,
			 :NEW.ID,
			 :NEW.WF_SEQFLOWTEMPLATE_ID,
			 :NEW.CURRENTROUNDNUMBER)
		RETURNING ID INTO :NEW.WF_SEQFLOWROUND_ID;
	END IF;
END;
/

